# Module-level cache: detected WAF per host. Populated after fingerprint_waf()
# calls. Used by adaptive obfuscation chain to pick WAF-specific bypasses.
_DETECTED_WAF_PER_HOST: Dict[str, str] = {}

# Module-level toggle: when True, the legacy waf_bypass_chain() call site
# in context-aware fuzzer is replaced with the adaptive _waf_generate_*
# pipeline. Set by run_scan() based on adaptive_waf= parameter.
_ADAPTIVE_WAF_ENABLED: bool = False

# Module-level cache: current target host for adaptive obfuscation lookup.
# Set by run_scan() at scan start.
_ADAPTIVE_WAF_TARGET_HOST: Optional[str] = None


def _waf_remember_detection(host: str, waf_name: str) -> None:
    """Record that `host` is protected by `waf_name`. Called from engine after
    each fingerprint_waf() detection."""
    if host and waf_name:
        _DETECTED_WAF_PER_HOST[host] = waf_name


def _waf_get_detected(host: str) -> Optional[str]:
    """Lookup detected WAF for a host."""
    return _DETECTED_WAF_PER_HOST.get(host)


def _waf_generate_obfuscation_chain(payload: str,
                                      target_waf: Optional[str] = None,
                                      context: str = "html",
                                      max_variants: int = 25
                                      ) -> List[str]:
    """Generate obfuscated payload variants. WAF-aware when target_waf set.

    Returns list of obfuscated variants. When `target_waf` matches a
    fingerprint key in _WAF_BYPASS_LIBRARY, prefers WAF-specific templates
    first, then fills with generic templates up to max_variants.

    Variants include:
    - Library templates (generic + WAF-specific)
    - The original payload's WAF-bypass mutations (legacy waf_bypass_chain)
    - Encoding variants (Unicode escape, hex entity, decimal entity,
      mixed entity, JS string concat)
    """
    out: List[str] = []
    seen: Set[str] = set()

    def _add(v: str) -> None:
        if v and v not in seen and len(out) < max_variants:
            seen.add(v)
            out.append(v)

    # Layer 1: WAF-specific templates (highest priority when WAF detected)
    if target_waf:
        for entry in _WAF_BYPASS_LIBRARY.get(target_waf, []):
            if entry.get("context", "html") == context:
                _add(entry["template"])

    # Layer 2: Generic high-success templates
    for entry in _WAF_BYPASS_LIBRARY.get("generic", []):
        if entry.get("context", "html") == context:
            _add(entry["template"])

    # Layer 3: Legacy waf_bypass_chain mutations (5 mutations)
    # Apply on the original payload — backward compat for context-aware fuzzer
    try:
        for v in waf_bypass_chain(payload):
            _add(v)
    except (NameError, Exception):
        pass  # waf_bypass_chain may not be defined yet at module load time

    # Layer 4: Encoding variants on original payload
    if payload:
        # Unicode escape on lowercase letters in 'alert', 'onerror', 'script'
        for keyword in ("alert", "script", "onerror", "onload", "javascript"):
            if keyword in payload.lower():
                escaped = "".join(
                    f"\\u{ord(c):04x}" if c.isalpha() else c
                    for c in keyword
                )
                _add(payload.replace(keyword, escaped))
        # Hex HTML entities on critical chars
        if "<" in payload or ">" in payload:
            entity_map = {"<": "&#x3c;", ">": "&#x3e;", '"': "&#x22;",
                          "'": "&#x27;"}
            mutated = "".join(entity_map.get(c, c) for c in payload)
            _add(mutated)
        # Mixed-case event handler names
        if "onerror=" in payload.lower():
            _add(re.sub(r'(onerror)=', r'OnErRoR=', payload, flags=re.IGNORECASE))
        if "onload=" in payload.lower():
            _add(re.sub(r'(onload)=', r'OnLoAd=', payload, flags=re.IGNORECASE))
        # NULL byte injection between < and tag name (very old, sometimes works)
        if payload.startswith("<"):
            _add("<\x00" + payload[1:])

    return out


def _waf_get_recommendations(waf_name: str) -> List[str]:
    """Return human-readable bypass recommendations for a detected WAF."""
    recs: List[str] = []
    waf_specific = _WAF_BYPASS_LIBRARY.get(waf_name, [])
    if waf_specific:
        recs.append(
            f"{len(waf_specific)} {waf_name}-specific bypass templates available"
        )
        for entry in waf_specific[:3]:
            recs.append(f"  • {entry['name']}: {entry['evades']}")
        if len(waf_specific) > 3:
            recs.append(f"  • ... and {len(waf_specific)-3} more")
    else:
        recs.append(
            f"No {waf_name}-specific templates yet — using generic + "
            "encoding obfuscation"
        )
    recs.append(
        f"{len(_WAF_BYPASS_LIBRARY.get('generic', []))} generic high-success "
        "templates always applied"
    )
    return recs


# ── End of inlined WAF Adaptive Obfuscation Pipeline ──────────────────────

# ── LIBRARY PATH HEURISTICS (v10.8 — signal-to-noise improvement) ──────────
# Static JS taint analysis often flags sinks inside vendor library code
# (jQuery 3.2.1 has innerHTML sinks — that's expected, not application bug).
# We classify each finding's path:
#   - "library":     vendor/library code → severity demoted to "info",
#                     library_audit=True flag (separate GUI tab)
#   - "application": project source code → original severity preserved
#
# This dramatically reduces noise in primary RESULTS view while preserving
# library findings in a separate Library Audit section for completeness
# (useful for supply chain reports — "this app uses vulnerable jQuery").

_LIB_PATH_PATTERNS = [
    # Path-based markers
    re.compile(r"/vendor/", re.IGNORECASE),
    re.compile(r"/node_modules/", re.IGNORECASE),
    re.compile(r"/bower_components/", re.IGNORECASE),
    re.compile(r"/lib/", re.IGNORECASE),
    re.compile(r"/libs/", re.IGNORECASE),
    re.compile(r"/_static/", re.IGNORECASE),
    re.compile(r"/assets/vendor/", re.IGNORECASE),
    re.compile(r"/3rd[-_ ]?party/", re.IGNORECASE),
    re.compile(r"/third[-_ ]?party/", re.IGNORECASE),
    re.compile(r"/cdn/", re.IGNORECASE),
    re.compile(r"/(static|public)/(js|javascript)/(lib|vendor)", re.IGNORECASE),
    # CDN host markers
    re.compile(r"//(cdn|cdnjs|ajax\.googleapis|code\.jquery|"
                r"unpkg|jsdelivr|cdnscale)\.", re.IGNORECASE),
    # Analytics / tag-manager / tracker scripts — third-party, NEVER the app's
    # own XSS surface. Their URLs (googletagmanager.com/gtag/js?id=UA-…) don't
    # end in .min.js, so without this they get miscast as application code at
    # full severity (a HIGH FP for Google's own reviewed tracker).
    re.compile(r"googletagmanager\.com", re.IGNORECASE),
    re.compile(r"google-analytics\.com", re.IGNORECASE),
    re.compile(r"connect\.facebook\.net", re.IGNORECASE),
    re.compile(r"\.gstatic\.com", re.IGNORECASE),
    re.compile(r"/(gtag|gtm|analytics|fbevents|hotjar|clarity)\.js", re.IGNORECASE),
    re.compile(r"/gtag/js\b", re.IGNORECASE),
    re.compile(r"[?&]id=(UA|G|GT|AW|DC)-", re.IGNORECASE),  # gtag / GA4 measurement IDs
    # Filename markers — library name + version pattern
    re.compile(r"jquery[\.-]?\d", re.IGNORECASE),
    re.compile(r"angular[\.-]?\d", re.IGNORECASE),
    re.compile(r"react[\.-]?\d", re.IGNORECASE),
    re.compile(r"vue[\.-]?\d", re.IGNORECASE),
    re.compile(r"lodash[\.-]?\d", re.IGNORECASE),
    re.compile(r"moment[\.-]?\d", re.IGNORECASE),
    re.compile(r"bootstrap[\.-]?\d", re.IGNORECASE),
    re.compile(r"axios[\.-]?\d", re.IGNORECASE),
    re.compile(r"d3[\.-]?\d", re.IGNORECASE),
    re.compile(r"three[\.-]?\d", re.IGNORECASE),
    # Minified bundle markers (heuristic — most app bundles also minify, so
    # this is not 100% library — but combined with path markers it's reliable)
    re.compile(r"\.min\.js$", re.IGNORECASE),
]


def _is_library_path(path_or_url: str) -> bool:
    """Return True if path looks like vendor/library code rather than
    application source. Used to demote static-js findings severity to 'info'
    and route them to Library Audit tab in GUI."""
    if not path_or_url:
        return False
    # Normalize — extract path component if full URL
    p = path_or_url
    if "://" in p:
        try:
            p = urlparse(p).path or p
        except Exception:
            pass
    for rx in _LIB_PATH_PATTERNS:
        if rx.search(path_or_url) or rx.search(p):
            return True
    return False

# ── End of library path heuristics ────────────────────────────────────────


def _shutdown_thread_local_browsers(executor, tls, n_workers, attr="hv"):
    """Close per-thread Playwright verifiers ON the worker thread that created
    each one.

    Playwright's sync API is thread-affine: a browser created on worker thread T
    can only be closed on T. The headless-verify pool creates one HeadlessVerifier
    per pool thread (thread-local), so closing them from the main thread (which is
    all the outer `finally` can do, since the pool has already shut down by then)
    raises a greenlet/thread-switch error that gets swallowed — leaking the
    Chromium + node-driver subprocesses for the life of the process.

    This fans a Barrier'd cleanup task to EVERY pool thread so each closes its own
    thread-local instance. The barrier forces exactly one task per distinct thread
    (a thread blocks after taking one, so the rest go to other threads). Must be
    called while `executor` is still alive (i.e. inside the `with` block).

    Returns the list of thread idents that actually closed an instance (for tests).
    """
    import threading as _t
    closed = []
    if n_workers < 1:
        return closed
    barrier = _t.Barrier(n_workers, timeout=15)

    def _close(_i):
        try:
            barrier.wait()          # pin one task per distinct worker thread
        except Exception:
            pass                    # broken barrier (dead thread) → still clean up
        inst = getattr(tls, attr, None)
        if inst is not None:
            try:
                inst.__exit__(None, None, None)
            except Exception:
                pass
            setattr(tls, attr, None)
            closed.append(_t.get_ident())

    try:
        list(executor.map(_close, range(n_workers)))
    except Exception:
        pass
    return closed


@contextlib.contextmanager
def _noop_bar(total=0, title="", spinner="", **kwargs):
    class _Bar:
        text = ""
        def __call__(self, *a, **kw): pass
    yield _Bar()

def alive_bar(total=0, title="", spinner="", **kwargs):
    import os
    if not os.isatty(1):
        return _noop_bar(total, title, spinner, **kwargs)
    return _alive_bar_real(total, title=title, spinner=spinner, **kwargs)

# ══════════════════════════════════════════════════════════════════════════════
# ── CALLBACK SYSTÉM ──────────────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#
# Všechny události scanu jsou předávány přes callbacks dict.
# GUI předá vlastní handlery; CLI použije výchozí print/logging handlery.
#
# Klíče callbacks:
#   on_log(msg: str, level: str)          - obecný log výstup
#   on_csp(result: CSPAnalysisResult)     - výsledek CSP analýzy
#   on_hit(data: dict)                    - XSS hit nalezen
#   on_waf(data: dict)                    - WAF detekován (jednou per host)
#   on_crawler_progress(data: dict)       - průběh crawleru
#   on_crawler_done(data: dict)           - crawler dokončen
#   on_progress(current: int, total: int) - progress skenování
#   on_phase(phase: str, data: dict)      - přechod fáze (crawl/scan/fuzz/dom)
#
# ══════════════════════════════════════════════════════════════════════════════

def _noop(*args, **kwargs):
    """Prázdný callback — použije se pokud GUI handler není předán."""
    pass


def make_callbacks(**overrides) -> Dict[str, Callable]:
    """
    Vytvoří callbacks dict s výchozími CLI handlery.
    GUI předá vlastní handlery přes overrides.
    """
    defaults = {
        "on_log":              _default_on_log,
        "on_csp":              _default_on_csp,
        "on_hit":              _default_on_hit,
        "on_waf":              _default_on_waf,
        "on_crawler_progress": _default_on_crawler_progress,
        "on_crawler_done":     _default_on_crawler_done,
        "on_progress":         _noop,
        "on_phase":            _noop,
    }
    defaults.update(overrides)
    return defaults


def _default_on_log(msg: str, level: str):
    if level == "debug":
        logging.debug(msg)
    elif level in ("warn", "warning"):
        logging.warning(msg)
    elif level == "error":
        logging.error(msg)
    else:
        logging.info(msg)


def _default_on_csp(result):
    _print_csp_summary(result)


def _default_on_hit(data: dict):
    color = "\033[91m" if data.get("context") in ("script_body", "event_handler") else "\033[93m"
    print(
        f"{color}[XSS] {data.get('url', '')}\n"
        f"  param  : {data.get('param', '')}\n"
        f"  context: {data.get('context', '')}\n"
        f"  csp    : {data.get('csp_note', '')}\033[0m",
        flush=True
    )


def _default_on_waf(data: dict):
    print(
        f"\033[90m[WAF] {data['name']} detected on {data['host']} "
        f"(confidence: {data['confidence']}%)\033[0m",
        flush=True
    )


# ════════════════════════════════════════════════════════════════════════════
# UNIFIED HIT EMITTER  —  the single chokepoint for all on_hit dispatches
# ════════════════════════════════════════════════════════════════════════════
# Three responsibilities:
#   1. DEDUP — every hit is keyed on (endpoint_normalized, param, source). A
#      pair seen before is silently dropped. This alone collapses the
#      example.com report from 16 856 hits → ~6 unique findings.
#   2. v2 GATE — runs context_engine classification + content-type downgrade
#      when body/headers are available. Replaces 12 ad-hoc gate calls.
#   3. ACTIVE RENDER PROBE — for high-confidence candidates with an
#      available session, sends ONE extra request with multi-encoded
#      markers and verifies that the breakout char survives in *executable*
#      form (not just \u003c text). API from _render_gate.py.
#
# Every cb["on_hit"](...) callsite in this module must go through here.
# ════════════════════════════════════════════════════════════════════════════

# Module-level dedup state — set per scan run via reset_emit_state()
_emitted_keys = set()
# v10.16: sběr SKUTEČNĚ vyemitovaných nálezů (prošly dedup + v2 gate +
# render probe) — to jsou ty, co GUI ukazuje ve "findings". JSON report dřív
# ukládal `results` (každý reflektující seed kandidát = stovky řádků šumu);
# teď ukládá tenhle čistý seznam.
_emitted_hits: List[dict] = []
_emit_lock = Lock()
_emit_stats = {
    "emitted": 0,
    "dedup_dropped": 0,
    "gate_dropped": 0,
    "render_probe_dropped": 0,
    "render_probe_passed": 0,
    "render_probe_skipped": 0,
}

# Active render gate config — disabled by default to avoid extra requests
# unless explicitly enabled. Can be flipped via reset_emit_state().
_active_render_gate_enabled = False
_active_render_gate_session = None
_active_render_gate_timeout = 6.0


def reset_emit_state(*, active_render_gate: bool = False,
                      session=None, timeout: float = 6.0) -> None:
    """Reset dedup + stats. Call once at scan start.

    Args:
        active_render_gate: if True, run an extra HTTP probe per
            candidate with multi-encoded markers to verify exec primitive
            survives sanitization. Costs +1 request per *unique* finding,
            not per probe.
        session: requests.Session for the active probe. Required if
            active_render_gate=True.
        timeout: per-probe timeout.
    """
    # _emit_stats se neresetuje rebindingem, ale in-place mutací níže
    # (_emit_stats[k] = 0), takže `global` pro něj není potřeba.
    global _emitted_keys, _emitted_hits
    global _active_render_gate_enabled, _active_render_gate_session
    global _active_render_gate_timeout
    with _emit_lock:
        _emitted_keys = set()
        _emitted_hits = []
        for k in _emit_stats:
            _emit_stats[k] = 0
        _active_render_gate_enabled = bool(active_render_gate and session is not None)
        _active_render_gate_session = session
        _active_render_gate_timeout = timeout


def _reseed_resumed_findings(resumed, cb) -> int:
    """v10.77: after reset_emit_state() wipes the emit state, re-seat findings
    restored from a checkpoint into the REAL emit state so they appear in
    get_emitted_hits() → JSON/HTML/SARIF report + the --fail-on-findings CI gate,
    and seed the dedup set so the (unconditionally re-run) seed phase does NOT
    double-emit one it happens to rediscover. Notifies the GUI once per finding.

    Fixes the silent-loss bug: the old restore ran BEFORE reset via a bare
    cb['on_hit'], so restored findings were both wiped by the reset and never in
    _emitted_hits — absent from every report artifact and undercounting CI.
    """
    if not resumed:
        return 0
    seeded = []
    with _emit_lock:
        for _rf in resumed:
            try:
                k = _dedup_key(_rf)
            except Exception:
                k = None
            if k is not None and k in _emitted_keys:
                continue
            if k is not None:
                _emitted_keys.add(k)
            _emitted_hits.append(_rf)
            seeded.append(_rf)
    on_hit = cb.get("on_hit") if isinstance(cb, dict) else None
    if callable(on_hit):
        for _rf in seeded:
            try:
                on_hit(_rf)
            except Exception:
                pass
    return len(seeded)


def get_emit_stats() -> Dict[str, int]:
    """Return a snapshot of dedup/gate stats. Safe to call any time."""
    with _emit_lock:
        return dict(_emit_stats)


def get_emitted_hits() -> List[dict]:
    """v10.16: Vrátí seznam SKUTEČNÝCH nálezů (prošly dedup + gate + probe),
    tj. to co GUI ukazuje ve findings. Pro JSON report — bez seed šumu."""
    with _emit_lock:
        return list(_emitted_hits)


def _ci_fail_count(emitted_count, found_count) -> int:
    """v10.76: CI-gate finding count for --fail-on-findings.

    Returns the REAL report total. `found_count` (=len(found_params)) is only
    populated by classic reflection; DOM-V6, headless, mXSS, static-JS, stored
    round-trip and proto-pollution emit solely via _emit_hit/get_emitted_hits(),
    so gating on found_params alone let a build with confirmed criticals exit 0
    (CI false negative). Taking the max of both counts fixes that.
    """
    return max(int(emitted_count or 0), int(found_count or 0))


# v10.16: kanonické pořadí závažnosti (vyšší index = závažnější).
_SEVERITY_ORDER = ["info", "low", "medium", "high", "critical"]


def _resolve_severity(hit: dict) -> str:
    """Vybere nejlepší dostupnou severity z nálezu. Priorita:
    explicitní 'severity' → 'gate_severity' → odvození z kontextu →
    fallback 'medium'. Normalizuje na _SEVERITY_ORDER."""
    for key in ("severity", "gate_severity"):
        v = (hit.get(key) or "").strip().lower()
        if v in _SEVERITY_ORDER:
            return v
        # běžné aliasy
        if v in ("crit",):
            return "critical"
        if v in ("med", "moderate"):
            return "medium"
        if v in ("informational", "note"):
            return "info"
    # Heuristika podle kontextu, když explicitní severity ani gate_severity
    # chybí (některé fáze ji nenastaví — DOM, postMessage, dangling, …).
    # v10.16: sladěno s context_engine._compute_severity — kritické kontexty
    # (přímý JS exec / code-exec sink / tag breakout) teď dostanou CRITICAL,
    # ne strop na high. Dřív se kritické nálezy z fází bez gate_severity tiše
    # srážely na high.
    ctx = (hit.get("context") or "").lower()
    evidence = (hit.get("evidence") or "").lower()
    sink = (hit.get("sink") or hit.get("sink_name") or "").lower()
    blob = f"{ctx} {evidence} {sink}"

    # CRITICAL — přímý JS exec nebo ekvivalent
    #  • reflexe uvnitř <script>/<style> raw textu
    #  • code-exec sinky: eval, Function, setTimeout(string), document.write
    #  • innerHTML/outerHTML s neescapovaným tag injection
    #  • template injection (SSTI → exec), prototype-pollution gadget chain
    #  • neuvozovkovaný atribut s breakoutem tagu
    _CRIT_SIGNALS = (
        "script_body", "script-body", "code-exec", "code_exec",
        "eval", "function(", "document.write", "settimeout", "setinterval",
        "innerhtml", "outerhtml", "template-injection", "template_injection",
        "ssti", "proto-pollution-chain", "prototype-pollution",
        "unquoted", "tag_injection", "tag-injection", "tag breakout",
        "dangling-markup",  # otevřený tag pohltí markup → tag injection
    )
    if any(s in blob for s in _CRIT_SIGNALS):
        return "critical"

    # HIGH — reálný XSS o stupeň níž
    #  • quoted-attribute breakout, event handler, stored, javascript: URL,
    #    DOM taint do sinku, postMessage/jsonp/svg reflection
    _HIGH_SIGNALS = (
        "script", "event", "stored", "dom-v6", "dom-dynamic", "dom_dynamic",
        "static-js-taint", "taint", "postmessage", "jsonp", "svg-xml",
        "javascript:", "href", "src=", "attr_breakout", "attribute breakout",
    )
    if any(s in blob for s in _HIGH_SIGNALS):
        return "high"

    # MEDIUM — text-only reflexe / hypotetická tag injekce / url/attr kontext
    if "url" in blob or "attr" in blob or "html" in blob:
        return "medium"
    return "medium"


def summarize_findings(hits: Optional[List[dict]] = None) -> Dict:
    """v10.16: Z emitnutých nálezů vyrobí (a) dedupovaný seznam podle
    (normalized_endpoint, param, context) a (b) breakdown podle závažnosti.

    Dedup: stejná zranitelnost na /clanek?id=1 a /clanek?id=2 je JEDEN bug
    (stejný endpoint+param+kontext). Reprezentant = první výskyt; ostatní
    URL se uloží do 'duplicate_urls' (počet + vzorek), aby se nic neztratilo.

    Vrací:
      {
        "by_severity": {"critical": N, "high": N, ...},
        "total": <počet dedupovaných nálezů>,
        "total_raw": <počet před dedup>,
        "deduped_findings": [ {... + severity, duplicate_count, duplicate_urls} ],
      }
    """
    if hits is None:
        hits = get_emitted_hits()

    groups: Dict[Tuple[str, str, str], dict] = {}
    for h in hits:
        endpoint = _normalize_endpoint(h.get("url", ""))
        param = h.get("param", "") or ""
        ctx = (h.get("context") or "").strip().lower()
        key = (endpoint, param, ctx)
        if key not in groups:
            rep = dict(h)
            rep["severity"] = _resolve_severity(h)
            rep["endpoint"] = endpoint
            rep["duplicate_count"] = 0
            rep["duplicate_urls"] = []
            groups[key] = rep
        else:
            rep = groups[key]
            rep["duplicate_count"] += 1
            # ulož vzorek dalších URL (max 10, ať report nenabobtná)
            u = h.get("url", "")
            if u and u != rep.get("url") and len(rep["duplicate_urls"]) < 10:
                if u not in rep["duplicate_urls"]:
                    rep["duplicate_urls"].append(u)

    deduped = list(groups.values())
    # Seřaď od nejzávažnějšího
    deduped.sort(key=lambda r: _SEVERITY_ORDER.index(
        r["severity"]) if r["severity"] in _SEVERITY_ORDER else 0,
        reverse=True)

    by_sev = {s: 0 for s in _SEVERITY_ORDER}
    for r in deduped:
        by_sev[r["severity"]] = by_sev.get(r["severity"], 0) + 1

    return {
        "by_severity": by_sev,
        "total": len(deduped),
        "total_raw": len(hits),
        "deduped_findings": deduped,
    }


def _normalize_endpoint(url: str) -> str:
    """Strip query, fragment, AND noise params so /x?a=1 and /x?a=2&_=xy
    dedup to the same endpoint. Returns scheme://host/path."""
    try:
        u = urlparse(url or "")
        # Lowercase scheme+host, keep path as-is
        scheme = (u.scheme or "http").lower()
        netloc = (u.netloc or "").lower()
        path = u.path or "/"
        # Strip trailing slash for consistency, except for root
        if len(path) > 1 and path.endswith("/"):
            path = path[:-1]
        return f"{scheme}://{netloc}{path}"
    except Exception:
        return url or ""


def _dedup_key(hit_data: dict) -> Tuple[str, str, str]:
    """Build dedup key from hit. Same (endpoint, param, source) → same finding.

    A hit may set 'dedup_url' to override the endpoint component. Library-scoped
    findings use this so the SAME vendor file embedded on N pages (or served from
    N hosts/paths) collapses to ONE finding — dedup on the library, not the
    embedding page. Without it, jquery-3.2.1.min.js on 6 pages = 6 findings."""
    param = (hit_data.get("param") or "").strip()
    source = hit_data.get("source") or "unknown"
    override = hit_data.get("dedup_url")
    if override:
        return (str(override), param, source)
    url = hit_data.get("url") or hit_data.get("test_url") or ""
    return (_normalize_endpoint(url), param, source)


def _run_v2_gate(body: str, payload: str, resp_headers,
                  cb_log) -> Tuple[Optional[dict], Optional[str]]:
    """Run context_engine v2 gate (static + dynamic + content-type).

    Returns:
        (gate_verdict_dict, skip_reason) — skip_reason None if hit should pass.
    """
    if not _CONTEXT_ENGINE_AVAILABLE:
        return None, None
    if not body or not payload:
        return None, None
    try:
        from context_engine import (
            classify_payload_static as _ce_static,
            classify_response as _ce_dyn,
            merge_static_dynamic as _ce_merge,
            classify_response_renderability as _ce_rend,
            apply_downgrade as _ce_down,
        )
        static_v = _ce_static(payload)
        dyn_v = _ce_dyn(body, payload)
        merged = _ce_merge(static_v, dyn_v)

        ct = ""
        try:
            if resp_headers is not None:
                ct = (resp_headers.get("Content-Type", "") or "").strip()
        except Exception:
            pass
        rend = _ce_rend(ct, body=body)

        new_sev, ds_notes = _ce_down(merged.severity, rend)

        verdict = {
            "klass":         merged.klass.value,
            "severity":      new_sev,
            "confidence":    merged.confidence,
            "primitives":    merged.primitives,
            "rationale":     merged.rationale,
            "renderability": rend.renderability.value,
            "content_type":  rend.content_type,
            "downgrade_notes": ds_notes,
        }

        # Decision
        is_non_html = rend.renderability.value not in (
            "html_rendered", "javascript_response", "unknown")
        skip_reason = None
        if is_non_html and merged.klass.value in ("text_only", "tag_injection"):
            skip_reason = (f"non_html_response({rend.content_type})"
                           f"_with_{merged.klass.value}")
        elif merged.klass.value == "text_only" and not is_non_html:
            skip_reason = "text_only_reflection_no_primitive"

        return verdict, skip_reason
    except Exception as e:
        try:
            cb_log(f"[GATE] error ({type(e).__name__}: {e}) — fallthrough", "warning")
        except Exception:
            pass
        return None, None


def _run_active_render_probe(url: str, param: str, top_context: str,
                              cb_log) -> Optional[Tuple[bool, str]]:
    """Send a multi-encoded marker to (url, param) and check if the
    breakout char survives in executable form.

    Returns:
        None if probe couldn't run (no session, error, etc.) — caller treats as inconclusive
        (True, reason) if executable form survived → finding is real
        (False, reason) if only inert forms survived → finding is FP

    Cost: 1 HTTP request.
    """
    if not _active_render_gate_enabled:
        return None
    sess = _active_render_gate_session
    if sess is None or not url or not param:
        return None
    try:
        from context_engine import (
            encoded_marker_set, gate_executability,
        )
    except ImportError:
        return None

    # Build marker base — must be unique enough not to collide with response
    base_marker = "<XSGT" + random_marker(6).upper()

    # Concat all 7 encoded variants into one payload string. The render gate
    # will look for each variant in the body; whichever survives in raw form
    # at least once means breakout primitive works.
    try:
        variants = encoded_marker_set(base_marker)
    except Exception:
        return None

    # Build multi-payload by joining with safe separators (commas/spaces)
    # so server reflects them all but they don't combine into something weird
    multi_payload = " ".join(v.payload for v in variants)

    # Fire one request — keep it lightweight
    try:
        test_url = inject_into_params(url, param, multi_payload, extra_params=None)
        if not test_url:
            return None
        resp = sess.get(test_url,
                        timeout=_active_render_gate_timeout,
                        allow_redirects=True)
        body = resp.text or ""
    except Exception as e:
        try:
            cb_log(f"[RENDER-PROBE] failed for {param}: "
                   f"{type(e).__name__}: {str(e)[:80]}", "debug")
        except Exception:
            pass
        return None

    try:
        verdict = gate_executability(body, variants, top_context=top_context)
    except Exception:
        return None

    return (verdict.executable, verdict.reason or "")


def _emit_hit(cb: Dict[str, Callable],
               hit_data: dict,
               *,
               body: Optional[str] = None,
               resp_headers=None,
               run_active_probe: bool = False) -> bool:
    """Single chokepoint for all on_hit dispatches.

    Performs (in order): dedup → v2 gate → active render probe → emit.

    Args:
        cb: callbacks dict
        hit_data: payload for cb["on_hit"]. Must include 'url', 'param', 'source'.
        body: response body (if available) for v2 gate
        resp_headers: response headers (if available) for content-type check
        run_active_probe: if True AND gate config enabled AND high-confidence
            finding, run extra probe to confirm exec primitive survives.

    Returns:
        True if hit was emitted, False if dropped.
    """
    if not hit_data:
        return False

    # ── DEDUP ──
    key = _dedup_key(hit_data)
    with _emit_lock:
        if key in _emitted_keys:
            _emit_stats["dedup_dropped"] += 1
            return False
        _emitted_keys.add(key)

    # ── v2 GATE ──
    payload = hit_data.get("payload") or ""
    gate_verdict, skip_reason = _run_v2_gate(
        body, payload, resp_headers, cb.get("on_log", _noop))

    if gate_verdict is not None:
        # Annotate hit with gate info for downstream consumers (GUI, report)
        hit_data["gate_klass"] = gate_verdict.get("klass")
        hit_data["gate_severity"] = gate_verdict.get("severity")
        hit_data["gate_renderability"] = gate_verdict.get("renderability")
        hit_data["gate_content_type"] = gate_verdict.get("content_type")
        hit_data["gate_verdict"] = gate_verdict
        try:
            cb.get("on_log", _noop)(
                f"[GATE] {hit_data.get('param','?')} → "
                f"klass={gate_verdict.get('klass')} "
                f"sev={gate_verdict.get('severity')} "
                f"render={gate_verdict.get('renderability')}",
                "info")
        except Exception:
            pass

    if skip_reason:
        with _emit_lock:
            _emit_stats["gate_dropped"] += 1
        try:
            cb.get("on_log", _noop)(
                f"[GATE-SKIP] {hit_data.get('param','?')} on "
                f"{_normalize_endpoint(hit_data.get('url',''))} → {skip_reason}",
                "info")
        except Exception:
            pass
        return False

    # ── ACTIVE RENDER PROBE (optional, costs 1 request) ──
    if run_active_probe and _active_render_gate_enabled:
        # Map gate klass → top_context family used by render gate
        klass = (gate_verdict or {}).get("klass") if gate_verdict else None
        # default to html_text — most common
        top_ctx = "html_text"
        ctx_name = (hit_data.get("context") or "").lower()
        if "script" in ctx_name or "js_" in ctx_name:
            top_ctx = "js_string"
        elif "href" in ctx_name or "url" in ctx_name:
            top_ctx = "url_attr"
        elif "attr" in ctx_name or "event" in ctx_name:
            top_ctx = "html_attr"

        probe_result = _run_active_render_probe(
            hit_data.get("url", ""), hit_data.get("param", ""),
            top_ctx, cb.get("on_log", _noop))

        if probe_result is None:
            with _emit_lock:
                _emit_stats["render_probe_skipped"] += 1
            hit_data["render_probe"] = "skipped"
        else:
            executable, reason = probe_result
            hit_data["render_probe"] = "executable" if executable else "inert"
            hit_data["render_probe_reason"] = reason
            if not executable:
                with _emit_lock:
                    _emit_stats["render_probe_dropped"] += 1
                try:
                    cb.get("on_log", _noop)(
                        f"[RENDER-PROBE-DROP] {hit_data.get('param','?')} → "
                        f"{reason} (server sanitizes; not exploitable)",
                        "info")
                except Exception:
                    pass
                return False
            else:
                with _emit_lock:
                    _emit_stats["render_probe_passed"] += 1
                try:
                    cb.get("on_log", _noop)(
                        f"[RENDER-PROBE-OK] {hit_data.get('param','?')} → "
                        f"executable: {reason}",
                        "info")
                except Exception:
                    pass

    # ── EMIT ──
    with _emit_lock:
        _emit_stats["emitted"] += 1
        # v10.16: ulož kopii nálezu pro JSON report (čistý findings seznam)
        _emitted_hits.append(dict(hit_data))
    try:
        cb.get("on_hit", _noop)(hit_data)
    except Exception as e:
        # An on_hit handler that crashes must not break the scanner
        try:
            cb.get("on_log", _noop)(
                f"[EMIT] on_hit handler raised: {type(e).__name__}: {e}",
                "warning")
        except Exception:
            pass
    return True


def _apply_headless_verdict(finding: dict, *, executed: bool, status: str,
                            kind: str, evidence: str = "",
                            method: str = "") -> Optional[str]:
    """v10.32: Promítne verdikt headless Chromia (ground-truth orákulum) do
    severity/fp_risk nálezu. JEDEN zdroj pravdy — volá se jak na results-ref,
    tak (reconciliací) na emitnutý hit, který jde reálně do reportu.

    Pravidla (záměrně konzervativní — "bez nesmyslů"):
      EXECUTED → PROVEN TP: dom_verified=True, fp_risk=False,
        dynamic_confirmation="playwright_confirmed" (sjednocuje historicky
        rozbité dom_verified↔headless_executed → scorer feature +0.50 teď
        reálně střelí). Severitu detektoru NEZVYŠUJE (proof ji potvrzuje,
        nevymýšlí vyšší).
      NOT_EXECUTED (jen kind ∈ {reflected, template_injection}) → LIKELY FP:
        MĚKKÝ demote na 'low' + fp_risk=True, potential_severity zachová
        původní (signál ZŮSTÁVÁ viditelný v HTML/SARIF/GUI, jen nepromuje).
        Platné vyvrácení JEN pro "fires-on-direct-load" třídy.
      ERROR / SKIPPED / timeout → orákulum nepromluvilo: severity beze změny.
      mXSS / stored / blind / DOM-stateful → NEdemotovat: jeden single-load
        výstřel u nich FP nedokazuje (payload se může spustit po akci / na
        jiné stránce / přes OOB).

    Vrací: "promoted" | "demoted" | None (co se stalo) — pro logging/testy.
    """
    if not isinstance(finding, dict):
        return None
    # v10.79 FP fix: a dialog that fired WITHOUT our canary (method contains
    # 'no_canary') is the target page's OWN alert/confirm/prompt (flash message,
    # consent dialog, dev build) — it must NOT promote our finding to
    # playwright_confirmed/dom_verified. The stored path already guarded this;
    # apply it centrally so the reflected/template/DOM-v6 paths do too. Since the
    # status is still 'executed' (not 'not_executed'), it also won't wrongly
    # DEMOTE — a foreign dialog neither confirms nor refutes our finding.
    if executed and "no_canary" in (method or ""):
        return None
    if executed:
        if evidence:
            finding["headless_evidence"] = evidence[:200]
        finding["dom_verified"] = True
        finding["fp_risk"] = False
        finding["fp_reason"] = ""
        finding["dynamic_confirmation"] = "playwright_confirmed"
        finding["verification_required"] = False
        finding["headless_demoted"] = False
        # ── v10.86: proof sets a severity FLOOR of high. ──
        # This used to deliberately leave severity alone ("proof confirms it,
        # doesn't invent a higher one"). The effect, measured on the Firing
        # Range corpus, was an INVERTED report: 255 findings on endpoints where
        # the browser actually executed our canary stayed `info` while only 10
        # reached `high` — meanwhile unproven static taint was emitted at
        # high/critical straight from its sink table. Triage by severity
        # therefore surfaced exactly the wrong queue.
        #
        # A canary-bearing dialog from injected input IS arbitrary script
        # execution in the user's origin; that is high by definition, so the
        # floor is a statement of fact rather than an invented escalation. The
        # `no_canary` guard above already excluded the page's own dialogs, and
        # anything the detector rated higher (critical) is preserved.
        _rank = {"info": 0, "informational": 0, "low": 1, "medium": 2,
                 "high": 3, "critical": 4}
        _cur = str(finding.get("severity") or "info").lower()
        if _rank.get(_cur, 0) < _rank["high"]:
            finding["severity_before_proof"] = _cur
            finding["severity"] = "high"
            finding["gate_severity"] = "high"
            finding["severity_reason"] = (
                "browser-confirmed execution of our canary (was "
                f"{_cur}; proof sets a high floor)")
        return "promoted"
    if status == "not_executed" and kind in ("reflected", "template_injection"):
        prev_sev = (finding.get("severity")
                    or finding.get("gate_severity") or "high")
        # zachovej původní severitu jen poprvé (idempotence při dvojím průchodu)
        finding.setdefault("potential_severity", prev_sev)
        finding["severity"] = "low"
        finding["gate_severity"] = "low"
        finding["fp_risk"] = True
        finding["verification_required"] = False
        finding["headless_demoted"] = True
        finding["dynamic_confirmation"] = "none"
        finding["fp_reason"] = (
            "Headless Chromium loaded the page and the payload did NOT fire "
            "(NOT_EXECUTED) — likely false positive (sanitized at render / CSP "
            "/ framework-escaped). Manual verification required; original "
            f"detector severity was '{finding.get('potential_severity')}'.")
        return "demoted"
    return None


def _reconcile_headless_onto_emitted(headless_verdicts: List[Dict],
                                     cb: Dict[str, Callable]) -> Dict[str, int]:
    """v10.32: Reflected report bere KOPIE z get_emitted_hits() (ne results-ref),
    takže verdikt aplikovaný na results-ref by se do reportu nepropsal. Tady
    dohledáme odpovídající emitnuté hity a aplikujeme TÝŽ helper.

    Match: (normalizovaný endpoint, param) + emitnutý hit musí být reflektovaný
    XSS nález (nese 'gate_klass' — síťové nálezy CORS/SSRF/JSONP/SVG ho nemají),
    aby se omylem nedemotoval nález jiné třídy se stejným parametrem.
    (template_injection se propisuje sám — jeho result_ref JE objekt v reportu.)
    """
    stats = {"promoted": 0, "demoted": 0}
    try:
        emitted = get_emitted_hits()
    except Exception:
        return stats
    if not emitted:
        return stats
    # index emitnutých reflektovaných hitů podle (endpoint, param)
    idx: Dict[Tuple[str, str], List[dict]] = {}
    for h in emitted:
        if not isinstance(h, dict) or not h.get("gate_klass"):
            continue
        k = (_normalize_endpoint(h.get("url", "")), (h.get("param") or "").strip())
        idx.setdefault(k, []).append(h)
    for v in headless_verdicts:
        if v.get("kind") != "reflected":
            continue
        k = (_normalize_endpoint(v.get("url", "")), (v.get("param") or "").strip())
        for h in idx.get(k, []):
            action = _apply_headless_verdict(
                h, executed=bool(v.get("executed")),
                status=str(v.get("status", "")),
                kind="reflected", evidence=v.get("evidence", ""),
                method=str(v.get("method", "")))
            if action:
                stats[action] = stats.get(action, 0) + 1
    if stats["promoted"] or stats["demoted"]:
        try:
            cb.get("on_log", _noop)(
                f"[HEADLESS] reconciled onto report findings: "
                f"{stats['promoted']} confirmed (proven TP), "
                f"{stats['demoted']} demoted to low (likely FP)", "info")
        except Exception:
            pass
    return stats


def _requests_cookies_to_pw(session, target: str):
    """Převede requests cookies na Playwright formát (pro autentizované view
    stránky při stored headless potvrzení). Best-effort, None při prázdnu."""
    try:
        host = urlparse(target).hostname or ""
        out = []
        for c in session.cookies:
            out.append({
                "name": c.name, "value": c.value,
                "domain": c.domain or host, "path": c.path or "/",
            })
        return out or None
    except Exception:
        return None


def _confirm_stored_headless(verifier, view_url: str, marker: str, *,
                             cookies=None, framework_wait: bool = True):
    """v10.35: Potvrdí stored XSS reálným renderem ve headless Chromiu.

    Po zasazení payloadu POSTem načte view_url a sleduje, jestli vystřelí NÁŠ
    kanárek (marker uvnitř alert(...)). Pokud ano, je to proven stored TP —
    i když exekuce proběhla až KLIENTSKY přes innerHTML (Google XSS-game
    level-2 typ), což HTTP reflexe (marker in body) nikdy nerozliší.

    Vrací (confirmed, verdict). confirmed=True JEN při shodě kanárku — ne
    'nějaký dialog' (na stránce koexistuje víc stored payloadů, cizí dialog
    se hlásí jako dialog_alert_no_canary a NESMÍ potvrdit tenhle nález)."""
    if verifier is None or not getattr(verifier, "available", False):
        return False, None
    try:
        verdict = verifier.verify_url(view_url, expect_canary=marker,
                                      framework_wait=framework_wait,
                                      cookies=cookies)
    except Exception:
        return False, None
    method = (getattr(verdict, "method", "") or "").lower()
    # v10.82 DEPTH: a STORED value is very often echoed verbatim into a console.log
    # or an error string (the app logging/displaying the submitted input) — that is
    # NOT execution and was a real stored false-positive source. Require an actual
    # DIALOG (alert/confirm/prompt, incl. native_dialog) carrying OUR canary — the
    # unambiguous execution signal — and still reject the page's own dialog
    # ('no_canary'). Real stored payloads (onerror=alert(canary)) fire a dialog, so
    # true positives are unaffected; console/error echoes are correctly dropped.
    confirmed = (bool(getattr(verdict, "executed", False))
                 and "dialog" in method
                 and "no_canary" not in method)
    return confirmed, verdict


def _reflected_breakout_confirm(verifier, session, url, param, cb,
                                timeout, follow_redirects, cap: int = 12):
    """v10.43: reflected XSS → breakout → headless potvrzení EXEKUCE, teď přes
    sjednocený DOMExploitEngine (source=QUERY). Naparsuje rich kontext reflexe,
    syntetizuje cílené breakouty (_breakout_synth) a předá je enginu jako
    extra_payloads; engine je zkusí PŘED generickou bankou napříč sinky
    JS_STRING/ATTR/HTML/SCRIPT_OUT/URL_SCHEME (javascript: URI klik je teď
    taky jen jeden ze sinků). Pokrývá level 4 (JS-string breakout) i level 5
    (javascript: URI) jedním průchodem.

    Vrací list potvrzených: [{url, param, payload, canary, tech}]."""
    findings = []
    if not _DOM_ENGINE_AVAILABLE or _DOMEngine is None:
        return findings
    eng = _DOMEngine(
        verifier,
        param_injector=lambda u, p, pl: inject_into_params(u, p, pl, extra_params=None),
        make_canary=_hv_make_canary)
    if not eng.available:
        return findings
    # naparsuj rich kontext reflexe → cílené synth breakouty (CANARY placeholder,
    # engine je nahradí čerstvým kanárkem per payload)
    synth: List[str] = []
    if (_BREAKOUT_SYNTH_AVAILABLE and _CONTEXT_ENGINE_AVAILABLE
            and _bsynth is not None and _ce_analyze is not None):
        try:
            marker = random_marker(10)
            turl = inject_into_params(url, param, marker, extra_params=None)
            if turl:
                r = session.get(turl, timeout=timeout,
                                allow_redirects=follow_redirects)
                rc = _ce_analyze(r.text or "", marker, None)
                if rc is not None:
                    synth = [p for _t, p in _bsynth.from_reflection_context(
                        rc, canary='"CANARY"', limit=cap)]
        except Exception:
            synth = []
    # synth se zkusí první (v JS_STRING sinku), pak generická banka všech sinků
    extra = {_SINK_JS_STRING: synth} if synth else None
    res = eng.probe(url, _SRC_QUERY, param=param, extra_by_sink=extra,
                    stop_after_first=True)
    for r in res:
        findings.append({"url": url, "param": param, "payload": r["payload"],
                         "canary": r.get("canary", ""),
                         "tech": r.get("technique", "")})
        cb["on_log"](
            f"[REFLECTED ✓ CONFIRMED] {param} → exec ({r.get('technique', '')}): "
            f"{r['payload'][:42]}", "info")
    return findings


def _fragment_xss_probe(verifier, urls, cb, cap: int = 15):
    """v10.43: DOM XSS přes URL fragment (#) — teď přes sjednocený
    DOMExploitEngine (source=FRAGMENT, sinky ATTR/HTML/SCRIPT_SRC). Chytá
    location.hash → innerHTML breakout (level 3) i hash → script.src přes
    data: URI (level 6). Čistě klientské (fragment se na server neposílá).

    Vrací list potvrzených: [{url, payload, canary, method}]."""
    findings = []
    if not _DOM_ENGINE_AVAILABLE or _DOMEngine is None:
        return findings
    eng = _DOMEngine(verifier, make_canary=_hv_make_canary)
    if not eng.available:
        return findings
    # level-3-specifický breakout z img src='cloud{hash}.jpg' (single/double quote)
    extra = {_SINK_ATTR: ["1' onerror='alert(\"CANARY\")",
                          "1\" onerror=\"alert('CANARY')",
                          "1.jpg'><svg onload=alert(\"CANARY\")>"]}
    seen = set()
    for u in list(urls)[:cap]:
        base = (u or "").split("#")[0]
        if not base or base in seen:
            continue
        seen.add(base)
        res = eng.probe(base, _SRC_FRAGMENT,
                        sinks=[_SINK_ATTR, _SINK_HTML, _SINK_SCRIPT_SRC],
                        extra_by_sink=extra, stop_after_first=True)
        for r in res:
            findings.append({"url": base, "payload": r["payload"],
                             "canary": r.get("canary", ""),
                             "method": r.get("technique", "")})
            cb["on_log"](
                f"[FRAGMENT ✓ CONFIRMED] DOM XSS via URL fragment at {base} "
                f"— canary fired ({r['payload'][:40]})", "info")
    return findings


def _build_evidence_chain(f: dict) -> List[str]:
    """v10.48: sestaví lidsky-čitelný evidence chain — co přesně nález prokázalo.
    Auditovatelná stopa pro klienta/triáž, ne jen jeden string."""
    chain: List[str] = []
    src = f.get("source", "")
    if src:
        chain.append(f"Detekováno detektorem: {src}")
    dc = f.get("dynamic_confirmation", "")
    if dc == "playwright_confirmed":
        chain.append("Dynamické potvrzení: payload SPUŠTĚN v reálném Chromiu "
                     "(kanárek vystřelil) — prokázaný true positive")
    elif f.get("dom_verified"):
        chain.append("DOM ověřeno headless verifierem")
    he = f.get("headless_evidence", "")
    if he:
        chain.append(f"Důkaz exekuce: {he[:160]}")
    # blind XSS OOB
    if src == "blind-oob" or f.get("fired_at_url"):
        fired = f.get("fired_at_url") or f.get("evidence", "")
        if fired:
            chain.append(f"OOB callback: payload zavolal domů z {fired[:120]} "
                         f"(blind — vystřelilo mimo injection point)")
        ex = f.get("exfil") or {}
        if isinstance(ex, dict):
            bits = []
            if ex.get("ck"):
                bits.append("cookies")
            if ex.get("html"):
                bits.append("DOM snapshot")
            if ex.get("dom"):
                bits.append(f"domain={ex.get('dom')}")
            if bits:
                chain.append("Vyexfiltrováno OOB callbackem: " + ", ".join(bits))
    if f.get("fp_risk"):
        reason = f.get("fp_reason") or f.get("downgrade_reason") or "neověřeno"
        chain.append(f"⚠ FP-risk (vyžaduje ruční ověření): {reason}")
    return chain


def _enrich_findings_for_report(findings):
    """v10.48: protáhne nálezy scorerem a doplní evidence chain. Vrací NOVÝ
    seznam kopií (původní emitnuté hity se nemění). Scorer je advisory —
    severitu detektoru nepřepisuje, jen přidá 'score' blok + 'evidence_chain'."""
    out = []
    for f in (findings or []):
        if not isinstance(f, dict):
            out.append(f)
            continue
        g = dict(f)
        if _SCORER_AVAILABLE and _annotate_finding is not None:
            try:
                g = _annotate_finding(g)  # přidá 'score' blok
            except Exception:
                pass
        try:
            g["evidence_chain"] = _build_evidence_chain(g)
        except Exception:
            g["evidence_chain"] = []
        out.append(g)
    return out


def _extract_forms_blind(html: str, base_url: str) -> List[Dict]:
    """v10.47: jednoduchá extrakce formulářů pro blind XSS spray —
    [{action, method, inputs:[{name,type}]}]."""
    out: List[Dict] = []
    try:
        soup = BeautifulSoup(html or "", "html.parser")
    except Exception:
        return out
    for form in soup.find_all("form"):
        try:
            action = requests.compat.urljoin(base_url, form.get("action") or base_url)
            if urlparse(action).scheme not in ("http", "https"):
                continue
            inputs = []
            for inp in form.find_all(["input", "textarea", "select"]):
                nm = inp.get("name")
                if not nm:
                    continue
                inputs.append({"name": nm, "type": (inp.get("type") or "text").lower()})
            out.append({"action": action,
                        "method": (form.get("method") or "get").lower(),
                        "inputs": inputs})
        except Exception:
            continue
    return out


def _run_headless_crawl(target, opts, auth_opts, cb, cancel_check):
    """v10.46: spustí authenticated headless-driven crawl. Vlastní Playwright
    browser (oddělený od verifieru). Vrací _headless_crawler.CrawlResult nebo None.

    opts: dict {max_depth,max_pages,settle_ms,network_idle,click_interactions,
                max_clicks_per_page,same_origin_only,allowed_hosts}
    auth_opts: dict {storage_state | login_url,username,password,username_selector,
                password_selector,submit_selector,logged_in_selector,logged_in_text,
                extra_headers}"""
    if not _HEADLESS_CRAWLER_AVAILABLE or _HeadlessCrawler is None:
        cb["on_log"]("[CRAWL] headless crawler unavailable (missing module/Playwright)", "warn")
        return None
    try:
        from playwright.sync_api import sync_playwright
    except Exception:
        cb["on_log"]("[CRAWL] Playwright not installed — headless crawl skipped", "warn")
        return None

    opts = opts or {}
    auth_opts = auth_opts or {}
    cfg = _CrawlConfig(
        max_depth=int(opts.get("max_depth", 3)),
        max_pages=int(opts.get("max_pages", 200)),
        same_origin_only=bool(opts.get("same_origin_only", True)),
        allowed_hosts=set(opts.get("allowed_hosts", []) or []),
        settle_ms=int(opts.get("settle_ms", 800)),
        network_idle=bool(opts.get("network_idle", True)),
        click_interactions=bool(opts.get("click_interactions", True)),
        max_clicks_per_page=int(opts.get("max_clicks_per_page", 6)),
    )
    auth = _AuthConfig(
        storage_state=auth_opts.get("storage_state"),
        login_url=auth_opts.get("login_url"),
        username=auth_opts.get("username"),
        password=auth_opts.get("password"),
        username_selector=auth_opts.get("username_selector"),
        password_selector=auth_opts.get("password_selector"),
        submit_selector=auth_opts.get("submit_selector"),
        logged_in_selector=auth_opts.get("logged_in_selector"),
        logged_in_text=auth_opts.get("logged_in_text"),
        extra_headers=auth_opts.get("extra_headers"),
    )
    _pw = _br = None
    try:
        _pw = sync_playwright().start()
        _br = _pw.chromium.launch(headless=True, args=["--no-sandbox"])
        crawler = _HeadlessCrawler(_br, cfg, auth,
                                   on_log=lambda m, l="info": cb["on_log"](m, l),
                                   cancel_check=cancel_check)
        cb["on_log"]("[CRAWL] authenticated headless-driven crawl starting…", "info")
        return crawler.crawl([target])
    except Exception as e:
        cb["on_log"](f"[CRAWL] headless crawl error: {e}", "warn")
        return None
    finally:
        for x, fn in ((_br, "close"), (_pw, "stop")):
            if x is not None:
                try: getattr(x, fn)()
                except Exception: pass


def _path_header_xss_probe(verifier, session, urls, cb, timeout=10.0,
                           follow_redirects=True, cap: int = 6):
    """v10.44/45: headlessně potvrzená reflected XSS z PATH segmentu, HTTP
    hlaviček (XFH/Referer), COOKIE hodnoty a postMessage přes sjednocený
    DOMExploitEngine.

    v10.45 výkon: každý drahý headless confirm je GATOVANÝ levným HTTP
    reflection pre-checkem (1 request s markerem). Headless render se spustí
    jen když se marker v odpovědi odrazí (resp. u postMessage jen když stránka
    má message listener). Na nereflektujících stránkách = pár HTTP GETů, žádný
    browser load. Doplňuje HTTP-level path/header/cookie skeny o exec-potvrzení.

    Vrací: [{url, kind, header?/cookie?, payload, technique}]."""
    findings = []
    if not _DOM_ENGINE_AVAILABLE or _DOMEngine is None or session is None:
        return findings
    eng = _DOMEngine(verifier, make_canary=_hv_make_canary)
    if not eng.available:
        return findings

    seen = set()
    for u in list(urls)[:cap]:
        base = (u or "").split("#")[0].split("?")[0]
        if not base or base in seen:
            continue
        seen.add(base)

        # PATH: marker jako segment → odrazí se?
        try:
            mk = "xg" + random_marker(8)
            r = session.get(base.rstrip("/") + "/" + mk, timeout=timeout,
                            allow_redirects=follow_redirects)
            if mk in (r.text or ""):
                for rr in eng.probe(base, _SRC_PATH, sinks=[_SINK_HTML, _SINK_ATTR],
                                    stop_after_first=True):
                    findings.append({"url": base, "kind": "path",
                                     "payload": rr["payload"], "technique": rr["technique"]})
                    cb["on_log"](f"[PATH ✓ CONFIRMED] reflected path-segment XSS "
                                 f"at {base} ({rr['payload'][:36]})", "info")
        except Exception:
            pass

        # HEADER: marker v hlavičce → odrazí se?
        for hname in ("X-Forwarded-Host", "Referer"):
            try:
                mk = "xg" + random_marker(8)
                r = session.get(base, timeout=timeout, allow_redirects=follow_redirects,
                                headers={hname: mk})
                if mk in (r.text or ""):
                    rr = eng.confirm_source_sink(base, _SRC_HEADER, _SINK_HTML, param=hname)
                    if rr:
                        findings.append({"url": base, "kind": "header", "header": hname,
                                         "payload": rr["payload"], "technique": rr["technique"]})
                        cb["on_log"](f"[HEADER ✓ CONFIRMED] reflected header XSS "
                                     f"({hname}) at {base} ({rr['payload'][:30]})", "info")
                        break
            except Exception:
                pass

        # COOKIE: marker v cookie → odrazí se?
        try:
            mk = "xg" + random_marker(8)
            r = session.get(base, timeout=timeout, allow_redirects=follow_redirects,
                            cookies={"xss": mk})
            if mk in (r.text or ""):
                rr = eng.confirm_source_sink(base, _SRC_COOKIE, _SINK_HTML, param="xss")
                if rr:
                    findings.append({"url": base, "kind": "cookie",
                                     "cookie": rr.get("cookie", "xss"),
                                     "payload": rr["payload"], "technique": rr["technique"]})
                    cb["on_log"](f"[COOKIE ✓ CONFIRMED] reflected cookie XSS "
                                 f"at {base} ({rr['payload'][:30]})", "info")
        except Exception:
            pass

        # POSTMESSAGE: jen když stránka má message listener (statický signál)
        try:
            r = session.get(base, timeout=timeout, allow_redirects=follow_redirects)
            body = r.text or ""
            if ('addeventlistener("message"' in body.lower()
                    or "addeventlistener('message'" in body.lower()
                    or ".onmessage" in body.lower() or "onmessage=" in body.lower()):
                for rr in eng.probe(base, _SRC_POSTMESSAGE,
                                    sinks=[_SINK_HTML, _SINK_DOC_WRITE, _SINK_EVAL],
                                    stop_after_first=True):
                    findings.append({"url": base, "kind": "postmessage",
                                     "payload": rr["payload"], "technique": rr["technique"]})
                    cb["on_log"](f"[POSTMESSAGE ✓ CONFIRMED] postMessage XSS at {base} "
                                 f"({rr['technique']}: {rr['payload'][:30]})", "info")
        except Exception:
            pass
    return findings


def _default_on_crawler_progress(data: dict):
    visited   = data.get("visited", 0)
    max_pages = data.get("max_pages", 1)
    depth     = data.get("depth", 0)
    success   = data.get("success", 0)
    errors    = data.get("errors", 0)
    queue     = data.get("queue", 0)
    rate      = data.get("rate", 0.0)
    eta       = data.get("eta", 0)

    percent    = int((visited / max_pages) * 100)
    bar_length = 30
    filled     = int((visited / max_pages) * bar_length)
    bar_visual = '█' * filled + '░' * (bar_length - filled)

    print(
        f"\r\033[K[CRAWL] {bar_visual} {visited}/{max_pages} ({percent}%) | "
        f"D:{depth} | OK:{success} ERR:{errors} | "
        f"Q:{queue} | {rate:.1f}p/s | ETA:{int(eta)}s",
        end='', flush=True
    )


def _default_on_crawler_done(data: dict):
    print()
    logging.info(
        f"Crawler finished: {data.get('pages', 0)} pages in {data.get('elapsed', 0):.1f}s"
    )
    logging.info(
        f"Stats: {data.get('success', 0)} success | {data.get('errors', 0)} errors | "
        f"{data.get('redirects', 0)} redirects | {data.get('params_found', 0)} param URLs found"
    )

# ---------------- Config ----------------
class TLSAdapter(HTTPAdapter):
    """HTTPS adapter for the requests path.

    v10.14 (anti-detection): by default now negotiates a
    browser-realistic ClientHello — TLS 1.2 minimum, a narrow modern
    cipher list close to what Chrome/Firefox offer. The previous
    behaviour ('ALL:@SECLEVEL=0' + TLSv1) produced a ClientHello no
    real browser ever sends, so JA3-based WAFs (Cloudflare/Akamai/
    Imperva) flagged the scanner as an automated tool before the first
    HTTP request — actively working against the UA/header/delay stealth.

    The old permissive behaviour is still available for genuinely
    ancient servers with broken TLS, but as an explicit opt-in
    (legacy_tls=True / --legacy-tls), not the default.

    NOTE: this is a best-effort approximation. requests/urllib3 does
    not expose full control over extension ordering, so the JA3 is not
    bit-identical to a real browser. For true browser-grade JA3/JA4 the
    curl_cffi path is used automatically when available (see
    make_session); this adapter is the fallback.
    """

    # Modern Chrome/Firefox-ish cipher preference. TLS 1.3 suites are
    # negotiated by the stack automatically; this governs the TLS 1.2
    # suite list and its order, which is what feeds the JA3 hash.
    _BROWSER_CIPHERS = ":".join([
        "ECDHE-ECDSA-AES128-GCM-SHA256",
        "ECDHE-RSA-AES128-GCM-SHA256",
        "ECDHE-ECDSA-AES256-GCM-SHA384",
        "ECDHE-RSA-AES256-GCM-SHA384",
        "ECDHE-ECDSA-CHACHA20-POLY1305",
        "ECDHE-RSA-CHACHA20-POLY1305",
        "ECDHE-RSA-AES128-SHA",
        "ECDHE-RSA-AES256-SHA",
        "AES128-GCM-SHA256",
        "AES256-GCM-SHA384",
        "AES128-SHA",
        "AES256-SHA",
    ])

    def __init__(self, *args, legacy_tls: bool = False, **kwargs):
        self._legacy_tls = legacy_tls
        super().__init__(*args, **kwargs)

    def _build_ctx(self):
        ctx = create_urllib3_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        if self._legacy_tls:
            # Opt-in: permissive — connects to ancient/broken-TLS
            # servers, but produces a non-browser JA3. Use only when
            # the target genuinely needs it.
            import warnings
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", DeprecationWarning)
                ctx.minimum_version = ssl.TLSVersion.TLSv1
            ctx.set_ciphers('ALL:@SECLEVEL=0')
        else:
            # Default: browser-realistic. TLS 1.2 floor + narrow
            # modern cipher list → JA3 close to a real browser.
            try:
                ctx.minimum_version = ssl.TLSVersion.TLSv1_2
            except (ValueError, AttributeError):
                pass
            try:
                ctx.set_ciphers(self._BROWSER_CIPHERS)
            except ssl.SSLError:
                # Some OpenSSL builds reject a cipher in the list —
                # fall back to the library default rather than crash.
                pass
        return ctx

    def init_poolmanager(self, *args, **kwargs):
        kwargs['ssl_context'] = self._build_ctx()
        super().init_poolmanager(*args, **kwargs)

    def proxy_manager_for(self, proxy, **proxy_kwargs):
        proxy_kwargs['ssl_context'] = self._build_ctx()
        return super().proxy_manager_for(proxy, **proxy_kwargs)
 
